vec4 lm_edge_sobel(vec2 uv0)
{
    vec4 n[9];
	float imageWidth = iResolution.x;
	float imageHeight = iResolution.y;
	float mid_weight = PREFIX(strength);
	vec2 stepScale = vec2(PREFIX(scale));
    float w = 1.0/float(imageWidth)*stepScale.x;
    float h = 1.0/float(imageHeight)*stepScale.y;
	n[0] = INPUT(uv0 + vec2( -w, -h));
	n[1] = INPUT(uv0 + vec2(0.0, -h));
	n[2] = INPUT(uv0 + vec2( w, -h));
	n[3] = INPUT(uv0 + vec2( -w, 0.0));
	n[4] = INPUT(uv0);
	n[5] = INPUT(uv0 + vec2( w, 0.0));
	n[6] = INPUT(uv0 + vec2( -w, h));
	n[7] = INPUT(uv0 + vec2(0.0, h));
	n[8] = INPUT(uv0 + vec2( w, h));

  	//float mid_weight = 1.0;
	vec4 sobel_edge_h = n[2] + (2.0*n[5]*mid_weight) + n[8] - (n[0] + (2.0*n[3]*mid_weight) + n[6]);
  	vec4 sobel_edge_v = n[0] + (2.0*n[1]*mid_weight) + n[2] - (n[6] + (2.0*n[7]*mid_weight) + n[8]);
	vec4 sobel = sqrt((sobel_edge_h * sobel_edge_h) + (sobel_edge_v * sobel_edge_v));

  	/*if(type==0)
    {
    	float gray = lm_rgb2gray(sobel.rgb);
    	sobel = vec4(vec3(gray),1.0);
    }*/
  	sobel.a = 1.0;
    return sobel;
}

vec4 changecolor(vec2 uv0)
{
	vec4 resultColor = lm_edge_sobel(uv0);
