bool inSize(vec2 coords){
	float iTime = PREFIX(global_time);
	float sizecolor = PREFIX(size);
	float speed1 = PREFIX(speed);	
    vec2 box = coords.xy-mod(coords.xy, sizecolor);
	vec2 center = box+(sizecolor/2.0);
    float size1 = (tan((iTime * speed1)+(randomize(box*18.0)*2.0))/2.0)*(sizecolor);
    return (abs(coords.x-center.x) < size1 && abs(coords.y-center.y) < size1);
}

