    float colorG        = PREFIX(GBlurIntension);
    float colorB        = PREFIX(BBlurIntension);

    vec4 tmpColor;
	tmpColor = getBloomOriginColor(outCenter, blurIntension);
    tmpColor.r = colorB > 0.0 ? outCenter.r*colorB : colorSrc.r;
