}

vec3 RGBToYCoCg(vec3 RGB) {
  float Y = dot(RGB, vec3(1, 2, 1)) * 0.25;
  float Co = dot(RGB, vec3(2, 0, -2)) * 0.25 + (0.5 * 256.0 / 255.0);
  float Cg = dot(RGB, vec3(-1, 2, -1)) * 0.25 + (0.5 * 256.0 / 255.0);
  return vec3(Y, Co, Cg);
}

vec3 YCoCgToRGB(vec3 YCoCg) {
  float Y = YCoCg.x;
  float Co = YCoCg.y - (0.5 * 256.0 / 255.0);
  float Cg = YCoCg.z - (0.5 * 256.0 / 255.0);
  float R = Y + Co - Cg;
  float G = Y + Cg;
  float B = Y - Co - Cg;
  return vec3(R, G, B);
}

vec4 bokehBlur(vec2 uv, float radius, int iter, float brighten){
  mat2 rot = rotateMat(2.3999632);
  vec3 accumulator = vec3(0.0);
  vec3 divisor = vec3(0.0);
  float r = 1.0;
  vec2 angle = vec2(radius, 0.0);
  vec2 pixelSize = 1.0 / iResolution.xy;
  for(int i = 0; i < iter; i++){
    r = sqrt(float(i));
    angle = rot * angle;
    vec3 col = RGBToYCoCg(INPUT1(vec2(uv + r * angle * pixelSize)).rgb);
    vec3 bokeh = pow(col, vec3(brighten));
    accumulator += col * bokeh;
    divisor += bokeh;
  }
  float alp = INPUT1(uv).a;
  vec3 res = YCoCgToRGB(accumulator / divisor).rgb;
  return vec4(res, 1.0) * alp;
}

vec4 FUNCNAME(vec2 tc) {
  int uStep = PREFIX(uStep);
  float blurProp = float(PREFIX(Blur)) / 100.0;
