vec4 radial_blur1(vec2 fc, vec2 radialCenter, float radialBlur, float iteration, float glowIntensity){
  vec2 fcc = fc - radialCenter;
  vec4 destColor = vec4(0.0);
  float random = rnd(vec3(12.9898, 78.233, 151.7182), 0.0, vec3(fc, 0.0));
  float totalWeight = 0.0;
  float nFrag = 1.0 / iteration;
  for (float i = 0.0; i <= iteration; i+=1.0) {
    float percent = (i + random) * nFrag;
    float weight = percent - percent * percent;
    vec2 t = fc - fcc * percent * radialBlur * nFrag;
    destColor += INPUT(t) * weight;
    totalWeight += weight;
  }
  return destColor / (totalWeight * glowIntensity) ;
}
vec4 Blur1(vec2 tc, vec2 center, float process, float strength, float glowIntensity)
{ 
    vec4 fragColor = vec4(0.0);
    vec2 radialCenter = center; 
    float maxRotateRad = radians(-20.0);
    float maxRadialRadius = 26.0;
    float iteration = 30.0; 

    float curPro = process * strength * 0.8;   
    float curRotateRad = maxRotateRad*curPro;    
    float curRadialRadius = mix(0.0, maxRadialRadius, curPro);
    fragColor = radial_blur1(tc, radialCenter, curRadialRadius, iteration, max(glowIntensity, (1.0 - process)) );
	return fragColor;	
}


float easeOutQuart(float x){
