#define PI 3.14159625

float bezier(float t, vec2 p1, vec2 p2, vec2 p3)
{   
    vec2 p0 = vec2(0.0);
    vec2 q0 = mix(p0, p1, t);
    vec2 q1 = mix(p1, p2, t);
    vec2 q2 = mix(p2, p3, t);

    vec2 r0 = mix(q0, q1, t);
    vec2 r1 = mix(q1, q2, t);

    return mix(r0, r1, t).y;
}

vec4 RadialBlur(vec2 itc, float iprocess, vec2 icenter)
{
    vec2 uv = itc;
    int nsamples = 16;
    float blurStart = 1.0;
    float blurWidth = 0.2 * iprocess;

    uv -= icenter;
    float precompute = blurWidth * (1.0 / float(nsamples - 1));

    vec4 curColor = vec4(0.0);
    vec4 color = vec4(0.0);
    for(int i = 0; i < nsamples; i++)
    {
        float scale = blurStart + float(i)* precompute;
        color += INPUT(uv * scale + icenter);
    }

    color /= float(nsamples);
    return color;
}

