float WS_DoOverlayPerChannel(float baseVal, float blendVal)
{
    float result;

    if(baseVal < 0.5)
    {
        result = 2.0 * baseVal * blendVal;
    }
    else
        result = 1.0 - 2.0 * (1.0 - baseVal) * (1.0 - blendVal);

    return result;
}


