#define NOISE_SIMPLEX_1_DIV_289 0.00346020761245674740484429065744
#define PI 3.141592653

vec2 mod289(vec2 x){
  return x - floor(x * NOISE_SIMPLEX_1_DIV_289) * 289.0;
}

vec3 mod289(vec3 x){
  return x - floor(x * NOISE_SIMPLEX_1_DIV_289) * 289.0;
}

vec3 permute(vec3 x){
  return mod289(x * x * 34.0 + x);
}

vec3 taylorInvSqrt(vec3 r){
  return 1.79284291400159 - 0.85373472095314 * r;
}

float snoise(vec2 v){
  vec4 C = vec4(0.211324865405187, // (3.0-sqrt(3.0))/6.0
                0.366025403784439, // 0.5*(sqrt(3.0)-1.0)
               -0.577350269189626, // -1.0 + 2.0 * C.x
                0.024390243902439);// 1.0 / 41.0
  // First corner
  vec2 i  = floor(v + dot(v, C.yy));
  vec2 x0 = v - i + dot(i, C.xx);

  // Other corners
  vec2 i1;
  i1.x = step(x0.y, x0.x);
  i1.y = 1.0 - i1.x;

  vec2 x1 = x0 + C.xx - i1;
  vec2 x2 = x0 + C.zz;

  // Permutations
  i      = mod289(i); // Avoid truncation effects in permutation
  vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));

  vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x1, x1), dot(x2, x2)), 0.0);
  m = m * m;
  m = m * m;

  // Gradients: 41 points uniformly over a line, mapped onto a diamond.
  // The ring size 17*17 = 289 is close to a multiple of 41 (41*7 = 287)
  vec3 x  = 2.0 * fract(p * C.www) - 1.0;
  vec3 h  = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;

  // Normalise gradients implicitly by scaling m
  m *= taylorInvSqrt(a0 * a0 + h * h);

  // Compute final noise value at P
  vec3 g;
  g.x = a0.x * x0.x + h.x * x0.y;
  g.y = a0.y * x1.x + h.y * x1.y;
  g.z = a0.z * x2.x + h.z * x2.y;
  return 130.0 * dot(m, g);
}

vec2 wave_glitch(vec2 uv, float iGlobalTime, float strength, float speed, float amount){
  float uv_y         = uv.y * iResolution.y;
  float noise_wave_1 = snoise(vec2(uv_y * 0.01, iGlobalTime * speed * 20.0)) * (strength * amount * 32.0);
  float noise_wave_2 = snoise(vec2(uv_y * 0.02, iGlobalTime * speed * 10.0)) * (strength * amount *  4.0);
  float noise_wave_3 = snoise(vec2(uv_y * 0.03, iGlobalTime * speed * 15.0)) * (strength * amount * 10.0);
  float noise_wave_x = noise_wave_1 * noise_wave_2 * noise_wave_3 / iResolution.x;
  return vec2(noise_wave_1,noise_wave_x);
}

vec4 screen(vec4 back, vec4 fore){
  return 1.0-(1.0-back)*(1.0-fore);
}

float modF(float a,float b){
  return (a)-floor((a)/(b))*(b);
}

float RightshiftOperation(float a, int b){
  float m = 1.0;
  for(int i=0;i<b;i++){
    m *= 2.0;
  }      
  return floor(a/m);
}

float truncation(float a, int b){
  return modF((a),float(b));
}

vec4 GetColor(int color){
  float color_red = truncation(RightshiftOperation(float(color), 16), 256);
  float color_green = truncation(RightshiftOperation(float(color), 8), 256);
  float color_blue = truncation(float(color), 256);
  vec4 colors = vec4(color_blue, color_green, color_red, 255.0) / 255.0;    
  return colors;
}

float inBound(vec2 uv){
  return step(0.0, uv.x)*step(uv.x, 1.0)*step(0.0, uv.y)*step(uv.y, 1.0);
}

