#define PI 3.14159265

float rgb2grey(vec3 rgbColor){
    return (rgbColor.r * 0.299 + rgbColor.g * 0.587 + rgbColor.b * 0.114);
}
vec3 selfGlowColor(vec4 curColor, float threshold) {
	vec4 resultColor=curColor;
	float t=clamp(threshold,.01,1.);
	resultColor.rgb=smoothstep(t - 0.065 * threshold, t + .065, resultColor.rgb);
	float gamma = 2.2;
	return pow(resultColor.rgb, vec3(1. / gamma));
}
vec3 abGlowColor(vec4 curColor, float threshold){
	float t = clamp(threshold, .01, 1.);
	float grey = rgb2grey(curColor.rgb);
	vec3 resultColor = smoothstep(t - .065 * threshold, t + .065, vec3(grey)); 
	return resultColor;
}
vec4 stepHighlight(vec2 uv, float Range)
{
    float flagGlowColor = 0.0;
    // float threshold = 1.0 - (0.1 + 0.25*Afterimage )*iPro;
    float threshold = 1.0 - 0.5*Range;
    // vec4 curColor = INPUT1(uv);
    vec4 curColor = vec4(0.0);
	// curColor = INPUT1(uv);
    if(INPUT1(uv).r > 0.68 - 0.4*Range){
        curColor = INPUT2(uv);
    }
    // if(rgb2grey(INPUT1(uv).rgb) > Range){
    //     curColor = INPUT2(uv);
    // }
	vec4 SelfGlowColor = curColor;
	SelfGlowColor.rgb = selfGlowColor(curColor, threshold);
	vec4 sourceColor = curColor;
	sourceColor.rgb = abGlowColor(curColor, threshold);
	vec4 ABColor = sourceColor;
	vec4 ABAColor = sourceColor;
	vec4 resultColor = vec4(0.);
	if (flagGlowColor < .5) resultColor = SelfGlowColor;
	else if (flagGlowColor < 1.5) resultColor = ABColor;
	else resultColor = ABAColor;
	return resultColor;
}



vec4 neighborColor(float i, vec2 uv0){
    vec2 u_ScreenParams = iResolution;
	float blurSize = 1.;
	float rescale = min(u_ScreenParams.x, u_ScreenParams.y) / 800.;
	blurSize *= rescale;
	vec2 unit = vec2(blurSize/u_ScreenParams.x,blurSize/u_ScreenParams.y);
	vec2 uv1 = uv0 + unit * vec2(i, 0.);
	vec2 uv2 = uv0 - unit * vec2(i, 0.);
	vec4 result = INPUT1(uv1) * step(uv1.x, 1.) * step(0., uv1.x)
				+ INPUT1(uv2) * step(uv2.x, 1.) * step(0., uv2.x);
	return result;
}
float Gaussian (float x)
{
    float horzR = 50.0;
    float sigma = 50.0;
	// multiply 10 to alleviate precision problem
    return exp(-(x*x) / (2.0 * sigma*sigma * horzR * horzR / 100.)) * 10.; 
}
vec4 horzBlurColor(vec4 curColor, vec2 uv0, float blur){
    float horzR = 200.0*blur;
	vec4 resultColor=vec4(0.);

	vec4 centerPixel=curColor*10.;
	resultColor += centerPixel;
	float weight=10.;
	float i = 1.;
	float w = 0.;
	for(float i=1.;i<= 80.;i++){
		if (i > 8. * (horzR / 10.)) break;
		w = Gaussian(float(i));
		resultColor += neighborColor(i, uv0) * w;
		weight += w * 2.;
	}
	resultColor /= weight;
	return resultColor;
}




vec4 neighborColorVert(float i, vec2 uv0){
    vec2 u_ScreenParams = iResolution;
	float blurSize = 1.;
	float rescale = min(u_ScreenParams.x, u_ScreenParams.y) / 800.;
	blurSize *= rescale;
	vec2 unit = vec2(blurSize/u_ScreenParams.x,blurSize/u_ScreenParams.y);
	vec2 uv1 = uv0 + unit * vec2(0., i);
	vec2 uv2 = uv0 - unit * vec2(0., i);
	vec4 result = INPUT1(uv1) * step(uv1.x, 1.) * step(0., uv1.x)
				+ INPUT1(uv2) * step(uv2.x, 1.) * step(0., uv2.x);
	return result;
}
vec4 vertBlurColor(vec4 curColor, vec2 uv0, float blur){
    float horzR = 200.0*blur;
	vec4 resultColor=vec4(0.);

	vec4 centerPixel=curColor*10.;
	resultColor += centerPixel;
	float weight=10.;
	float i = 1.;
	float w = 0.;
	for(float i=1.;i<= 80.;i++){
		if (i > 8. * (horzR / 10.)) break;
		w = Gaussian(float(i));
		resultColor += neighborColorVert(i, uv0) * w;
		weight += w * 2.;
	}
	resultColor /= weight;
	return resultColor;
}




vec4 adjustColor(vec4 sourceColor, vec2 uv0, float flagGlowColor) {

    float threshold = 1.0;
    float intensity = 1.0;
    vec3 ColorA = vec3(255., 255., 255.)/255.0;
    vec3 ColorB = vec3(0., 0., 0.);

	vec4 resultColor = sourceColor;
	float grey = rgb2grey(resultColor.rgb);
	vec4 ABColor = sourceColor;
	ABColor.rgb = sourceColor.rgb * ColorA;
	ABColor.rgb = mix(ABColor.rgb, ColorB, (1. - grey) * .2);//AB乘0.2

	if (sourceColor.r < .5) sourceColor.r = sourceColor.r / .5;
	else sourceColor.r = 1. - (sourceColor.r - .5) / .5;
	if (sourceColor.g < .5) sourceColor.g = sourceColor.g / .5;
	else sourceColor.g = 1. - (sourceColor.g - .5) / .5;
	if (sourceColor.b < .5) sourceColor.b = sourceColor.b / .5;
	else sourceColor.b = 1. - (sourceColor.b - .5) / .5;
	vec4 ABAColor = sourceColor;
	ABAColor.rgb *= ColorA * grey;
	ABAColor.rgb = mix(ABAColor.rgb, ColorB, grey);


	if (flagGlowColor < .5) {
		if (intensity <= 1.) {
			resultColor.rgb = resultColor.rgb * intensity;
		}
		else {
			float range = .035;
			float edge = -.0;
			float edge1 = edge + range * 2.;
			float v = smoothstep(-range, range, 1. - edge - uv0.x) * smoothstep(-range, range, 1. - edge - uv0.y)
					* smoothstep(-range, range, uv0.x - edge) * smoothstep(-range, range, uv0.y - edge);
			vec3 addColor = max(resultColor.rgb, min(vec3(.7), resultColor.rgb * intensity));
			resultColor.rgb = mix(addColor, resultColor.rgb * intensity, v);
			resultColor.rgb = clamp(resultColor.rgb, 0., 1.);
			float v1 = smoothstep(-range, range, 1. - edge1 - uv0.x) * smoothstep(-range, range, 1. - edge1 - uv0.y)
					* smoothstep(-range, range, uv0.x - edge1) * smoothstep(-range, range, uv0.y - edge1);
			resultColor.rgb = mix(addColor, resultColor.rgb, v1);
		}
	}
	else if (flagGlowColor < 1.5) {
		// AB color
		resultColor = ABColor;
		if (intensity <= 1.) {
			resultColor.rgb = resultColor.rgb * intensity;
		}
		else {
			float range = .035;
			float edge = -.0;
			float edge1 = 0.;//edge + range * 2.;
			float v = smoothstep(-range, range, 1. - edge - uv0.x) * smoothstep(-range, range, 1. - edge - uv0.y)
					* smoothstep(-range, range, uv0.x - edge) * smoothstep(-range, range, uv0.y - edge);
			vec3 addColor = max(resultColor.rgb, min(vec3(.7) * (ColorA + ColorB) / 2., resultColor.rgb * intensity));
			resultColor.rgb = mix(addColor, min(resultColor.rgb * intensity, ColorA), v);
			resultColor.rgb = clamp(resultColor.rgb, 0., 1.);
			float v1 = smoothstep(-range, range, 1. - edge1 - uv0.x) * smoothstep(-range, range, 1. - edge1 - uv0.y)
					* smoothstep(-range, range, uv0.x - edge1) * smoothstep(-range, range, uv0.y - edge1);
			resultColor.rgb = mix(addColor, resultColor.rgb, v1);
		}
	}
	else{
		resultColor = sourceColor;
	}
	return resultColor;
}


