float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

/*
 * @param aX: 传入时间变量
 * @param p1/p2: 贝塞尔曲线两个控制点
 * 说明: 这个函数以上的其他函数都是本函数使用的辅助函数
 */
float KeySpline(vec4 p, float aX) {
  float mX1 = p.x;
  float mY1 = p.y;
  float mX2 = p.z;
  float mY2 = p.w;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;  // linear
  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

float sat(float x){
  return clamp(x, 0.0, 1.0);
}

mat2 rotateMat(float theta){
  float c = cos(theta);
  float s = sin(theta);
  return mat2(c, s, -s, c);
}

vec3 RGBToYCoCg(vec3 RGB) {
  float Y = dot(RGB, vec3(1, 2, 1)) * 0.25;
  float Co = dot(RGB, vec3(2, 0, -2)) * 0.25 + (0.5 * 256.0 / 255.0);
  float Cg = dot(RGB, vec3(-1, 2, -1)) * 0.25 + (0.5 * 256.0 / 255.0);
  return vec3(Y, Co, Cg);
}

vec3 YCoCgToRGB(vec3 YCoCg) {
  float Y = YCoCg.x;
  float Co = YCoCg.y - (0.5 * 256.0 / 255.0);
  float Cg = YCoCg.z - (0.5 * 256.0 / 255.0);
  float R = Y + Co - Cg;
  float G = Y + Cg;
  float B = Y - Co - Cg;
  return vec3(R, G, B);
}

float IrisMask(vec2 uv, float areaSize){
  vec2 center = uv * 2.0 - 1.0;
  float dist = dot(center, center);
  vec4 p = vec4(.55,.54,.55,.91);
  return KeySpline(p, sat(dist * 0.2 * areaSize));
}

