#define PI 3.141592653

float normpdf(float x, float sigma)
{
  return 0.39894 * exp(-0.5 * x * x / (sigma * sigma)) / sigma;
}

vec4 motionBlur(vec2 tc, float angle, float blur, float repears)
{
  float sigma = 28.0;
  float theta = radians(angle);
  vec2 direction = vec2(sin(theta), cos(theta));
  float weight = normpdf(0.0, sigma);
  vec4 retCol = INPUT(tc);
  retCol *= weight;
  float sum = weight;
  float radius = 0.03 * blur;

  for (float j = 1.0; j < repears; j += 1.0)
  {
    weight = normpdf(j / 10.0 * 25.0, sigma);
    float offset = radius * j * 1.2;
    vec2 uv = tc + direction * offset;
    retCol += INPUT(uv) * weight;
    sum += weight;

    uv = tc - direction * offset;
    retCol += INPUT(uv) * weight;
    sum += weight;
  }

  retCol /= sum;
  retCol = clamp(retCol, 0.0, 1.0);
  return retCol;
}

vec4 adjustExposure(vec4 color, float exposure, float contrast){
  vec4 retCol = color;
  retCol.rgb = pow(retCol.rgb, vec3(2.2));
  if(exposure < 0.0){
      retCol.rgb *= pow(2.0, exposure * 0.02353);
  }else if(exposure > 0.0){
      retCol.rgb *= 1.0 + pow(vec3(6.0), -retCol.rgb) * exposure * 0.034;
  }
  retCol.rgb = pow(retCol.rgb, vec3(1.0 / contrast));
  retCol.rgb = pow(retCol.rgb, vec3(1.0 / 2.2));
  retCol = clamp(retCol, 0.0, 1.0);
  return retCol;
}

