vec4 simple_fast_gaussian_blur(vec2 uv,vec2 resolution)
{
    float range = PI * 2.0;

    // GAUSSIAN BLUR SETTINGS {{{
    float Directions = 16.0; // BLUR DIRECTIONS (Default 16.0 - More is better but slower)
    float Quality = 12.0; // BLUR QUALITY (Default 4.0 - More is better but slower)
    vec2 radius = vec2(0.02, 0.037) ; // BLUR SIZE (Radius)
    // GAUSSIAN BLUR SETTINGS }}}

	vec3 W = vec3(0.299,0.587,0.114);

    // Pixel colour
    vec4 Color = INPUT(uv);
    Color.a = setMaskVal(Color,W);

    // Blur calculations
    for( float d=0.0; d<range; d+=range/Directions)
    {
		for(float i=1.0/Quality; i<=1.0; i+=1.0/Quality)
        {
			vec4 acc_color = INPUT(uv+vec2(cos(d),sin(d))*radius*i);
			acc_color.a = setMaskVal(acc_color,W);
			Color += acc_color;	
        }
    }

    // Output to screen
    Color /= Quality * Directions;
	return Color;
}

