vec3 HSL_RGBtoHSL(vec3 RGB)
{
    vec3 hsl;
    float R = RGB.x;
    float G = RGB.y;
    float B = RGB.z;
    float Max = 0.0;
    float Min = 0.0;
    float H = 0.0;
    float S = 0.0;
    float L = 0.0;

    Min = min(R, min(G, B));
    Max = max(R, max(G, B));

    if (Min == Max)
    {
        H = 2.0 / 3.0;
        S = 0.0;
        L = R;
    }
    else
    {
        L = (Max + Min) / 2.0;

        if (L < 0.5)
            S = (Max - Min) / (Max + Min);
        else
            S = (Max - Min) / (2.0 - Max - Min);

        if (R == Max)
            H = (G - B) / (Max - Min);
        else if (G == Max)
            H = 2.0 + (B - R) / (Max - Min);
        else
            H = 4.0 + (R - G) / (Max - Min);

        H /= 6.0;
        if (H < 0.0)
            H += 1.0;
    }

    hsl.x = H * 360.0;
    hsl.y = S;
    hsl.z = L;

    return hsl;
}

vec3 HSL_HSLtoRGB(vec3 HSL)
{
    vec3 RGB;
    float H = HSL.x / 360.0;
    float S = HSL.y;
    float L = HSL.z;
    float R = 0.0;
    float G = 0.0;
    float B = 0.0;
    float var_1 = 0.0;
    float var_2 = 0.0;
    float tempr = 0.0;
    float tempg = 0.0;
    float tempb = 0.0;

    if (S == 0.0)
    {
        R = G = B = L;
    }
    else
    {
        if (L < 0.5)
            var_2 = L * (1.0 + S);
        else
            var_2 = (L + S) - (L * S);

        var_1 = 2.0 * L - var_2;

        tempr = H + 1.0 / 3.0;
        if (tempr > 1.0)
            tempr=tempr-1.0;

        tempg = H;

        tempb = H - 1.0 / 3.0;
        if (tempb < 0.0)
            tempb=tempb+1.0;

        // Red
        if (tempr < 1.0 / 6.0)
            R = var_1 + (var_2 - var_1) * 6.0 * tempr;
        else if (tempr < 0.5)
            R = var_2;
        else if (tempr < 2.0 / 3.0)
            R = var_1 + (var_2 - var_1) * ((2.0 / 3.0) - tempr) * 6.0;
        else
            R = var_1;
        // Green
        if (tempg < 1.0 / 6.0)
            G = var_1 + (var_2 - var_1) * 6.0 * tempg;
        else if (tempg < 0.5)
            G = var_2;
        else if (tempg < 2.0 / 3.0)
            G = var_1 + (var_2 - var_1) * ((2.0 / 3.0) - tempg) * 6.0;
        else
            G = var_1;
        // Blue
        if (tempb < 1.0 / 6.0)
            B = var_1 + (var_2 - var_1) * 6.0 * tempb;
        else if (tempb < 0.5)
            B = var_2;
        else if (tempb < 2.0 / 3.0)
            B = var_1 + (var_2 - var_1) * ((2.0 / 3.0) - tempb) * 6.0;
        else
            B = var_1;
    }

    RGB.x = R;
    RGB.y = G;
    RGB.z = B;

    return RGB.zyx;
}

vec4 adjustSat(vec4 origCol, float satVal){
    if(abs(satVal) > 0.00001)
    {
        float maxV = max(origCol.b,max(origCol.r,origCol.g));
        float minV = min(origCol.b,min(origCol.r,origCol.g));
        if(abs(maxV - minV) > 0.00001)
        {
            float grayValue = (origCol.r * 11.0 + origCol.g * 59.0 + origCol.b * 30.0 + 0.196) * 0.01;
            float alpha = satVal;
            float ratio = (maxV - minV) / maxV;
            if(satVal > 0.0){
                alpha = satVal * (1.0 - ratio);
            }
            origCol.rgb += (origCol.rgb - grayValue) * alpha;
        }
        origCol = clamp(origCol, 0.0, 1.0);
    }
    return origCol;
}

float calBrightValue(float bright)
{
    float brightValue = 0.0;

    if (bright > 0.0)
    {
        brightValue = 1.0 + bright / 100.0;
    }
    else
    {
        brightValue = 1.0 - 1.0 / (0.99 + bright / 253.0);
        brightValue *= 0.6;
    }

    return brightValue;
}

vec4 newBrightness(vec4 color, float bright)
{
    vec4 ret;

    if (bright > 0.0)
