float easeOutCubic(float x) 
{
    return 1.0 - pow(1.0 - x, 3.0);
}
float easeInSine(float x)
{
  return 1.0 - cos((x * 3.141592653) / 2.0);
}
float easeOutQuad(float x) 
{
    return 1.0 - (1.0 - x)*(1.0 - x);
}
float easeInOutQuint(float x) 
{
    return x < 0.5 ? 16.0 * x * x * x * x * x : 1.0 - pow(-2.0 * x + 2.0, 5.0) / 2.0;
}

vec3 bokeh(vec2 uv,vec2 radius,float lod, float ang, float gamma, float SAMPLES){
	vec3 col = vec3( 0.0 );
    for(float i = 0.; i<SAMPLES; i++){
        float d = i/SAMPLES;
    	vec2 p = vec2(sin(ang*i), cos(ang*i)) * sqrt(d) * radius;
        vec4 resCol = INPUT(uv+p);
        col += pow(resCol.rgb, vec3(gamma));
    }
    return pow(col/SAMPLES, vec3(1./gamma));
}
