    float lutR = INPUT3(vec2((color.r * 255.0 + 0.5) / 256.0, 0.5)).b;  // 采样B=BlueLUT → R通道
    float lutG = INPUT3(vec2((color.g * 255.0 + 0.5) / 256.0, 0.5)).g;  // 采样G=GreenLUT → G通道
    float lutB = INPUT3(vec2((color.b * 255.0 + 0.5) / 256.0, 0.5)).r;  // 采样R=RedLUT → B通道
    return vec3(lutR, lutG, lutB);
