#define param_alpha 100
#define param_eItime u_global_time
// 70S 复古滤镜 - OpenGL版本 (纹理优化版)
// 原始 ~280行常量数组 → 3张预计算纹理查表
// 纹理布局 (conf TEXTURES顺序绑定):
//   INPUT1 = 视频源 (SetInputFilterData)
//   INPUT2 = t.png  (占位, TEXTURES[0])
//   INPUT3 = 70s_lut.png   (256×1 RGB, R=BlueLUT, G=GreenLUT, B=RedLUT, TEXTURES[1])
//   INPUT4 = 70s_noise.png (10×60 灰度, 6个10×10噪点模板纵向堆叠, TEXTURES[2])
//   INPUT5 = 70s_line.png  (128×1 灰度, 32组×4值线条模板, TEXTURES[3])

// 简化的随机函数（模拟C++ rand()）
float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

// 70S LUT颜色映射 - 纹理查表版
// 引擎加载PNG为BGR: 存储RGB(BlueLUT,GreenLUT,RedLUT) → 采样得到BGR(RedLUT,GreenLUT,BlueLUT)
// 所以: .r采样=RedLUT(用于B通道), .g采样=GreenLUT(用于G通道), .b采样=BlueLUT(用于R通道)
vec3 apply70sLUT(vec3 color) {
    // 用各通道值直接查LUT纹理 (256×1)
    float lutR = INPUT3(vec2((color.r * 255.0 + 0.5) / 256.0, 0.5)).b;  // 采样B=BlueLUT → R通道
    float lutG = INPUT3(vec2((color.g * 255.0 + 0.5) / 256.0, 0.5)).g;  // 采样G=GreenLUT → G通道
    float lutB = INPUT3(vec2((color.b * 255.0 + 0.5) / 256.0, 0.5)).r;  // 采样R=RedLUT → B通道
    return vec3(lutR, lutG, lutB);
}

// 噪点模板查表 - 纹理版
// 噪点纹理: 10×60, 6个10×10模板纵向堆叠
// 引擎BGR: 灰度纹理R=G=B，取任意通道即可
float getNoiseValue(int templateIdx, int y, int x) {
    float u = (float(x) + 0.5) / 10.0;
    float v = (float(templateIdx * 10 + y) + 0.5) / 60.0;
    return INPUT4(vec2(u, v)).r * 255.0;
}

// 线条模板查表 - 纹理版
// 线条纹理: 128×1, 索引 = k*4+x
// 引擎BGR: 灰度纹理取任意通道
float getLineValue(int k, int x) {
    k = k % 32;
    float u = (float(k * 4 + x) + 0.5) / 128.0;
    return INPUT5(vec2(u, 0.5)).r * 255.0;
}

// 精确复刻CL的doAndNoise函数
vec3 addFilmNoise(vec3 color, vec2 uv, float time) {
    // 使用固定种子生成确定性随机数（模拟rand()）
    // mod限制seed范围，防止移动端mediump精度下sin()大数退化
    float seed = mod(floor(time * 25.0), 1000.0); // 每帧变化，循环250帧(~10秒)

    // 1. 黑色噪点块（&= 位运算变暗）
    // 在768x1024画布上生成0-29个10x10噪点块
    vec2 canvasSize = vec2(1024.0, 768.0);
    vec2 canvasCoord = uv * canvasSize;

    float noiseValue = 255.0; // 初始值（白色=不变）

    // 模拟rand()%30个噪点块
    int noiseCount = int(mod(random(vec2(seed, 0.0)) * 1000.0, 30.0));

    for (int i = 0; i < 30; i++) {
        if (i >= noiseCount) break;

        // 随机位置和模板
        float randSeed = seed * 100.0 + float(i);
        vec2 noisePos = vec2(
            mod(random(vec2(randSeed, 1.0)) * 1000.0, 1014.0), // 0-1013
            mod(random(vec2(randSeed, 2.0)) * 1000.0, 758.0)   // 0-757
        );
        int templateIdx = int(mod(random(vec2(randSeed, 3.0)) * 1000.0, 6.0));

        // 检查当前像素是否在这个10x10块内
        vec2 offset = canvasCoord - noisePos;
        if (offset.x >= 0.0 && offset.x < 10.0 && offset.y >= 0.0 && offset.y < 10.0) {
            int blockX = int(offset.x);
            int blockY = int(offset.y);
            noiseValue = min(noiseValue, getNoiseValue(templateIdx, blockY, blockX));
        }
    }

    // 缩放后应用&=位运算（转换到0-1）
    noiseValue = noiseValue / 255.0;
    color = color * noiseValue; // 模拟 &= 的变暗效果

    // 2. 白色竖线（(原值 & 模板) + 30）
    // rand()%5条线，宽度1-3像素
    int lineCount = int(mod(random(vec2(seed, 10.0)) * 1000.0, 5.0));

    // 转换到实际分辨率
    vec2 screenCoord = uv * iResolution.xy;

    for (int i = 0; i < 5; i++) {
        if (i >= lineCount) break;

        float lineSeed = seed * 200.0 + float(i) * 10.0;
        float lineX = mod(random(vec2(lineSeed, 1.0)) * 1000.0, max(1.0, iResolution.x - 10.0));
        int lineWidth = 1 + int(mod(random(vec2(lineSeed, 2.0)) * 1000.0, 3.0)); // 1-3

        // 检查当前像素是否在线条范围内
        float distToLine = abs(screenCoord.x - lineX);
        if (distToLine < float(lineWidth)) {
            int x = int(distToLine);
            x = clamp(x, 0, min(lineWidth - 1, 3)); // 确保在有效范围

            // C++代码中k始终为0（没有递增逻辑），所以我们也固定使用k=0
            int k = 0;

            // 特殊算法: (原值 & 线条值) + 30
            float lineValue = getLineValue(k, x) / 255.0;

            vec3 afterAnd = color * lineValue; // 模拟 & 运算
            color = min(vec3(1.0), afterAnd + vec3(30.0 / 255.0)); // +30并限制在0-1
        }
    }

    return clamp(color, 0.0, 1.0);
}

vec4 FUNCNAME(vec2 tc) {
    // 1. 获取alpha参数（0-100 → 0.0-1.0）
    float alpha = float(PREFIX(alpha)) / 100.0;

    // 2. 采样输入图像
    vec4 color = INPUT1(tc);

    // 3. 保存原始颜色（用于混合）
    vec3 originalColor = color.rgb;

