    vec3 lutColor = apply70sLUT(color.rgb);

    // 5. Alpha混合（在应用噪点之前）
    // 重要：OpenCL的混合逻辑是 mix(original, lut, alpha)
    vec3 blendedColor = mix(originalColor, lutColor, alpha);

    // 6. 添加胶片噪点效果（后做噪点，模拟CPU端的doAndNoise）
    // eItime = 秒数, *25.0 = 帧号 (25fps)
    float time = PREFIX(eItime) * 25.0;
