float perlinNoise(vec2 uv, vec2 seed, vec2 resolution){
  vec2 prop = resolution.xy / min(resolution.x, resolution.y);
  vec2 i = floor(uv * prop * 6.0);
  vec2 f = fract(uv * prop * 6.0);

  vec2 offset = vec2(0.0, 1.0);
  vec2 a = hash22(i, seed);
  vec2 b = hash22(i + offset.yx, seed);
  vec2 c = hash22(i + offset.xy, seed);
  vec2 d = hash22(i + offset.yy, seed);

  vec2 u = smoothstep(vec2(0.0), vec2(1.0), f);
  float ret = mix(mix(dot(a, f), dot(b, f - offset.yx), u.x), mix(dot(c, f - offset.xy), dot(d, f - offset.yy), u.x), u.y);
  return smoothstep(-1.0, 1.0, ret);
}

float FBMnoise(vec2 uv, float scaleVal, float randVal, vec2 resolution) {
  vec2 seed = vec2(1.0, 1.0 + randVal);
  float sum = perlinNoise(uv, seed, resolution);
  vec2 tc = (uv - vec2(0.5)) * scaleVal + vec2(0.5);
  sum += perlinNoise(tc, seed, resolution);
  sum = clamp(sum / 2.0, 0.0, 1.0);
  return sum;
}

