// BlueSkies 蓝天特效 - OpenGL版本 (纹理优化版)
// 原OpenCL kernel: filter_BlueSkies (filter1.cl)
// 算法：使用LUT纹理实现蓝天色调效果
//
// LUT纹理布局:
//   INPUT1 = 视频源 (SetInputFilterData)
//   INPUT2 = t.png (占位, TEXTURES[0])
//   INPUT3 = blueskies_lut.png (256×1 RGB, TEXTURES[1])
//
// blueskies_lut.png 存储: R=BlueTearB(BlueLUT), G=BlueTearG, B=BlueTearR(RedLUT)
// 引擎BGR加载后采样: .r=BlueTearR(RedLUT), .g=BlueTearG, .b=BlueTearB(BlueLUT)

vec4 FUNCNAME(vec2 tc) {
    // 1. 获取alpha参数（0-100 → 0.0-1.0）
    float alpha = float(PREFIX(alpha)) / 100.0;

    // 2. 采样原图
    vec4 originalColor = INPUT1(tc);

    // 3. 通过LUT纹理查表
    // INPUT1是BGR: .r=Blue .g=Green .b=Red
    float u_r = (floor(originalColor.r * 255.0 + 0.5) + 0.5) / 256.0;
    float u_g = (floor(originalColor.g * 255.0 + 0.5) + 0.5) / 256.0;
    float u_b = (floor(originalColor.b * 255.0 + 0.5) + 0.5) / 256.0;

    // 通道映射:
    // .r = Blue通道 → 查BlueTearB → 引擎加载后在 .b
    // .g = Green通道 → 查BlueTearG → 引擎加载后在 .g
    // .b = Red通道 → 查BlueTearR → 引擎加载后在 .r
    vec3 lutColor;
    lutColor.r = INPUT3(vec2(u_r, 0.5)).b;  // Blue通道 → BlueTearB(.b)
    lutColor.g = INPUT3(vec2(u_g, 0.5)).g;  // Green通道 → BlueTearG(.g)
    lutColor.b = INPUT3(vec2(u_b, 0.5)).r;  // Red通道 → BlueTearR(.r)

    // 4. Alpha混合：控制效果强度
    vec3 finalColor = mix(originalColor.rgb, lutColor, alpha);

    // 5. 预乘alpha（与OpenCL一致）
    return vec4(finalColor * originalColor.a, originalColor.a);
}

