#define MAKE_GREY(b, g, r) ((29.0 * (b) + 150.0 * (g) + 76.0 * (r) + 255.0) / 256.0)

float ChannelBlend_SoftLight(float B, float L) {
    if (L < 128.0) {
        return (2.0 * ((B / 2.0) + 64.0) * L) / 255.0;
    } else {
        return 255.0 - (2.0 * (255.0 - ((B / 2.0) + 64.0)) * (255.0 - L)) / 255.0;
    }
}


