	vec4 orig = INPUT(tc);
	vec2 scaleFragCoord = tc*iResolution.xy; 

	//declare stuff
	const int mSize = 5;
	const int kSize = (mSize-1)/2;
	float kernel[mSize];
	vec3 final_colour = vec3(0.0);
	vec3 col;
	vec2 offset;
	float ns;

	//create the 1-D kernel
	float sigma = 7.0;
	float Z = 0.0;

	for (int j = 0; j <= kSize; ++j)
	{
		kernel[kSize+j] = kernel[kSize-j] = normpdf(float(j), sigma);
	}

	//get the normalization factor (as the gaussian has been clamped)
	for (int j = 0; j < mSize; ++j)
	{
		Z += kernel[j];
	}

	//read out the texels
    for (int i=-kSize; i <= kSize; ++i)
    {
        for (int j=-kSize; j <= kSize; ++j)
        {
            offset = (scaleFragCoord.xy+vec2(float(i)*iResolution.x/1280.0,float(j)*iResolution.y/640.0)) / iResolution.xy;
            col = INPUT(offset).rgb;
            ns = noise(  offset*(PREFIX(global_time) + 100.) ) * 0.38;
            col = col * 0.68 + vec3(ns,ns,ns);
            final_colour += kernel[kSize+j]*kernel[kSize+i]*col.bbb;

        }
    }

	 int alpha = PREFIX(alpha); 
	 vec4 mapped = vec4(final_colour/(Z*Z), 1.0);
     return mix( vec4(mapped.rgb, orig.a), orig, 1.0 - float(alpha)/100.0);	
}

