// Cartoon 特效 - LUT纹理查表优化版
// 原始版本：每像素循环97次调色板搜索 → 优化为单次纹理采样
// LUT纹理布局: 128x256, linearIdx = (r5<<10) + (g5<<5) + b5
// LUT预计算了原始shader的完整映射（含CL兼容的BGR交换逻辑）

vec4 FUNCNAME(vec2 tc) {
    // 1. 获取alpha参数（0-100 → 0.0-1.0）
    float factor = float(PREFIX(alpha)) / 100.0;

    // 2. 采样原图
    vec4 originalColor = INPUT1(tc);

    // 3. 量化到5位 (32级) - 逐分量转换避免CL编译器float3→int3强转报错
    int r255 = int(originalColor.r * 255.0);
    int g255 = int(originalColor.g * 255.0);
    int b255 = int(originalColor.b * 255.0);
    int r5 = clamp(r255 >> 3, 0, 31);
    int g5 = clamp(g255 >> 3, 0, 31);
    int b5 = clamp(b255 >> 3, 0, 31);

    // 4. 计算LUT纹理坐标
    int linearIdx = (r5 << 10) + (g5 << 5) + b5;
    int row = linearIdx / 128;
    int col = linearIdx - row * 128;
    float tableU = (float(col) + 0.5) / 128.0;
    float tableV = (float(row) + 0.5) / 256.0;

    // 5. 单次纹理采样（引擎加载纹理为BGR，需交换R↔B）
    vec4 tableColor = INPUT2(vec2(tableU, tableV));
    vec3 cartoonRGB = tableColor.bgr;

    // 6. Alpha混合
    vec3 finalColor = mix(originalColor.rgb, cartoonRGB, factor);

    return vec4(finalColor, originalColor.a);
}

