	scaleRandX = decay(scaleRandX, process, InOutStage );
	ScaleX = scaleRandX.x;

	scaleRandY =  vec2( (scaleRandY.x + peak)*(ScaleYUp + ScaleYDown)/(2.0*peak) - ScaleYDown,  scaleRandY.x* (ScaleXUp + ScaleXDown)/(2.0*peak) );
