			accumRGB.g += s2.g * s2.a;
			accumRGB.b += s3.b * s3.a;
		}
		float invSamples = 1.0/float(samples);
		outCol.a = accumA * invSamples;
		outCol.rgb = accumRGB * invSamples / max(outCol.a, 1e-5);
