#define SQRT3 1.732050807
#define PI 3.141592653


vec2 hexCenter(vec2 id, float odd)
{
	return vec2(
		SQRT3 * R * (id.x +0.5*odd),
		1.5 * id.y * R
		);
}
vec4 FUNCNAME(vec2 tc) 
