float WS_DoOverlayPerChannel(float baseVal, float blendVal)
{
    float result;

    if(baseVal < 0.5)
    {
        result = 2.0 * baseVal * blendVal;
    }
    else
        result = 1.0 - 2.0 * (1.0 - baseVal) * (1.0 - blendVal);

    return result;
}

float normpdf(in float x, in float sigma)
{
	return (0.39894 * exp(-0.5 * x * x / (sigma * sigma)) / sigma);
}


vec4 FUNCNAME(vec2 tc) 
{
    int alpha = PREFIX(alpha); 
    vec4 tuneColor = INPUT1(tc);
	vec4 orig = tuneColor;
    vec4 blendColor = tuneColor;

	const int kernel_size = 11;
	const int half_size = (kernel_size - 1) / 2;
	float kernel[kernel_size];
	vec4 blurColor = vec4(0.0);

	float sigma = 7.0;
	float weight_sum = 0.0;
	for (int j = 0; j <= half_size; ++j)
	{
		kernel[half_size + j] = kernel[half_size - j] = normpdf(float(j), sigma);
	}

	for (int j = 0; j < kernel_size; ++j)
	{
		weight_sum += kernel[j];
	}

	for (int i=-half_size; i <= half_size; ++i)
	{
		for (int j=-half_size; j <= half_size; ++j)
		{
			blurColor += kernel[half_size + j] * kernel[half_size + i] * INPUT1(tc + (vec2(float(i),float(j))) / iResolution.xy);
		}
	}

	blurColor = blurColor / (weight_sum * weight_sum);

    tuneColor.r = INPUT2(vec2(blurColor.r, .16666)).r;
	tuneColor.g = INPUT2(vec2(blurColor.g, .5)).g;
	tuneColor.b = INPUT2(vec2(blurColor.b, .83333)).b;

    tuneColor.r = WS_DoOverlayPerChannel(tuneColor.r, blendColor.r);
    tuneColor.g = WS_DoOverlayPerChannel(tuneColor.g, blendColor.g); 
    tuneColor.b = WS_DoOverlayPerChannel(tuneColor.b, blendColor.b); 

    tuneColor.r = INPUT2(vec2(tuneColor.r, .16666)).r;
	tuneColor.g = INPUT2(vec2(tuneColor.g, .5)).g;
	tuneColor.b = INPUT2(vec2(tuneColor.b, .83333)).b;	

	return mix(orig,tuneColor,float(alpha)/100.0);
}

// GetColor Fragment Shader - OpenGL版本 (v5)
// 功能：根据色相范围保留特定颜色，其他颜色转换为灰度
//
// 参数含义（与原版完全一致）:
// - DecolorPosX (0~100): 取色位置X坐标
// - DecolorPosY (0~100): 取色位置Y坐标
// - radius (0~100): 色相容差范围
// - alpha (0~100): 去色强度
//
// 优化点:
// - 色相向量点积法替代角度计算，消除除法精度问题
// - smoothstep 柔和过渡，消除硬切边界
// - 所有中间值 ≤ 1.0，mediump 完全安全

// 从RGB计算色相向量 (投影到色轮2D平面)
// 返回向量，长度 ≈ 色彩饱和度
// 中间值范围: hx ∈ [-0.75, 1.0], hy ∈ [-0.866, 0.866]，mediump安全
vec2 rgbToHueVec(vec3 c) {
    return vec2(
        c.r - 0.5 * (c.g + c.b),
        0.866 * (c.g - c.b)
    );
}

vec4 FUNCNAME(vec2 tc) {
    // ===== 参数（含义与原版完全一致）=====
    float decolorPosX = float(PREFIX(DecolorPosX)) / 100.0;
    float decolorPosY = float(PREFIX(DecolorPosY)) / 100.0;
    float radius = float(PREFIX(radius)) / 100.0;
    float alpha = float(PREFIX(alpha)) / 100.0;

    // ===== 采样原图 =====
    vec4 color = INPUT(tc);
    float grayValue = dot(color.rgb, vec3(0.299, 0.587, 0.114));

    // ===== 采样点击位置颜色 =====
    vec2 clickPos = vec2(decolorPosX, 1.0 - decolorPosY);
    vec3 clickColor = INPUT(clickPos).rgb;

    // ===== 计算色相向量 =====
    vec2 curVec = rgbToHueVec(color.rgb);
    vec2 clickVec = rgbToHueVec(clickColor);

    float curLen = length(curVec);
    float clickLen = length(clickVec);

    // ===== 色相匹配 =====
    vec3 finalColor;

    // 饱和度阈值: 低于此值视为灰色
    float satThreshold = 0.05;

    if (clickLen < satThreshold) {
        // 点击位置是灰色 → 全图去色
        finalColor = mix(color.rgb, vec3(grayValue), alpha);
    } else if (curLen < satThreshold) {
        // 当前像素本身就是灰色 → 去色
        finalColor = mix(color.rgb, vec3(grayValue), alpha);
    } else {
        // 两者都有颜色: 用点积计算色相相似度
        // cosAngle = dot(a,b) / (|a|*|b|)，范围 [-1, 1]
        // 1.0 = 色相完全一致，-1.0 = 互补色
        float cosAngle = dot(curVec, clickVec) / (curLen * clickLen);

        // radius 映射到余弦阈值:
        // radius=0   → cosThreshold=1.0  (只保留完全一致)
        // radius=50  → cosThreshold=0.0  (保留半个色环)
        // radius=100 → cosThreshold=-1.0 (保留所有颜色)
        float cosThreshold = 1.0 - radius * 2.0;

        // smoothstep 柔和过渡 (过渡带宽度0.15)
        float edge0 = cosThreshold - 0.15;
        float edge1 = cosThreshold + 0.15;
        // cosAngle > edge1 → keepColor=1 (保留)
        // cosAngle < edge0 → keepColor=0 (去色)
        float keepColor = smoothstep(edge0, edge1, cosAngle);

        vec3 decolored = mix(color.rgb, vec3(grayValue), alpha);
        finalColor = mix(decolored, color.rgb, keepColor);
    }

    return vec4(finalColor, color.a);
}

