//Holiday Fragment Shader (纹理优化版)
// LUT纹理布局:
//   INPUT  = 视频源 (SetInputFilterData, 无额外纹理时默认)
//   INPUT2 = t.png  (占位, TEXTURES[0])
//   INPUT3 = holiday_lut.png (256×1 RGB, TEXTURES[1])
//
// holiday_lut.png 存储: R=BlueLUT, G=GreenLUT, B=RedLUT
// 引擎BGR加载后采样: .r=RedLUT, .g=GreenLUT, .b=BlueLUT

vec4 FUNCNAME(vec2 tc)
{
    vec4 color = INPUT1(tc);

    // BGR format: color.r = blue, color.g = green, color.b = red
    // 用通道值直接查LUT纹理 (256×1)
    float u_b = (color.r * 255.0 + 0.5) / 256.0;  // blue index
    float u_g = (color.g * 255.0 + 0.5) / 256.0;  // green index
    float u_r = (color.b * 255.0 + 0.5) / 256.0;  // red index

    // 引擎BGR: .b采样=BlueLUT, .g采样=GreenLUT, .r采样=RedLUT
    vec3 mapped;
    mapped.r = INPUT3(vec2(u_b, 0.5)).b;  // Blue通道查BlueLUT
    mapped.g = INPUT3(vec2(u_g, 0.5)).g;  // Green通道查GreenLUT
    mapped.b = INPUT3(vec2(u_r, 0.5)).r;  // Red通道查RedLUT

    // Apply alpha blending
    float alpha = float(PREFIX(alpha)) / 100.0;
    vec3 finalColor = mix(color.rgb, mapped, alpha); 

    return vec4(finalColor * color.a, color.a);
}

