			temp1 = abs(uv + float(i+1) / float(samples)*totalDir*blurAmp + vec2(0.0));
            temp1 = step(temp1,ttwo) * (2.0*ttwo - 2.0*temp1) + temp1;     

			temp2 = abs(uv + float(i+1) / float(samples)*totalDir*blurAmp + processColorSp)+ RGB_offset;
            temp2 = step(temp2,ttwo) * (2.0*ttwo - 2.0*temp2) + temp2;  

			temp3 = abs(uv + float(i+1) / float(samples)*totalDir*blurAmp + processColorSp)+ RGB_offset;
            temp3 = step(temp3,ttwo) * (2.0*ttwo - 2.0*temp3) + temp3;     		
			color.ra += INPUT(temp1).ra;
			color.g += INPUT(temp2).g;
			color.b += INPUT(temp3).b;	
		}
		outCol = color/float(samples);
	}else
	{
		temp1 = abs(uv + 1.0 / float(samples)*totalDir*blurAmp + vec2(0.0)); 
        temp1 = step(temp1,ttwo) * (2.0*ttwo - 2.0*temp1) + temp1;        
        //temp1 = step(roiXY,temp1) * (2.0*roiXY - temp1 - ttwo - temp1) + temp1;
        //temp1 = step(mirror,temp1)*mirror*2.0f - temp1 + ttwo;
		temp2 = abs(uv + 1.0 / float(samples)*totalDir*blurAmp + vec2(processColorSp)) + RGB_offset;
        temp2 = step(temp2,ttwo) * (2.0*ttwo - 2.0*temp2) + temp2;        

		temp3 = abs(uv + 1.0 / float(samples)*totalDir*blurAmp + vec2(processColorSp)) + RGB_offset;
        temp3 = step(temp3,ttwo) * (2.0*ttwo - 2.0*temp3) + temp3;        


		color.ra += INPUT(temp1).ra;
		color.g += INPUT(temp2).g;
		color.b += INPUT(temp3).b;	 

		outCol = color;
	}
    outCol.rgb *= outCol.a;
	return outCol;
}

