     texel = vec3(
                  INPUT2(vec2(texel.r, .16666)).r,
                  INPUT2(vec2(texel.g, .5)).g,
                  INPUT2(vec2(texel.b, .83333)).b);
     texel.rgb = texel.rgb * orig.a;
     return mix(vec4(texel, orig.a), orig, 1.0 - alpha/100.0);
}

/*{
	"GUID":"53D37319-8F37-4593-BBAF-9FF0A6307C01",
