float Sample(vec2 uv, vec2 offset)
{
	float factor = iResolution.y / 433.0;
    vec4 color = INPUT(uv + (offset / iResolution.xy) * factor);
    return dot(color.rgb, vec3(0.114, 0.587, 0.299));
}

vec2 SobelFilter(vec2 uv)
{
    float tl = Sample(uv, vec2(-1.0, 1.0));
    float tc = Sample(uv, vec2(0.0, 1.0));
    float tr = Sample(uv, vec2(1.0, 1.0));

    float l = Sample(uv, vec2(-1.0, 0.0));
    float c = Sample(uv, vec2(0.0, 0.0));
    float r = Sample(uv, vec2(1.0, 0.0));

    float bl = Sample(uv, vec2(-1.0, -1.0));
    float bc = Sample(uv, vec2(0.0, -1.0));
    float br = Sample(uv, vec2(1.0, -1.0));

    float gx = tl - tr + 2.0 * l - 2.0 * r + bl - br;
    float gy = -tl - 2.0 * tc - tr + bl + 2.0 * bc + br;

    return vec2(gx, gy);
}

vec4 FUNCNAME(vec2 tc)
{    
	vec4 orig = INPUT(tc);

	int color = PREFIX(color); 
	int red = (color >> 16) & 0xff;
	int green = (color >> 8) & 0xff;
	int blue = color & 0xff;

    vec2 sobelFilter = SobelFilter(tc);
    float gradient = sobelFilter.x * sobelFilter.x + sobelFilter.y * sobelFilter.y;

	vec3 inputColor = vec3(float(blue), float(green), float(red)) / 255.0;

	inputColor.rgb = step(0.0000001, inputColor.r + inputColor.g + inputColor.b) * (inputColor.rgb - vec3(-0.2)) + vec3(-0.2);

	vec4 retColor = vec4(0.0);
	retColor.rgb = orig.rgb + inputColor.rgb * gradient;
	retColor.rgb = clamp(retColor.rgb, 0.0, 1.0);
	retColor = mix(orig,retColor,float(PREFIX(alpha))/100.0);
	retColor.a = orig.a;

	return retColor;
}

float distLine(vec2 p, vec2 a, vec2 b) {
	vec2 ap = p - a;
    vec2 ab = b - a;
    float aDotB = clamp(dot(ap, ab) / dot(ab, ab), 0.0, 1.0);
    return length(ap - ab * aDotB);
}

float drawLine(vec2 uv, vec2 a, vec2 b) {
    float line = smoothstep(0.014, 0.01, distLine(uv, a, b));
    float dist = length(b-a);
    return line * (smoothstep(1.3, 0.8, dist) * 0.5 + smoothstep(0.04, 0.03, abs(dist - 0.75)));
}

float n21(vec2 i) {
    i += fract(i * vec2(223.64, 823.12));
    i += dot(i, i + 23.14);
    return fract(i.x * i.y);
}

vec2 n22(vec2 i) {
    float x = n21(i);
    return vec2(x, n21(i+x));
}

vec2 getPoint(vec2 id, vec2 offset,float iGlobalTime) {
	return offset + sin(n22(id + offset) * iGlobalTime) * 0.4;
}

float layer (vec2 uv,float iGlobalTime) {
    float m = 0.0;
    float t = iGlobalTime * 2.0;

    vec2 gv = fract(uv) - 0.5;
    vec2 id = floor(uv) - 0.5;

    vec2 p[9];
    int i = 0;
    for (float y = -1.0; y <= 1.0; y++) {
        for (float x = -1.0; x <= 1.0; x++) {
        	p[i++] = getPoint(id, vec2(x,y),iGlobalTime);
        }
    }

    for (int i = 0; i < 9; i++) {
    	m += drawLine(gv, p[4], p[i]);
        float sparkle = 1.0 / pow(length(gv - p[i]), 1.5) * 0.005;
        m += sparkle * (sin(t + fract(p[i].x) * 12.23) * 0.4 + 0.6);
    }

    m += drawLine(gv, p[1], p[3]);
    m += drawLine(gv, p[1], p[5]);
    m += drawLine(gv, p[7], p[3]);
    m += drawLine(gv, p[7], p[5]);

    return m;
}

vec4 screen(vec4 base, vec4 blend)
{
    vec4 white = vec4(1.0);
    vec4 result = white - ((white - blend) * (white - base));
    return result;
}

vec4 FUNCNAME(vec2 tc)
{    
	vec4 orig = INPUT(tc);
    int alpha = PREFIX(alpha); 
    float iGlobalTime = PREFIX(global_time);

    vec2 uv = tc - vec2(0.5);
	uv.x *= iResolution.x / iResolution.y;

    vec3 vary = sin(iGlobalTime * 2.0 * vec3(.234, .324,.768)) * 0.4 + 0.6;

    vec4 retColor = vec4(0.0);
    float rand = INPUT(vec2(0.5, 0.5)).x;
    vary.x += (uv.x + 0.5);
    retColor.rgb += pow(-uv.y + 0.5, 5.0) * rand * vary;

    float m = 0.0;
    float x = sin(iGlobalTime * 0.1);
    float y = cos(iGlobalTime * 0.2);

    mat2 rotMat = mat2(x, y, -y, x);
    uv *= rotMat;

    for (float i = 0.0; i <= 1.0; i+= 1.0/4.0) {
        float z = fract(i + iGlobalTime * 0.05);
        float size = mix(15.0, .1, z) * 1.50;
        float fade = smoothstep(0.0, 1.0, z) * smoothstep(1.0, 0.9, z);
        m += layer((size * uv) + i * 10.0 ,iGlobalTime) * fade;
    }

    retColor.rgb += m * vary;
	retColor.rgb = clamp(retColor.rgb, 0.0, 1.0);
	retColor = screen(orig,retColor);
	retColor.w = orig.w;
	retColor.xyz *= retColor.w;

	return mix(orig,retColor,float(alpha)/100.0);
}

//Purple Haze Fragment Shader (纹理优化版)
// LUT纹理布局:
//   INPUT1 = 视频源 (SetInputFilterData)
//   INPUT2 = t.png  (占位, TEXTURES[0])
//   INPUT3 = purplehaze_lut.png (256×1 RGB, TEXTURES[1])
