// RadioExplikeFX Fragment Shader - OpenGL版本
// 功能：径向光爆效果，使用混合模式查找表

// 混合模式查找函数（替代256x256查找表）
// OpenCL: table[(原图 << 8) + 纹理]
// 参数：original = 原图颜色值，texture = 纹理颜色值
float blendLookup(float original, float texture) {
    // OpenCL查找表的算法：
    // i = 原图 (第一个索引), j = 纹理 (第二个索引)
    // 当原图 < 128: result = (原图 * 纹理 + 127) >> 7
    // 当原图 >= 128: result = 255 - (((255-原图)*(255-纹理) + 127) >> 7)

    if (original < 0.5) {
        // 前半部分：(原图 * 纹理) / 128 + 四舍五入
        return (original * texture * 2.0);
    } else {
        // 后半部分：Screen混合模式
        // 255 - ((255-原图)*(255-纹理))/128
        // = 1 - (1-原图)*(1-纹理)*2
        return 1.0 - ((1.0 - original) * (1.0 - texture) * 2.0);
    }
}

vec4 FUNCNAME(vec2 tc) {
    // 获取参数
    float alpha = float(PREFIX(alpha)) / 100.0;

    // 读取原图（前景）
    vec4 srcColor = INPUT1(tc);

    // 读取径向纹理（merge图层，用于光爆效果）
    vec4 mergeColor = INPUT2(vec2(tc.x, 1.0-tc.y));

    // 对每个通道应用混合查找表
    // 注意：第一个参数是原图，第二个参数是纹理（与CL中table[原图*256+纹理]对应）
    vec3 blended;
    blended.r = blendLookup(srcColor.r, mergeColor.r);
    blended.g = blendLookup(srcColor.g, mergeColor.g);
    blended.b = blendLookup(srcColor.b, mergeColor.b);

    // 根据alpha参数混合原图和效果图
    vec3 finalColor = mix(srcColor.rgb, blended, alpha);

    return vec4(finalColor, srcColor.a);
}

