// Rise 滤镜 - OpenGL版本
// 原OpenCL: filter_Rise (filter2.cl)
// 转换日期: 2026-01-29
// 效果：Rise风格滤镜 - 灰度+对比度+暖色调映射

// ============================================================
// 常量定义（从C++代码提取）
// ============================================================

// iPercent = 5, deta = 35 (固定值)
#define I_PERCENT 5
#define DETA 35
#define AM_PI 3.1415926

// ============================================================
// g_pixel_table768 数据
// 结构：[0-255]=0, [256-511]=0-255, [512-767]=255
// g_pixel_table_start = g_pixel_table768 + 256
// 所以 g_pixel_table_start[i] 实际上是 clamp(i, 0, 255)
// ============================================================

// 简化实现：直接用clamp替代table查找
float getPixelTable(int idx) {
    // g_pixel_table_start 偏移256开始
    // [0-255] -> 0-255 (直接映射)
    // [-256, -1] -> 0 (下溢为0)
    // [256, 511] -> 255 (上溢为255)
    return float(clamp(idx, 0, 255));
}

// ============================================================
// calTableValue - 对比度增强函数
// 原C++代码：
// float aPercent = 1.0f + 0.005f * LIMIT_VALUE(iPercent, 0, 100);
// float angle = aPercent * AmPI * (x - 128) / 256;
// angle = LIMIT_VALUE(angle, -AmPI/2, AmPI/2);
// return (uchar)(128 + 128 * sin(angle));
// ============================================================

float calTableValue(float x, int iPercent) {
    float aPercent = 1.0 + 0.005 * float(clamp(iPercent, 0, 100));
    float angle = aPercent * AM_PI * (x - 128.0) / 256.0;
    angle = clamp(angle, -AM_PI / 2.0, AM_PI / 2.0);
    return 128.0 + 128.0 * sin(angle);
}

// ============================================================
// RGB to Gray 转换系数
// g_R_306_1[i] = i * 306
// g_G_601_1[i] = i * 601
// g_B_117_1[i] = i * 117
// gray = (R*306 + G*601 + B*117 + 512) >> 10
// ============================================================

float rgb2Gray(float r, float g, float b) {
    // 转换为0-255
    float ri = r * 255.0;
    float gi = g * 255.0;
    float bi = b * 255.0;

    // 加权灰度计算 (约等于 0.299R + 0.587G + 0.114B)
    float gray = (ri * 306.0 + gi * 601.0 + bi * 117.0 + 512.0) / 1024.0;
    return clamp(gray, 0.0, 255.0);
}

// ============================================================
// 主滤镜函数
// ============================================================

vec3 applyRiseLUT(vec3 color, float factor) {
    // ⚠️ 通道对调修正：OpenCV BGRA → OpenCL RGBA读取
    // color.r 实际是 B，color.b 实际是 R
    float sr = color.b * 255.0;  // 实际Red
    float sg = color.g * 255.0;  // 实际Green
    float sb = color.r * 255.0;  // 实际Blue

    // 1. 计算灰度
    float gray = rgb2Gray(sr/255.0, sg/255.0, sb/255.0);

    // 2. 对比度增强 (iPercent = 5)
    gray = calTableValue(gray, I_PERCENT);

    // 3. 颜色映射
    // b = gray
    // g = table[gray + deta]  (deta = 35)
    // r = table[gray + deta + 6]
    float newB = gray;
    float newG = getPixelTable(int(gray) + DETA);
    float newR = getPixelTable(int(gray) + DETA + 6);

    // 4. Alpha混合
    newB = newB * factor + sb * (1.0 - factor);
    newG = newG * factor + sg * (1.0 - factor);
    newR = newR * factor + sr * (1.0 - factor);

    // 5. 返回（注意：输出时要交换回来）
    // 因为输入时r实际是b，所以输出时也要保持一致
    return vec3(newB / 255.0, newG / 255.0, newR / 255.0);
}

// ============================================================
// 主函数
// ============================================================

vec4 FUNCNAME(vec2 tc) {
    // 读取原图
    vec4 color = INPUT1(tc);

    // 获取alpha参数 (0-100)
    float alpha = float(PREFIX(alpha));
    float factor = alpha / 100.0;

    // 应用Rise滤镜
    vec3 riseColor = applyRiseLUT(color.rgb, factor);

    // 预乘alpha输出
    return vec4(riseColor * color.a, color.a);
}

