// 引擎BGR加载后采样: .r=VioletB(RedLUT), .g=VioletG, .b=VioletR(BlueLUT)

vec4 FUNCNAME(vec2 tc)
{
    // 获取原始颜色
    vec4 color = INPUT1(tc);

    // 获取叠加纹理颜色 (dark.png)
    vec4 merge = INPUT2(tc);

    // 乘法混合 (与叠加纹理) - 在0~1空间直接计算
    // 公式: (sr * mr + 255) / 256 ≈ sr * mr / 255
    vec3 blended = (color.rgb * merge.rgb * 255.0 + 1.0) / 256.0;

    // 用混合后的值查LUT纹理
    // 通道交换: R通道用VioletB表, B通道用VioletR表
    float u_r = (blended.r * 255.0 + 0.5) / 256.0;
    float u_g = (blended.g * 255.0 + 0.5) / 256.0;
    float u_b = (blended.b * 255.0 + 0.5) / 256.0;

    // 引擎BGR: .r=VioletB(RedLUT), .g=VioletG, .b=VioletR(BlueLUT)
    vec3 mapped;
    mapped.r = INPUT3(vec2(u_r, 0.5)).r;  // R通道用VioletB(RedLUT)
    mapped.g = INPUT3(vec2(u_g, 0.5)).g;  // G通道用VioletG
    mapped.b = INPUT3(vec2(u_b, 0.5)).b;  // B通道用VioletR(BlueLUT)

    // 根据alpha混合
    float factor = float(PREFIX(alpha)) / 100.0;
    vec4 result = vec4(mix(color.rgb, mapped, factor), color.a);

    return result;
}

