    float ntop1 = (top1.b + top1.g + top1.g + top1.r) / 4.0;
    float ntop2 = (top2.b + top2.g + top2.g + top2.r) / 4.0;

    vec4 mid0 = INPUT(vec2(fragCoord.x, fragCoord.y)/iResolution.xy) * 255.0;
    vec4 mid1 = INPUT(vec2(fragCoord.x + 1.0, fragCoord.y)/iResolution.xy) * 255.0;
    vec4 mid2 = INPUT(vec2(fragCoord.x + 2.0, fragCoord.y)/iResolution.xy) * 255.0;

    float nmid0 = (mid0.b + mid0.g + mid0.g + mid0.r) / 4.0;
    float nmid1 = (mid1.b + mid1.g + mid1.g + mid1.r) / 4.0;
    float nmid2 = (mid2.b + mid2.g + mid2.g + mid2.r) / 4.0;

    vec4 bom0 = INPUT(vec2(fragCoord.x, fragCoord.y - 1.0)/iResolution.xy) * 255.0;
    vec4 bom1 = INPUT(vec2(fragCoord.x + 1.0, fragCoord.y - 1.0)/iResolution.xy) * 255.0;
    vec4 bom2 = INPUT(vec2(fragCoord.x + 2.0, fragCoord.y - 1.0)/iResolution.xy) * 255.0;

    float nbom0 = (bom0.b + bom0.g + bom0.g + bom0.r) / 4.0;
    float nbom1 = (bom1.b + bom1.g + bom1.g + bom1.r) / 4.0;
    float nbom2 = (bom2.b + bom2.g + bom2.g + bom2.r) / 4.0;

    // 求三个最大值 (原AmMAX3宏)
    float value1 = max(max(ntop0, ntop1), ntop2);
    float value2 = max(max(nmid0, nmid1), nmid2);
