    // 获取原始颜色
    vec4 color = INPUT1(tc);

    // 加法混合并限制 (clip_byte等效于clamp到0-255)
    // CL: index = (merge + color) * 255, result = clip[index] / 255
    // 简化为: result = clamp(merge + color, 0, 1)
    float r = clamp(merge.r + color.r, 0.0, 1.0);
    float g = clamp(merge.g + color.g, 0.0, 1.0);
    float b = clamp(merge.b + color.b, 0.0, 1.0);

    vec4 result = vec4(r, g, b, color.a);
    result.rgb *= result.a;

    // 根据alpha混合
    float factor = float(PREFIX(alpha)) / 100.0;
    result = result * factor + color * (1.0 - factor);

    return result;
}

