// SimpleElegent Effect - 简约优雅特效
// 将原图与灰度图按比例混合，产生去饱和效果
// 混合比例 en = 0.48 (约48%灰度 + 52%原色)

vec4 FUNCNAME(vec2 tc)
{
    // 获取原始颜色
    vec4 color = INPUT(tc);

    // 转换为0-255整数
    int sr = int(color.r * 255.0);
    int sg = int(color.g * 255.0);
    int sb = int(color.b * 255.0);

    // 计算灰度值 (使用标准灰度权重: R*306 + G*601 + B*117)
    // gray = (R*306 + G*601 + B*117 + 512) >> 10
    int gray = (sr * 306 + sg * 601 + sb * 117 + 512) / 1024;

    // 混合参数 en = 0.48 * 256 = 123
    int en = 123;
    int de = 256 - en;  // de = 133
    int newgray = gray * en;

    // 混合灰度和原色: result = (original * de + gray * en) >> 8
    int r = (sr * de + newgray) / 256;
    int g = (sg * de + newgray) / 256;
    int b = (sb * de + newgray) / 256;

    // 限制范围 (等效于 g_pixel_table_start)
    r = clamp(r, 0, 255);
    g = clamp(g, 0, 255);
    b = clamp(b, 0, 255);

    vec4 result = vec4(float(r) / 255.0, float(g) / 255.0, float(b) / 255.0, color.a);

    // 根据alpha混合
    float factor = float(PREFIX(alpha)) / 100.0;
    result = result * factor + color * (1.0 - factor);

    return result;
}

