//This sketch algorithm is our own inverted method of sketch
//Sketch
vec4 FUNCNAME(vec2 tc) 
{
  vec2 kernel_offset[9];
  kernel_offset[0] = vec2(-1.0 / iResolution.x, -1.0 / iResolution.y);
  kernel_offset[1] = vec2(0.0, -1.0 / iResolution.y);
  kernel_offset[2] = vec2(1.0 / iResolution.x, -1.0 / iResolution.y);
  kernel_offset[3] = vec2(-1.0 / iResolution.x, 0.0);
  kernel_offset[4] = vec2(0.0, 0.0);
  kernel_offset[5] = vec2(1.0 / iResolution.x, 0.0);
  kernel_offset[6] = vec2(-1.0 / iResolution.x, 1.0 / iResolution.y);
  kernel_offset[7] = vec2(0.0, 1.0 / iResolution.y);
  kernel_offset[8] = vec2(1.0 / iResolution.x, 1.0 / iResolution.y);
  float alpha = float(PREFIX(alpha))/100.0;   
  vec4 tempColor;   
  float samples[9];
  float maxGray = 0.0;
  float W = iResolution.x;
  vec4 orig = INPUT(tc);
  for(int i=0; i < 9; i++)
  {
    tempColor = INPUT(tc + kernel_offset[i]);
    //samples[i] = dot(tempColor.rgb, vec3(0.114, 0.587, 0.299));
	samples[i] = (tempColor.x + tempColor.y * 2.0 + tempColor.z)/4.0; //consistent with C algorithm
    maxGray = max(samples[i], maxGray);
  }
  vec4 tuneColor = vec4(vec3(samples[4]/maxGray),1.0);
  vec4 outputCol = vec4(orig.rgb*(1.0 - alpha) + tuneColor.rgb*alpha, orig.a);
  outputCol.rgb *= outputCol.a;
  return outputCol;

}

