float parabolaInterp(float x, float cv) {
    // 模拟CL的整数LUT量化过程：
    // 1. 输入量化: (int)(x*255 + 0.5)
    // 2. 计算曲线
    // 3. 输出量化: (int)(y*255 + 0.5) / 255.0

    // 输入量化
    float xi = floor(x * 255.0 + 0.5) / 255.0;

    // C++高斯消元的实际输出:
    float a = 1.0 - 0.25 * cv;
    float b = 0.25;

    // y = a*x^2 + b*x
    float y = xi * (a * xi + b);

    // 输出量化 (模拟整数LUT)
    float result = floor(y * 255.0 + 0.5) / 255.0;
    return clamp(result, 0.0, 1.0);
}

vec4 FUNCNAME(vec2 tc) {
