    float m_dRCol = float(PREFIX(m_dRCol)) / 255.0;
    float m_dGCol = float(PREFIX(m_dGCol)) / 255.0;
    float m_dBCol = float(PREFIX(m_dBCol)) / 255.0;
    int m_bSrcLeft = PREFIX(m_bSrcLeft);
    int m_bSplit = PREFIX(m_bSplit);
    float alphaFactor = float(PREFIX(alpha)) / 100.0;

    // 读取原图
    vec4 color = INPUT(tc);

    // 分屏逻辑 - 与CL完全一致
    bool bSplit = (m_bSplit == 1);
    bool bSrcLeft = (m_bSrcLeft == 0);
    bool applyEffect = false;

    if (bSplit) {
        if (bSrcLeft && (tc.x < 0.5)) {
            applyEffect = true;
        } else if (!bSrcLeft && (tc.x >= 0.5)) {
            applyEffect = true;
        }
    }

    if (applyEffect) {
        // 调试：显示纯红色确认shader正在执行
        // return vec4(1.0, 0.0, 0.0, 1.0);

        // 直接使用color的rgb
        float r = color.r;
        float g = color.g;
        float b = color.b;
        float a = color.a;

        float r0 = parabolaInterp(b, m_dBCol);  // CL的"r"实际是B
        float g0 = parabolaInterp(g, m_dRCol);  // G通道不变
        float b0 = parabolaInterp(r, m_dGCol);  // CL的"b"实际是R

        // 输出也要交换回来 (CL写入BGR，GL写入RGB)
        float finalR = b0;  // CL的b0写到x位置，实际是R
        float finalG = g0;
        float finalB = r0;  // CL的r0写到z位置，实际是B

        // Alpha混合
        finalR = finalR * alphaFactor + r * (1.0 - alphaFactor);
        finalG = finalG * alphaFactor + g * (1.0 - alphaFactor);
        finalB = finalB * alphaFactor + b * (1.0 - alphaFactor);

        // 预乘Alpha输出
        return vec4(finalR * a, finalG * a, finalB * a, a);
    } else {
        return color;
    }
}

