// SunFlower GL Shader (纹理优化版)
// 转换自 OpenCL 版本 filter_Holiday kernel
// 效果：ZhouTian暖色调映射 (向日葵)
//
// LUT纹理布局:
//   INPUT1 = 视频源 (SetInputFilterData)
//   INPUT2 = t.png  (占位, TEXTURES[0])
//   INPUT3 = sunflower_lut.png (256×1 RGB, TEXTURES[1])
//
// sunflower_lut.png 存储: R=tableB(BlueLUT), G=tableG(GreenLUT), B=tableR(RedLUT)
// 引擎BGR加载后采样: .r=tableR(RedLUT), .g=tableG(GreenLUT), .b=tableB(BlueLUT)

vec4 FUNCNAME(vec2 tc) {
    // 获取参数
    float factor = float(PREFIX(alpha)) / 100.0;

    // 读取原图
    vec4 color = INPUT1(tc);

    // 通道交换查LUT:
    // GL的R通道 → CL的z位置(R) → 用tableB查 → .b采样
    // GL的G通道 → CL的y位置(G) → 用tableG查 → .g采样
    // GL的B通道 → CL的x位置(B) → 用tableR查 → .r采样
    // (原代码 +0.5 四舍五入，纹理采样的 +0.5 是texel center offset)
    float u_r = (floor(color.r * 255.0 + 0.5) + 0.5) / 256.0;
    float u_g = (floor(color.g * 255.0 + 0.5) + 0.5) / 256.0;
    float u_b = (floor(color.b * 255.0 + 0.5) + 0.5) / 256.0;

    vec3 mapped;
    mapped.r = INPUT3(vec2(u_r, 0.5)).b;  // R通道用tableB(BlueLUT)
    mapped.g = INPUT3(vec2(u_g, 0.5)).g;  // G通道用tableG(GreenLUT)
    mapped.b = INPUT3(vec2(u_b, 0.5)).r;  // B通道用tableR(RedLUT)

    // Alpha混合
    vec3 finalColor = mix(color.rgb, mapped, factor);

    // 预乘Alpha输出
    return vec4(finalColor * color.a, color.a);
}

