// Tunnel Effect - Pulls pixels outside radius toward center
// CL to GL conversion

vec4 FUNCNAME(vec2 tc) {
    // Get parameters (0-100 integer from conf)
    int centerXParam = PREFIX(centerX);
    int centerYParam = PREFIX(centerY);
    int radiusParam = PREFIX(radius);
    int alphaParam = PREFIX(alpha);

    // Get original color
    vec4 color = INPUT(tc);

    // 使用标准参考分辨率计算 (与SunShine一致)
    vec2 resolution =vec2(iResolution.x,iResolution.y);
    float aWidth = resolution.x;
    float aHeight = resolution.y;
    float aMinWH = min(aWidth, aHeight);

    // 计算像素坐标
    float px = tc.x * aWidth;
    float py = tc.y * aHeight;

    // 计算中心位置 (与C++一致)
    // C++: cx = centerX * width / 100; cy = (100 - centerY) * height / 100
    float cx = float(clamp(centerXParam, 0, 100)) * aWidth / 100.0;
    float cy = float(clamp(100 - centerYParam, 0, 100)) * aHeight / 100.0;

    // 计算半径 (与C++一致)
    // C++: cr = radius * min(width, height) / 200
    float cr = float(clamp(radiusParam, 2, 100)) * aMinWH / 200.0;
    float crr = cr * cr;

    // 计算距离
    float dx = px - cx;
    float dy = py - cy;
    float dss = dx * dx + dy * dy;

    vec2 newTc = tc;

    if (dss > crr) {
        // 在半径外 - 拉向中心
        // C++: i = dx * cr / ds + cx; j = dy * cr / ds + cy
        float ds = sqrt(dss);
        float newPx = dx * cr / ds + cx;
        float newPy = dy * cr / ds + cy;
        newTc = vec2(newPx / aWidth, newPy / aHeight);
    }

    // Sample the remapped color
    vec4 retColor = INPUT(newTc);

    // Blend with original based on alpha
    float factor = float(alphaParam) / 100.0;
    vec4 result = mix(color, retColor, factor);

    return result;
}

