float noise(vec2 p, float iGlobalTime)
{
	vec2 v = vec2(1.,2.*cos(iGlobalTime))*iGlobalTime*8. + p*1.;
	v.x = mod(v.x, 1.0);
	v.y = mod(v.y, 1.0);
	float sample_x = INPUT2(v).x;
	sample_x *= sample_x;
	return sample_x;
}

float onOff(float a, float b, float c, float iGlobalTime)
{
	return step(c, sin(iGlobalTime + a*cos(iGlobalTime*b)));
}

float ramp(float y, float start, float end)
{
	float inside = step(start,y) - step(end,y);
	float fact = (y-start)/(end-start)*inside;
	return (1.-fact) * inside;

}

float stripes(vec2 uv, float iGlobalTime)
{

	float noi = noise(uv*vec2(0.5,1.) + vec2(1.,3.), iGlobalTime);
	return ramp(mod(uv.y*4. + iGlobalTime/2.+sin(iGlobalTime + sin(iGlobalTime*0.63)),1.),0.5,0.6)*noi;
}

vec3 getVideo(vec2 uv, float iGlobalTime)
{
	vec2 look = uv;
	float window = 1./(1.+20.*(look.y-mod(iGlobalTime/4.,1.))*(look.y-mod(iGlobalTime/4.,1.)));
	look.x = look.x + (sin(look.y*10. + iGlobalTime)/50.*onOff(4.,4.,.3, iGlobalTime)*(1.+cos(iGlobalTime*80.))*window);
	float vShift = 0.4*onOff(2.,3.,.9, iGlobalTime)*(sin(iGlobalTime)*sin(iGlobalTime*20.) + 
										 (0.5 + 0.1*sin(iGlobalTime*200.)*cos(iGlobalTime)));
	look.y = mod(look.y + (vShift), 1.);
	vec3 video = INPUT1(look).rgb;
	return video;
}

vec2 screenDistort(vec2 uv)
{
	uv -= vec2(.5,.5);
	uv = uv*1.2*(1./1.2+2.*uv.x*uv.x*uv.y*uv.y);
	uv += vec2(.5,.5);
	return uv;
}

vec4 FUNCNAME(vec2 tc)
{
	float iGlobalTime = PREFIX(global_time);
	vec2 uv = tc;
	//uv = screenDistort(uv);
	vec3 video = getVideo(uv, iGlobalTime);
	float vigAmt = 3.+.3*sin(iGlobalTime + 5.*cos(iGlobalTime*5.));
	float vignette = (1.-vigAmt*(uv.y-.5)*(uv.y-.5))*(1.-vigAmt*(uv.x-.5)*(uv.x-.5));

	video += stripes(uv, iGlobalTime);
	video += noise(uv*2.0,iGlobalTime)/2.;

	vec4 col = INPUT1(tc);

	float vig = vignette *((12.)+mod(uv.y*30.+iGlobalTime,1.))/(13.-PREFIX(bright)*10.0);
	video *= vig;

	float factor = float(PREFIX(alpha))/100.0;
	vec4 retColor = col*(1.0 - factor) + vec4(video,col.a)*factor;
    retColor.rgb *= retColor.a;
	return retColor;
}

// VideoWall Effect - Grid display with center enlarged
// CL to GL conversion (性能优化版)
// 将图像分成4x4网格，中间2x2区域显示完整图像，边缘格子显示缩小平铺

vec4 FUNCNAME(vec2 tc) {
    // 获取参数
    float factor = float(PREFIX(alpha)) / 100.0;

    // 早退：alpha=0 时直接返回原图，无需任何网格计算
    if (factor <= 0.0) {
        return INPUT(tc);
    }

    // 网格参数 (splite=4, hori=4, vert=4, midHori=2, midVert=2)
    // 全部用浮点避免整数除法（GPU整数除法很慢）
    const float fHori = 4.0;
    const float fVert = 4.0;
    const float invHori = 1.0 / fHori;  // 0.25
    const float invVert = 1.0 / fVert;  // 0.25

    // 在归一化坐标空间直接计算，避免像素坐标转换
    // 每个格子在UV空间的大小 = 1/4 = 0.25
    // 中间区域: x=[0.25, 0.75], y=[0.25, 0.75]

    // 当前像素所在格子索引 (0~3)
    float cellX = floor(tc.x * fHori);
    float cellY = floor(tc.y * fVert);
    cellX = min(cellX, fHori - 1.0);  // 防止边界溢出
    cellY = min(cellY, fVert - 1.0);

    // 判断是否在中间2x2区域 (格子索引 1,2)
    bool isMid = (cellX >= 1.0 && cellX <= 2.0 && cellY >= 1.0 && cellY <= 2.0);

    vec2 sampleTc;
    bool drawBorder = false;

    if (isMid) {
        // 中间2x2区域 - 将 [0.25, 0.75] 映射到 [0, 1]
        sampleTc = (tc - vec2(invHori, invVert)) * 2.0;
    } else {
        // 边缘格子 - 格子内局部坐标 × 4 = 平铺缩小
        vec2 localTc = tc * fHori - vec2(cellX, cellY);  // 格子内 [0,1)
        sampleTc = localTc;  // 直接用局部坐标采样（等效于 inBlock * hori / resolution）

        // 边框检测：格子内位置接近0时画黑线 (1像素 ≈ 1/1920)
        drawBorder = (localTc.x < 1.0 / 1920.0 * fHori || localTc.y < 1.0 / 1080.0 * fVert);
    }

    // 采样
    vec4 retColor = INPUT(clamp(sampleTc, 0.0, 1.0));

    // 边框线（黑色）
    if (drawBorder) {
        retColor = vec4(0.0, 0.0, 0.0, 1.0);
    }

    // Alpha混合
    vec4 color = INPUT(tc);
    return mix(color, retColor, factor);
}

