// VignetteWhite - 白色晕影滤镜
// 从OpenCL转换为OpenGL
// 算法: Screen混合模式 (滤色)
// 公式: 1 - (1-src) * (1-dst)

vec4 FUNCNAME(vec2 tc) {
    // 读取原图
    vec4 color = INPUT1(tc);

    // 读取叠加图(白色晕影)
    vec4 colorM = INPUT2(tc);

    // 获取alpha参数
    float factor = float(PREFIX(alpha)) / 100.0;

    // Screen混合模式 (滤色)
    // OpenCL原始算法:
    // dr = 255 - color.x * 255
    // sr = 255 - colorM.x * 255
    // r = 255 - ((sr * dr + 255) >> 8)
    // 
    // 等价于: result = 1 - (1-src) * (1-dst)
    // 这是标准的Screen混合模式

    vec3 srcInv = 1.0 - color.rgb;
    vec3 dstInv = 1.0 - colorM.rgb;

    // Screen混合: 1 - (1-a) * (1-b)
    // 近似原CL的位运算: 255 - ((sr * dr + 255) >> 8)
    // 浮点等价: 1.0 - srcInv * dstInv
    vec3 screenResult = 1.0 - srcInv * dstInv;

    // 与原图混合
    vec4 retColor = vec4(screenResult, color.a);
    retColor = retColor * factor + (1.0 - factor) * color;
    retColor = vec4(retColor.rgb * retColor.a, retColor.a);

    return retColor;
}

