    ivec3 cmy2 = ivec3(0);
    ivec3 cmy3 = ivec3(0);

    int maxV = max(max(inBGRA.x, inBGRA.y), inBGRA.z);
    int minV = min(min(inBGRA.x, inBGRA.y), inBGRA.z);
    int midV = max(min(inBGRA.x, inBGRA.y), min(max(inBGRA.x, inBGRA.y), inBGRA.z));

	lim = maxV - midV;
	if(maxV == inBGRA.z)//r
	{
		cmy1.z = min((lim * cmy0.z) >> 8, lim * 38 / 100);//r
		cmy1.y = min((lim * inBGRA.y) >> 8, lim / 10);//g
		cmy1.y = -cmy1.y;
		cmy1.x = min((lim * cmy0.x) >> 8, lim / 5);//b
	}

	lim = midV - minV;
	if(minV == inBGRA.x)//b
	{
		cmy2.z = min((lim * cmy0.z) >> 8, lim * 28 / 100);
		cmy2.y = min((lim * inBGRA.y) >> 8, lim / 20);
		cmy2.y = -cmy2.y;
		cmy2.x = min((lim * cmy0.x) >> 8, lim / 4);
		cmy2.x = -cmy2.x;
	}

   if(maxV < 128)
    {
        lim = 255 - maxV - maxV;
        cmy3.z = min((lim * cmy0.z) >> 8, lim * 6 / 100);
		cmy3.y = min((lim * inBGRA.y) >> 8, lim * 7 / 100);
		cmy3.y = -cmy3.y;
		cmy3.x = min((lim * cmy0.x) >> 8, lim * 9 / 100);
    }

    if (minV > 128) 
    {
        lim = minV + minV - 255;
        cmy3.z = min((lim * inBGRA.z) >> 8, lim  / 50);
		cmy3.z = -cmy3.z;
        cmy3.y = min((lim * cmy0.y) >> 8, lim * 3 / 100);
        cmy3.x = min((lim * cmy0.x) >> 8, lim * 3 / 100);
    }

    color.xyz = clamp(inBGRA.xyz + cmy1 + cmy2 + cmy3, 0, 255);

	vec4 retColor;
    retColor.x = INPUT2(vec2(float(color.x) / 255.0, .16666)).x;
	retColor.y = INPUT2(vec2(float(color.y) / 255.0, .5)).y;
	retColor.z = INPUT2(vec2(float(color.z) / 255.0, .83333)).z;
    retColor.w = oriColor.w;

	return  mix(retColor, oriColor, 1.0 - float(alpha)/100.0);
}

