float col(vec2 coord, float u_time, int steps)
{
	//speed
	float speed = 0.2;
	float speed_x = 0.3;
	float speed_y = 0.3;

	float time = u_time * 1.3;
	float time_speed = time * speed;
	float time_speed_x = time * speed_x;
	float time_speed_y = time * speed_y;

	// refraction
	float intensity = 2.4;
	float frequency = 6.0;
	int angle = 7; // better when a prime
	float delta_theta = 0.8975979010256551; // 2.0 * PI / float(angle);
    float col = 0.0;
    float theta = 0.0;
    for (int i = 0; i < steps; i++)
    {
      vec2 adjc = coord;
      theta = delta_theta*float(i);
      adjc.x += cos(theta)*time_speed + time_speed_x;
      adjc.y -= sin(theta)*time_speed - time_speed_y;
      col = col + cos( (adjc.x*cos(theta) - adjc.y*sin(theta))*frequency)*intensity;
    }

    return cos(col);
}

