vec4 FUNCNAME(vec2 tc) {
	float u_time = PREFIX(global_time);
	int strength = PREFIX(alpha); 	
	int steps = PREFIX(steps);
	float emboss = PREFIX(emboss);

	// reflection
	float delta = 60.;
	float intence = 700.;

	float reflectionCutOff = 0.012;
	float reflectionIntence = 200000.;

	vec2 p = tc, c1 = p, c2 = p;
	float cc1 = col(c1, u_time, steps);

	c2.x += iResolution.x/delta;
	float dx = emboss*(cc1-col(c2, u_time, steps))/delta;

	c2.x = p.x;
	c2.y += iResolution.y/delta;
	float dy = emboss*(cc1-col(c2, u_time, steps))/delta;

	c1.x += dx*2.;
	c1.y = c1.y+dy*2.;

	float alpha = 1.+dot(dx,dy)*intence;

	float ddx = dx - reflectionCutOff;
	float ddy = dy - reflectionCutOff;
	if (ddx > 0. && ddy > 0.)
		alpha = pow(alpha, ddx*ddy*reflectionIntence);

	vec4 col = INPUT(c1)*(alpha);
	vec4 orig = INPUT(tc);

	return mix(vec4(col.rgb, orig.a), orig, 1.0 - float(strength)/100.0);

}

