    float gray = (orig.r + orig.g + orig.b) / 3.0;

    // 灰度颜色
    vec3 grayColor = vec3(gray);

    // 与原图混合
    vec3 blended = grayColor * factor + (1.0 - factor) * orig.rgb;

    // 预乘Alpha
    blended *= orig.a;

    return vec4(blended, orig.a);
}

