vec4 FUNCNAME(vec2 tc) 
{
    int alpha = PREFIX(alpha); 
	vec2 uv = tc;
    vec4 gaussian;
    vec4 samples[9];
    //initOffset(2.);
	vec2 offset[25];
	float st = 2.0;
	float xInc = st / iResolution.x;
    float yInc = st / iResolution.y;
    int loc = 0;
    float startPxlX = -(3.0 / 2.) * xInc;
    float startPxlY = -(3.0 / 2.) * yInc;
    float curPxLY = 0.;
    for(int j = 0; j < 3; j++)
    {
        curPxLY = startPxlY + float(j) * yInc;
        for(int i = 0; i < 3; i++)
        {
            offset[j*3+i].x=startPxlX + float(i) * xInc;
            offset[j*3+i].y = curPxLY;
            loc+=1;
        }
    }

    for (int i = 0; i < 9; i++)
    {
        // Sample a grid around and including our texel
        samples[i] = INPUT1(uv + offset[i]);
    }

    // Gaussian weighting:
    // 1  4  7  4 1
    // 4 16 26 16 4
    // 7 26 41 26 7 / 273 (i.e. divide by total of weightings)
    // 4 16 26 16 4
    // 1  4  7  4 1

    gaussian = ( (16.0  * (samples[0] + samples[2]  + samples[6] + samples[8])) +
                 (26.0  * (samples[1] + samples[3]  + samples[5] + samples[7])) +
                 (41.0 * samples[4]) ) / (4.0 * 16.0 + 4.0 * 26.0 + 41.0);

    vec4 original = samples[4];


    //Level adjust
    float levelAdjust = DoGrayLevel(original.rgb, 50.0/255.0, 200.0/255.0);

    //Blending
    gaussian = (gaussian + levelAdjust) / 2.0;

    gaussian.a = original.a;

    vec4 border = INPUT2(vec2(uv.x, 1.0 - uv.y));

	vec4 texel = mix(gaussian, border, border.a);
	vec4 orig = INPUT1(tc);

	return mix(vec4(texel.rgb, orig.a), orig, 1.0 - float(alpha)/100.0);
}

