float overlayBlend(float src, float dst) {
    // src和dst都是0-1范围
    float s = src * 255.0;
    float d = dst * 255.0;

    float result;

    // 分段混合算法（模拟256x256查找表）
    if (d < 128.0) {
        // 正片叠底 (Multiply): (d * s + 127) >> 7
        result = (d * s + 127.0) / 128.0;
    } else {
        // 滤色 (Screen): 255 - (((255-d)*(255-s)+127)>>7)
        result = 255.0 - (((255.0 - d) * (255.0 - s) + 127.0) / 128.0);
    }

    return result / 255.0;
}

// 应用BlueExplosion效果
vec3 applyBlueExplosion(vec3 srcColor, vec3 dstColor) {
    // srcColor: color_explosion纹理颜色
    // dstColor: 原图颜色

    // 对每个通道分别应用overlay混合
    float r = overlayBlend(srcColor.r, dstColor.r);
    float g = overlayBlend(srcColor.g, dstColor.g);
    float b = overlayBlend(srcColor.b, dstColor.b);

    return vec3(r, g, b);
}

vec4 FUNCNAME(vec2 tc) {
    // 1. 获取alpha参数（0-100 → 0.0-1.0）
    float alpha = float(PREFIX(alpha)) / 100.0;

    // 2. 采样原图（INPUT1 通过SetInputFilterData绑定）
    vec4 originalColor = INPUT1(tc);

    // 3. 采样color_explosion纹理（INPUT2 来自TEXTURES[0]）
    // 翻转Y轴以匹配OpenCL的纹理坐标系统
    vec4 explosionColor = INPUT2(vec2(tc.x, 1.0 - tc.y));

    // 4. 应用Overlay混合模式
    // explosionColor作为src，originalColor作为dst
    vec3 blendedColor = applyBlueExplosion(explosionColor.rgb, originalColor.rgb);

    // 5. Alpha混合：alpha控制效果强度
    // alpha=0: 完全原图
    // alpha=1: 完全混合效果
    vec3 finalColor = mix(originalColor.rgb, blendedColor, alpha);

    // 6. 保持原图的alpha通道
    return vec4(finalColor, originalColor.a);
