//   INPUT3 = blueskies_lut.png (256×1 RGB, TEXTURES[1])
//
// blueskies_lut.png 存储: R=BlueTearB(BlueLUT), G=BlueTearG, B=BlueTearR(RedLUT)
// 引擎BGR加载后采样: .r=BlueTearR(RedLUT), .g=BlueTearG, .b=BlueTearB(BlueLUT)

vec4 FUNCNAME(vec2 tc) {
    // 1. 获取alpha参数（0-100 → 0.0-1.0）
    float alpha = float(PREFIX(alpha)) / 100.0;

    // 2. 采样原图
    vec4 originalColor = INPUT1(tc);

    // 3. 通过LUT纹理查表
    // INPUT1是BGR: .r=Blue .g=Green .b=Red
    float u_r = (floor(originalColor.r * 255.0 + 0.5) + 0.5) / 256.0;
    float u_g = (floor(originalColor.g * 255.0 + 0.5) + 0.5) / 256.0;
    float u_b = (floor(originalColor.b * 255.0 + 0.5) + 0.5) / 256.0;

