// ==================== Charcoal效果 OpenGL实现 ====================
// 算法：灰度计算 + 查找表映射 + 素材混合
// 步骤：RGB → 灰度 → table查找 → Alpha混合

// 灰度计算宏（匹配CL实际计算：CL因BGRA格式导致R/B权重互换）
// CL: MAKE_GREY(sb=R, sg=G, sr=B) → (29*R + 150*G + 76*B + 255) >> 8
#define MAKE_GREY(color) ((29.0 * (color).r + 150.0 * (color).g + 76.0 * (color).b + 255.0) / 256.0)

// 查找表函数（模拟 table[merge + gray] 查找）
// 返回 0-255 范围的值
float lookupTable(float mergeVal, float grayVal) {
    // 将 0-1 范围转换为 0-255 整数索引
    int merge255 = int(mergeVal * 255.0);
    int gray255 = int(grayVal);
    int index = merge255 + gray255;

    // 限制索引范围到 0-511
    index = clamp(index, 0, 511);

    // 简化的查找表实现
    // 完整版应该使用预计算的 table 或纹理查找
    // 这里使用简化映射：直接返回索引值（0-255范围）
    return float(min(index, 255));
}

vec4 FUNCNAME(vec2 tc) {
    // 1. 获取 alpha 参数（0-100 → 0.0-1.0）
    float alpha = float(PREFIX(alpha)) / 100.0;

    // 2. 采样原图（前景图）
    vec4 originalColor = INPUT1(tc);

    // 3. 采样素材纹理（翻转Y轴）
    vec2 texCoord = vec2(tc.x, 1.0 - tc.y);
    vec4 mergeColor = INPUT2(texCoord);

    // 4. 转换到 0-255 范围
    vec3 rgb255 = originalColor.rgb * 255.0;
    vec3 merge255 = mergeColor.rgb * 255.0;

    // 5. 计算灰度值（0-255范围）
    float gray = MAKE_GREY(rgb255);

    // 6. 查找表映射（返回0-255值，对每个通道独立处理）
    float tableR = lookupTable(mergeColor.r, gray);
    float tableG = lookupTable(mergeColor.g, gray);
    float tableB = lookupTable(mergeColor.b, gray);

    // 7. 与原图混合（CL逻辑：table * alpha + original * (1-alpha)）
    float finalR = (tableR * alpha + rgb255.r * (1.0 - alpha)) / 255.0;
    float finalG = (tableG * alpha + rgb255.g * (1.0 - alpha)) / 255.0;
    float finalB = (tableB * alpha + rgb255.b * (1.0 - alpha)) / 255.0;

    // 8. 乘以原图 alpha（CL: result * color.w）
    vec3 finalColor = vec3(finalR, finalG, finalB) * originalColor.a;

    // 9. 返回结果
    return vec4(finalColor, originalColor.a);
}

