// ==================== FocusColor效果 OpenGL实现 ====================
// 算法：基于矩形区域的彩色/灰度混合
// 步骤：计算矩形区域 → RGB查找表 → 区域判断 → 混合处理

// 灰度计算宏（RGB查找表后）
#define rgb2Gray(r, g, b) ((r + g + b + 512.0) / 1024.0)

// RGB查找表（基于固定系数：R*306, G*601, B*117）
vec3 applyLUT(vec3 rgb255) {
    return vec3(
        rgb255.r * 306.0,
        rgb255.g * 601.0,
        rgb255.b * 117.0
    );
}

vec4 FUNCNAME(vec2 tc) {
    // 1. 获取参数
    float alpha = float(PREFIX(alpha)) / 100.0;
    float posX = float(PREFIX(posX)) / 100.0;
    float posY = float(PREFIX(posY)) / 100.0;

    // 2. 采样原图
    vec4 originalColor = INPUT1(tc);
    vec3 rgb255 = originalColor.rgb * 255.0;

    // 3. 计算矩形区域边界（基于 posX/posY）
    // C++: int cx = posX * width / 100, cy = posY * height / 100;
    // 矩形半径：rw = width/2 - 1, rh = height/2 - 1
    vec2 center = vec2(posX, posY);
    vec2 halfSize = vec2(0.5, 0.5); // 矩形半尺寸

    vec2 topLeft = center - halfSize;
    vec2 bottomRight = center + halfSize;

    // 钳制边界
    topLeft = max(topLeft, vec2(0.0));
    bottomRight = min(bottomRight, vec2(1.0));

    // 4. 判断当前像素是否在矩形内
    bool inRegion = (tc.x >= topLeft.x && tc.x <= bottomRight.x && 
                     tc.y >= topLeft.y && tc.y <= bottomRight.y);

    vec3 result;

    if (inRegion) {
        // 区域内：彩色混合（基于素材纹理）
        // 将当前像素坐标映射到素材纹理空间（以矩形中心为原点）
        vec2 relativePos = (tc - center) / halfSize; // 相对于中心的归一化坐标 [-1, 1]
        vec2 texCoord = vec2((relativePos.x + 1.0) * 0.5, 1.0 - (relativePos.y + 1.0) * 0.5);
        vec4 mergeColor = INPUT2(texCoord);

        float iC = mergeColor.b * 255.0;
        float iG = 256.0 - iC;

        // 应用查找表
        vec3 lut = applyLUT(rgb255);
        float gray = rgb2Gray(lut.r, lut.g, lut.b);
        float iOlaGray = gray * iG;

        // 混合计算
        vec3 mixed;
        mixed.b = (iC * rgb255.b + iOlaGray) / 256.0;
        mixed.g = (iC * rgb255.g + iOlaGray) / 256.0;
        mixed.r = (iC * rgb255.r + iOlaGray) / 256.0;

        // Alpha混合
        result = (mixed * alpha + rgb255 * (1.0 - alpha)) / 255.0;
    } else {
        // 区域外：灰度化
        vec3 lut = applyLUT(rgb255);
        float gray = rgb2Gray(lut.r, lut.g, lut.b);

        // Alpha混合
        result = (vec3(gray) * alpha + rgb255 * (1.0 - alpha)) / 255.0;
    }

    return vec4(result, originalColor.a);
}

