// ==================== FourSeason效果 OpenGL实现 (纹理优化版) ====================
// 算法：四分屏颜色滤镜
// 步骤：计算区域 → 采样LUT纹理 / 简单色温 → Alpha混合
//
// LUT纹理布局:
//   INPUT1 = 视频源 (SetInputFilterData)
//   INPUT2 = t.png (占位, TEXTURES[0])
//   INPUT3 = cross_lut.png (256×1 RGB, TEXTURES[1])
//   INPUT4 = pro_lut.png (256×1 RGB, TEXTURES[2])
//
// cross_lut.png 存储: R=CrossBlue(BlueLUT), G=CrossGreen, B=CrossRed(RedLUT)
// 引擎BGR加载后采样: .r=CrossRed(RedLUT), .g=CrossGreen, .b=CrossBlue(BlueLUT)
//
// pro_lut.png 存储: R=ProBlue(BlueLUT), G=ProGreen, B=ProRed(RedLUT)
// 引擎BGR加载后采样: .r=ProRed(RedLUT), .g=ProGreen, .b=ProBlue(BlueLUT)

// 从LUT纹理采样 (INPUT1是BGR: .r=B .g=G .b=R)
// 输出也是BGR格式
vec3 sampleLUT(vec3 color, int lutInput) {
    // 计算texel中心偏移的UV
    float u_r = (floor(color.r * 255.0 + 0.5) + 0.5) / 256.0;
    float u_g = (floor(color.g * 255.0 + 0.5) + 0.5) / 256.0;
    float u_b = (floor(color.b * 255.0 + 0.5) + 0.5) / 256.0;

    // 通道映射:
    // color.r = Blue通道值 → 查BlueLUT → 引擎加载后在 .b
    // color.g = Green通道值 → 查GreenLUT → 引擎加载后在 .g
    // color.b = Red通道值 → 查RedLUT → 引擎加载后在 .r
    vec3 mapped;
    if (lutInput == 3) {
        mapped.r = INPUT3(vec2(u_r, 0.5)).b;  // Blue通道 → CrossBlue(.b)
        mapped.g = INPUT3(vec2(u_g, 0.5)).g;  // Green通道 → CrossGreen(.g)
        mapped.b = INPUT3(vec2(u_b, 0.5)).r;  // Red通道 → CrossRed(.r)
    } else {
        mapped.r = INPUT4(vec2(u_r, 0.5)).b;  // Blue通道 → ProBlue(.b)
        mapped.g = INPUT4(vec2(u_g, 0.5)).g;  // Green通道 → ProGreen(.g)
        mapped.b = INPUT4(vec2(u_b, 0.5)).r;  // Red通道 → ProRed(.r)
    }

    return mapped;
}

vec3 applyWarm(vec3 color) {
    // Warm 色温调整（INPUT1是BGR：.r=蓝 .g=绿 .b=红）
    // aPercent_warm = (65 - 50) * 3 = 45
    // aGOffset_warm = 45 >> 1 = 22
    // 暖色：红↑ 绿↓ 蓝↓
    float percent = 45.0 / 255.0;
    float gOffset = 22.0 / 255.0;

    vec3 adjusted;
    adjusted.r = clamp(color.r - percent, 0.0, 1.0);  // 减少蓝色
    adjusted.g = clamp(color.g - gOffset, 0.0, 1.0);  // 减少绿色
    adjusted.b = clamp(color.b + percent, 0.0, 1.0);  // 增加红色

    return adjusted;
}

vec3 applyCool(vec3 color) {
    // Cool 色温调整（INPUT1是BGR：.r=蓝 .g=绿 .b=红）
    // aPercent_cool = (20 - 50) * 3 = -90
    // aGOffset_cool = -90 >> 1 = -45
    // 冷色：红↓ 绿↑ 蓝↑
    float percent = 90.0 / 255.0;
    float gOffset = 45.0 / 255.0;

    vec3 adjusted;
    adjusted.r = clamp(color.r + percent, 0.0, 1.0);  // 增加蓝色
    adjusted.g = clamp(color.g + gOffset, 0.0, 1.0);  // 增加绿色
    adjusted.b = clamp(color.b - percent, 0.0, 1.0);  // 减少红色

    return adjusted;
}

vec4 FUNCNAME(vec2 tc) {
    // 1. 获取 alpha 参数
    float alpha = float(PREFIX(alpha)) / 100.0;

    // 2. 采样原图
    vec4 originalColor = INPUT1(tc);

    // 3. 计算分隔线宽度（基于屏幕宽度）
    float lineWidth = 2.0 / 640.0; // 假设基准宽度640

    // 4. 根据 X 坐标判断区域并应用滤镜
    vec3 result;

    if (tc.x < 0.25 - lineWidth) {
        // 区域1：Cross LUT (纹理采样)
        result = sampleLUT(originalColor.rgb, 3);
    } else if (tc.x >= 0.25 - lineWidth && tc.x < 0.25) {
        // 分隔线1：黑色
        result = vec3(0.0);
    } else if (tc.x >= 0.25 && tc.x < 0.5 - lineWidth) {
        // 区域2：Pro LUT (纹理采样)
        result = sampleLUT(originalColor.rgb, 4);
    } else if (tc.x >= 0.5 - lineWidth && tc.x < 0.5) {
        // 分隔线2：黑色
        result = vec3(0.0);
    } else if (tc.x >= 0.5 && tc.x < 0.75 - lineWidth) {
        // 区域3：Warm
        result = applyWarm(originalColor.rgb);
    } else if (tc.x >= 0.75 - lineWidth && tc.x < 0.75) {
        // 分隔线3：黑色
        result = vec3(0.0);
    } else {
        // 区域4：Cool
        result = applyCool(originalColor.rgb);
    }

    // 5. 应用 alpha 预乘
    vec3 filtered = result * originalColor.a;

    // 6. Alpha 混合
    vec3 finalColor = filtered * alpha + originalColor.rgb * (1.0 - alpha);

    return vec4(finalColor, originalColor.a);
}

