        mapped.b = INPUT4(vec2(u_b, 0.5)).r;  // Red通道 → ProRed(.r)
    }

    return mapped;
}

vec3 applyWarm(vec3 color) {
    // Warm 色温调整（INPUT1是BGR：.r=蓝 .g=绿 .b=红）
    // aPercent_warm = (65 - 50) * 3 = 45
    // aGOffset_warm = 45 >> 1 = 22
    // 暖色：红↑ 绿↓ 蓝↓
    float percent = 45.0 / 255.0;
    float gOffset = 22.0 / 255.0;

    vec3 adjusted;
    adjusted.r = clamp(color.r - percent, 0.0, 1.0);  // 减少蓝色
    adjusted.g = clamp(color.g - gOffset, 0.0, 1.0);  // 减少绿色
    adjusted.b = clamp(color.b + percent, 0.0, 1.0);  // 增加红色

    return adjusted;
}

vec3 applyCool(vec3 color) {
    // Cool 色温调整（INPUT1是BGR：.r=蓝 .g=绿 .b=红）
    // aPercent_cool = (20 - 50) * 3 = -90
    // aGOffset_cool = -90 >> 1 = -45
    // 冷色：红↓ 绿↑ 蓝↑
    float percent = 90.0 / 255.0;
    float gOffset = 45.0 / 255.0;

    vec3 adjusted;
    adjusted.r = clamp(color.r + percent, 0.0, 1.0);  // 增加蓝色
    adjusted.g = clamp(color.g + gOffset, 0.0, 1.0);  // 增加绿色
    adjusted.b = clamp(color.b - percent, 0.0, 1.0);  // 减少红色

    return adjusted;
}

vec4 FUNCNAME(vec2 tc) {
    // 1. 获取 alpha 参数
    float alpha = float(PREFIX(alpha)) / 100.0;

    // 2. 采样原图
    vec4 originalColor = INPUT1(tc);

    // 3. 计算分隔线宽度（基于屏幕宽度）
    float lineWidth = 2.0 / 640.0; // 假设基准宽度640

    // 4. 根据 X 坐标判断区域并应用滤镜
    vec3 result;

    if (tc.x < 0.25 - lineWidth) {
        // 区域1：Cross LUT (纹理采样)
        result = sampleLUT(originalColor.rgb, 3);
    } else if (tc.x >= 0.25 - lineWidth && tc.x < 0.25) {
        // 分隔线1：黑色
        result = vec3(0.0);
    } else if (tc.x >= 0.25 && tc.x < 0.5 - lineWidth) {
        // 区域2：Pro LUT (纹理采样)
        result = sampleLUT(originalColor.rgb, 4);
    } else if (tc.x >= 0.5 - lineWidth && tc.x < 0.5) {
        // 分隔线2：黑色
        result = vec3(0.0);
    } else if (tc.x >= 0.5 && tc.x < 0.75 - lineWidth) {
        // 区域3：Warm
        result = applyWarm(originalColor.rgb);
    } else if (tc.x >= 0.75 - lineWidth && tc.x < 0.75) {
        // 分隔线3：黑色
        result = vec3(0.0);
    } else {
        // 区域4：Cool
        result = applyCool(originalColor.rgb);
    }

    // 5. 应用 alpha 预乘
    vec3 filtered = result * originalColor.a;

    // 6. Alpha 混合
    vec3 finalColor = filtered * alpha + originalColor.rgb * (1.0 - alpha);

    return vec4(finalColor, originalColor.a);
}

