// ==================== FreshNew效果 OpenGL实现 (纹理优化版) ====================
// 算法：Exclusion混合 + LUT映射
// 步骤：1. Exclusion混合固定值 → 2. LUT纹理查表 → 3. Alpha混合
// 纹理布局:
//   INPUT1 = 视频源 (SetInputFilterData)
//   INPUT2 = t.png (占位, TEXTURES[0])
//   INPUT3 = freshnew_lut.png (256×1 RGB, R=MappingR, G=MappingG, B=MappingB, TEXTURES[1])

// Exclusion混合宏 (根据C++定义)
#define ChannelBlend_Exclusion(B, L) (B + L - ((B * L) * 2.0 / 255.0))

// LUT纹理查表: 引擎加载PNG为BGR
// 存储RGB(MappingR,MappingG,MappingB) → 采样得到BGR(MappingB,MappingG,MappingR)
// 所以: .r采样=MappingB, .g采样=MappingG, .b采样=MappingR

vec4 FUNCNAME(vec2 tc) {
    // 1. 获取alpha参数
    float alpha = float(PREFIX(alpha)) / 100.0;

    // 2. 采样原图 (INPUT1返回BGR格式)
    vec4 color = INPUT1(tc);

    // 3. 转换为0-255整数
    int b = int(color.r * 255.0);  // INPUT1的.r是蓝色通道
    int g = int(color.g * 255.0);  // INPUT1的.g是绿色通道
    int r = int(color.z * 255.0);  // INPUT1的.b是红色通道

    // 4. Exclusion混合 (C++代码中的固定值)
    float fb = float(b);
    float fg = float(g);
    float fr = float(r);

    r = int(ChannelBlend_Exclusion(fr, 31.0));
    g = int(ChannelBlend_Exclusion(fg, 25.0));
    b = int(ChannelBlend_Exclusion(fb, 81.0));

    // 5. 边界检查
    r = clamp(r, 0, 255);
    g = clamp(g, 0, 255);
    b = clamp(b, 0, 255);

    // 6. LUT纹理查表 (引擎BGR: 采样.r=MappingB, .g=MappingG, .b=MappingR)
    float uR = (float(r) + 0.5) / 256.0;
    float uG = (float(g) + 0.5) / 256.0;
    float uB = (float(b) + 0.5) / 256.0;
    float mapped_r = INPUT3(vec2(uR, 0.5)).b;  // .b采样 = MappingR
    float mapped_g = INPUT3(vec2(uG, 0.5)).g;  // .g采样 = MappingG
    float mapped_b = INPUT3(vec2(uB, 0.5)).r;  // .r采样 = MappingB

    // 7. Alpha混合 (注意：返回BGR格式)
    vec3 filtered = vec3(mapped_b, mapped_g, mapped_r);
    vec3 original = vec3(color.r, color.g, color.b);
    vec3 result = filtered * alpha + original * (1.0 - alpha);

    return vec4(result * color.a, color.a);
}

