// Retro 复古滤镜 - OpenGL版本 (纹理优化版)
// LUT纹理布局:
//   INPUT1 = 视频源 (SetInputFilterData)
//   INPUT2 = t.png  (占位, TEXTURES[0])
//   INPUT3 = retro_lut.png (256×1 RGB, TEXTURES[1])
//
// retro_lut.png 存储: R=BlueLUT, G=GreenLUT, B=RedLUT
// 引擎BGR加载后采样: .r=RedLUT, .g=GreenLUT, .b=BlueLUT
//
// 注意: Retro LUT 值为原始 0~255，纹理已存为像素值
//       采样得到 0~1 归一化值，直接用于混合即可

vec4 FUNCNAME(vec2 tc) {
    vec4 color = INPUT1(tc);

    // BGR format: color.r = blue, color.g = green, color.b = red
    float u_b = (color.r * 255.0 + 0.5) / 256.0;
    float u_g = (color.g * 255.0 + 0.5) / 256.0;
    float u_r = (color.b * 255.0 + 0.5) / 256.0;

    // 引擎BGR: .b=BlueLUT, .g=GreenLUT, .r=RedLUT
    // R通道(实际Blue)用BlueLUT, G通道用GreenLUT, B通道(实际Red)用RedLUT
    vec3 mapped;
    mapped.r = INPUT3(vec2(u_b, 0.5)).b;  // Blue通道查BlueLUT
    mapped.g = INPUT3(vec2(u_g, 0.5)).g;  // Green通道查GreenLUT
    mapped.b = INPUT3(vec2(u_r, 0.5)).r;  // Red通道查RedLUT

    // Apply alpha blending
    float factor = float(PREFIX(alpha)) / 100.0;
    vec3 finalColor = mix(color.rgb, mapped, factor);

    // 预乘alpha输出
    return vec4(finalColor * color.a, color.a);
}

