/*{
    "GUID": "B8C4D5E6-7F2A-4B91-9C3E-1A2D4F5E6B7C"
}*/

// Screen Effect - 滤色混合模式特效
// Screen混合公式: result = 1 - (1 - src) * (1 - dst)
// 使用叠加纹理 Screen.jpg

vec4 FUNCNAME(vec2 tc)
{
    // 获取原始颜色
    vec4 color = INPUT1(tc);

    // 获取叠加纹理颜色 (Screen.jpg)
    vec4 merge = INPUT2(vec2(tc.x, 1.0 - tc.y));

    // Screen混合模式: result = 1 - (1 - src) * (1 - dst)
    // 反转原图颜色
    float dr = 1.0 - color.r;
    float dg = 1.0 - color.g;
    float db = 1.0 - color.b;

    // 反转叠加图颜色
    float sr = 1.0 - merge.r;
    float sg = 1.0 - merge.g;
    float sb = 1.0 - merge.b;

    // Screen混合: 1 - (1-src)*(1-dst)
    float r = 1.0 - sr * dr;
