    vec4 fragColor = vec4(0.);
	float interval = 1. - PREFIX(speed) + 0.1;
	float framemod = mod(iTime, interval);
	framemod /= interval;
	framemod = 3.*pow(framemod, 2.) - 2.*pow(framemod, 3.);

	float amountMin = -100.0;
    float amountMax = 100.0;
	float maxHorizontalDM = 0.5;
	float dist  = PREFIX(amplitude);
	float dist2 = dist / 2.;
	float dist3 = dist / 3.;

	//偏移节奏控制
	if(framemod >= 0.05 && framemod <= 0.1){
		maxHorizontalDM -= (framemod-0.05)/0.05*dist;
	} 
	else if(framemod > 0.1 && framemod <= 0.3){
		maxHorizontalDM -= dist;
		maxHorizontalDM += dist*((framemod - 0.1) / 0.2);
	} 
	else if(framemod > 0.3 && framemod <= 0.4){
		maxHorizontalDM -= (framemod-0.3)/0.1*dist2;
	} 
	else if(framemod > 0.4 && framemod <= 0.6){
		maxHorizontalDM -= dist2;
		maxHorizontalDM += (framemod-0.4)/0.2*dist2;
	}
	else if(framemod > 0.6 && framemod <= 0.7){
		maxHorizontalDM -= (framemod-0.6)/0.1*dist3;
	}
	else if(framemod > 0.7 && framemod <= 0.8){
		maxHorizontalDM -= dist3;
		maxHorizontalDM += (framemod-0.7)/0.2*dist3;
	} 
	else{
		maxHorizontalDM = 0.5;
	}

	float horizontal = mix(amountMin, amountMax, maxHorizontalDM);
	float horizontalNormal = horizontal/(amountMax - amountMin) + 0.5;
	float horizontalTarget = mix(-1.0, 1.0, horizontalNormal);

	vec4 fractalNoise = INPUT2(uv);
	float factorX = mix(-1.0, 1.0, fractalNoise.b) * horizontalTarget*0.5;

	vec2 finalUV = vec2(uv.x + factorX, uv.y);

