	if(PREFIX(styleType) == 1){
		vec3 weight = vec3(0.0721, 0.7154, 0.2125);
		float luminance = dot(fragColor.rgb, weight);
		fragColor.rgb = vec3(luminance);
	}

    return fragColor;
}

vec2 rotate2D(vec2 st, float angle, float aspect,vec2  rotateCenter)
{
    st.x 	-= rotateCenter.x;
	st.y    -= rotateCenter.y;
    st.x 	 = st.x * aspect;
    st 	     = mat2(cos(angle), -sin(angle), sin(angle), cos(angle)) * st;
    st.x 	 = st.x / aspect;
    st.x	+= rotateCenter.x;
	st.y 	+= rotateCenter.y;
    return st;
}

vec3 screen(vec3 base, vec3 blend)
{
    vec3 white = vec3(1.0);
    vec3 result = white - ((white - blend) * (white - base));

    return result;
}

