float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
  vec2 p1 = vec2(p.x, p.y);
  vec2 p2 = vec2(p.z, p.w);
  float mX1 = p1.x;
  float mY1 = p1.y;
  float mX2 = p2.x; 
  float mY2 = p2.y;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;  // linear
  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

vec2 distort(vec2 uv, float Range){
  vec2 uvCentered = uv - 0.5;
  float ratio = iResolution.x/iResolution.y;
  vec2 uvAdjusted = vec2(uvCentered.x * ratio, uvCentered.y);

  float radius = max(Range, 0.0001);
  float r = length(uvAdjusted);
  float rNorm = clamp(r / radius, 0.0, 1.0);

  float multiplier = 5.0 * (1.0 - Range);
  float strength = max(1.0 - multiplier * (rNorm * rNorm), 0.0);
  uvAdjusted *= strength;

  vec2 uvDistorted = vec2(uvAdjusted.x / ratio, uvAdjusted.y);
  uvDistorted += 0.5;
  return uvDistorted;
}

