  float multiplier = 5.0 * (1.0 - Range);
  float rNormClamp = clamp(r / radius, 0.0, 1.0);
  float strength = max(1.0 - multiplier * (rNormClamp * rNormClamp), 0.0);
  float feather = mix(0.08, 0.02, clamp(Range, 0.0, 1.0));
  float alphaStrength = smoothstep(0.0, feather, strength);
  float rNorm = r / radius;

