vec2 rotateFunc(vec2 uv, vec2 center, float theta, vec2 iResolution)
{
    vec2 uv0 = uv - center;
    uv0.y *= iResolution.y / iResolution.x;
    vec2 temp;
    temp.x = dot(vec2(cos(theta), -sin(theta)), uv0);
    temp.y = dot(vec2(sin(theta), cos(theta)), uv0);
    temp.y /= iResolution.y / iResolution.x;
    temp += center;
    return temp;
}

