vec4 Digital_YMD(vec2 tc, vec2 iResolution, vec2 scale, float num_height, float process, float blur, int nLoop, int start_num, int end_num, vec4 roi, vec3 font_color)
{
	vec2 uv = tc;
	uv.y = 1.0 - uv.y;
	int offset = end_num - start_num + 10 * nLoop;
	if(start_num > end_num){
		offset += 10;
	}
	uv.y += num_height * (float(start_num) + float(offset) * process);
	uv *= scale;
	uv -= vec2(roi.x, roi.y) * scale;
	uv = fract(uv);

	vec4 retCol = vec4(0.0);
    vec4 blurCol = vec4(0.0);
	int samples = 32;
	float blurAmp = blur * 0.05 * (1.0 - process);
	vec2 dir = vec2(0.0, 1.0);
	float offset_y = 0.01;
	if(iResolution.y > iResolution.x){
		offset_y = 0.0;
	}
	float matt = step(roi.x, tc.x)*step(tc.x, roi.z)*step(roi.y+offset_y, 1.0-tc.y)*step(1.0-tc.y, roi.w);

	if(matt > 0.0){
		if(process > 0.001){
			for (int i = 0; i < samples; i += 4)
			{
				vec2 temp = uv + float(i) / float(samples) * dir * blurAmp;
				blurCol += INPUT2(temp);

				temp = uv + float(i+1) / float(samples) * dir * blurAmp;	
				blurCol += INPUT2(temp);

				temp = uv + float(i+2) / float(samples) * dir * blurAmp;
				blurCol += INPUT2(temp);

				temp = uv + float(i+3) / float(samples) * dir * blurAmp;	
				blurCol += INPUT2(temp);
			}
			retCol = blurCol / float(samples);
		}else{
			retCol = INPUT2(uv);
		}
	}

	retCol.rgb = font_color * retCol.a;
	retCol *= matt;

	return retCol;
}

