vec4 Line(vec2 tc, vec2 iResolution, vec2 scale, float process, float height, vec4 roi, vec3 font_color)
{
	if(process < 0.001)
		return vec4(0.0);

	float offset = -0.12;
	if(iResolution.x < iResolution.y)
		offset = -0.08;

	vec2 uv = tc;
	uv.y = 1.0 - uv.y;
	vec2 center = vec2(roi.x+(roi.z-roi.x)*0.5, roi.y+(roi.w-roi.y)*0.5);
