float sdEllipse(vec2 p, vec2 s, float feather) 
{
  float d = p.x * p.x / (s.x * s.x + 0.00001) + p.y * p.y / (s.y * s.y + 0.00001);
  return (1.0 - smoothstep(0.99 - feather * 10.0, 1.01 + feather * 10.0, d));
}

vec2 rotateFunc(vec2 uv, vec2 center, float theta)
{
  vec2 temp;
  temp.x = dot(vec2(cos(theta), -sin(theta)), uv - center);
  temp.y = dot(vec2(sin(theta), cos(theta)), uv - center);
  return temp + center;
}

vec4 adjustTemperature(vec4 color, float temperature, float tint){
  float deltaR = 1.0 + tint / 400.0 + temperature / 400.0;
  float deltaB = 1.0 + tint / 400.0 - temperature / 400.0;
  float deltaG = 1.0 - tint * 0.002;

  color.z = color.z * deltaR;
  color.y = color.y * deltaG;
  color.x = color.x * deltaB;
  return clamp(color, 0.0, 1.0);
}

vec4 adjustVibrance(vec4 color, float u_vibrance){
  float maxV = max(color.x, max(color.y, color.z));
  float minV = min(color.x, min(color.y, color.z));
  if(abs(maxV - minV) > 0.00001)
  {
    float avg = (maxV + minV) * 0.5;
    float vibrance = -0.01 * u_vibrance;
    float ratio = (maxV - minV) / maxV;
    if (vibrance <= 0.0){
      ratio = (1.0 - ratio) * 0.75;
    }else{
      ratio = ratio > 0.5 ? 0.5: (1.0 - ratio);
    }
    float armVal = vibrance * ratio;
    color.xyz += (maxV - color.xyz) * armVal;
  }
  return clamp(color, 0.0, 1.0);
}

vec4 adjustSaturation(vec4 color, float u_saturation){
  float maxV = max(color.x, max(color.y, color.z));
  float minV = min(color.x, min(color.y, color.z));
  if(abs(maxV - minV) > 0.00001)
  {
    float grayValue = dot(color.rgb, vec3(0.114, 0.587, 0.299));
    float saturation = 0.01 * u_saturation;
    float alpha = saturation;
    float ratio = (maxV - minV) / maxV;
    if(saturation > 0.0){
      alpha = saturation * (1.0 - ratio);
    }
    color.xyz += (color.xyz - grayValue) * alpha;
  }
  return clamp(color, 0.0, 1.0);
}

