float calBrightValue(float bright)
{
  float brightValue = 0.0;

  if (bright > 0.0)
  {
    brightValue = 1.0 + bright / 100.0;
  }
  else
  {  
        brightValue = 1.0 - 1.0 / (0.99 + bright / 253.0);  
    brightValue *= 0.6;
  }

  return brightValue;
}

vec4 newBrightness(vec4 color, float bright)
{
  vec4 ret;
  if (bright > 0.0)
    ret = color * bright;
  else
    ret = color + bright;

  ret.w = color.w;
  ret = clamp(ret, vec4(0.0), vec4(1.0));

  return ret;
}

vec4 adjustBrightness(vec4 color, float brightness){
  float brightValue = calBrightValue(brightness);
  color = newBrightness(color, brightValue);
  return color;
}

vec4 adjustContrast(vec4 color, float u_contrast){
  if(u_contrast < 0.0){
    float contrast = 1.0 / (1.0 + abs(u_contrast) * 0.005);

    if(color.x > 0.0 && color.x < 0.5){
      color.x = pow(color.x * 2.0, contrast) / 2.0;
    }else if(color.x >= 0.5 && color.x < 1.0){
      color.x = 1.0 - pow(2.0 - color.x * 2.0, contrast) / 2.0;
    }

    if(color.y > 0.0 && color.y < 0.5){
      color.y = pow(color.y * 2.0, contrast) / 2.0;
    }else if(color.y >= 0.5 && color.y < 1.0){
      color.y = 1.0 - pow(2.0 - color.y * 2.0, contrast) / 2.0;
    }

    if(color.z > 0.0 && color.z < 0.5){
      color.z = pow(color.z * 2.0, contrast) / 2.0;
    }else if(color.z >= 0.5 && color.z < 1.0){
      color.z = 1.0 - pow(2.0 - color.z * 2.0, contrast) / 2.0;
    }

    color = clamp(color, 0.0, 1.0);
  }else if(u_contrast > 0.0){
    float contrast = 1.0 + u_contrast * 0.005;

    if(color.x > 0.0 && color.x < 0.5){
      color.x = pow(color.x * 2.0, contrast) / 2.0;
    }else if(color.x >= 0.5 && color.x < 1.0){
      color.x = 1.0 - pow(2.0 - color.x * 2.0, contrast) / 2.0;
    }

    if(color.y > 0.0 && color.y < 0.5){
      color.y = pow(color.y * 2.0, contrast) / 2.0;
    }else if(color.y >= 0.5 && color.y < 1.0){
      color.y = 1.0 - pow(2.0 - color.y * 2.0, contrast) / 2.0;
    }

    if(color.z > 0.0 && color.z < 0.5){
      color.z = pow(color.z * 2.0, contrast) / 2.0;
    }else if(color.z >= 0.5 && color.z < 1.0){
      color.z = 1.0 - pow(2.0 - color.z * 2.0, contrast) / 2.0;
    }

    color = clamp(color, 0.0, 1.0);
  }
  return color;
}

float enHanceColor(float color, float coff)
{
  float adjust = coff * color;
  float val = 1.0 - (1.0 - adjust) * (1.0 - color);

  return val;
}

vec4 calHighlight(vec4 color, float highLight)
{
  vec4 ret;
  float lumaince = highLight * (max(color.z, max(color.y, color.x)));

  ret.x = enHanceColor(color.x, lumaince);
  ret.y = enHanceColor(color.y, lumaince);
  ret.z = enHanceColor(color.z, lumaince);
  ret.w = color.w;

  ret = clamp(ret, vec4(0.0), vec4(1.0));

  return ret;
}

vec4 adjustHighlight(vec4 color, float highLight){
  if (abs(highLight) > 0.00001)
  {
    float coff = highLight / 100.0;
    color = calHighlight(color, coff);
  }
  return color;
}

vec4 adjustShadow(vec4 color, float shadow){
  if(shadow > 0.0){
    float temp = 1.0 - shadow * 0.004;
    if(color.x > 0.0)
      color.x = pow(color.x, temp);
    if(color.y > 0.0)
      color.y = pow(color.y, temp);
    if(color.z > 0.0)
      color.z = pow(color.z, temp);
    color = clamp(color, 0.0, 1.0);
  }else if(shadow < 0.0){
    float temp = 1.0 - shadow * 0.006;
    if(color.x > 0.0)
      color.x = pow(color.x, temp);
    if(color.y > 0.0)
      color.y = pow(color.y, temp);
    if(color.z > 0.0)
      color.z = pow(color.z, temp);
    color = clamp(color, 0.0, 1.0);
  }
  return color;
}

