float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
  vec2 p1 = vec2(p.x, p.y);
  vec2 p2 = vec2(p.z, p.w);
  float mX1 = p1.x;
  float mY1 = p1.y;
  float mX2 = p2.x;
  float mY2 = p2.y;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;

  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

vec2 SmoothFunc(vec2 uv, int iter) {
  for (int i = 0; i < iter; i++) {
    uv = smoothstep(0.0, 1.0, uv);
  }
  return uv;
}

vec2 Mosaic(vec2 uv, float size) {
    float texRes = 512.0 * size;
    vec2 prop;
    if (iResolution.x < iResolution.y) {
        prop = vec2(iResolution.x / iResolution.y, 1.0);
    } else {
        prop = vec2(1.0, iResolution.y / iResolution.x);
    }
    uv = uv * vec2(texRes) * prop + 0.5;
    vec2 i = floor(uv);
    vec2 f = fract(uv);

    f = SmoothFunc(f, 3);
    f = SmoothFunc(f * f * f * f, 3);
    uv = i + f;
    uv = (uv - 0.5) / (texRes * prop);
    return uv;
}

float calSize(float t) {
    float ft = fract(t * 4.0);
    int it = int(t * 4.0);
    ft = floor(ft * 12.0) / 12.0;

    if(it < 1){
        float tt = mix(0.02, 0.05, ft);
        return tt;
    }else if(it < 2){
        float tt = mix(0.03, 0.06, ft);
        return tt;
    }else{
        ft = (t - 0.5) / 0.5;
        ft = clamp(ft, 0.0, 1.0);
        vec4 p = vec4(.51,0.0,.72,.59);
        ft = KeySpline(p, ft);
        float tt = mix(0.04, 1.0, ft);
        return tt;
    }
}

