float enHanceColor(float color, float coff) {
  float adjust = coff * color;
  float val = 1.0 - (1.0 - adjust) * (1.0 - color);
  return val;
}

vec4 calWhiteColor(vec4 color, float level) {
  vec4 ret;
  level /= 100.0;
  float luminance = level * (max(color.x, max(color.y, color.z)));

  ret.x = enHanceColor(color.x, luminance);
  ret.y = enHanceColor(color.y, luminance);
  ret.z = enHanceColor(color.z, luminance);

  if (luminance > 0.0) {
    ret.x = enHanceColor(ret.x, luminance);
    ret.y = enHanceColor(ret.y, luminance);
    ret.z = enHanceColor(ret.z, luminance);
  }

  ret.w = color.w;
  return clamp(ret, vec4(0.0), vec4(1.0));
}

vec3 calContrastValue(float contrast){
  float contrastValue = 0.0;
  int contrastVal = 0;
  int nHigh = 0;
  int nStretch = 0;
  vec3 ret;

  if (contrast > 0.0)       contrastValue = 1.0 / (1.0 - contrast / 255.0) - 1.0;
  else                      contrastValue = contrast / 255.0;

  contrastVal = int((contrastValue * 100.0) / 2.0);
  nHigh = 255 - contrastVal;

  if (nHigh < contrastVal){
    nHigh = 127;
    contrastVal = 120;
  }
  if (contrastVal < -127)   contrastVal = -120;

  if (contrastVal >= 0)     nStretch = 255 - 2 * contrastVal;
  else                      nStretch = 255 + 2 * contrastVal;

  ret.x = float(contrastVal) / 255.0;
  ret.y = float(nHigh) / 255.0;
  ret.z = float(nStretch) / 255.0;

  return ret;
}

vec4 calContrastColor(vec4 color, float contrast){
  vec3 resultVal = calContrastValue(contrast);
  float contrastVal = resultVal.x;
  float nHigh = resultVal.y;
  float nStretch = resultVal.z;

  vec4 ret;
  if (contrastVal > 0.0){
    if (color.z <= contrastVal) ret.z = 0.0;
    else if (color.z > nHigh)   ret.z = 1.0;
    else                        ret.z = (color.z - contrastVal) / nStretch;
    if (color.y <= contrastVal) ret.y = 0.0;
    else if (color.y > nHigh)   ret.y = 1.0;
    else                        ret.y = (color.y - contrastVal) / nStretch;
    if (color.x <= contrastVal) ret.x = 0.0;
    else if (color.x > nHigh)   ret.x = 1.0;
    else                        ret.x = (color.x - contrastVal) / nStretch;
  }
  else{
    ret.x = (color.x * nStretch) - contrastVal;
    ret.y = (color.y * nStretch) - contrastVal;
    ret.z = (color.z * nStretch) - contrastVal;
  }  
  ret.w = color.w;

  return ret;
}

vec4 calSaturationColor(vec4 color, float saturation){
  float maxV = max(color.x,max(color.y,color.z));
  float minV = min(color.x,min(color.y,color.z));
  if(abs(maxV - minV) > 0.00001){
    float grayValue = (color.x * 11.0 + color.y * 59.0 + color.z * 30.0 + 0.196) * 0.01;
    saturation = 0.01 * saturation;
    float alpha = saturation;
    float ratio = (maxV - minV) / maxV;
    if(saturation > 0.0)
      alpha = saturation * (1.0 - ratio);
    color.xyz += (color.xyz - grayValue) * alpha;
  }
  color = clamp(color, 0.0, 1.0);
  return color;
}

vec4 calTemperatureColor(vec4 color, float temperature, float tint, bool isNewColor) {
  vec4 ret = color;
  float deltaR, deltaB, deltaG;

  temperature /= 150.0;
  tint /= 150.0;

  if (isNewColor) {
    deltaR = 1.0 + tint / 2.0 + temperature / 2.0;
    deltaB = 1.0 + tint / 2.0 - temperature / 2.0;
    deltaG = 1.0 - tint * 0.4;
  } else {
    deltaR = 1.0 + tint / 2.0 + temperature;
    deltaB = 1.0 + tint / 2.0 - temperature;
    deltaG = 1.0 - tint;
  }

  if (abs(temperature) > 0.00001 || abs(tint) > 0.00001) {
    ret.z = ret.z * deltaR;
    ret.y = ret.y * deltaG;
    ret.x = ret.x * deltaB;
    ret = clamp(ret, 0.0, 1.0);
  }

  return ret;
}

