}

vec4 FUNCNAME(vec2 tc) 
{
	vec4 c = INPUT(tc);
    int SkinColor = PREFIX(SkinColor);
    int SkinColor_r = int (((SkinColor)>>16) & 0xff);
    int SkinColor_g = int (((SkinColor)>>8) & 0xff);
    int SkinColor_b = int ((SkinColor) & 0xff);
    float tolerance = PREFIX(Tolerance)/20.0;
    int AutoSkin = PREFIX(Auto_Skin_Detection);

    int alpha = PREFIX(alpha);    
    int radius = PREFIX(radius);     
    vec2 resolution = iResolution.xy;
    int kSize = (radius - 1) / 2;
	if(kSize == 0)
		return c;

    vec3 final_colour = vec3(0.0);
    float Z = 0.0;   
    float bZ = 1.0 / normpdf(0.0, BSIGMA);
    for (int i=-kSize; i <= kSize; ++i) {
        for (int j=-kSize; j <= kSize; ++j) {
            vec2 tmp_uv = vec2(float(i),float(j))/iResolution;
            vec4 cc = INPUT(tc + tmp_uv);        
            float sigmaJ = abs(float(j));
            float sigmaI = abs(float(i));
            float factor = normpdf3(cc.xyz-c.xyz, BSIGMA) * bZ * normpdf(sigmaI,SIGMA) * normpdf(sigmaJ,SIGMA);
            Z += factor;
            final_colour += factor * cc.xyz;
        }
    }

    vec4 fragColor = vec4(final_colour / Z, c.w);

    bool isSkin = false; 

    float skin_cb_min = 0.0;
    float skin_cb_max = 0.0;
    float skin_cr_min = 0.0;
    float skin_cr_max = 0.0;

    if(AutoSkin > 0){
        skin_cb_min = 100.0;
        skin_cb_max = 118.0;
        skin_cr_min = 121.0;
        skin_cr_max = 161.0;

        vec4 bgr = fragColor * 255.0;
        vec3 rgb = vec3(bgr.z,bgr.y,bgr.x);
        vec3 ycbcr = rgb;
        ycbcr.y = 128.0 - rgb.x*0.148 - rgb.y*0.291 + rgb.z*0.439;
        ycbcr.z = 128.0 + rgb.x*0.439 - rgb.y*0.368 - rgb.z*0.071;

        if (ycbcr.y > skin_cb_min && ycbcr.y < skin_cb_max &&
            ycbcr.z > skin_cr_min && ycbcr.z < skin_cr_max) {
            isSkin = true; 
        }
    }else{
        vec3 SkinColor_normal = vec3(SkinColor_b/255.0,SkinColor_g/255.0,SkinColor_r/255.0);
        float dis = ColorDistance(SkinColor_normal,c.xyz);
        if(dis < tolerance)
            isSkin = true;        
    }

    if (!isSkin)     
        fragColor = c; 

    return mix( fragColor, c, 1.0 - float(alpha)/100.0 );  
}

float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
    float mX1 = p.x;
    float mY1 = p.y;
    float mX2 = p.z; 
    float mY2 = p.w;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;  // linear
  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}
float easeOutQuad(float x){
  return 1.0 - (1.0 - x) * (1.0 - x);
}
vec4 FUNCNAME(vec2 tc)
{
    vec2 uv = tc;
    vec4 col = INPUT(uv);
    vec2 lastUV = uv;
    float flag = 0.0;

    float iTime = PREFIX(global_time);
    // float duration = PREFIX(duration);
    // float iPro = clamp(iTime/duration, 0.0, 1.0);

    float total_time = PREFIX(total_time);
    float duration = (1.05 - easeOutQuad(PREFIX(Speed)/100.0)) * total_time;
    float iPro = clamp(iTime/duration, 0.0, 1.0);

    float midMove = 0.0;
    float bottomMove = 1.0;
    float topMove = 1.0;


    if(iPro < 0.5){
        float progress = iPro * 2.0;

        vec4 p = vec4(1.0 ,0.0, 0.97, 0.36);
        progress = (progress > 0.92) ? (abs(progress-0.96)*3.0/4.0 + 0.97) : pow(progress/0.92, 5.0);
        midMove = -(1.01 - progress*1.01);
    }
    if(iPro > 0.48)
    {
        float progress = (iPro - 0.48)/0.52;
        // vec4 p = vec4(.11,.24,.74,1.18);
        vec4 p = vec4(1.0,.21,.62,1.23);
        topMove = 1.0 - KeySpline(p, progress);
        bottomMove = 1.0 - pow(progress, 3.0);
    }


    if(iResolution.x > iResolution.y)
    {
        vec2 myUV = uv - vec2(0.5, 0.0);
        vec2 n = vec2(-0.5, 1.0);
        vec2 normalLine = vec2(n.y, -n.x);
        flag += step(0.0, dot(myUV, normalLine));

        vec2 myUV2 = uv - vec2(1.0, 0.0);
        flag += step(0.0, dot(myUV2, normalLine));

        lastUV += step(flag, 0.5) * n * bottomMove;
        lastUV += step(0.5, flag) * step(flag, 1.5) * n * midMove;
        lastUV += step(1.5, flag) * n * topMove;
    }
    else
    {
        vec2 myUV = uv - vec2(1.0, 0.0);
        vec2 n = vec2(-1.0, 0.5);
        vec2 normalLine = vec2(n.y, -n.x);
        flag += step(0.0, dot(myUV, normalLine));

        vec2 myUV2 = uv - vec2(1.0, 0.5);
        flag += step(0.0, dot(myUV2, normalLine));

        lastUV += step(flag, 0.5) * n * bottomMove;
        lastUV += step(0.5, flag) * step(flag, 1.5) * n * midMove;
        lastUV += step(1.5, flag) * n * topMove;
    }
    col = INPUT(lastUV);
    col = col*step(0.0, lastUV.x)*step(0.0, lastUV.y)*step(lastUV.x, 1.0)*step(lastUV.y, 1.0);
    return col;
}

