    horizontal = false;
  }

  float max_len = max(iResolution.x, iResolution.y);
  float min_len = min(iResolution.x, iResolution.y);

  vec2 pos = vec2(tc);
  if (!horizontal) {
    pos = vec2(1.0 - tc.y, tc.x);
  }

  float lower_line = mid_line - 0.29;
  float upper_line = mid_line + 0.29;

  bool in_mask = false;
  vec2 uv = vec2(0.);
  if (step(lower_line, pos.y) * step(pos.y, upper_line) > 0.) {
    uv.y = (pos.y - lower_line) / 0.58;
    if (step(region_1.x, pos.x) * step(pos.x, region_1.y) > 0.) {
      uv.x = (pos.x - region_1.x) / (region_1.y - region_1.x);
      in_mask = true;
    }

    if (step(region_2.x, pos.x) * step(pos.x, region_2.y) > 0.) {
      uv.x = (pos.x - region_2.x) / (region_2.y - region_2.x);
      in_mask = true;
    }

    if (step(region_3.x, pos.x) * step(pos.x, region_3.y) > 0.) {
      uv.x = (pos.x - region_3.x) / (region_3.y - region_3.x);
      in_mask = true;
    }

    uv.x = ((uv.x - 0.5) * ((region_2.y - region_2.x) / 0.58)) + 0.5;
  }

  vec4 col = INPUT1(tc);
  if (in_mask) {
    if (!horizontal) {
      uv = vec2(uv.y, 1.0 - uv.x);
    }
    float filter_val = float(PREFIX(Filter)) / 100.0;
    col.rgb = INPUT1(uv).rgb;
    col.rgb = mix(col.rgb, gray(col.rgb), filter_val);
    vec4 noise_col = INPUT5(tc);
    col.rgb = mix(col.rgb, noise_col.rgb, noise_col.a);
  } else {
    if (!horizontal) {
      tc = vec2(tc.y, 1.0 - tc.x);
    }
    col.rgb = INPUT2(tc).rgb;
  }
  float text_width = 1280.;
  float text_height = 24.;
  float text_size = text_height / 720.;
  float text_padding = 26. / 720.;
  vec2 text_1 =
      vec2(lower_line - (text_padding + text_size), lower_line - text_padding);
  vec2 text_2 =
      vec2(upper_line + text_padding, upper_line + text_padding + text_size);

  float text_pixel = min_len * text_size;

  float text_len = text_pixel * (text_width / text_height);

  float opacity = float(PREFIX(Opacity)) / 100.0;
  if (step(text_1.x, pos.y) * step(pos.y, text_1.y) > 0.) {
    uv.y = 1.0 - ((pos.y - text_1.x) / text_size);
    uv.x = pos.x * max_len / text_len;
    uv.x = mod(uv.x, 1.);

    vec4 text_col = INPUT4(uv);
    col.rgb = mix(col.rgb, text_col.rgb, text_col.a * opacity);
  }

  if (step(text_2.x, pos.y) * step(pos.y, text_2.y) > 0.) {
    uv.y = 1.0 - ((pos.y - text_2.x) / text_size);
    uv.x = pos.x * max_len / text_len;
    uv.x = mod(uv.x, 1.);

    vec4 text_col = INPUT3(uv);
    col.rgb = mix(col.rgb, text_col.rgb, text_col.a * opacity);
  }

  col.rgb *= col.a;

  return col;
}

vec4 FUNCNAME(vec2 tc)
{   
