    float show_process = min(1.0, process/0.25);

    float tstep = 2.0 + (1.0-PREFIX(Speed)/100.0)*8.0;
    float times = floor(PREFIX(global_time) * 30.0) / tstep;
    float uv_stage = ceil(uv.x / 0.25);
    if (uv_stage < times) {
        fragOutCol = INPUT(uv);
    }

    float light_tag_1 = 0.0;
    float light_tag_2 = 0.0;
    float light_stage_1 = ceil(uv.x / 0.25);

    if (uv_stage > (times-1.0)) {
        light_tag_1 = -0.5;
    }
    if (uv_stage > (times-2.0)) {
        light_tag_2 = PREFIX(Glow)/100.0 * step(abs(light_tag_1), 0.1);
    }
    light_tag_1 *= step(light_tag_2, 0.01);

    float gap = 4.0 + floor(mix(2.0, 5.0, 1.0-PREFIX(Speed)/100.0));
    if (times > gap) {
        light_tag_1 = 0.0;
        light_tag_2 = 0.0;
        if (uv_stage > (4.0-(times-gap)) && uv_stage < (5.0-(times-gap))) {
            light_tag_1 = -0.5;
        }
        if (uv_stage >= (5.0-(times-gap)) && uv_stage < (6.0-(times-gap))) {
            light_tag_2 = PREFIX(Glow)/100.0;
        }
    }
    light_tag_1 *= step(light_tag_2, 0.01);

    fragOutCol = vec4(fragOutCol.rgb * pow(2.0, light_tag_1+light_tag_2), fragOutCol.a);

    return fragOutCol;
