    mosaic_uv.x = floor(fragCoord.x/(1.0/scale*iResolution.y))*(1.0/scale*iResolution.y)/iResolution.x;
    mosaic_uv.y = floor(fragCoord.y/(1.0/scale*iResolution.y))*(1.0/scale*iResolution.y)/iResolution.y;
    fragColor = INPUT(mosaic_uv);
    vec3 color = fragColor.rgb;

    //lego block effects
