    float circle = 0.0; 
    if(dis > 0.3 && dis < 0.4) circle = smoothstep(0.3, 0.4, dis) * smoothstep(0.40, 0.35, dis);
    color *= circle * dot(vec2(0.707),normalize(block_uv - middle))*0.5 + 1.0;

