vec4 FUNCNAME(vec2 tc)
{
    int isGray = PREFIX(Gray);

    vec4 fragColor = vec4(0.0);
    float u_aspectRatio = iResolution.x / iResolution.y;
    vec2 uv = vec2((tc.x * u_aspectRatio + 0.5 - 0.5 * u_aspectRatio), tc.y);

    float iGlobalTime = PREFIX(global_time);
    float iTotalTime = PREFIX(total_time);
    // float iPro = iGlobalTime / iTotalTime;
	float iPro = clamp(iGlobalTime / (iTotalTime*(1.5 - PREFIX(Speed)/100.0) ), 0.0, 1.0);

    vec2 center = vec2(0.5) + vec2(0.0/20.0*u_aspectRatio, 0.0/20.0);
    float radius = 5.0/11.0;
    float blur = -100.0/1200.0 - 0.005;
    if(iPro <= 0.02){
        fragColor = INPUT(tc);
    }else if(iPro > 0.02 && iPro <= 0.30){
        float progress = clamp( (iPro - 0.02) / 0.28, 0.0, 1.0);
        progress = easeInQuad(progress);
        float sign1 = sdCircle(uv-center,(1.0 - progress)*(1.2 - radius) + radius);
        if(sign1 < 0.){
            fragColor = INPUT(tc)*(1.0- smoothstep(blur,0.0,sign1));
        }    
    }else if(iPro <= 0.8){
        if(iPro <= 0.56){
            float sign1 = sdCircle(uv-center,radius);
            if(sign1 < 0.){
                fragColor = INPUT(tc)*(1.0 - smoothstep(blur,0.0,sign1));
            }
        }else if(iPro < 0.8){
            float progress = clamp( (iPro-0.56) / 0.24, 0.0, 1.0);
            float sign1 = sdCircle(uv-center, (1.0 - progress)*radius);
            if(sign1 < 0.){
                fragColor = INPUT(tc)*(1.0- smoothstep(blur,0.0,sign1));
            }
        }
        if(isGray == 1){
            if(iPro >= 0.48){
                float progress = clamp( (iPro-0.48) / 0.32, 0.0, 1.0);
                progress = easeOutQuad(progress);
                fragColor.rgb = mix(fragColor.rgb, vec3(lm_rgb2gray(fragColor.rgb)), progress);
            }
        }
    }else{
        float sign1 = sdCircle(uv-center, 0.0);
        if(sign1 < 0.){
            fragColor = INPUT(tc)*(1.0- smoothstep(blur,0.0,sign1));
        }            
    }
    return fragColor;

}

