float RightshiftOperation(float a, int b){
   float m = 1.0;
   for(int i=0;i<b;i++){
     m *= 2.0;
   }      
   return floor(a/m);
}

float LeftshiftOperation(float a,int b){
    float m = 1.0;
    for(int i=0;i<b;i++){
        m *= 2.0;
    }
    return floor(a*m);
}

float truncation(float a, int b){
    return modF((a),float(b));
}

vec4 calColor(int color){
    float color_red = truncation(RightshiftOperation(float(color), 16), 256);
    float color_green = truncation(RightshiftOperation(float(color), 8), 256);
    float color_blue = truncation(float(color), 256);
    vec4 colors = vec4(color_blue, color_green, color_red, 255.0) / 255.0;    
    return colors;

}

vec4 Digital(vec2 tc, vec2 scale, float num_height, int number, vec4 roi, vec3 color)
{
	vec2 uv = tc;
	uv.y = 1.0 - uv.y;
	uv.y += num_height * float(number);
	uv *= scale;
	uv -= vec2(roi.x, roi.y) * scale;
	uv = fract(uv);
    vec4 retCol = INPUT2(uv);
	retCol.rgb = color.rgb * retCol.a;

	float matt = step(roi.x, tc.x)*step(tc.x, roi.z)*step(roi.y, tc.y)*step(tc.y, roi.w);
	retCol *= matt;

	return retCol;
}

vec4 Colon(vec2 tc, vec2 scale, vec4 roi, vec3 color)
{
	vec2 uv = tc;
	uv.y = 1.0 - uv.y;
	uv *= scale;
	uv -= vec2(roi.x, roi.y) * scale;
	uv = fract(uv);
    vec4 retCol = INPUT3(uv);
	retCol.rgb = color.rgb * retCol.a;

	float matt = step(roi.x, tc.x)*step(tc.x, roi.z)*step(roi.y, 1.0-tc.y)*step(1.0-tc.y, roi.w);
	retCol *= matt;

	return retCol;
}

vec4 TextureDigital(vec2 uv, vec2 iResolution, int iMinute, int iSecond, float iGlobalTime, vec3 fontCol, float speed, bool isNotEnd)
{
	float prop = iResolution.x / iResolution.y;
	float imgProp = 60.0 / 1200.0;
	float colonProp = 60.0 / 120.0;

	int totalTime = (iMinute * 60 + iSecond) * 100;
    float speed_globalTime = iGlobalTime * speed;
	int changeTime = int(floor(speed_globalTime * 100.0));
	int curTime = totalTime - changeTime;
	int hundredthsOfSec = 0;
    int tenthsOfSec = 0;
    curTime = maxI(curTime, 0);
    float aFullSecond = modF(speed_globalTime, 1.0);	
	if(totalTime >= changeTime && iGlobalTime > 0.0 && aFullSecond != 0.0 && isNotEnd){
        float show_freq = 2.0;
        if(speed >= 2.0){
            show_freq = 1.0;
            speed_globalTime = iGlobalTime;
        }
        hundredthsOfSec = modI(int(float(totalTime - int(floor(speed_globalTime / 4.0 * 100.0)))/show_freq), 10);
        if(hundredthsOfSec == 0) hundredthsOfSec = 1;
        hundredthsOfSec = maxI(hundredthsOfSec, 0);
        if(speed >= 3.0){
            tenthsOfSec = modI(hundredthsOfSec+5, 10);
        }else{
            tenthsOfSec = modI(curTime / 10, 10);
        }
		tenthsOfSec = maxI(tenthsOfSec, 0);       
    }

	int minute = maxI(curTime / 100 / 60, 0);
	int second = maxI(modI(curTime / 100, 60), 0);

	float numWidth = (0.1-3.0/10000.0) * (10.0 / 20.0);
	float numHeight = numWidth * 2.0 * prop;
	float numGap = numWidth + 0.005;
	float colonOffset = 0.015;
	float colonWidth = numGap - colonOffset * 2.0;

	float startPos = 0.305- 18.0/10000.0;
	float roiY = 0.5 - numHeight * 0.5;
	float roiY1 = roiY + numHeight;

	vec2 scale_val = vec2(20.0, 20.0 * imgProp * (iResolution.y / iResolution.x));
	vec2 colon_scale = vec2(20.0, 20.0 * colonProp * (iResolution.y / iResolution.x));

	vec4 retCol = vec4(0.0);
	for(int i = 0;i < 8; ++i){
		float roiX = startPos + numGap * float(i);
		float roiX1 = roiX + numWidth;
		vec4 roi = vec4(roiX, roiY, roiX1, roiY1);
		int number = 0;
		if(i == 0){
			number = minute / 10;
		}else if(i == 1){
			number = modI(minute, 10);
		}else if(i == 2){
			roiX = startPos + numGap * float(i) - colonOffset;
			roiX1 = roiX + numWidth;
			float tempRoiX = roiX + 0.001;
            float tempRoiY = roiY - 0.007875*iResolution.x/iResolution.y;
			roi = vec4(tempRoiX, tempRoiY, roiX1, roiY1);
			retCol += Colon(uv, colon_scale, roi, fontCol);
			continue ;
		}else if(i == 3){
			roiX = startPos + numGap * float(i - 1) + colonWidth + 0.005;
			number = second / 10;
		}else if(i == 4){
			roiX = startPos + numGap * float(i - 1) + colonWidth + 0.005;
			number = modI(second, 10);
		}else if(i == 5){
			roiX = startPos + numGap * float(i - 1) + colonWidth - colonOffset + 0.01;
			roiX1 = roiX + numWidth;
            float tempRoiX = roiX - 16.0/10000.0;
            float tempRoiY = roiY - 0.007875*iResolution.x/iResolution.y;
            // float tempRoiY = roiY;
			roi = vec4(tempRoiX, tempRoiY, roiX1, roiY1);
			retCol += Colon(uv, colon_scale, roi, fontCol);
			continue ;
		}else if(i == 6){
			roiX = startPos + numGap * float(i - 2) + colonWidth * 2.0 + 0.015;
			number = tenthsOfSec;
		}else if(i == 7){
			roiX = startPos + numGap * float(i - 2) + colonWidth * 2.0 + 0.015;
			number = hundredthsOfSec;
		}
		roiX1 = roiX + numWidth;
		roi = vec4(roiX, roiY, roiX1, roiY1);
		retCol += Digital(uv, scale_val, numHeight, number, roi, fontCol);
	}
	return retCol;
}

float draw_roundBox( vec2 uv, vec2 center,vec2 leftPos, vec2 rightPos, float width, float blur)
{
    vec2 ba = rightPos-leftPos;
    vec2 pa = uv-leftPos;
    float h =clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    float d = length(pa-h*ba)-width;
	return (1.0-smoothstep(0.0,blur,abs(d)))*1.5;
}

float draw_roundBox_bevel(vec2 uv, vec2 p, vec2 size, float radius, float blur, float rad, float bevel){
	size *= radius;
	bevel *= size.y;
	radius *= bevel;
	uv = rotateFunc(uv, p, -rad);
	uv = abs(uv-p)-size+radius;
	float d = length(maxVec2F(uv,0.0))+minF(maxF(uv.x, uv.y),0.0)-radius+blur;
	return (1.0-smoothstep(0.0, blur, abs(d)))*1.5; 
}

