float sdRoundBox_bevel(vec2 uv, vec2 size, float bevel, float blur) {
  vec2 c = vec2(0.0);
  float radius = 1.0;
  size *= radius; 
  if(iResolution.x < iResolution.y){
    bevel *= size.y / (iResolution.y / iResolution.x);
  }else{
    bevel *= size.y;
  }
  radius *= bevel;

  uv = abs(uv - c) - size + radius;
  float d = length(max(uv, 0.0)) + min(max(uv.x, uv.y), 0.0) - radius;
  return clamp(2.0 - sign(d) - smoothstep(0.0, blur, abs(d)), 0.0, 1.0);
}

