  uv = fract(uv);
  vec4 retCol = INPUT3(uv);
  retCol.rgb = color.rgb * retCol.a;

  float matt = step(roi.x, tc.x) * step(tc.x, roi.z) * step(roi.y, 1.0 - tc.y) * step(1.0 - tc.y, roi.w);
  retCol *= matt;

  return retCol;
}

vec4 Slash(vec2 tc, vec2 scale, vec4 roi, vec3 color) {
  vec2 uv = tc;
  uv.y = 1.0 - uv.y;
  uv *= scale;
  uv -= vec2(roi.x, roi.y) * scale;
  uv = fract(uv);
  vec4 retCol = INPUT4(uv);
  retCol.rgb = color.rgb * retCol.a;

  float matt = step(roi.x, tc.x) * step(tc.x, roi.z) * step(roi.y, 1.0 - tc.y) * step(1.0 - tc.y, roi.w);
  retCol *= matt;

  return retCol;
}

vec4 TextureDigital(vec2 uv, vec2 iResolution, int iHour, int iMinute, int iSecond, float iGlobalTime, vec3 fontCol,
                    float speed, out int carryDay) {
  float prop = iResolution.x / iResolution.y;
  float imgProp = 60.0 / 1200.0;
  float colonProp = 60.0 / 120.0;

  int totalTime = int(PREFIX(total_time) * PREFIX(frame_rate));
  float speed_globalTime = iGlobalTime * speed;
  int changeTime = int(floor(speed_globalTime * 100.0));
  int curTime = changeTime;
  curTime = maxI(curTime, 0);

  // 计算基础时间和增量时间
  int base_hours = iHour;
  int base_minutes = iMinute;
  int base_seconds = iSecond;

  int add_hours = maxI(changeTime / 100 / 3600, 0);
  int add_minutes = maxI(modI(changeTime / 100 / 60, 60), 0);
  int add_seconds = maxI(modI(changeTime / 100, 60), 0);

  // 合并时间并处理进位
  int total_seconds = base_seconds + add_seconds;
  int carry_minutes = total_seconds / 60;
  int seconds = modI(total_seconds, 60);

  int total_minutes = base_minutes + add_minutes + carry_minutes;
  int carry_hours = total_minutes / 60;
  int minutes = modI(total_minutes, 60);

  int total_hours = base_hours + add_hours + carry_hours;
  carryDay = total_hours / 24;
  int hours = modI(total_hours, 24);

  float numWidth = (0.1 - 3.0 / 10000.0) * (10.0 / 20.0);
  float numHeight = numWidth * 2.0 * prop;
  float numGap = numWidth + 0.005;
  float colonOffset = 0.015;
  float colonWidth = numGap - colonOffset * 2.0;

  float startPos = 0.305 - 18.0 / 10000.0;
  float roiY = 0.5 - numHeight * 0.5;
  float roiY1 = roiY + numHeight;

  vec2 scale_val = vec2(20.0, 20.0 * imgProp * (iResolution.y / iResolution.x));
  vec2 colon_scale = vec2(20.0, 20.0 * colonProp * (iResolution.y / iResolution.x));

  vec4 retCol = vec4(0.0);
  for (int i = 0; i < 8; ++i) {
    float roiX = startPos + numGap * float(i);
    float roiX1 = roiX + numWidth;
    vec4 roi = vec4(roiX, roiY, roiX1, roiY1);
    int number = 0;
    if (i == 0) {
      number = hours / 10;
    } else if (i == 1) {
      number = modI(hours, 10);
    } else if (i == 2) {
      roiX = startPos + numGap * float(i) - colonOffset;
      roiX1 = roiX + numWidth;
      float tempRoiX = roiX + 0.001;
      float tempRoiY = roiY + 0.004 * iResolution.x / iResolution.y;
      roi = vec4(tempRoiX, tempRoiY, roiX1, roiY1);
      retCol += Colon(uv, colon_scale, roi, fontCol);
      continue;
    } else if (i == 3) {
      roiX = startPos + numGap * float(i - 1) + colonWidth + 0.005;
      number = minutes / 10;
    } else if (i == 4) {
      roiX = startPos + numGap * float(i - 1) + colonWidth + 0.005;
      number = modI(minutes, 10);
    } else if (i == 5) {
      roiX = startPos + numGap * float(i - 1) + colonWidth - colonOffset + 0.01;
      roiX1 = roiX + numWidth;
      float tempRoiX = roiX - 16.0 / 10000.0;
      float tempRoiY = roiY + 0.004 * iResolution.x / iResolution.y;
      roi = vec4(tempRoiX, tempRoiY, roiX1, roiY1);
      retCol += Colon(uv, colon_scale, roi, fontCol);
      continue;
    } else if (i == 6) {
      roiX = startPos + numGap * float(i - 2) + colonWidth * 2.0 + 0.015;
      number = seconds / 10;
    } else if (i == 7) {
      roiX = startPos + numGap * float(i - 2) + colonWidth * 2.0 + 0.015;
      number = modI(seconds, 10);
    }
    roiX1 = roiX + numWidth;
    roi = vec4(roiX, roiY, roiX1, roiY1);
    retCol += Digital(uv, scale_val, numHeight, number, roi, fontCol);
  }
  return retCol;
}

vec4 TextureDate(vec2 uv, vec2 iResolution, int year, int month, int day, vec3 fontCol, int carryDay) {
  // 处理日期进位
  int days_in_month[12];
  days_in_month[0] = 31;
  days_in_month[1] = 28;
  days_in_month[2] = 31;
  days_in_month[3] = 30;
  days_in_month[4] = 31;
  days_in_month[5] = 30;
  days_in_month[6] = 31;
  days_in_month[7] = 31;
  days_in_month[8] = 30;
  days_in_month[9] = 31;
  days_in_month[10] = 30;
  days_in_month[11] = 31;

  // 检查是否闰年
  if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) {
    days_in_month[1] = 29;
  }

  day += carryDay; // carry_days从TextureDigital传入

  while (day > days_in_month[month - 1]) {
    day -= days_in_month[month - 1];
    month++;
    if (month > 12) {
      month = 1;
      year++;
    }
  }

  float prop = iResolution.x / iResolution.y;
  float imgProp = 60.0 / 1200.0;
  float slashProp = 60.0 / 120.0;

  float numWidth = (0.1 - 3.0 / 10000.0) * (10.0 / 20.0);
  float numHeight = numWidth * 2.0 * prop;
  float numGap = numWidth + 0.005;
  float slashOffset = 0.015;
  float slashWidth = numGap - slashOffset * 2.0;

  float startPos = 0.305 - 18.0 / 10000.0;
  float roiY = 0.5 - numHeight * 0.5;
  float roiY1 = roiY + numHeight;

  vec2 scale_val = vec2(20.0, 20.0 * imgProp * (iResolution.y / iResolution.x));
  vec2 slash_scale = vec2(20.0, 20.0 * slashProp * (iResolution.y / iResolution.x));

  vec4 retCol = vec4(0.0);
  // 总共显示10个数字位: YYYY-MM-DD
  for (int i = 0; i < 10; ++i) {
    float roiX = startPos + numGap * float(i);
    float roiX1 = roiX + numWidth;
    vec4 roi = vec4(roiX, roiY, roiX1, roiY1);
    int number = 0;

    // 年份的4位数字
    if (i == 0) {
      number = year / 1000;
    } else if (i == 1) {
      number = modI(year / 100, 10);
    } else if (i == 2) {
      number = modI(year / 10, 10);
    } else if (i == 3) {
      number = modI(year, 10);
    }
    // 第一个横杠
    else if (i == 4) {
      roiX = startPos + numGap * float(i) - slashOffset;
      roiX1 = roiX + numWidth;
      float tempRoiX = roiX + 0.001;
      float tempRoiY = roiY;
      roi = vec4(tempRoiX, tempRoiY, roiX1, roiY1);
      retCol += Slash(uv, slash_scale, roi, fontCol);
      continue;
    }
    // 月份的2位数字
    else if (i == 5) {
      roiX = startPos + numGap * float(i - 1) + slashWidth + 0.005;
      number = month / 10;
    } else if (i == 6) {
      roiX = startPos + numGap * float(i - 1) + slashWidth + 0.005;
      number = modI(month, 10);
    }
    // 第二个横杠
    else if (i == 7) {
      roiX = startPos + numGap * float(i - 1) + slashWidth - slashOffset + 0.01;
      roiX1 = roiX + numWidth;
      float tempRoiX = roiX - 16.0 / 10000.0;
      float tempRoiY = roiY;
      roi = vec4(tempRoiX, tempRoiY, roiX1, roiY1);
      retCol += Slash(uv, slash_scale, roi, fontCol);
      continue;
    }
    // 日期的2位数字
    else if (i == 8) {
      roiX = startPos + numGap * float(i - 2) + slashWidth * 2.0 + 0.015;
      number = day / 10;
    } else if (i == 9) {
      roiX = startPos + numGap * float(i - 2) + slashWidth * 2.0 + 0.015;
      number = modI(day, 10);
    }

    roiX1 = roiX + numWidth;
    roi = vec4(roiX, roiY, roiX1, roiY1);
    retCol += Digital(uv, scale_val, numHeight, number, roi, fontCol);
  }
  return retCol;
}

