  days_in_month[10] = 30;
  days_in_month[11] = 31;

  // 检查是否闰年
  if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) {
    days_in_month[1] = 29;
  }

  day += carryDay; // carry_days从TextureDigital传入

  while (day > days_in_month[month - 1]) {
    day -= days_in_month[month - 1];
    month++;
    if (month > 12) {
      month = 1;
      year++;
    }
  }

  float prop = iResolution.x / iResolution.y;
  float imgProp = 60.0 / 1200.0;
  float slashProp = 60.0 / 120.0;

  float numWidth = (0.1 - 3.0 / 10000.0) * (10.0 / 20.0);
  float numHeight = numWidth * 2.0 * prop;
  float numGap = numWidth + 0.005;
  float slashOffset = 0.015;
  float slashWidth = numGap - slashOffset * 2.0;

  float startPos = 0.305 - 18.0 / 10000.0;
  float roiY = 0.5 - numHeight * 0.5;
  float roiY1 = roiY + numHeight;

  vec2 scale_val = vec2(20.0, 20.0 * imgProp * (iResolution.y / iResolution.x));
  vec2 slash_scale = vec2(20.0, 20.0 * slashProp * (iResolution.y / iResolution.x));

  vec4 retCol = vec4(0.0);
  // 总共显示10个数字位: YYYY-MM-DD
  for (int i = 0; i < 10; ++i) {
    float roiX = startPos + numGap * float(i);
    float roiX1 = roiX + numWidth;
    vec4 roi = vec4(roiX, roiY, roiX1, roiY1);
    int number = 0;

    // 年份的4位数字
    if (i == 0) {
      number = year / 1000;
    } else if (i == 1) {
      number = modI(year / 100, 10);
    } else if (i == 2) {
      number = modI(year / 10, 10);
    } else if (i == 3) {
      number = modI(year, 10);
    }
    // 第一个横杠
    else if (i == 4) {
      roiX = startPos + numGap * float(i) - slashOffset;
      roiX1 = roiX + numWidth;
      float tempRoiX = roiX + 0.001;
      float tempRoiY = roiY;
      roi = vec4(tempRoiX, tempRoiY, roiX1, roiY1);
      retCol += Slash(uv, slash_scale, roi, fontCol);
      continue;
    }
    // 月份的2位数字
    else if (i == 5) {
      roiX = startPos + numGap * float(i - 1) + slashWidth + 0.005;
      number = month / 10;
    } else if (i == 6) {
      roiX = startPos + numGap * float(i - 1) + slashWidth + 0.005;
      number = modI(month, 10);
    }
    // 第二个横杠
    else if (i == 7) {
      roiX = startPos + numGap * float(i - 1) + slashWidth - slashOffset + 0.01;
      roiX1 = roiX + numWidth;
      float tempRoiX = roiX - 16.0 / 10000.0;
      float tempRoiY = roiY;
      roi = vec4(tempRoiX, tempRoiY, roiX1, roiY1);
      retCol += Slash(uv, slash_scale, roi, fontCol);
      continue;
    }
    // 日期的2位数字
    else if (i == 8) {
      roiX = startPos + numGap * float(i - 2) + slashWidth * 2.0 + 0.015;
      number = day / 10;
    } else if (i == 9) {
      roiX = startPos + numGap * float(i - 2) + slashWidth * 2.0 + 0.015;
      number = modI(day, 10);
    }

    roiX1 = roiX + numWidth;
    roi = vec4(roiX, roiY, roiX1, roiY1);
    retCol += Digital(uv, scale_val, numHeight, number, roi, fontCol);
  }
  return retCol;
}

