#define PI 3.14159265358979323846

vec2 rotateFunc(vec2 uv, vec2 center, float theta) {
  vec2 temp;
  temp.x = dot(vec2(cos(theta), -sin(theta)), uv - center);
  temp.y = dot(vec2(sin(theta), cos(theta)), uv - center);
  return temp + center;
}
vec2 rotateFunc2(vec2 uv, vec2 center, float theta) {
  vec2 temp;
  temp.x = dot(vec2(cos(theta), -sin(theta)), uv - center);
  temp.y = dot(vec2(sin(theta), cos(theta)), uv - center);
  return temp;
}

vec4 mixFunc(vec4 back, vec4 overlap, float alp) {
  float invAlp = 1.0 - alp;
  vec4 ret = back;

  if (alp > 0.0) {
    ret.x = overlap.x + back.x * invAlp;
    ret.y = overlap.y + back.y * invAlp;
    ret.z = overlap.z + back.z * invAlp;
    ret.a = alp + back.a * invAlp;
  }

  return ret;
}

int modI(int a, int b) {
  return (a) - ((a) / (b)) * (b);
}

float modF(float a, float b) {
  return (a)-floor((a) / (b)) * (b);
}

int maxI(int a, int b) {
  return a > b ? a : b;
}

float maxF(float a, float b) {
  return a > b ? a : b;
}

vec2 maxVec2(vec2 a, vec2 b) {
  return vec2((a.x > b.x ? a.x : b.x), (a.y > b.y ? a.y : b.y));
}

vec2 maxVec2F(vec2 a, float b) {
  return vec2((a.x > b ? a.x : b), (a.y > b ? a.y : b));
}

int minI(int a, int b) {
  return a < b ? a : b;
}

float minF(float a, float b) {
  return a < b ? a : b;
}

vec2 minVec2(vec2 a, vec2 b) {
  return vec2((a.x < b.x ? a.x : b.x), (a.y < b.y ? a.y : b.y));
}

vec2 minVec2F(vec2 a, float b) {
  return vec2((a.x < b ? a.x : b), (a.y < b ? a.y : b));
}

float RightshiftOperation(float a, int b) {
  float m = 1.0;
  for (int i = 0; i < b; i++) {
    m *= 2.0;
  }
  return floor(a / m);
}

float LeftshiftOperation(float a, int b) {
  float m = 1.0;
  for (int i = 0; i < b; i++) {
    m *= 2.0;
  }
  return floor(a * m);
}

float truncation(float a, int b) {
  return modF((a), float(b));
}

vec4 calColor(int color) {
  float color_red = truncation(RightshiftOperation(float(color), 16), 256);
  float color_green = truncation(RightshiftOperation(float(color), 8), 256);
  float color_blue = truncation(float(color), 256);
  vec4 colors = vec4(color_blue, color_green, color_red, 255.0) / 255.0;
  return colors;
}

vec4 Digital(vec2 tc, vec2 scale, float num_height, int number, vec4 roi, vec3 color) {
  vec2 uv = tc;
  uv.y = 1.0 - uv.y;
  uv.y += num_height * float(number);
  uv *= scale;
  uv -= vec2(roi.x, roi.y) * scale;
  uv = fract(uv);
  vec4 retCol = INPUT2(uv);
  retCol.rgb = color.rgb * retCol.a;

  float matt = step(roi.x, tc.x) * step(tc.x, roi.z) * step(roi.y, tc.y) * step(tc.y, roi.w);
  retCol *= matt;

  return retCol;
}

vec4 Colon(vec2 tc, vec2 scale, vec4 roi, vec3 color) {
  vec2 uv = tc;
  uv.y = 1.0 - uv.y;
  uv *= scale;
  uv -= vec2(roi.x, roi.y) * scale;
  uv = fract(uv);
  vec4 retCol = INPUT3(uv);
  retCol.rgb = color.rgb * retCol.a;

  float matt = step(roi.x, tc.x) * step(tc.x, roi.z) * step(roi.y, 1.0 - tc.y) * step(1.0 - tc.y, roi.w);
  retCol *= matt;

  return retCol;
}

vec4 TextureDigital(vec2 uv, vec2 iResolution, int iHour, int iMinute, int iSecond, float iGlobalTime, vec3 fontCol,
                    float speed) {
  float prop = iResolution.x / iResolution.y;
  float imgProp = 60.0 / 1200.0;
  float colonProp = 60.0 / 120.0;

  int totalTime = int(PREFIX(total_time) * PREFIX(frame_rate));
  float speed_globalTime = iGlobalTime * speed;
  int changeTime = int(floor(speed_globalTime * 100.0));
  int curTime = changeTime;
  curTime = maxI(curTime, 0);

  // 计算基础时间和增量时间
  int base_hours = iHour;
  int base_minutes = iMinute;
  int base_seconds = iSecond;

  int add_hours = maxI(changeTime / 100 / 3600, 0);
  int add_minutes = maxI(modI(changeTime / 100 / 60, 60), 0);
  int add_seconds = maxI(modI(changeTime / 100, 60), 0);

  // 合并时间并处理进位
  int total_seconds = base_seconds + add_seconds;
  int carry_minutes = total_seconds / 60;
  int seconds = modI(total_seconds, 60);

  int total_minutes = base_minutes + add_minutes + carry_minutes;
  int carry_hours = total_minutes / 60;
  int minutes = modI(total_minutes, 60);

  int hours = modI(base_hours + add_hours + carry_hours, 24);

  float numWidth = (0.1 - 3.0 / 10000.0) * (10.0 / 20.0);
  float numHeight = numWidth * 2.0 * prop;
  float numGap = numWidth + 0.005;
  float colonOffset = 0.015;
  float colonWidth = numGap - colonOffset * 2.0;

  float startPos = 0.305 - 18.0 / 10000.0;
  float roiY = 0.5 - numHeight * 0.5;
  float roiY1 = roiY + numHeight;

  vec2 scale_val = vec2(20.0, 20.0 * imgProp * (iResolution.y / iResolution.x));
  vec2 colon_scale = vec2(20.0, 20.0 * colonProp * (iResolution.y / iResolution.x));

  vec4 retCol = vec4(0.0);
  for (int i = 0; i < 8; ++i) {
    float roiX = startPos + numGap * float(i);
    float roiX1 = roiX + numWidth;
    vec4 roi = vec4(roiX, roiY, roiX1, roiY1);
    int number = 0;
    if (i == 0) {
      number = hours / 10;
    } else if (i == 1) {
      number = modI(hours, 10);
    } else if (i == 2) {
      roiX = startPos + numGap * float(i) - colonOffset;
      roiX1 = roiX + numWidth;
      float tempRoiX = roiX + 0.001;
      float tempRoiY = roiY + 0.003 * iResolution.x / iResolution.y;
      roi = vec4(tempRoiX, tempRoiY, roiX1, roiY1);
      retCol += Colon(uv, colon_scale, roi, fontCol);
      continue;
    } else if (i == 3) {
      roiX = startPos + numGap * float(i - 1) + colonWidth + 0.005;
      number = minutes / 10;
    } else if (i == 4) {
      roiX = startPos + numGap * float(i - 1) + colonWidth + 0.005;
      number = modI(minutes, 10);
    } else if (i == 5) {
      roiX = startPos + numGap * float(i - 1) + colonWidth - colonOffset + 0.01;
      roiX1 = roiX + numWidth;
      float tempRoiX = roiX - 16.0 / 10000.0;
      float tempRoiY = roiY + 0.003 * iResolution.x / iResolution.y;
      roi = vec4(tempRoiX, tempRoiY, roiX1, roiY1);
      retCol += Colon(uv, colon_scale, roi, fontCol);
      continue;
    } else if (i == 6) {
      roiX = startPos + numGap * float(i - 2) + colonWidth * 2.0 + 0.015;
      number = seconds / 10;
    } else if (i == 7) {
      roiX = startPos + numGap * float(i - 2) + colonWidth * 2.0 + 0.015;
      number = modI(seconds, 10);
    }
    roiX1 = roiX + numWidth;
    roi = vec4(roiX, roiY, roiX1, roiY1);
    retCol += Digital(uv, scale_val, numHeight, number, roi, fontCol);
  }
  return retCol;
}

