float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
	vec2 p1 = vec2(p.x, p.y);
	vec2 p2 = vec2(p.z, p.w);
    float mX1 = p1.x;
    float mY1 = p1.y;
    float mX2 = p2.x; 
    float mY2 = p2.y;
  if (mX1 == mY1 && mX2 == mY2)
    return aX; 
  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

float normpdf(float x, float sigma){
	return 0.39894 * exp(-0.5 * x * x / (sigma * sigma)) / sigma;
}

vec4 motionBlur(vec2 tc, vec2 direction, float blur) {
	float sigma = 28.0;
	float weight = normpdf(0.0, sigma);
	vec4 retCol = INPUT(tc);
	retCol *= weight;
	float sum = weight;
	float radius = 0.03 * blur;

	for(float j = 1.0; j < 21.0; j += 1.0)
	{
		weight = normpdf(j / 10.0 * 25.0, sigma);
		float offset = radius * j;
		vec2 uv = tc + direction * offset;
		retCol += INPUT(uv) * weight;
		sum += weight;

		uv = tc - direction * offset;
		retCol += INPUT(uv) * weight;
		sum += weight;
	}

	retCol /= sum;
	retCol = clamp(retCol, 0.0, 1.0);
	return retCol;
}

float easeOutBounce1(float x){
  float n1 = 7.5625;
  float d1 = 2.75;

  if (x < 1.0 / d1) {
      return n1 * x * x;
  } else if (x < 2.0 / d1) {
      x -= 1.5 / d1;
      return n1 * x * x + 0.75;
  } else if (x < 2.5 / d1) {
      x -= 2.25 / d1;
      return n1 * x * x + 0.9375;
  } else {
      x -= 2.625 / d1;
      return n1 * x * x + 0.984375;
}
}

vec4 FUNCNAME(vec2 tc) {
    float global_time  = PREFIX(global_time);
    float total_time  = PREFIX(total_time);
    float process = global_time / total_time;
    float blur = (PREFIX(Blur) / 100.0 ) / 5.0;
    float speed = 1.0 - PREFIX(Speed) / 150.0;
    float alpha = INPUT(tc).a;
    float strength = 1.2;
    float x_strength = 1.1;
    float y_strength = 1.2;
    float shake = 0.0;
    float scale = 1.0;
    vec2 center = vec2(0.5, 0.3);

    vec2 uv = tc; 
    if(process < speed)
    {
        float first_stage_process = clamp(global_time / (total_time * speed), 0.0, 1.0);
        vec4 p = vec4(0.0 ,1.0, 1.0, 1.0);
        first_stage_process = easeOutBounce1(first_stage_process);

        blur -= first_stage_process * blur;
        scale -= first_stage_process * (scale - 1.0);
        if(blur != 0.0)
        {
          shake = sin(global_time * 2.0) * 0.001;
          alpha = alpha * (1.0 + (1.0 - first_stage_process));
        }
        else
        {
          alpha = INPUT(tc).a;
        }

        center = mix(vec2(0.5, 0.0),vec2(0.5, 0.5),first_stage_process);
        uv -= center;
        uv *= scale;
        uv.x += shake;
        uv.y /=  y_strength - (y_strength - 1.0) * first_stage_process;
        uv += center;
    }else
    {
        blur = 0.0;
        alpha = INPUT(tc).a;
    }

    vec2 direction = vec2(0.0, -1.0);
    vec4 fragColor = motionBlur(uv, direction, blur);
    fragColor.rgb *= alpha;
    return fragColor;
}

#define edgeMax 0.888
#define edgeMin 0.288

float S;

vec4 rgb2cmyk(vec3 color)
{
	float maxVal = max(max(color.r, color.g), color.b);
	return min(vec4(color.rgb / maxVal, maxVal), 1.0);
}

vec3 cmyk2rgb(vec4 color)
{
	return color.rgb * color.a;
}

vec2 makeGrid(vec2 tc)
{
	return tc - mod(tc,S);
}

vec4 sm(vec4 co)
{
	return smoothstep(edgeMax - edgeMin, edgeMax + edgeMin, co);
}

vec4 tone2(vec2 fc, mat2 m)
{
	vec2 smp = (makeGrid(m*fc) + 0.5*S) * m;
	float s = min(length(fc-smp) / (1.48*0.5*S), 1.0);
    vec3 texc = INPUT((smp + 0.5 * iResolution.xy) / iResolution.xy).rgb;
    texc = pow(texc, vec3(2.2));
	vec4 color = rgb2cmyk(texc);
	return color + s;
}

mat2 rt(float r)
{
	float cr = cos(r);
	float sr = sin(r);
	return mat2(
		cr,-sr,
		sr,cr
	);
}

vec4 tone(vec2 fragCoord, float iGlobalTime, float speed, float size)
{
    vec4 fragColor = vec4(1.0);
    float theta = speed*0.333*iGlobalTime;
    S = size;

	vec2 center = fragCoord.xy - 0.5 * iResolution.xy;

	mat2 mc = rt(theta + radians(15.0));
	mat2 mm = rt(theta + radians(75.0));
	mat2 my = rt(theta);
	mat2 mk = rt(theta + radians(45.0));

	vec3 color = cmyk2rgb(sm(vec4(
		tone2(center, mc).r,
		tone2(center, mm).g,
		tone2(center, my).b,
		tone2(center, mk).a
	)));

    color = pow(color, vec3(1.0/2.2));
	fragColor = vec4(color, 1.0);
    return fragColor;
