vec4 mixFunc(vec4 back, vec4 overlap, float alp){

	float invAlp = 1.0 - alp;
	vec4 ret = back;

	if(alp > 0.0){
		ret.x = overlap.x + back.x * invAlp;
		ret.y = overlap.y + back.y * invAlp;
		ret.z = overlap.z + back.z * invAlp;
		ret.a = alp + back.a * invAlp;
	}

	return ret;	
}

