vec4 motionBlur(vec2 _st, vec2 dir, int imgIndex) {
    vec2 texCoord = _st.xy;
    vec4 color = vec4(0.0);
    float total = 0.0;
    float offset = rand(texCoord);

    float iterNum = 20.0;
    for (float t = 0.0; t <= iterNum; t += 1.0) {
        float percent = (t + offset) / iterNum;
        float weight = 4.0 * (percent - percent * percent);
        vec2 curUV = texCoord + dir * percent;
        float matt = inBound(curUV);
        curUV = fract(curUV);
		vec4 imgCol = vec4(0.0);
        if(imgIndex == 5)
            imgCol = INPUT5(curUV);
        else if(imgIndex == 4)
            imgCol = INPUT4(curUV);
        else if(imgIndex == 3)
            imgCol = INPUT3(curUV);
        else if(imgIndex == 2)
            imgCol = INPUT2(curUV);

		imgCol = imgCol.a * vec4(255.0)/255.0;
        color += imgCol*weight*matt;
        total += weight;
    }
    color /= total;
    return color;
}

float calFlickerTime(float x, float speed){
    float frame_interval = 0.04*speed;
    float frame_num = floor(1.0 / frame_interval);
    float frame_halfNum = ceil(float(frame_num) / 2.0);
    float cur_frameIndex = floor(x / frame_interval + 0.5); 

    if((cur_frameIndex == frame_halfNum + 0.0) || (cur_frameIndex == frame_halfNum + 2.0) ||
       ( (cur_frameIndex == frame_num - 4.0)||(cur_frameIndex == frame_num - 2.0)) && ((frame_num - 4.0) > (frame_halfNum + 2.0) )
       ){
       return 1.0;
    }else{
        return 0.0;
    }
}

vec4 draw_arrow(vec2 uv, vec2 scale, vec2 center, vec2 start_offset, vec2 end_offset, vec4 arrowCol,vec4 arrowCol2, float iTime, float need_blur, float speed){
    vec2 p1 = vec2(0.0, 0.8);
    vec2 p2 = vec2(0.36, 1.0);  
    float blurTime = 1.0-calBezierTime(p1, p2, iTime);
    p1 = vec2(0.0, 1.0);
    p2 = vec2(0.0, 1.0);
    float moveTime = calBezierTime(p1, p2, iTime);
    moveTime = calBezierTime(p1, p2, moveTime);
    vec2 cur_offset = start_offset + (end_offset - start_offset)*moveTime;
    center += cur_offset;
	uv = (uv - center) / (scale + 0.001) + center;
	uv -= cur_offset;
	float matt = 0.0;
	vec4 retColor = INPUT5(uv);
    float flicker_time = calFlickerTime(iTime, speed);
    if(need_blur == 0.0){				
		matt = inBound(vec2(uv.x, uv.y));
	}else{
		vec2 dir = vec2(0.3, 0.0)*blurTime;
    	retColor = motionBlur(uv, dir, 5);
		matt = inBound(vec2(uv.x+0.1, uv.y));
	}    
	if(flicker_time == 0.0){
        retColor = retColor.a * arrowCol;
    }else{
        retColor = retColor.a * arrowCol2;
    }
	retColor *= matt;
	return retColor;
}

vec4 draw_number_arrow(vec2 uv, vec2 num_center, vec2 num_scale, vec2 num_offset, vec4 paintCol, 
					   vec2 arrow_center, vec2 arrow_scale, vec2 arrow_offset, vec2 arrow2_offset,
                       vec4 arrowColor,vec4 arrowColor2, float iGlobalTime, float speed){
	vec2 num_uv = uv;
	vec2 arrow_uv = uv;
	/* number */
	vec4 numCol = vec4(0.0);
	vec4 numBlurCol = vec4(0.0);
	vec2 p1 = vec2(0.0, 1.0);
	vec2 p2 = vec2(0.0, 1.0);
	float fract_time = fract(iGlobalTime);
	float bezier_time = calBezierTime(p1, p2, fract_time);
    float motionBlur_time = bezier_time;
	bezier_time = calBezierTime(p1, p2, bezier_time);
	vec2 num_scale1 = num_scale;
	vec2 num_uv1 = (num_uv - num_center) / (num_scale1 + 0.001) + num_center;   
    num_uv1 -= num_offset;
	vec2 num_scale2 = num_scale*(1.0+2.0*(1.0-bezier_time));
	vec2 num_uv2 = (num_uv - num_center) / (num_scale2 + 0.001) + num_center;   	
    num_uv2 -= num_offset;
    vec2 blurUV = 2.0*num_uv2-1.0;
    blurUV.x = calBezierTime(p1, p2,abs(blurUV.x))*sign(blurUV.x);
	blurUV.y = calBezierTime(p1, p2,abs(blurUV.y))*sign(blurUV.y);
    vec2 blurSpeed = vec2(0.1, 0.1)*blurUV*(1.0-bezier_time);
	/* number */

	/* arrow */
	vec2 arrow_startOffset = vec2(-0.52, arrow_offset.y);
	vec2 arrow_endOffset = arrow_offset;
	vec2 arrow_startOffset2 = vec2(-0.52, arrow2_offset.y);
	vec2 arrow_endOffset2 = arrow2_offset;
	vec2 arrow_center1 = arrow_center + arrow_offset;
	vec2 arrow_center2 = arrow_center + arrow2_offset;
    float need_blur = 1.0;
	/* arrow */

	float three_internal = 0.18;
	float two_internal = 0.15;
	float one_internal = 0.14;
    if(iResolution.x<iResolution.y){
        float prop = iResolution.y/iResolution.x;
        three_internal *= prop;
        two_internal *= prop;
        one_internal *= prop;
    }
	if(iGlobalTime == 0.0){
		arrow_endOffset += vec2(-0.52, 0.0);
		arrow_endOffset2 += vec2(-0.52, 0.0);
		// numCol = vec4(0.0);
	}else if( 0.0 < iGlobalTime && iGlobalTime < 1.0){
		arrow_endOffset += vec2(-three_internal, 0.0);
		arrow_endOffset2 += vec2(three_internal, 0.0);
		// numCol = vec4(INPUT4(num_uv2).a);
		numBlurCol = motionBlur(num_uv2, blurSpeed, 4);
	}else if(1.0 <= iGlobalTime && iGlobalTime < 2.0){
		arrow_endOffset += vec2(-two_internal, 0.0);
		arrow_endOffset2 += vec2(two_internal, 0.0);
		// numCol = vec4(INPUT3(num_uv2).a);
		numBlurCol = motionBlur(num_uv2, blurSpeed, 3);
	}else if(2.0 <= iGlobalTime && iGlobalTime < 3.0){
		arrow_endOffset += vec2(-one_internal+0.01, 0.0);
		arrow_endOffset2 += vec2(one_internal, 0.0);
		// numCol = vec4(INPUT2(num_uv2).a);
		numBlurCol = motionBlur(num_uv2, blurSpeed, 2);
	}else{
		arrow_startOffset = arrow_offset + vec2(-one_internal+0.01, 0.0);
		arrow_startOffset2 = arrow2_offset + vec2(one_internal, 0.0);
		arrow_endOffset += vec2(-one_internal+0.01, 0.0);
		arrow_endOffset2 += vec2(one_internal, 0.0);
		num_uv2 = num_uv1;
		// numCol = vec4(INPUT2(num_uv1).a);
        numBlurCol = vec4(INPUT2(num_uv1).a);
		need_blur = 0.0;
	}	
	float matt = inBound(num_uv2);
	numBlurCol *= paintCol * matt;

	vec4 arrowCol = draw_arrow(arrow_uv, arrow_scale, arrow_center1, arrow_startOffset, arrow_endOffset, arrowColor, arrowColor2, fract_time, need_blur, speed);
	vec4 arrowCol2 = draw_arrow(arrow_uv, arrow_scale, arrow_center2, arrow_startOffset2, arrow_endOffset2, arrowColor, arrowColor2, fract_time, need_blur, speed);
	vec4 retCol = mixFunc(arrowCol, numBlurCol, numBlurCol.a);
	retCol = mixFunc(arrowCol2, retCol, retCol.a);
	return retCol;
}

