#define PI 3.14

float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
	vec2 p1 = vec2(p.x, p.y);
	vec2 p2 = vec2(p.z, p.w);
    float mX1 = p1.x;
    float mY1 = p1.y;
    float mX2 = p2.x; 
    float mY2 = p2.y;
  if (mX1 == mY1 && mX2 == mY2)
    return aX; 

  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

vec3 getTexure(vec2 uv){
	return INPUT(uv).rgb;    
}

mat2 rotate(float a) 
{
    float s = sin(a);
    float c = cos(a);
    return mat2(c,-s,s,c);
}

vec3 getBloom(vec2 coord, float blur, float position_x, float position_y, float angle){
    const int samples = 4;
    vec3 color = vec3(0.0);
    int weight = 0;
    float size = blur; 
    for (int i = 0; i < samples; i++){
        vec2 coord0 = coord + (rotate(angle * PI) * vec2(i,i) * position_x * size / float(samples) / iResolution.xy);
        vec2 coord1 = coord + (rotate(angle * PI) * vec2(-i,-i) * position_x * size / float(samples) / iResolution.xy);
        vec2 coord2 = coord + (rotate(angle * PI) * vec2(-i,i) * position_y * size / float(samples) / iResolution.xy);
        vec2 coord3 = coord + (rotate(angle * PI) * vec2(i,-i) * position_y * size / float(samples) / iResolution.xy);
        color += getTexure(coord0);
        color += getTexure(coord1);
        color += getTexure(coord2);
        color += getTexure(coord3);
        weight++;
    }
    color /= float(weight);
    color = pow(color,vec3(1.0));
    return (color / 4.0);
}

