float Circle(vec2 iuv, float iprocess, float iangle, float ialpha) {
    vec2 st = iuv;
    st -= vec2(0.5, 0.5);
    st.x *= iResolution.x / iResolution.y;

    float radius = 1.5;
    float PI = 3.14159265359;
    float TAU = 2.0 * PI;

    float d = length(st);
    float angle = atan(st.y, st.x);
    angle = angle < 0.0 ? angle + TAU : angle;
    angle = mod(angle + TAU*iangle, TAU);
    angle = TAU - angle;

    float cutoff = iprocess * TAU;
    float aa = 0.0001 * ialpha;

    float fadeProgress = smoothstep(0.7, 1.0, iprocess);

    float startFade = 1.0;
    float endFade = 1.0 - smoothstep(max(cutoff, 0.0) - aa, cutoff + aa, angle);

    float gradientMask = startFade * endFade;
    float circle = smoothstep(radius + aa, radius - aa, d);
    float alpha = circle * gradientMask;

    return alpha;
}

vec2 RotateFunc(vec2 iuv, float irotation) {
    vec2 rotateUV = iuv * iResolution;
    vec2 center = vec2(0.5);
    float rotation = irotation;
    rotateUV -= center * iResolution;
    vec4 rotateMat = vec4(cos(rotation), -sin(rotation), sin(rotation), cos(rotation));
    float new_x = rotateUV.x*rotateMat.x + rotateUV.y*rotateMat.z;
    float new_y = rotateUV.x*rotateMat.y + rotateUV.y*rotateMat.w;
    rotateUV = vec2(new_x, new_y);
    rotateUV += center * iResolution;
    rotateUV = rotateUV / iResolution;

    return rotateUV;
}

vec4 RadialBlur(vec2 iuv, float istrength)
{	
    vec2 BLUR_CENTER = vec2(0.5, 0.5);
    int NUM_SAMPLES = 25;
    float WEIGHT = 0.1 * istrength;

    vec2 currentPosition = iuv;
    vec2 originalPosition = currentPosition;

    vec2 toCenter = BLUR_CENTER - currentPosition;
    vec2 stepSize = toCenter / float(NUM_SAMPLES);

    vec4 color = INPUT(currentPosition);

    for (int i = 0; i < NUM_SAMPLES; i++) {
    	currentPosition += stepSize * WEIGHT;
        vec3 smp = INPUT(currentPosition).rgb;
        color.rgb += smp;
    }

    color.rgb /= vec3(float(NUM_SAMPLES) + 1.0);


    return color;
}

vec4 RotateBlur(vec2 iuv, float istrength)
{	
    vec2 BLUR_CENTER = vec2(0.5, 0.5);
    int NUM_SAMPLES = 25;
    float WEIGHT = 0.2 * istrength;

    float stepSize = WEIGHT / float(NUM_SAMPLES);
    float rotation = 0.0;

    vec4 color = INPUT(iuv);

    for (int i = 0; i < NUM_SAMPLES; i++) {
    	rotation += stepSize;
        vec3 smp = INPUT(RotateFunc(iuv, rotation)).rgb;
        color.rgb += smp;
    }

    color.rgb /= vec3(float(NUM_SAMPLES) + 1.0);


    return color;
}

float Random(vec2 st, float time) {
  return fract(sin(dot(st.xy, vec2(12.9898, 78.233)) + time) * 43758.5453123);
}

