        layer_right_uv.x -= cos(iGlobaltime*100.0*3.1415926*sub_pro) * 0.025 * zoom_pro;
        layer_right_uv.y += sin(iGlobaltime*100.0*3.1415926*sub_pro) * 0.025 * zoom_pro;
        mask_right = Circle(layer_right_uv, 0.25, 0.875, sub_pro);
        vec4 layer_right = INPUT(layer_right_uv) * mask_right;

        fragOutCol.rgb = mix(fragOutCol.rgb, layer_top.rgb + layer_bottom.rgb + layer_left.rgb + layer_right.rgb, min(1.0, mask_top + mask_bottom + mask_left + mask_right));
    } else {
        fragOutCol = INPUT(uv);
    }

    return fragOutCol;
}

float A(float aA1, float aA2) {
    return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}
float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
      float currentSlope = GetSlope(aGuessT, mX1, mX2);
      if (currentSlope == 0.0)
          return aGuessT;
      float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
      aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

