vec4 FUNCNAME(vec2 tc) {
	int Opacity = PREFIX(Opacity);

	vec4 origCol = INPUT1(tc);
	vec4 depthCol = INPUT2(tc);
	vec4 retCol = origCol;

	vec2 uv = vec2(tc.x, 1.0 - tc.y);

	vec2 texSize = vec2(720.0, 480.0);
	vec2 scale = vec2(1.0, iResolution.y / iResolution.x * (texSize.x / texSize.y));
	if(iResolution.y > iResolution.x){
		scale = vec2(iResolution.x / iResolution.y * (texSize.y / texSize.x), 1.0);
	}

	float layer1 = 0.1;
	float layer2 = 0.4;
	float feather = 0.02;
	float matt = 1.0;
	float factor = 1.0;

	if(depthCol.g < layer1){
		factor = 3.0;
		matt = smoothstep(layer1, layer1 - feather, depthCol.g);
	}else if(depthCol.g < layer2){
		matt = smoothstep(layer1, layer1 + feather, depthCol.g) * smoothstep(layer2, layer2 - feather, depthCol.g);
	}else{
		factor = 0.5;
		matt = smoothstep(layer2, layer2 + feather, depthCol.g);
	}

	uv = (uv - vec2(0.5)) * scale * factor + vec2(0.5);

	uv = fract(uv);
	vec4 snowCol = INPUT3(uv);
	snowCol *= matt;
	retCol.rgb = mix(retCol.rgb, snowCol.rgb, snowCol.a);
	retCol.rgb = mix(origCol.rgb, retCol.rgb, float(Opacity) / 100.0);

	retCol.a = origCol.a;
	retCol.rgb *= retCol.a;

    return retCol;
}

