    float uv_y = tc.y * iResolution.y;
    float noise_wave_1 = snoise(vec2(uv_y * 0.1, iGlobalTime * Speed * 15.0)) * (strength * _Amount * 3.0);
    float noise_wave_2 = snoise(vec2(uv_y * 0.08, iGlobalTime * Speed * 5.0)) * (strength * _Amount * 5.0);
    float noise_wave_3 = snoise(vec2(uv_y * 0.22, iGlobalTime * Speed * 10.0)) * (strength * _Amount * 4.0);
    float noise_wave_x = noise_wave_1 * noise_wave_2 * noise_wave_3 / iResolution.x;
    float uv_x = tc.x + noise_wave_x;

