mat2 rotate(float a) // Rotation matrix
{
    float s = sin(a);
    float c = cos(a);
    return mat2(c,-s,s,c);
}

vec2 twirl(vec2 uv, vec2 center, float range, float angle)
{
    float d = distance(uv, center);
    uv -= center;
    float nor = clamp(d/range, 0., 1.);
    d = (1.-pow(abs(sin(PI*nor/2.)), .5)) * angle;
    uv *= rotate(d);
    uv += center;
    return uv;
}

