vec2 computeUV(vec2 uv, float k, float kcube) {
    vec2 t = uv - 0.5;
    float r2 = t.x * t.x + t.y * t.y;
	float f = 0.0;

    if( kcube == 0.0){
        f = 1.0 + r2 * k;
    }else{
        f = 1.0 + r2 * ( k + kcube * sqrt( r2 ) );
    }

    vec2 nUv = f * t + 0.5;
    nUv.y = 1.0 - nUv.y;

    return nUv;
}

