vec2 rotateFunc(vec2 uv, vec2 center, float theta, vec2 iResolution)
{
    vec2 uv0 = uv - center;
    uv0.y *= iResolution.y / iResolution.x;
    vec2 temp;
    temp.x = dot(vec2(cos(theta), -sin(theta)), uv0);
    temp.y = dot(vec2(sin(theta), cos(theta)), uv0);
    temp.y /= iResolution.y / iResolution.x;
    temp += center;
    return temp;
}

float stepFunc(vec2 tc)
{
    return step(0.0, tc.x) * step(tc.x, 1.0) * step(0.0, tc.y) * step(tc.y, 1.0);
}

float smoothstepFunc(vec2 tc)
{
    float feather = 0.005;
    return (smoothstep(0.12, 0.12 + feather, tc.x) * smoothstep(0.88, 0.88 - feather, tc.x) 
           * smoothstep(0.0, feather, tc.y) * smoothstep(0.98, 0.98 - feather, tc.y));
}

float smoothstepFunc2(vec2 tc)
{
    float feather = 0.005;
    return (smoothstep(0.128, 0.128 + feather, tc.y) * smoothstep(0.86, 0.86 - feather, tc.y) 
           * smoothstep(0.0, feather, tc.x) * smoothstep(0.98, 0.98 - feather, tc.x));
}

float smoothstepFunc3(vec2 tc)
{
    float feather = 0.005;
    return (smoothstep(0.0, 0.0 + feather, tc.y) * smoothstep(1.0, 1.0 - feather, tc.y) 
           * smoothstep(0.105, 0.105 + feather, tc.x) * smoothstep(0.87, 0.87 - feather, tc.x));
}

