        mid_matt = smoothstepFunc2(mid_uv);
        right_uv = rotate_tc + vec2(-0.018, 0.71);
        right_matt = smoothstepFunc2(right_uv);
    }else{
        if(iResolution.x / iResolution.y < 16.0 / 9.0){
            scale = 0.69;
