    vec4 midCol = INPUT1(mid_uv) * mid_matt;
    vec4 rightCol = INPUT1(right_uv) * right_matt;

    vec4 retCol = leftCol + midCol + rightCol;
    float alpha = left_matt + mid_matt + right_matt;
    retCol.rgb = mix(backCol.rgb, retCol.rgb, alpha);
    retCol.rgb = mix(retCol.rgb, filmCol.rgb, filmCol.a * float(Opacity) / 100.0);
    retCol.a = 1.0;

