// Layering particles to imitate 3D view
vec3 layeredParticles(in vec2 uv, in float sizeMod, in float alphaMod,
                      in int layers, vec3 colors[3], int quantity) {
  vec3 particles = vec3(0);
  float size = 1.0;
  float alpha = 1.0; //0.1 + pow(smoothstep(-1.0 , 1.5, uv.y), 0.8);
  vec2 offset = vec2(0.0);
  vec2 noiseOffset = vec2(0.0);
  vec2 bokehUV;

  float ty = smoothstep(.0, 1.8, uv.y);
  int addition_layers = int(ty * 3.);
  layers += addition_layers;

  for (int i = 0; i < layers; i++) {
    // Particle noise movement
    // noiseOffset = (noise2_2(uv * size * 2.0 + 0.5) - 0.5) * 0.15;

    // UV with applied movement
    bokehUV = (uv * size + time * movement_direction * movement_speed) +
              offset + noiseOffset;

    vec3 color = colors[int(mod(float(i), float(quantity)))];

    vec3 out_color = fireParticles(bokehUV, uv, color) * alpha * (1.0 - (float(i) / float(layers)));
    // Adding particles
    particles += out_color;

    // Moving uv origin to avoid generating the same particles
    offset += hash2_2(vec2(size, size)) * 10.0;

    alpha *= alphaMod;
    size *= sizeMod;
  }

  return particles;
}

