	// float position_y = (PREFIX(Position_Y) - 50.0) / 100.0;
    float position_y = (PREFIX(Position_Y) + 110.0) / 4.0;
    position_y = (position_y - 30.0) / 40.0;

    float time_speed = PREFIX(Speed) * 2.0 / 100.0;
    float scale = (PREFIX(Scale) + 15.0) * 2.0 / 100.0 + 0.001;

    float iTime = PREFIX(global_time) * time_speed;
    vec3 c1 = vec3(0.5, 0.0, 0.1);
    vec3 c2 = vec3(0.9, 0.1, 0.0);
    vec3 c3 = vec3(0.2, 0.1, 0.7);
    vec3 c4 = vec3(1.0, 0.9, 0.1) * strength;
    vec3 c5 = vec3(0.1);
    vec3 c6 = vec3(0.9);

    vec2 speed = vec2(1.3, 0.1);
    float shift = 1.77+sin(iTime*2.0)/10.0;
    float alpha = PREFIX(Opacity) * 2.0 / 100.0;
	float dist = 6.0 +sin(iTime*0.4)/ 0.6;
    vec2 fragCoord = (tc - vec2(position_x, position_y)) * iResolution.xy;

    vec2 p = fragCoord.xy / iResolution.xx;
    p -= vec2(0.5, 0.5);
    p *= dist / scale;
    p += vec2(0.5, 0.5);

    p.x -= iTime/1.1;
    float q = fbm(p - iTime * 0.01+1.0*sin(iTime)/10.0);
    float qb = fbm(p - iTime * 0.002+0.1*cos(iTime)/5.0);
    float q2 = fbm(p - iTime * 0.44 - 5.0*cos(iTime)/7.0) - 6.0;
    float q3 = fbm(p - iTime * 0.9 - 10.0*cos(iTime)/30.0) - 4.0;
    float q4 = fbm(p - iTime * 2.0 - 20.0*sin(iTime)/20.0) + 2.0;
    q = (q + qb - q2 -q3  + q4)/3.8;

    vec2 r = vec2(fbm(p + q /2.0 + iTime * speed.x - p.x - p.y), fbm(p + q - iTime * speed.y));
    vec3 c = mix(c1, c2, fbm(p + r)) + mix(c3, c4, r.x) - mix(c5, c6, r.y);
    vec3 color = vec3(c * cos(shift * fragCoord.y / iResolution.y));
    color -= .25;
    color.r *= 1.02;
    vec3 hsv = rgb2hsv(color);
    hsv.y *= hsv.z  * 0.8;
    hsv.z *= hsv.y * 1.3;
    color = hsv2rgb(hsv);
    vec4 fragColor = vec4(color.z, color.y, color.x, alpha);
    // fragColor.rgb *= alpha;

    vec4 bg_color = INPUT1(tc);
    fragColor.rgb = screen(bg_color.rgb,fragColor.rgb) * alpha;

    if(strength == 0.0)
    {
        fragColor = bg_color;
    }
    return fragColor;
}

vec3 mod289(vec3 x) {
	return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec4 mod289(vec4 x) {
	return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec4 permute(vec4 x) {
		 return mod289(((x*34.0)+1.0)*x);
}

vec4 taylorInvSqrt(vec4 r)
{
	return 1.79284291400159 - 0.85373472095314 * r;
}

float snoise(vec3 v)
{ 
	const vec2	C = vec2(1.0/6.0, 1.0/3.0);
	const vec4	D = vec4(0.0, 0.5, 1.0, 2.0);

// First corner
	vec3 i	= floor(v + dot(v, C.yyy) );
	vec3 x0 = v - i + dot(i, C.xxx) ;

// Other corners
	vec3 g = step(x0.yzx, x0.xyz);
	vec3 l = 1.0 - g;
	vec3 i1 = min( g.xyz, l.zxy );
	vec3 i2 = max( g.xyz, l.zxy );

	vec3 x1 = x0 - i1 + C.xxx;
	vec3 x2 = x0 - i2 + C.yyy; // 2.0*C.x = 1/3 = C.y
	vec3 x3 = x0 - D.yyy;			// -1.0+3.0*C.x = -0.5 = -D.y

// Permutations
	i = mod289(i); 
	vec4 p = permute( permute( permute( 
						 i.z + vec4(0.0, i1.z, i2.z, 1.0 ))
					 + i.y + vec4(0.0, i1.y, i2.y, 1.0 )) 
					 + i.x + vec4(0.0, i1.x, i2.x, 1.0 ));


	float n_ = 0.142857142857; // 1.0/7.0
	vec3	ns = n_ * D.wyz - D.xzx;

	vec4 j = p - 49.0 * floor(p * ns.z * ns.z);	//	mod(p,7*7)

	vec4 x_ = floor(j * ns.z);
	vec4 y_ = floor(j - 7.0 * x_ );		// mod(j,N)

	vec4 x = x_ *ns.x + ns.yyyy;
	vec4 y = y_ *ns.x + ns.yyyy;
	vec4 h = 1.0 - abs(x) - abs(y);

	vec4 b0 = vec4( x.xy, y.xy );
	vec4 b1 = vec4( x.zw, y.zw );

	//vec4 s0 = vec4(lessThan(b0,0.0))*2.0 - 1.0;
	//vec4 s1 = vec4(lessThan(b1,0.0))*2.0 - 1.0;
	vec4 s0 = floor(b0)*2.0 + 1.0;
	vec4 s1 = floor(b1)*2.0 + 1.0;
	vec4 sh = -step(h, vec4(0.0));

	vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy ;
	vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww ;

	vec3 p0 = vec3(a0.xy,h.x);
	vec3 p1 = vec3(a0.zw,h.y);
	vec3 p2 = vec3(a1.xy,h.z);
	vec3 p3 = vec3(a1.zw,h.w);

	vec4 norm = 1.0 / sqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
	p0 *= norm.x;
	p1 *= norm.y;
	p2 *= norm.z;
	p3 *= norm.w;

	vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
	m = m * m;
	return 42.0 * dot( m*m, vec4( dot(p0,x0), dot(p1,x1), 
																dot(p2,x2), dot(p3,x3) ) );
	}

float prng(in vec2 seed) {
	seed = fract (seed * vec2 (5.3983, 5.4427));
	seed += dot (seed.yx, seed.xy + vec2 (21.5351, 14.3137));
	return fract (seed.x * seed.y * 95.4337);
}

float noiseStack(vec3 pos,int octaves,float falloff){
	float noise = snoise(vec3(pos));
	float off = 1.0;
	if (octaves>1) {
		pos *= 2.0;
		off *= falloff;
		noise = (1.0-off)*noise + off*snoise(vec3(pos));
	}
	if (octaves>2) {
		pos *= 2.0;
		off *= falloff;
		noise = (1.0-off)*noise + off*snoise(vec3(pos));
	}
	if (octaves>3) {
		pos *= 2.0;
		off *= falloff;
		noise = (1.0-off)*noise + off*snoise(vec3(pos));
	}
	return (1.0+noise)/2.0;
}

vec2 noiseStackUV(vec3 pos,int octaves,float falloff,float diff){
	float displaceA = noiseStack(pos,octaves,falloff);
	float displaceB = noiseStack(pos+vec3(3984.293,423.21,5235.19),octaves,falloff);
	return vec2(displaceA,displaceB);
}

vec3 screen(vec3 s,vec3 d){
    return s + d - s*d;
}

vec4 FUNCNAME(vec2 tc) {
    float PI = 3.1415926535897932384626433832795;
	float time = PREFIX(global_time);
    float aa = INPUT(tc).a * PREFIX(Opacity) * 2.0 / 100.0;
    float bb = PREFIX(Height) * 10.0 / 100.0;
    float cc = PREFIX(Strength) * 2.0 / 100.0;
    float dd = PREFIX(Speed) * 2.0 / 100.0;
    float ee = -1.0 * (PREFIX(Position_X) - 50.0) / 1200.0;
    float ff = (-1.0 * (PREFIX(Position_Y) - 100.0)) / 100.0;
    vec2 fragCoord = (tc + vec2(ee, ff)) * iResolution.xy;

    vec2 resolution = iResolution.xy;
	vec2 offset = vec2(0.5);
	float xpart = fragCoord.x/resolution.x;
	float ypart = fragCoord.y/resolution.y;
    vec4 fragColor = vec4(0.0);
	float clip = 210.0  * bb;
	float ypartClip = fragCoord.y / clip;
	float ypartClippedFalloff = clamp(2.0-ypartClip,0.0,1.0);
	float ypartClipped = min(ypartClip,1.0);
	float ypartClippedn = (1.0-ypartClipped);
	float xfuel = (1.0-abs(2.0*xpart-1.0));//pow(1.0-abs(2.0*xpart-1.0),0.5);
	float timeSpeed = 0.5 * dd;
	float realTime = timeSpeed*time;

	vec2 coordScaled = 0.01*fragCoord - 0.02*vec2(offset.x,0.0);
	vec3 position = vec3(coordScaled,0.0) + vec3(1223.0, 6434.0, 8425.0);
	vec3 flow = vec3(4.1*(0.5-xpart)*pow(ypartClippedn,4.0),-2.0*xfuel*pow(ypartClippedn,64.0),0.0);
	vec3 timing = realTime*vec3(0.0,-1.7,1.1) + flow;
	vec3 displacePos = vec3(1.0,0.5,1.0)*2.4*position+realTime*vec3(0.01,-0.7,1.3);
	vec3 displace3 = vec3(noiseStackUV(displacePos,2, 0.4,0.1),0.0);
	vec3 noiseCoord = (vec3(2.0,1.0,1.0)*position+timing+0.4*displace3)/1.0;

	float noise = noiseStack(noiseCoord,3,0.4);
	float flames = pow(ypartClipped,0.3*xfuel)*pow(noise,0.3*xfuel);
	float f = ypartClippedFalloff*pow(1.0-flames*flames*flames,8.0);
	float fff = f*f*f;
	vec3 fire = 1.5*vec3(fff*fff, fff, f) * cc;
	// smoke
	float smokeNoise = (0.5 +snoise(0.4*position+timing*vec3(1.0,1.0,0.2))/2.0);
	vec3 smoke = vec3(0.3*pow(xfuel,3.0)*pow(ypart,2.0)*(smokeNoise+0.4*(1.0-noise)));

	// sparks
	float sparkGridSize = 30.0;
	vec2 sparkCoord = fragCoord - vec2(2.0 * offset.x, 190.0 * realTime);
	sparkCoord -= 30.0 * noiseStackUV(0.01 * vec3(sparkCoord, 30.0 * time), 1, 0.4, 0.1);
	sparkCoord += 100.0 * flow.xy;
	if (mod(sparkCoord.y/sparkGridSize,2.0)<1.0) sparkCoord.x += 0.5*sparkGridSize;
	vec2 sparkGridIndex = vec2(floor(sparkCoord/sparkGridSize));
	float sparkRandom = prng(sparkGridIndex);
	float sparkLife = min(10.0*(1.0-min((sparkGridIndex.y+(190.0*realTime/sparkGridSize))/(24.0-20.0*sparkRandom),1.0)),1.0);
	vec3 sparks = vec3(0.0);
	if (sparkLife>0.0) 
    {
		float sparkSize = xfuel*xfuel*sparkRandom*0.08;
		float sparkRadians = 999.0*sparkRandom*2.0*PI + 2.0*time;
		vec2 sparkCircular = vec2(sin(sparkRadians),cos(sparkRadians));
		vec2 sparkOffset = (0.5-sparkSize)*sparkGridSize*sparkCircular;
		vec2 sparkModulus = mod(sparkCoord+sparkOffset,sparkGridSize) - 0.5*vec2(sparkGridSize);
		float sparkLength = length(sparkModulus);
		float sparksGray = max(0.0, 1.0 - sparkLength/(sparkSize*sparkGridSize));
		sparks = sparkLife*sparksGray*vec3(1.0,0.3,0.0);
	}

    vec4 bg_color = INPUT(tc);
	vec4 fireColor = vec4(max(fire,vec3(0.0))+smoke,1.0);
    // fragColor = vec4(screen(bg_color.rgb,fireColor.rgb), 1.0);
    fragColor = vec4(screen(bg_color.rgb, fireColor.rgb), 1.0);
	// sfragColor.rgb *= aa;
    return fragColor;
}



