vec2 EdgeFishEye(vec2 uv, float radious, float distortion, float range){
    vec2 uv2 = uv;
    vec2 center = vec2(0.5);
    if(distance(uv, center) <= radious) {
        uv -= center;
        float n = radious;
        float radius = length(uv) ;
        float power = (PI / n) * (distortion / 10.0);
        float AdjustmentFactor = tan(radius * power) * n / tan(n * power);
        uv = normalize(uv) * AdjustmentFactor;
        uv += center;
    }
    float l = length(uv2 - 0.5);
    uv = mix(uv2, uv, pow(smoothstep(0.0, 1.0, l / 0.5), range));
    return uv;
