float softLights(float src, float dst) {
    return dst + (src * 2.0 - 1.0) * (sqrt(dst) - dst);
}
vec4 softLight(vec4 src, vec4 dst) {
    float ColorR = softLights(src.x, dst.x);
    float ColorG = softLights(src.y, dst.y);
    float ColorB = softLights(src.z, dst.z);
    return vec4(ColorR, ColorG, ColorB, 1.0);
}
vec4 softLightByWeight(vec4 src, vec4 dst, float weight) {
    vec4 softlight = softLight(src, dst);
    return mix(clamp(dst,0.0,1.0), clamp(softlight,0.0,1.0), weight);
}

