        float power = (PI / parameter) * (Twist / 10.); // Hyperbola, when the Twist is larger, the value is larger
        uv1 = normalize(uv1) * tan(radius * power) * (parameter / tan(parameter * power));
        uv1.y /= iResolution.y / iResolution.x;
    }
    uv1 += center;

    uv1.x = fract(uv1.x * Size + (1. - Size) * 0.5);
    uv1.y = fract(uv1.y * Size + (1. - Size) * 0.5);
    col = INPUT1(fract(uv1));
    vec4 fragColor = mix(col, sucai, sucai.a);
    return fragColor;
}

