float modF(float a, float b) {
  return (a)-floor((a) / (b)) * (b);
}

float RightshiftOperation(float a, int b) {
  float m = 1.0;
  for (int i = 0; i < b; i++) {
    m *= 2.0;
  }
  return floor(a / m);
}

float truncation(float a, int b) {
  return modF((a), float(b));
}

vec4 CalColor(int color) {
  float color_red = truncation(RightshiftOperation(float(color), 16), 256);
  float color_green = truncation(RightshiftOperation(float(color), 8), 256);
  float color_blue = truncation(float(color), 256);
  vec3 colors = vec3(float(color_blue), float(color_green), float(color_red)) / 255.0;
  return vec4(colors, 1.0);
}

vec2 rotateFunc(vec2 p, float angle) {
  angle = radians(angle);
  return vec2(p.x * cos(angle) - p.y * sin(angle), p.x * sin(angle) + p.y * cos(angle));
}

vec2 sdHexagon(vec2 p, vec2 c, float r, float r2, float edge, float angle) {
  float prop = iResolution.x / iResolution.y;
  c = c * 2.0 - 1.0;
  c.x *= prop;
  p = p * 2.0 - 1.0;
  p.x *= prop;
  p = p - c;
  p = rotateFunc(p, angle);

  float rad = radians(180.0 / edge);
  vec3 k = vec3(-cos(rad), sin(rad), tan(rad));
  if(edge == 5.0){
    p.x = abs(p.x);
    p.y = -p.y;
    k.x = -k.x;
    p -= 2.0 * min(dot(vec2(-k.x, k.y), p), 0.0) * vec2(-k.x, k.y);
    p -= 2.0 * min(dot(vec2(k.x, k.y), p), 0.0) * vec2(k.x, k.y);
    p -= vec2(clamp(p.x, -r * k.z, r * k.z), r);
  }else{
    p = abs(p);
    p -= 2.0 * min(dot(k.xy, p), 0.0) * k.xy;
    p -= vec2(clamp(p.x, -k.z * r, k.z * r), r);
  }
  float d = length(p) * sign(p.y);
  float d1 = smoothstep(0.0, 0.01, d - r2);
  float d2 = smoothstep(0.0, 0.01, d - (r2 + 0.01));
  vec2 result = vec2(sat(d1 - d2), d1);
  return result;
}

vec4 mixFunc(vec4 back, vec4 overlap, float alp) {
  float invAlp = 1.0 - alp;
  vec4 ret = back;

  if (alp > 0.0) {
    ret.xyz = overlap.xyz + back.xyz * invAlp;
    ret.a = alp + back.a * invAlp;
  }
  return ret;
}

float generateNoise(vec2 tc, float iGlobalTime) {
  float strength = 16.0 * max(iResolution.x, iResolution.y) / 960.0;
  float x = (tc.x + 5.0) * (tc.y + 5.0) * (iGlobalTime * 20.0 + 20.0);
  return (mod((mod(x, 13.0) + 1.0) * (mod(x, 123.0) + 1.0), 0.01) - 0.005) * strength;
}

