vec4 CenteredZoom(vec2 uv, float scale) {    
    float strength = float(PREFIX(Strength)) / 50.0;
    if (strength > 1.)
      strength = 1.0 + (strength - 1.0) * 0.5;
    scale *= 10. * strength;
    scale = min(pow(scale, 0.5), 1.);

    float SAMPLES = 32.; 
    float decay = 0.66; 
    float density = 0.6; 
    float weight = 0.33 * scale;
    weight += max(strength - 1., 0.) * 0.2 * 0.22;

    vec2 tuv = uv - .5;
    vec2 dTuv = tuv*density/SAMPLES;

    vec4 col = INPUT(uv)* (1.0 - 0.75 * scale);

    uv += dTuv*(hash(uv.xy));

    for(float i=0.; i < SAMPLES; i++){
        uv -= dTuv;
        col += INPUT(uv) * weight;
        weight *= decay;   
    }

    col *= (1. - dot(tuv, tuv)*.75 * scale);

    return pow(col, vec4((1.0 - 0.5 * scale)));

}

float GetScale(float process) {
  const float M_PI = 3.1415926535897932384626433832795;
  if (process > 0.05 && process < 0.28) {
    return cos(((process - 0.165) / 0.115) * M_PI * 0.5) * 0.8;
  } else if (process > 0.38 && process < 0.61) {
    return cos(((process - 0.495) / 0.115) * M_PI * 0.5) * 0.8;
  } else if (process > 0.71 && process < 0.94) {
    return cos(((process - 0.825) / 0.115) * M_PI * 0.5) * 0.8;
  }
  return 0.;
}

