  vec2 RotateDir = rotateblur *
                   rotateFunc(normalize(uv - center), vec2(0.0), -1.570796) *
                   length(uv - center) * detaRotate * 0.01745329;

  vec2 totalDir = radialDir + RotateDir + dir;
  totalDir *= smooth_intensity;

  vec2 processColorSp = vec2(0.0);
  if (RGBSeparate == 1)
    processColorSp = clamp(totalDir * 0.2, -0.05, 0.05);

  float count = 0.0;
  vec4 outCol;
  vec2 temp1;
  vec2 temp2;
  vec2 temp3;
  if (MotionBlur == 1) {
    for (int i = 0; i < samples;
         i += 2) // operating at 2 samples for better performance
    {
      temp1 = (uv + float(i) / float(samples) * totalDir * blurAmp + vec2(0.0));
      temp2 = (uv + float(i) / float(samples) * totalDir * blurAmp +
               processColorSp);
      temp3 = (uv + float(i) / float(samples) * totalDir * blurAmp +
               processColorSp);

      color.ra += INPUT(temp1).ra;
      ;
      color.g += INPUT(temp2).g;
