      temp1 =
          (uv + float(i + 1) / float(samples) * totalDir * blurAmp + vec2(0.0));
      temp2 = (uv + float(i + 1) / float(samples) * totalDir * blurAmp +
               processColorSp);
      temp3 = (uv + float(i + 1) / float(samples) * totalDir * blurAmp +
               processColorSp);

      color.ra += INPUT(temp1).ra;
      ;
      color.g += INPUT(temp2).g;
      color.b += INPUT(temp3).b;
    }
    outCol = color / float(samples);
  } else {
    temp1 = (uv + 1.0 / float(samples) * totalDir * blurAmp + vec2(0.0));
    temp2 =
        (uv + 1.0 / float(samples) * totalDir * blurAmp + vec2(processColorSp));
    temp3 =
        (uv + 1.0 / float(samples) * totalDir * blurAmp + vec2(processColorSp));
    color.ra += INPUT(temp1).ra;
    ;
    color.g += INPUT(temp2).g;
    color.b += INPUT(temp3).b;
    outCol = color;
  }
  outCol.rgb *= outCol.a;
  return outCol;
}

