    // rotateUV *= mat2(cos(rotation), -sin(rotation), sin(rotation), cos(rotation));
    vec4 rotateMat = vec4(cos(rotation), -sin(rotation), sin(rotation), cos(rotation));
    float new_x = rotateUV.x*rotateMat.x + rotateUV.y*rotateMat.z;
    float new_y = rotateUV.x*rotateMat.y + rotateUV.y*rotateMat.w;
    rotateUV = vec2(new_x, new_y);
    rotateUV += center*iResolution;
    rotateUV = rotateUV / iResolution;

    vec2 waveUV = rotateUV;
    waveUV.y -= (easeOutElastic(min(iGlobalTime*2.0, 1.0)) - 1.0)*0.2;

    fragOutCol = INPUT(waveUV);

    return fragOutCol;
