	{
		float nDistance = sqrt(float(i - aMidTop.y) * (i - aMidTop.y) + (j - aMidTop.x) * (j - aMidTop.x));
		uv.x = aMidTop.x + nDistance * cos(angleTopMid - 120. * PI / 180.);
		uv.y = aMidTop.y + nDistance * sin(angleTopMid - 120. * PI / 180.);
	}
