		float nDistance = sqrt(float(i - aRightBottom.y) * (i - aRightBottom.y) + (j - aRightBottom.x) * (j - aRightBottom.x));
		uv.x = aRightBottom.x + nDistance * cos(-angleBottomRight + 120. * PI / 180.);
