    mix_factor = clamp((uv.x - min_rect_x) / abs(max_rect_x - min_rect_x), 0.0, 1.0);
  }
  vec3 lineMaskCol = mix(lineCol1, lineCol2, mix_factor);
  line_mask = smoothstep(0.0, 0.9, line_mask);
  retCol = mix(retCol, vec4(lineMaskCol, 1.0), line_mask);
  retCol.rgb = mix(retCol.rgb, circleCol.rgb, circleCol.a);
  retCol.a = mix(retCol.a, 1.0, circleCol.a);

  return retCol;
}

float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
    vec2 p1 = vec2(p.x, p.y);
    vec2 p2 = vec2(p.z, p.w);
    float mX1 = p1.x;
    float mY1 = p1.y;
    float mX2 = p2.x; 
    float mY2 = p2.y;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;  // linear
  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

vec3 GetColor(int color){
  return vec3(float(color & 0xff), float((color >> 8) & 0xff), float((color >> 16) & 0xff)) / 255.0;
}

vec2 rotateFunc(vec2 uv, vec2 center, float theta, vec2 resolution)
{
  vec2 uv0 = uv - center;
  uv0.y *= resolution.y / resolution.x;
  vec2 temp;
  temp.x = dot(vec2(cos(theta), -sin(theta)), uv0);
  temp.y = dot(vec2(sin(theta), cos(theta)), uv0);
  temp.y /= resolution.y / resolution.x;
  temp += center;
  return temp;
}

