// 定义圆周率常量
#define PI 3.14159265358979323846

/**
 * 旋转函数：围绕指定中心点旋转UV坐标
 * @param uv 输入的纹理坐标
 * @param center 旋转中心点
 * @param theta 旋转角度（弧度）
 * @return 旋转后的UV坐标
 */
vec2 rotateFunc(vec2 uv, vec2 center, float theta) {
  vec2 temp;
  // 使用旋转矩阵的点积形式计算旋转后的X坐标
  temp.x = dot(vec2(cos(theta), -sin(theta)), uv - center);
  // 使用旋转矩阵的点积形式计算旋转后的Y坐标
  temp.y = dot(vec2(sin(theta), cos(theta)), uv - center);
  // 加回中心点偏移
  return temp + center;
}

/**
 * 旋转函数2：围绕原点旋转（不加回中心点）
 * @param uv 输入的纹理坐标
 * @param center 旋转中心点
 * @param theta 旋转角度（弧度）
 * @return 旋转后的相对坐标
 */
vec2 rotateFunc2(vec2 uv, vec2 center, float theta) {
  vec2 temp;
  // X坐标旋转
  temp.x = dot(vec2(cos(theta), -sin(theta)), uv - center);
  // Y坐标旋转
  temp.y = dot(vec2(sin(theta), cos(theta)), uv - center);
  // 返回相对坐标（不加回中心点）
  return temp;
}

/**
 * Alpha混合函数：将前景色叠加到背景色上
 * @param back 背景颜色
 * @param overlap 前景颜色（已预乘alpha）
 * @param alp 前景透明度
 * @return 混合后的颜色
 */
vec4 mixFunc(vec4 back, vec4 overlap, float alp) {
  // 计算反向透明度（不透明度的补数）
  float invAlp = 1.0 - alp;
  vec4 ret = back;

  // 只在前景有透明度时进行混合
  if (alp > 0.0) {
    // RGB通道：前景色 + 背景色 × (1-前景透明度)
    ret.x = overlap.x + back.x * invAlp;
    ret.y = overlap.y + back.y * invAlp;
    ret.z = overlap.z + back.z * invAlp;
    // Alpha通道：前景alpha + 背景alpha × (1-前景alpha)
    ret.a = alp + back.a * invAlp;
  }

  return ret;
}

/**
 * 整数取模运算
 * @param a 被除数
 * @param b 除数
 * @return a % b
 */
int modI(int a, int b) {
  return (a) - ((a) / (b)) * (b);
}

/**
 * 浮点数取模运算
 * @param a 被除数
 * @param b 除数
 * @return a % b
 */
float modF(float a, float b) {
  return (a)-floor((a) / (b)) * (b);
}

/**
 * 整数最大值
 * @return max(a, b)
 */
int maxI(int a, int b) {
  return a > b ? a : b;
}

/**
 * 浮点数最大值
 * @return max(a, b)
 */
float maxF(float a, float b) {
  return a > b ? a : b;
}

/**
 * 二维向量逐分量最大值
 * @return vec2(max(a.x, b.x), max(a.y, b.y))
 */
vec2 maxVec2(vec2 a, vec2 b) {
  return vec2((a.x > b.x ? a.x : b.x), (a.y > b.y ? a.y : b.y));
}

/**
 * 二维向量与浮点数比较取最大值
 * @return vec2(max(a.x, b), max(a.y, b))
 */
vec2 maxVec2F(vec2 a, float b) {
  return vec2((a.x > b ? a.x : b), (a.y > b ? a.y : b));
}

/**
 * 整数最小值
 * @return min(a, b)
 */
int minI(int a, int b) {
  return a < b ? a : b;
}

/**
 * 浮点数最小值
 * @return min(a, b)
 */
float minF(float a, float b) {
  return a < b ? a : b;
}

/**
 * 二维向量逐分量最小值
 * @return vec2(min(a.x, b.x), min(a.y, b.y))
 */
vec2 minVec2(vec2 a, vec2 b) {
  return vec2((a.x < b.x ? a.x : b.x), (a.y < b.y ? a.y : b.y));
}

/**
 * 二维向量与浮点数比较取最小值
 * @return vec2(min(a.x, b), min(a.y, b))
 */
vec2 minVec2F(vec2 a, float b) {
  return vec2((a.x < b ? a.x : b), (a.y < b ? a.y : b));
}

/**
 * 右移位运算（模拟位运算 a >> b）
 * @param a 输入值
 * @param b 移位位数
 * @return floor(a / 2^b)
 */
float RightshiftOperation(float a, int b) {
  float m = 1.0;
  // 计算 2^b
  for (int i = 0; i < b; i++) {
    m *= 2.0;
  }
  // 除以 2^b 并向下取整
  return floor(a / m);
}

/**
 * 左移位运算（模拟位运算 a << b）
 * @param a 输入值
 * @param b 移位位数
 * @return floor(a * 2^b)
 */
float LeftshiftOperation(float a, int b) {
  float m = 1.0;
  // 计算 2^b
  for (int i = 0; i < b; i++) {
    m *= 2.0;
  }
  // 乘以 2^b 并向下取整
  return floor(a * m);
}

/**
 * 截断函数（取模运算的包装）
 * @param a 输入值
 * @param b 模数
 * @return a % b
 */
float truncation(float a, int b) {
  return modF((a), float(b));
}

/**
 * 将整数颜色值转换为归一化的vec4颜色
 * 输入格式：0xRRGGBB（十进制整数）
 * @param color 整数形式的颜色值（如16777215表示白色0xFFFFFF）
 * @return 归一化的RGBA颜色（范围0.0-1.0）
 */
vec4 calColor(int color) {
  // 提取红色通道：右移16位后取低8位
  float color_red = truncation(RightshiftOperation(float(color), 16), 256);
  // 提取绿色通道：右移8位后取低8位
  float color_green = truncation(RightshiftOperation(float(color), 8), 256);
  // 提取蓝色通道：直接取低8位
  float color_blue = truncation(float(color), 256);
  // 组装RGBA颜色（注意OpenGL是BGRA顺序），alpha设为255（完全不透明）
  vec4 colors = vec4(color_blue, color_green, color_red, 255.0) / 255.0;
  return colors;
}

/**
 * 渲染单个数字（0-9）
 * @param tc 纹理坐标
 * @param scale 缩放比例
 * @param num_height 单个数字在纹理中的高度（归一化）
 * @param number 要显示的数字（0-9）
 * @param roi 数字显示的区域（x=左，y=下，z=右，w=上，OpenGL坐标系）
 * @param color 文字颜色
 * @param strokeColor 描边颜色
 * @param hasStroke 是否有描边（0=无，1=有）
 * @return 渲染后的颜色
 */
vec4 Digital(vec2 tc, vec2 scale, float num_height, int number, vec4 roi, vec3 color, vec3 strokeColor, int hasStroke) {
  vec2 uv = tc;
  // 转换为屏幕坐标系（Y轴向下）
  uv.y = 1.0 - uv.y;
  // 偏移到对应数字的纹理位置（数字纹理是竖直排列的0-9）
  uv.y += num_height * float(number);
  // 应用缩放
  uv *= scale;
  // roi.y是OpenGL坐标系（Y向上，roi.y是底部，roi.w是顶部）
  // 需要转换为屏幕坐标系：screen_y = 1.0 - opengl_y
  // roi.y是OpenGL底部，对应屏幕顶部：screen_top = 1.0 - roi.w
  float roi_y_screen = 1.0 - roi.w;  // OpenGL顶部转换为屏幕顶部
  // 减去ROI的偏移量
  uv -= vec2(roi.x, roi_y_screen) * scale;
  // 取小数部分，实现平铺效果
  uv = fract(uv);
  // 从数字纹理中采样（INPUT2是数字纹理）
  vec4 retCol = INPUT2(uv);

  // === 混合采样：支持描边功能 ===
  float luminance = dot(retCol.rgb, vec3(0.299, 0.587, 0.114));

  if (hasStroke == 1) {
    // 有描边：黑色边框使用描边颜色，白色填充使用文字颜色
    // 使用更严格的阈值，确保边缘区域也使用描边颜色
    float mixAmount = smoothstep(0.2, 0.8, luminance);
    retCol.rgb = mix(strokeColor, color, mixAmount);
    // 对于边缘区域（扩大范围），完全使用描边颜色，避免边缘出现白线
    // 使用smoothstep扩大边缘范围：alpha在0.7-1.0之间时，edgeFactor从1.0逐渐降到0
    float edgeFactor = 1.0 - smoothstep(0.7, 1.0, retCol.a);
    retCol.rgb = mix(retCol.rgb, strokeColor, edgeFactor);
  } else {
    // 无描边：黑色边框改为白色，白色填充使用文字颜色
    float mixAmount = smoothstep(0.3, 0.7, luminance);
    retCol.rgb = mix(vec3(1.0), color, mixAmount);  // 边框使用白色 vec3(1.0)
  }
  // 进行alpha预乘，确保边缘正确混合（mixFunc期望预乘alpha的颜色）
  retCol.rgb *= retCol.a;

  // 应用矩形遮罩：只在指定的ROI区域内显示
  // step函数：x < edge返回0，否则返回1
  // 检查tc是否在roi定义的矩形内
  float matt = step(roi.x, tc.x) * step(tc.x, roi.z) * step(roi.y, tc.y) * step(tc.y, roi.w);
  retCol *= matt;

  return retCol;
}

/**
 * 渲染冒号":"
 * @param tc 纹理坐标
 * @param scale 缩放比例
 * @param roi 冒号显示的区域（屏幕坐标系，y是顶部，w是底部）
 * @param color 文字颜色
 * @param strokeColor 描边颜色
 * @param hasStroke 是否有描边（0=无，1=有）
 * @return 渲染后的颜色
 */
vec4 Colon(vec2 tc, vec2 scale, vec4 roi, vec3 color, vec3 strokeColor, int hasStroke) {
  vec2 uv = tc;
  // 转换为屏幕坐标系（Y轴向下）
  uv.y = 1.0 - uv.y;
  // 应用缩放
  uv *= scale;
  // roi是OpenGL坐标系（Y向上，roi.y是底部，roi.w是顶部）
  // 需要转换为屏幕坐标系：screen_y = 1.0 - opengl_y
  // roi.w是OpenGL顶部，对应屏幕顶部：screen_top = 1.0 - roi.w
  float roi_y_screen = 1.0 - roi.w;  // OpenGL顶部转换为屏幕顶部
  // 减去ROI的偏移量
  uv -= vec2(roi.x, roi_y_screen) * scale;
  // 取小数部分，实现平铺效果
  uv = fract(uv);
  // 从冒号纹理中采样（INPUT3是冒号纹理）
  vec4 retCol = INPUT3(uv);

  // === 混合采样：支持描边功能 ===
  float luminance = dot(retCol.rgb, vec3(0.299, 0.587, 0.114));

  if (hasStroke == 1) {
    // 有描边：黑色边框使用描边颜色，白色填充使用文字颜色
    // 使用更严格的阈值，确保边缘区域也使用描边颜色
    float mixAmount = smoothstep(0.2, 0.8, luminance);
    retCol.rgb = mix(strokeColor, color, mixAmount);
    // 对于边缘区域（扩大范围），完全使用描边颜色，避免边缘出现白线
    // 使用smoothstep扩大边缘范围：alpha在0.7-1.0之间时，edgeFactor从1.0逐渐降到0
    float edgeFactor = 1.0 - smoothstep(0.7, 1.0, retCol.a);
    retCol.rgb = mix(retCol.rgb, strokeColor, edgeFactor);
  } else {
    // 无描边：黑色边框改为白色，白色填充使用文字颜色
    float mixAmount = smoothstep(0.3, 0.7, luminance);
    retCol.rgb = mix(vec3(1.0), color, mixAmount);  // 边框使用白色 vec3(1.0)
  }
  // 进行alpha预乘，确保边缘正确混合（mixFunc期望预乘alpha的颜色）
  retCol.rgb *= retCol.a;

  // === 应用遮罩：与Digital函数完全一致 ===
  // 检查tc是否在roi定义的矩形内（OpenGL坐标系）
  float matt = step(roi.x, tc.x) * step(tc.x, roi.z) * 
               step(roi.y, tc.y) * step(tc.y, roi.w);
  retCol *= matt;

  return retCol;
}

/**
 * 渲染完整的数字计时器（SS:MS格式）
 * @param uv 纹理坐标
 * @param iResolution 分辨率
 * @param iSecond 起始秒数
 * @param iGlobalTime 全局时间（秒）
 * @param fontCol 文字颜色
 * @param strokeCol 描边颜色
 * @param hasStroke 是否有描边
 * @param speed 播放速度倍率
 * @return 渲染后的颜色
 */
vec4 TextureDigital(vec2 uv, vec2 iResolution, int iSecond, float iGlobalTime, vec3 fontCol, vec3 strokeCol, int hasStroke, float speed) {
  // === 计算屏幕和纹理的宽高比 ===
  float prop = iResolution.x / iResolution.y;  // 屏幕宽高比
  float imgProp = 60.0 / 1200.0;  // 数字纹理宽高比（纹理是竖直排列0-9）
  float colonProp = 60.0 / 120.0;  // 冒号纹理宽高比

  // === 计算当前显示的时间 ===
  float speed_globalTime = iGlobalTime * speed;  // 应用速度倍率
  // 将当前时间转换为毫秒（1秒 = 1000毫秒）
  int changeTime = int(floor(speed_globalTime * 1000.0));
  changeTime = maxI(changeTime, 0);  // 确保时间非负

  // 获取基础时间（用户设置的起始秒数）
  int base_seconds = iSecond;

  // 将经过的时间从毫秒分解为秒和毫秒
  int total_milliseconds = changeTime;
  int add_seconds = total_milliseconds / 1000;  // 经过的完整秒数
  int milliseconds = modI(total_milliseconds, 1000);  // 剩余的毫秒数

  // 将基础秒数和经过的秒数合并
  int total_seconds = base_seconds + add_seconds;
  int seconds = modI(total_seconds, 60);  // 秒数取模60（0-59）

  // 毫秒转换为2位显示（0-99，即百分之一秒）
  // 例如：563毫秒 → 56（显示56）
  int millisecond_display = milliseconds / 10;

  // === 计算数字和冒号的布局参数 ===
  float numWidth = (0.1 - 3.0 / 10000.0) * (10.0 / 20.0);  // 单个数字的宽度
  float numHeight = numWidth * 2.0 * prop;  // 单个数字的高度（考虑宽高比）
  float numGap = numWidth + 0.002;  // 数字之间的间距（从0.005减小到0.002，更紧凑）
  float colonOffset = 0.015;  // 冒号的偏移量
  float colonWidth = numGap - colonOffset * 2.0;  // 冒号的实际宽度

  // 起始位置（左下角为原点）
  float startPos = 0.0;  // 从左边开始
  float roiY = 0.0;  // 数字底部的Y坐标（OpenGL坐标系，Y向上）
  float roiY1 = roiY + numHeight;  // 数字顶部的Y坐标

  // 计算数字和冒号的缩放值（考虑屏幕宽高比）
  vec2 scale_val = vec2(20.0, 20.0 * imgProp * (iResolution.y / iResolution.x));
  vec2 colon_scale = vec2(20.0, 20.0 * colonProp * (iResolution.y / iResolution.x));

  vec4 retCol = vec4(0.0);

  // === 循环渲染4个字符：SS:MS（秒:毫秒）===
  for (int i = 0; i < 4; ++i) {
    float roiX = startPos + numGap * float(i);
    float roiX1 = roiX + numWidth;
    vec4 roi = vec4(roiX, roiY, roiX1, roiY1);
    int number = 0;

    if (i == 0) {
      number = seconds / 10;  // 秒十位
    } else if (i == 1) {
      number = modI(seconds, 10);  // 秒个位
    } else if (i == 2) {
      // 冒号（秒和毫秒之间）
      // 计算冒号的居中位置：在第2个数字（秒个位）和第3个数字（毫秒十位）之间
      // 第2个数字的右边界
      float digit2Right = startPos + numWidth + numGap * 1.0;
      // 第3个数字的左边界
      float digit3Left = startPos + numGap * 3.0;
      // 冒号可用空间
      float colonSpace = digit3Left - digit2Right;
      // 居中放置冒号
      roiX = digit2Right + (colonSpace - numWidth) * 0.5;
      roiX1 = roiX + numWidth;

      // 冒号垂直居中，使用完整的数字高度以显示两个点
      float tempRoiY = roiY;  // 底部
      float tempRoiY1 = roiY1;  // 顶部

      // 使用OpenGL坐标系：x=左，y=下，z=右，w=上
      roi = vec4(roiX, tempRoiY, roiX1, tempRoiY1);
      retCol += Colon(uv, colon_scale, roi, fontCol, strokeCol, hasStroke);
      continue;
    } else if (i == 3) {
      // 毫秒十位：放在冒号右边
      roiX = startPos + numGap * 3.0;
      number = millisecond_display / 10;
    }

    // 渲染数字
    roiX1 = roiX + numWidth;
    roi = vec4(roiX, roiY, roiX1, roiY1);
    retCol += Digital(uv, scale_val, numHeight, number, roi, fontCol, strokeCol, hasStroke);
  }

  // 渲染毫秒个位（第5个字符）
  float roiX = startPos + numGap * 4.0;
  float roiX1 = roiX + numWidth;
  vec4 roi = vec4(roiX, roiY, roiX1, roiY1);
  int number = modI(millisecond_display, 10);  // 毫秒个位
  retCol += Digital(uv, scale_val, numHeight, number, roi, fontCol, strokeCol, hasStroke);

  return retCol;
}

/**
 * 主着色器函数（片段着色器入口）
 * @param tc 纹理坐标
 * @return 最终的像素颜色
 */
vec4 FUNCNAME(vec2 tc) {
  // 获取用户参数
  float iGlobalTime = PREFIX(global_time);
  int iSecond = PREFIX(Number_Second);
  float speed = PREFIX(General_Speed);

  // 获取新参数
  int posX = PREFIX(Position_X);
  int posY = PREFIX(Position_Y);
  int size = PREFIX(Size);
  int hasStroke = PREFIX(Stroke);
  int color1 = PREFIX(Text_Color);
  int color2 = PREFIX(Stroke_Color);
  float opacity = float(PREFIX(General_Opacity)) / 100.0;

  // 将大小参数转换为缩放值（0-100 -> 0.1-2.0）
  // Size越大，计时器越大
  float clockScale = max(0.1, float(size) / 50.0);

  // 获取颜色
  vec3 fontCol = calColor(color1).xyz;
  vec3 strokeCol = calColor(color2).xyz;

  // === 计算计时器的尺寸 ===
  float prop = iResolution.x / iResolution.y;
  float numWidth = (0.1 - 3.0 / 10000.0) * (10.0 / 20.0);
  float numHeight = numWidth * 2.0 * prop;
  float numGap = numWidth + 0.005;
  float colonOffset = 0.015;
  float colonWidth = numGap - colonOffset * 2.0;

  // 计时器总宽度：SS:MS = 5个字符位置
  float baseTimerWidth = numGap * 4.0 + colonWidth;
  float baseTimerHeight = numHeight;

  // 考虑缩放后的屏幕占比（clockScale越大，占用屏幕空间越大）
  float timerWidth = baseTimerWidth * clockScale;
  float timerHeight = baseTimerHeight * clockScale;

  // === 将位置参数转换为归一化坐标 ===
  // Position X: 0=左侧，100=右侧
  // Position Y: 0=底部，100=顶部
  // 添加边距，确保计时器完全显示
  float marginX = 0.02;
  float marginY = 0.02;

  float maxPosX = max(0.0, 1.0 - timerWidth - marginX);
  float maxPosY = max(0.0, 1.0 - timerHeight - marginY);

  // 计算实际位置（左下角坐标）
  float normPosX = marginX + (float(posX) / 100.0) * maxPosX;
  float normPosY = marginY + (float(posY) / 100.0) * maxPosY;

  // === 应用坐标变换 ===
  vec2 uv = tc;
  vec4 fragCol = vec4(0.0);

  // 转换到计时器的局部坐标系（除以clockScale使内容变大）
  vec2 uv_clock = (uv - vec2(normPosX, normPosY)) / clockScale;

  // 渲染数字计时器（SS:MS格式）
  vec4 retCol = vec4(0.0);
  retCol = TextureDigital(uv_clock, iResolution, iSecond, iGlobalTime, fontCol, strokeCol, hasStroke, speed);

  // === 应用不透明度并与原始视频混合 ===
  fragCol = retCol * opacity;
  vec4 orig = INPUT1(tc);  // 原始视频帧
  fragCol = mixFunc(orig, fragCol, fragCol.a);  // Alpha混合

  return fragCol;
}

float easeOutExpo(float x) {
    return x == 1.0 ? 1.0 : 1.0 - pow(2.0, -10.0 * x);
}

vec4 FUNCNAME(vec2 tc)
{
    vec2 uv = tc;
    vec4 fragOutCol = vec4(0.0);
    vec2 center = vec2(0.5);
    float iGlobalTime = PREFIX(global_time) / PREFIX(total_time);

    float speed = float(PREFIX(Speed));
    if (speed != 0.0) {
        speed = min(1.0, iGlobalTime / (1.1 - speed / 100.0 * 0.9));
    }

    vec2 zoomUV = uv;

    float scale = mix(1.0 - float(PREFIX(Scale)) / 100.0 * 0.9999, 1.0, easeOutExpo(speed));
    zoomUV = (zoomUV - center) * scale + center;
    vec4 bgTexture = abs(INPUT(zoomUV) - vec4(1.0)) * float(PREFIX(Opacity)) / 100.0;
    bgTexture.rgb = vec3(0.0) * bgTexture.a;

    fragOutCol = bgTexture;

    return fragOutCol;
}

float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

vec3 random_perlin( vec3 p ) {
    p = vec3(
            dot(p,vec3(127.1,311.7,69.5)),
            dot(p,vec3(269.5,183.3,132.7)), 
            dot(p,vec3(247.3,108.5,96.5)) 
            );
    return -1.0 + 2.0*fract(sin(p)*43758.5453123);
}

float noise_perlin(vec3 p) {
    vec3 i = floor(p);
    vec3 s = fract(p);

    float a = dot(random_perlin(i),s);
    float b = dot(random_perlin(i + vec3(1.0, 0.0, 0.0)),s - vec3(1.0, 0.0, 0.0));
    float c = dot(random_perlin(i + vec3(0.0, 1.0, 0.0)),s - vec3(0.0, 1.0, 0.0));
    float d = dot(random_perlin(i + vec3(0.0, 0.0, 1.0)),s - vec3(0.0, 0.0, 1.0));
    float e = dot(random_perlin(i + vec3(1.0, 1.0, 0.0)),s - vec3(1.0, 1.0, 0.0));
    float f = dot(random_perlin(i + vec3(1.0, 0.0, 1.0)),s - vec3(1.0, 0.0, 1.0));
    float g = dot(random_perlin(i + vec3(0.0, 1.0, 1.0)),s - vec3(0.0, 1.0, 1.0));
    float h = dot(random_perlin(i + vec3(1.0, 1.0, 1.0)),s - vec3(1.0, 1.0, 1.0));

    vec3 u = smoothstep(0.,1.,s);

    return mix(mix(mix( a, b, u.x),
                mix( c, e, u.x), u.y),
            mix(mix( d, f, u.x),
                mix( g, h, u.x), u.y), u.z);
}

float noise_turbulence(vec3 p)
{
    float f = 0.0;
    float a = 1.0;
    p = 4.0 * p;
    for (int i = 0; i < 5; i++) {
        f += a * abs(noise_perlin(p));
        p = 2.0 * p;
        a /= 2.0;
    }
    return f;
}

vec4 FUNCNAME(vec2 tc){
