}

vec2 hash22(vec2 p) {
  p = vec2(dot(p,vec2(127.1, 311.7)), dot(p,vec2(269.5, 183.3)));

  return -1.0 + 2.0 * fract(sin(p)*43758.5453123);
}

float perlin_noise(vec2 p) {
  vec2 pi = floor(p);
  vec2 pf = p - pi;
  vec2 w = pf * pf * (3.0 - 2.0 * pf);

  return mix(mix(dot(hash22(pi + vec2(0.0, 0.0)), pf - vec2(0.0, 0.0)), 
                  dot(hash22(pi + vec2(1.0, 0.0)), pf - vec2(1.0, 0.0)), w.x), 
              mix(dot(hash22(pi + vec2(0.0, 1.0)), pf - vec2(0.0, 1.0)), 
                  dot(hash22(pi + vec2(1.0, 1.0)), pf - vec2(1.0, 1.0)), w.x),
              w.y);
}

float noise_sum(vec2 p) {
  float pf = 0.0;
  p = p * 6.0;
  pf += 1.0000 * perlin_noise(p); p = 2.0 * p;
  pf += 0.5000 * perlin_noise(p); p = 2.0 * p;

  return pf / 1.5;
}

vec4 FUNCNAME(vec2 tc) {
  vec2 uv = tc;
  vec4 fragOutCol = vec4(0.0);
  float iTime = PREFIX(global_time) * PREFIX(Speed) / 200.0;
  vec4 noise = INPUT2(uv);

  vec2 dis_uv1 = uv;
  vec2 dis_uv2 = uv;

  vec2 screenSize = iResolution.xy / (min(iResolution.x, iResolution.y) / 1280.0);
  if (iResolution.y < iResolution.x) {
    dis_uv2.x = (dis_uv2.x - 0.5) / (iResolution.y / iResolution.x) + 0.5;
  } else {
    dis_uv2.y = (dis_uv2.y - .5) / (iResolution.x / iResolution.y) + 0.5;
  }
  float noise0 = noise_sum((dis_uv2 - 0.5) * mix(5.0, 10.0, noise.b * PREFIX(Frequency) / 50.0) + iTime);
  float noise1 = noise_sum((dis_uv2 - 0.5) * mix(-(5.0), -(10.0), noise.b * PREFIX(Frequency) / 50.0) + iTime);

  vec2 n = vec2(noise0, noise1);
  dis_uv1.x += (n.x) * 100.0 / screenSize.x * PREFIX(Variance) / 500.0;
  float strength_y = (n.y) * 100.0 / screenSize.y * PREFIX(Variance) / 500.0;
  if (strength_y < 0.0) strength_y *= 0.5;
  dis_uv1.y += strength_y;
  if (dis_uv1.x < 0.0) dis_uv1.x = -dis_uv1.x;
  if (dis_uv1.y < 0.0) dis_uv1.y = -dis_uv1.y;
  if (dis_uv1.x > 1.0) dis_uv1.x = 2.0 - dis_uv1.x;
  if (dis_uv1.y > 1.0) dis_uv1.y = 2.0 - dis_uv1.y;

  dis_uv1.x += sin(noise.r*PREFIX(Number)/5.0) * 0.002 * PREFIX(Size) / 50.0;
  dis_uv1.y += sin(noise.g*PREFIX(Number)/5.0) * 0.002 * PREFIX(Size) / 50.0;
  fragOutCol = INPUT1(dis_uv1);

  return fragOutCol;
}

