  float process = min(iGlobalTime / iDuration, 1.0);
  process = (3.0 * process * process - 2.0 * process * process * process);

  vec4 origCol = INPUT(tc);

  float range = 0.5;
  float pi = 4.0 * atan(1.0);
  float ang = (3.0 - sqrt(5.0))*pi;
  float gamma = 1.8;
  float SAMPLES = 30.;

  vec2 pix = 1.0 / iResolution.xy;
  float r = 20.0;
  float lod = log2(r / SAMPLES * pi * 5.0);
  vec3 col = bokeh(tc, r * pix, lod, ang, gamma, SAMPLES);
  vec4 blurCol = vec4(col, 1.0);

  vec4 retCol = origCol;
  retCol.rgb = mix(blurCol.rgb, origCol.rgb, process);
  return retCol;
}

float box(vec2 position, vec2 halfSize, float cornerRadius)
{
