vec4 tinyBlur(vec2 uv){
    float w = 3.0 / iResolution.x;
    float h = 3.0 / iResolution.y;

    vec4 sum = vec4(0.0);

    sum += INPUT(uv) * 0.8;
    sum += INPUT(uv + vec2(-w, 0.0)) * 0.025;
    sum += INPUT(uv + vec2(w, 0.0)) * 0.025;
    sum += INPUT(uv + vec2(0.0, -h)) * 0.025;
    sum += INPUT(uv + vec2(0.0, h)) * 0.025;
    sum += INPUT(uv + vec2(-w, -h)) * 0.025;
    sum += INPUT(uv + vec2(w, -h)) * 0.025;
    sum += INPUT(uv + vec2(-w, h)) * 0.025;
    sum += INPUT(uv + vec2(w, h)) * 0.025;

    return sum;
}

vec4 SobelFilter(vec2 uv,vec2 offsetStep)
{
    float w = offsetStep.x / iResolution.x;
    float h = offsetStep.y / iResolution.y;
    vec4 samples[8];
    samples[0] = tinyBlur(uv + vec2(-w, -h));
    samples[1] = tinyBlur(uv + vec2(0.0, -h));
    samples[2] = tinyBlur(uv + vec2(w, -h));
    samples[3] = tinyBlur(uv + vec2(-w, 0.0));
    samples[4] = tinyBlur(uv + vec2(w, 0.0));
    samples[5] = tinyBlur(uv + vec2(-w, h));
    samples[6] = tinyBlur(uv + vec2(0.0, h));
    samples[7] = tinyBlur(uv + vec2(w, h));

    vec4 sobel_h = samples[2] + (6.0 * samples[4]) + samples[7] - (samples[0] + (6.0 * samples[3]) + samples[5]);
    vec4 sobel_v = samples[0] + (6.0 * samples[1]) + samples[2] - (samples[5] + (6.0 * samples[6]) + samples[7]);
    vec4 sobel = sqrt((sobel_h * sobel_h) + (sobel_v * sobel_v));

    return sobel;
}

