  return vec3(float(r), float(g), float(b)) / 255.0;
}

// Simple interpolated noise
vec2 noise2_2(vec2 uv) {
  // vec2 f = fract(uv);
  vec2 f = smoothstep(0.0, 1.0, fract(uv));

  vec2 uv00 = floor(uv);
  vec2 uv01 = uv00 + vec2(0, 1);
  vec2 uv10 = uv00 + vec2(1, 0);
  vec2 uv11 = uv00 + 1.0;
  vec2 v00 = hash2_2(uv00);
  vec2 v01 = hash2_2(uv01);
  vec2 v10 = hash2_2(uv10);
  vec2 v11 = hash2_2(uv11);

  vec2 v0 = mix(v00, v01, f.y);
  vec2 v1 = mix(v10, v11, f.y);
  vec2 v = mix(v0, v1, f.x);

  return v;
}

// Rotates point around 0,0
vec2 rotate(in vec2 point, in float deg) {
  float s = sin(deg);
  float c = cos(deg);
  return mat2(s, c, -c, s) * point;
}

// Cell center from point on the grid
vec2 voronoiPointFromRoot(in vec2 root, in float deg) {
  vec2 point = hash2_2(root) - 0.5;
  float s = sin(deg);
  float c = cos(deg);
  point = mat2(s, c, -c, s) * point * 0.66;
  point += root + 0.5;
  return point;
}

// Voronoi cell point rotation degrees
float degFromRootUV(in vec2 uv) {
  return time * ANIMATION_SPEED * (hash1_2(uv) - 0.5) * 2.0;
}

float sdEquilateralTriangle(in vec2 p, in float r) {
  const float k = sqrt(3.0);
  p.x = abs(p.x) - r;
  p.y = p.y + r / k;
  if (p.x + k * p.y > 0.0)
    p = vec2(p.x - k * p.y, -k * p.x - p.y) / 2.0;
  p.x -= clamp(p.x, -2.0 * r, 0.0);
  return -length(p) * sign(p.y);
}

float sdBox(in vec2 p, in vec2 b) {
  vec2 d = abs(p) - b;
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

float sdPentagon(in vec2 p, in float r) {
  const vec3 k = vec3(0.809016994, 0.587785252, 0.726542528);
  p.x = abs(p.x);
  p -= 2.0 * min(dot(vec2(-k.x, k.y), p), 0.0) * vec2(-k.x, k.y);
  p -= 2.0 * min(dot(vec2(k.x, k.y), p), 0.0) * vec2(k.x, k.y);
  p -= vec2(clamp(p.x, -r * k.z, r * k.z), r);
  return length(p) * sign(p.y);
}

float sdHexagon(in vec2 p, in float r) {
  const vec3 k = vec3(-0.866025404, 0.5, 0.577350269);
  p = abs(p);
  p -= 2.0 * min(dot(k.xy, p), 0.0) * k.xy;
  p -= vec2(clamp(p.x, -k.z * r, k.z * r), r);
  return length(p) * sign(p.y);
}

float sdHeptagon(in vec2 p, in float r) {

  // PI/7: cos, sin, tan.
  const vec3 k = vec3(.9009688679, .43388373911, .4815746188);
  p.y = -p.y;
  p.x = abs(p.x);
  p -= 2. * min(dot(vec2(-k.x, k.y), p), 0.) * vec2(-k.x, k.y);
  p -= 2. * min(dot(vec2(k.x, k.y), p), 0.) * vec2(k.x, k.y);
  p -= 2. * min(dot(vec2(-k.x, k.y), p), 0.) * vec2(-k.x, k.y);
  p -= vec2(clamp(p.x, -r * k.z, r * k.z), r);
  return length(p) * sign(p.y);
}

float sdOctogon(in vec2 p, in float r) {
  const vec3 k = vec3(-0.9238795325, 0.3826834323, 0.4142135623);
  p = abs(p);
  p -= 2.0 * min(dot(vec2(k.x, k.y), p), 0.0) * vec2(k.x, k.y);
  p -= 2.0 * min(dot(vec2(-k.x, k.y), p), 0.0) * vec2(-k.x, k.y);
  p -= vec2(clamp(p.x, -k.z * r, k.z * r), r);
  return length(p) * sign(p.y);
}

float sdEllipse(vec2 p, vec2 ab) {
  // symmetry
  p = abs(p);

  // initial value
  vec2 q = ab * (p - ab);
  vec2 cs = normalize((q.x < q.y) ? vec2(0.01, 1) : vec2(1, 0.01));

  // find root with Newton solver (see https://www.shadertoy.com/view/4lsXDN)
  for (int i = 0; i < 5; i++) {
    vec2 u = ab * vec2(cs.x, cs.y);
    vec2 v = ab * vec2(-cs.y, cs.x);

    float a = dot(p - u, v);
    float c = dot(p - u, u) + dot(v, v);
    float b = sqrt(c * c - a * a);

    cs = vec2(cs.x * b - cs.y * a, cs.y * b + cs.x * a) / c;
  }

  // compute final point and distance
  float d = length(p - ab * cs);

  // return signed distance
  return (dot(p / ab, p / ab) > 1.0) ? d : -d;
}

vec3 fireParticles(in vec2 uv, in vec2 originalUV, out bool is_end, int mode,
                   inout vec3 addition_color) {
  vec3 particles = vec3(0.0);
  vec3 _addition_color = vec3(0.0);
  vec2 rootUV = floor(uv);
  if (rootUV.x == 0. || rootUV.y == 0.)
    return particles;
  float deg = degFromRootUV(rootUV) * float(PREFIX(RandomFloat)) * 0.1;
  vec2 pointUV = voronoiPointFromRoot(rootUV, deg);
  float dist = 2.0;

  // UV manipulation for the faster particle movement
  vec2 tempUV = uv;
  // tempUV += -(noise2_2(uv * 3.0) - 0.5) * 0.1 * PREFIX(random_float);
  // tempUV += -(noise2_2(uv * 3.0 + time) - 0.5) * 0.1;
  float particle_size = 0.03;

  float radian = PI;
  if (0 == PREFIX(RandomRotate)) {
    float degree = float(PREFIX(RotateFixedAngle));
    radian += radians(degree);
  } else {
    radian += degFromRootUV(rootUV) * 2.;
  }

  mat2 rotate_mat = mat2(cos(radian), sin(radian), -sin(radian), cos(radian));
  mat2 scale_mat =
      mat2(1. / float(PREFIX(ScaleX)), 0., 0., 1. / float(PREFIX(ScaleY)));
  tempUV = scale_mat * rotate_mat * (tempUV - pointUV) + pointUV;

  float core_size = particle_size * (1.0 - PREFIX(Blur) * 0.1);

  if (mode == 0) {
    dist = length(tempUV - pointUV) - core_size;
  } else if (mode >= 3 && mode <= 8) {
    int edge = mode;
    if (3 == edge) {
      dist = sdEquilateralTriangle(tempUV - pointUV, core_size);
    } else if (4 == edge) {
      dist = sdBox(tempUV - pointUV, vec2(core_size));
    } else if (5 == edge) {
      dist = sdPentagon(tempUV - pointUV, core_size);
    } else if (6 == edge) {
      dist = sdHexagon(tempUV - pointUV, core_size);
    } else if (7 == edge) {
      dist = sdHeptagon(tempUV - pointUV, core_size);
    } else if (8 == edge) {
      dist = sdOctogon(tempUV - pointUV, core_size);
    }
  } else if (mode >= 10) {
    dist = sdBox(tempUV - pointUV, vec2(particle_size));
  }

  if (mode < 10) {
    particles +=
        (1.0 -
         pow(smoothstep(0., particle_size * 0.2 + particle_size - core_size,
                        dist),
             0.1)) *
        base_color * 1.;
  } else {
    particles +=
        (1.0 - smoothstep(0., particle_size * 0.2 + particle_size - core_size,
                          dist)) *
        base_color * 1.;
  }

  if (mode >= 10) {
    vec2 image_tc =
        clamp((tempUV - pointUV) / particle_size, vec2(-0.99), vec2(.99));
    image_tc = (image_tc + 1.) * 0.5;
    image_tc.y = 1.0 - image_tc.y;

    int index = mode - 10;
    float image_alpha = 0.0;
    if (1 == index) {
      image_alpha = INPUT2(image_tc).a;
      addition_color = INPUT2(image_tc).rgb;
    } else if (2 == index) {
      image_alpha = INPUT3(image_tc).a;
      addition_color = INPUT3(image_tc).rgb;
    } else if (3 == index) {
      image_alpha = INPUT4(image_tc).a;
      addition_color = INPUT4(image_tc).rgb;
    } else if (4 == index) {
      image_alpha = INPUT5(image_tc).a;
      addition_color = INPUT5(image_tc).rgb;
    }
    particles *= image_alpha;
    addition_color *= image_alpha;
  }

  // is_end = dist < particle_size * 0.02;

  return particles;
}

// Layering particles to imitate 3D view
// Layering particles to imitate 3D view
vec3 layeredParticles(vec2 uv, float base_size, float sizeMod, float base_alpha,
                      float alphaMod, int layers, int mode,
                      inout vec3 addition_color) {
  vec3 particles = vec3(0);
  float size = base_size;
  float alpha = base_alpha;
  vec2 offset = vec2(0.0);
  vec2 noiseOffset = vec2(0.0);
  vec2 bokehUV;

  bool is_end = false;

  for (int i = 0; i < layers; i++) {
    // Particle noise movement
    // noiseOffset = (noise2_2(uv * size * 2.0 + 0.5) - 0.5) * 0.15;

    // UV with applied movement
    bokehUV = (uv * size + time * movement_direction * movement_speed) +
              offset + noiseOffset;

    vec3 _addition_color = vec3(0.);
    // Adding particles
    particles +=
        fireParticles(bokehUV, uv, is_end, mode, _addition_color) * alpha;

    addition_color += _addition_color * alpha;

    if (is_end)
      break;

    // Moving uv origin to avoid generating the same particles
    offset += hash2_2(vec2(alpha, alpha)) * 10.0;

    alpha *= alphaMod;
    size *= sizeMod;
  }

  return particles;
}

