float GetMatt(vec2 tc, int index){
    vec2 uv = tc;
    uv.y = 1.0 - uv.y;
    float width = 1.0 / 3.0;
    float pos_x = width * float(mod(float(index), 3.0));
    float pos_y = width * float(index / 3);
    return step(pos_x, uv.x) * step(uv.x, pos_x + width) * step(pos_y, uv.y) * step(uv.y, pos_y + width);
}

