	retCol *= matt;

	return retCol * matt;
}

vec2 rotateFunc(vec2 uv, vec2 center, float theta)
{
	vec2 temp;
	temp.x = dot(vec2(cos(theta), -sin(theta)), uv - center);
	temp.y = dot(vec2(sin(theta), cos(theta)), uv - center);
	return temp + center;
}

//Bézier curve
float fun2(vec2 p0, vec2 p1, vec2 p2, vec2 p3, float t)
{
    vec2 q0 = mix(p0, p1, t);
    vec2 q1 = mix(p1, p2, t);
    vec2 q2 = mix(p2, p3, t);

    vec2 r0 = mix(q0, q1, t);
    vec2 r1 = mix(q1, q2, t);

    return mix(r0, r1, t).y;
}

int maxI(int a, int b)
{
    float x = float(a);
    float y = float(b);
    float m = x > y ? x : y;

	return int(m);
}

int modI(int a,int b){
    return (a)-((a)/(b))*(b);
}

int RightshiftOperation(int a,int b)
{
    int m = int(pow(2.0, float(b)));
	int temp = modI(a / m, 256);
    return temp;
}

float modF(float a,float b){
    return (a)-floor((a)/(b))*(b);
}

float RightshiftOperation(float a, int b){
    float m = 1.0;
    for(int i=0;i<b;i++){
        m *= 2.0;
    }       
    return floor(a/m);
}

float truncation(float a, int b){
    return modF((a),float(b));
}

vec3 calColor(int color){
    float color_red = truncation(RightshiftOperation(float(color), 16), 256);
	float color_green = truncation(RightshiftOperation(float(color), 8), 256);
	float color_blue = truncation(float(color), 256);
	vec3 colors = vec3(float(color_blue), float(color_green), float(color_red)) / 255.0;	
    return colors;
}

float calRollingProcess(float current_time, float rolling_time, float static_time, 
						int total_number_count, int current_count, int direction, int static_opening_enable){
	float duration = rolling_time * (float(total_number_count - current_count + 1) / float(total_number_count));
	if(direction == 1){
		duration = rolling_time * (float(current_count) / float(total_number_count));
	}

	float t = 0.0;
	if(duration > 0.0){
		t = (current_time - static_time) / duration;
		if(static_opening_enable == 1){
			t = current_time / duration;
		}
		t = clamp(t, 0.0, 1.0);
	}

	//Bézier points
	vec2 po = vec2(0.0,0.0);
	vec2 p1 = vec2(0.26,0.41);
	vec2 p2 = vec2(0.49,1.0);
	vec2 p3 = vec2(1.0,1.0);
	float process = fun2(po, p1, p2, p3, t);
	process = clamp(process, 0.0, 1.0);
	if(static_opening_enable == 0 && current_time < static_time){
		process = 0.0;
	}

	return process;
}

