			float normalize_pos = (uv.x - (startPos-0.012))/(endPos+0.012 - (startPos-0.012));
			alpha = smoothstep(1.0-progress-0.02, 1.0-progress, normalize_pos);
			if(direction == 1){
				normalize_pos = 1.0 - normalize_pos;
				alpha = smoothstep(1.0-progress, 1.002-progress, normalize_pos);
			}
		}
	}

	vec4 origCol = INPUT1(tc);
	outCol.rgb = mix(origCol.rgb, outCol.rgb, outCol.a * alpha);
	outCol.a = max(origCol.a,outCol.a);
    outCol = mix(origCol,outCol,float(opacity)/100.0);
