float mirrored_repeat(float x) {
    x = mod(x, 2.0)/2.0;
    x += (2.0 - 2.0 * x) * ifGreaterThan(x, 1.0);
    return x;
}

vec2 getFoldPosition(float progress) {

    float angle = 170.0; 
    vec2 direction = vec2(cos(radians(angle)), sin(radians(angle)));
    float adjustedProgress = progress ; // 增加进度范围
    return vec2(1.0, progress*3.0) + direction * mirrored_repeat(adjustedProgress) * 2.0; // 增加位移距离到4.0
}

float easeOutQuad(float x){
  return 1.0 - (1.0 - x) * (1.0 - x);
}
vec4 FUNCNAME(vec2 tc) {

