    vec2 invAspect = vec2(1.0 / aspectRatio, 1.0);

    vec2 cornerPosition = vec2(1.0, 0.0); 
    vec2 foldPosition = getFoldPosition(iPro);

    vec2 normalizedFoldPosition = foldPosition;
    vec2 diers =(foldPosition - cornerPosition);
    vec2 dir = normalize(vec2(diers.x-20.0, (diers.y +1.0))); 
    vec2 origin = normalizedFoldPosition - dir * (normalizedFoldPosition.x - aspectRatio * ifGreaterThan(dir.x, -EPSILON)) / (dir.x + EPSILON);
    float curlDist = length(normalizedFoldPosition - origin) + (cornerPosition.x - aspectRatio * ifLessThan(dir.x, EPSILON)) / (dir.x + EPSILON);

    float proj = dot(origin - uv, dir);
    float dist = proj - curlDist;
    vec2 linePoint = uv + dist * dir;

    vec4 outColor;
    if (dist > foldRadius) {
        outColor = vec4(0.0);
    }
    else if (dist > EPSILON) {
        float theta = asin(dist / foldRadius);
        vec2 p1 = linePoint - dir * theta * foldRadius;
        vec2 p2 = linePoint - dir * (PI - theta) * foldRadius;
        if (isInBounds(p2) > 0.0) {
            vec4 frontPage = INPUT(p1);
            vec4 backPage = INPUT(p2);
            float alpha = backPage.a * frontPage.a;
            float light = smoothstep(0.0, 1.0, (foldRadius - dist) / foldRadius) * 0.3;
            backPage.rgb += light * backPage.a;
            outColor = vec4(mix(frontPage.rgb, backPage.rgb, backPage.a * opacity), max(backPage.a, frontPage.a));
            outColor.rgb *= pow((foldRadius - dist) / foldRadius, 0.2);
        }
        else {
            outColor = INPUT(p1);
            outColor.rgb *= pow((foldRadius - dist) / foldRadius, 0.2);
        }
    }
    else {
        vec2 p = linePoint - dir * (abs(dist) + PI * foldRadius);
        if (isInBounds(p) > 0.0) {
            vec4 frontPage = INPUT(uv);
            vec4 backPage = INPUT(p);
            float light = smoothstep(0.0, 1.0, (foldRadius + dist) / foldRadius) * 0.3;
            backPage.rgb += light * backPage.a;
            outColor = vec4(mix(frontPage.rgb, backPage.rgb, backPage.a * opacity), max(backPage.a, frontPage.a));
        }
        else {
            outColor = INPUT(uv);
        }
    }
    outColor *= isInBounds(uv);
    return outColor;
}

float my_tan(float x) {
    float x2 = x * x;
    float x3 = x * x2;
    float x5 = x3 * x2;
    float x7 = x5 * x2;
    return x + (1.0/3.0) * x3 + (2.0/15.0) * x5 + (17.0/315.0) * x7;
}
