vec4 Digital(vec2 tc, vec2 scale, float num_height, float process, float blur, int nLoop, int start_num, int end_num, vec4 roi, vec3 font_color)
{
	vec2 uv = tc;
	uv.y = 1.0 - uv.y;
	int offset = end_num - start_num + 10 * nLoop;
	if(start_num > end_num){
		offset += 10;
	}
	uv.y += num_height * (float(start_num) + float(offset) * process);
	uv *= scale;
	uv -= vec2(roi.x, 0.5 - num_height * 0.5) * scale;
	uv = fract(uv);

	vec4 retCol = vec4(0.0);
    vec4 blurCol = vec4(0.0);
	int samples = 32;
	float blurAmp = blur * 0.05 * (1.0 - process);
	vec2 dir = vec2(0.0, 1.0);
	float matt = step(roi.x, tc.x)*step(tc.x, roi.z)*step(roi.y, tc.y)*step(tc.y, roi.w);

	if(matt > 0.0){
		if(process > 0.001){
			for (int i = 0; i < samples; i += 4)
			{
				vec2 temp = uv + float(i) / float(samples) * dir * blurAmp;
				blurCol += INPUT2(temp);

				temp = uv + float(i+1) / float(samples) * dir * blurAmp;	
				blurCol += INPUT2(temp);

				temp = uv + float(i+2) / float(samples) * dir * blurAmp;
				blurCol += INPUT2(temp);

				temp = uv + float(i+3) / float(samples) * dir * blurAmp;	
				blurCol += INPUT2(temp);
			}
			retCol = blurCol / float(samples);
		}else{
			retCol = INPUT2(uv);
		}
	}

	retCol.rgb = font_color * retCol.a;
	retCol *= matt;

	return retCol;
}

vec4 percent(vec2 tc, vec2 scale, float process, float height, vec4 roi, vec3 font_color)
{
	if(process < 0.001)
		return vec4(0.0);

	vec2 uv = tc;
	uv.y = 1.0 - uv.y;
	vec2 center = vec2(roi.x + (roi.z - roi.x) * 0.5, 0.5);
	uv -= center;
	uv *= scale * (8.0 - process * 7.0);
	uv += center;

	vec4 retCol = INPUT3(uv);
	retCol.rgb = font_color * retCol.a;
	float matt = step(0.0, uv.x)*step(uv.x, 1.0)*step(0.0, uv.y)*step(uv.y, 1.0);
	retCol *= matt;

	return retCol;
}

vec2 rotateFunc(vec2 uv, vec2 center, float theta)
{
	vec2 temp;
	temp.x = dot(vec2(cos(theta), -sin(theta)), uv - center);
	temp.y = dot(vec2(sin(theta), cos(theta)), uv - center);
	return temp + center;
}

//Bézier curve
float fun2(vec2 p0, vec2 p1, vec2 p2, vec2 p3, float t)
{
    vec2 q0 = mix(p0, p1, t);
    vec2 q1 = mix(p1, p2, t);
    vec2 q2 = mix(p2, p3, t);

    vec2 r0 = mix(q0, q1, t);
    vec2 r1 = mix(q1, q2, t);

    return mix(r0, r1, t).y;
}

int maxI(int a, int b)
{
    float x = float(a);
    float y = float(b);
    float m = x > y ? x : y;

	return int(m);
}

int modI(int a,int b){
    return (a)-((a)/(b))*(b);
}

int RightshiftOperation(int a,int b)
{
    int m = int(pow(2.0, float(b)));
	int temp = modI(a / m, 256);
    return temp;
}

float modF(float a,float b){
    return (a)-floor((a)/(b))*(b);
}

float RightshiftOperation(float a, int b){
    float m = 1.0;
    for(int i=0;i<b;i++){
        m *= 2.0;
    }       
    return floor(a/m);
}

float truncation(float a, int b){
    return modF((a),float(b));
}

vec3 calColor(int color){
    float color_red = truncation(RightshiftOperation(float(color), 16), 256);
	float color_green = truncation(RightshiftOperation(float(color), 8), 256);
	float color_blue = truncation(float(color), 256);
	vec3 colors = vec3(float(color_blue), float(color_green), float(color_red)) / 255.0;	
    return colors;
}

vec4 FUNCNAME(vec2 tc) 
{
	float iGlobalTime = PREFIX(global_time);
	float iTotalTime = PREFIX(total_time);
