	int temp_end = end_number;
	while(temp_start != 0){
		temp_start /= 10;
		start_count++;
	}
	while(temp_end != 0){
		temp_end /= 10;
		end_count++;
	}

	int total_count = maxI(start_count, end_count);
	total_count = int(clamp(float(total_count), 1.0, 4.0));

	float rolling_time = motion_time;
	if(static_time + motion_time > iTotalTime){
		if(static_time < iTotalTime){
			rolling_time = iTotalTime - static_time;
		}
	}

	int start_number1 = modI(start_number / 1000, 10);
	int end_number1 = modI(end_number / 1000, 10);
	int start_number2 = modI(start_number / 100, 10);
	int end_number2 = modI(end_number / 100, 10);
	int start_number3 = modI(start_number / 10, 10);
	int end_number3 = modI(end_number / 10, 10);
	int start_number4 = modI(start_number, 10);
	int end_number4 = modI(end_number, 10);

	int nLoop = int(rolling_time + 0.5);
	nLoop = maxI(nLoop - 1, 1);

	float texWidth = 60.0;
	float texHeight = 1200.0;

	vec3 fontCol = calColor(PREFIX(Theme_font_color)); 

	float prop = iResolution.x / iResolution.y;
	float imgProp = texWidth / texHeight;

	float percentWidth = 60.0;
	float percentHeight = 120.0;
	float percentProp = percentWidth / percentHeight;

	float numWidth = 0.05;
	float numHeight = numWidth * 2.0 * prop;
	float numGap = numWidth + gap * 0.005;

	float roiY = 0.5 - numHeight * 0.5;
	float roiY1 = 0.5 + numHeight * 0.5;

	vec2 center = vec2(position_x, position_y);
	float theta = radians(rotate);

	vec2 offset = vec2(0.5) - center;
	vec2 uv = tc;
	uv = (uv - center) / scale + center;
    uv = rotateFunc(uv * iResolution.xy, center * iResolution.xy, theta) / iResolution.xy;
    uv += offset;

	float startPos = (1.0 - float(total_count + 1) * numGap) * 0.5;
	if(total_count == 1)
		startPos = 0.5 - numWidth - numGap * 0.5;

	vec2 scale_val = vec2(20.0, 20.0 * imgProp * (iResolution.y / iResolution.x));
	vec2 percent_scale = vec2(20.0, 20.0 * percentProp * (iResolution.y / iResolution.x));

	//Bézier points
	vec2 po = vec2(0.0,0.0);
	vec2 p1 = vec2(0.26,0.41);
	vec2 p2 = vec2(0.49,1.0);
	vec2 p3 = vec2(1.0,1.0);

	vec4 numberCol = vec4(0.0);
	int count = 0;
	for(int i = 4 - total_count; i < 5; ++i){
		float roiX = startPos + numGap * float(count++);
		float roiX1 = roiX + 0.05;
		vec4 roi = vec4(roiX, roiY, roiX1, roiY1);
		int start_num = 0;
		int end_num = 0;
		if(i == 0){
			start_num = start_number1;
			end_num = end_number1;
		}else if(i == 1){
			start_num = start_number2;
			end_num = end_number2;
		}else if(i == 2){
			start_num = start_number3;
			end_num = end_number3;
		}else if(i == 3){
			start_num = start_number4;
			end_num = end_number4;
		}

		if(i == 4){
			float percent_time = 1.0;
			if(rolling_time > 0.0){
				if(static_opening_enable == 0)
					percent_time = (iGlobalTime - static_time) / rolling_time;
				else 
					percent_time = iGlobalTime / rolling_time;
			}

			percent_time = clamp(percent_time, 0.0, 1.0);
			float percent_process = fun2(po, p1, p2, p3, percent_time);
			percent_process = clamp(percent_process, 0.0, 1.0);
			if(static_opening_enable == 0 && iGlobalTime < static_time){
				percent_process = 1.0;
			}
			numberCol += percent(uv, percent_scale, percent_process, numHeight, roi, fontCol);
		}else{
			float duration = rolling_time * (float(total_count - count + 1) / float(total_count));
			if(direction == 1){
				duration = rolling_time * (float(count) / float(total_count));
			}

			float t = 0.0;
			if(duration > 0.0){
				t = (iGlobalTime - static_time) / duration;
				if(static_opening_enable == 1){
					t = iGlobalTime / duration;
				}
				t = clamp(t, 0.0, 1.0);
			}

			float process = fun2(po, p1, p2, p3, t);
			process = clamp(process, 0.0, 1.0);
			if(static_opening_enable == 0 && iGlobalTime < static_time){
				process = 0.0;
			}	
			numberCol += Digital(uv, scale_val, numHeight, process, blur, nLoop, start_num, end_num, roi, fontCol);
		}
	}

	vec4 outCol = numberCol;
	outCol = clamp(outCol, 0.0, 1.0);		
	if(outCol.a > 0.0){
		outCol.rgb /= outCol.a;
	}

	float matt_startPos = startPos - 0.002;
	float endPos = startPos + numGap * float(total_count);
