vec2 rotateFunc(vec2 uv, vec2 center, float theta, vec2 resolution)
{
  vec2 uv0 = uv - center;
  uv0.y *= resolution.y / resolution.x;
  vec2 temp;
  temp.x = dot(vec2(cos(theta), -sin(theta)), uv0);
  temp.y = dot(vec2(sin(theta), cos(theta)), uv0);
  temp.y /= resolution.y / resolution.x;
  temp += center;
  return temp;
}

float CircleProgressBar(vec2 tc, vec2 center, vec2 resolution, float innerRadius, float outerRadius, float percentage, float progress, int invert)
{
  float middleRadius = 0.5 * (innerRadius + outerRadius);
  float halfWidth = 0.5 * (outerRadius - innerRadius);

  vec2 pos = (tc - center) * resolution.xy;
  float radius = length(pos.xy);

  float fr = halfWidth - abs(radius - middleRadius) + 1.0;
  fr = clamp(fr, 0.0, 1.0);

  float angle = 0.0;
  if(abs(pos.y) > 0.0){
    angle = degrees(atan(pos.x, -pos.y)) + 180.0;  
  }
  float fa = radians(angle - progress * 361.0 * (1.0 - percentage)) * radius + 1.0;
  if(progress > 0.999 && percentage < 0.00001 && invert == 1){
    fa = 0.0;
  }
  fa = clamp(fa, 0.0, 1.0);
  if(invert == 1){
    fa = 1.0 - fa;
  }

  return (fa * fr);
}

