vec4 GetColor(vec2 tc) {

  if (1.0 == PREFIX(Size)) return INPUT(tc);

  tc = (tc - 0.5) * 2.0;

  float size = float(PREFIX(Size)) / 250.0;

  if (iResolution.x >= iResolution.y) {
    tc.x *= iResolution.x / iResolution.y;
  } else {
    tc.y *= iResolution.y / iResolution.x;
  }

  float border = float(PREFIX(Border)) / 5.0;

  float mosaic_tc_size = size;
  float border_tc_size = mosaic_tc_size * 0.4 * border;

  vec2 center;

  center.x =
      floor(tc.x / mosaic_tc_size) * mosaic_tc_size + mosaic_tc_size * 0.5;
  center.y =
      floor(tc.y / mosaic_tc_size) * mosaic_tc_size + mosaic_tc_size * 0.5;

  vec2 uv = center;
  if (iResolution.x >= iResolution.y) {
    uv.x *= iResolution.y / iResolution.x;
  } else {
    uv.y *= iResolution.x / iResolution.y;
  }

  uv = (uv * 0.5) + 0.5;
  // Time varying pixel color
  vec4 col = INPUT(uv);

  col.rgb *= smoothstep(
      0.001, .0, sdCircle(tc - center, mosaic_tc_size * 0.5 - border_tc_size));

  return col;
}

