vec4 rotationRadialBlur(vec2 uv, float rotAngle, float strength) {
    vec2 center = vec2(0.5);
    vec2 toCenter = uv - center;
    float len = length(toCenter);

    // 计算旋转方向
    float rad = rotAngle * PI / 180.0;
    vec2 rotDir = vec2(cos(rad), sin(rad));

    vec4 color = vec4(0.0);
    float total = 0.0;

    // 沿旋转方向采样
    for(float i = 0.0; i < 9.0; i++) {
        float weight = 1.0 - (i / 9.0);
        float offset = (i / 9.0) * strength * 0.05;

        // 计算旋转后的采样位置
        vec2 rotatedOffset = roataionAngle(rotAngle) * (toCenter * offset);
