vec2 rotateFunc(vec2 uv, vec2 center, float theta)
{
	vec2 temp;
	temp.x = dot(vec2(cos(theta), -sin(theta)), uv - center);
	temp.y = dot(vec2(sin(theta), cos(theta)), uv - center);
	return temp + center;
}

vec4 Digital(vec2 tc, vec2 scale, float num_height, float number, vec4 roi, vec3 color)
{
	vec2 uv = tc;
	uv.y = 1.0 - uv.y;
	uv.y += num_height * number;
	uv *= scale;
	uv -= vec2(roi.x, 0.5 - num_height * 0.5) * scale;
	uv = fract(uv);
    vec4 retCol = INPUT2(uv);
	retCol.rgb = color * retCol.a;

	float matt = step(roi.x, tc.x)*step(tc.x, roi.z)*step(roi.y, tc.y)*step(tc.y, roi.w);
	retCol *= matt;

	return retCol;
}

vec4 percent(vec2 tc, vec2 scale, float height, vec4 roi, vec3 font_color)
{
	vec2 uv = tc;
	uv.y = 1.0 - uv.y;
	vec2 center = vec2(roi.x + (roi.z - roi.x) * 0.5, 0.5);
	uv -= center;
	uv *= scale;
	uv += center;

	vec4 retCol = INPUT3(uv);
	retCol.rgb = font_color * retCol.a;
	float matt = step(0.0, uv.x)*step(uv.x, 1.0)*step(0.0, uv.y)*step(uv.y, 1.0);
	retCol *= matt;

	return retCol;
}

vec4 mixFunc(vec4 back, vec4 overlap, float alp){

	float invAlp = 1.0 - alp;
	vec4 ret = back;

	if(alp > 0.0){
		ret.x = overlap.x + back.x * invAlp;
		ret.y = overlap.y + back.y * invAlp;
		ret.z = overlap.z + back.z * invAlp;
		ret.a = alp + back.a * invAlp;
	}

	return ret;	
}

