	vec2 size1 = vec2(1.19+rect_width,0.15+rect_height);
	float distance1 = roundedBoxSDF(pos1,size1*prop,radius,edgeSoftness);
	float smoothedAlpha1 = smoothstep(0.0, edgeSoftness,distance1);
	vec4 boardcolor = mix(borderColor,ret1,smoothedAlpha1);
//----------------------------------------------------------
	vec2 pos = vec2(0.0);
	vec2 size = vec2(0.0);
	float smoothedAlpha = 0.0;
	int total = int(18.0 * process);

	for(int number = 0; number < total; number++)
