        ret1 += barColor*(1.0-smoothedAlpha);
		//ret1 += mix(barColor,boardcolor,smoothedAlpha);
	}
    if(process<0.01)
		return boardcolor;
    return mix(boardcolor,ret1,ret1.a);
}

