    float rect_y = PREFIX(rect_y);
    float rect_x = PREFIX(rect_x);
    uv.x = uv.x - rect_x;
    uv.y = uv.y - rect_y;
    vec4 barColor = vec4(color_picker2,1.0);
	vec4 borderColor = vec4(color_picker1,1.0);
	//vec4 frameColor = vec4(color_picker4,1.0);
	float prop = iResolution.x / iResolution.y;
	vec2 coord = uv * iResolution;
    uv = 2.0*(coord.xy / iResolution.y) - vec2(prop, 1.0);
	uv = uv * (1.8 / vec2(prop, 1.0));

	float edgeSoftness  = 0.01;//PREFIX(fuzzy);
	float radius = 0.0;//PREFIX(radius)*prop;
	vec4 ret1 = vec4(0.0);
	vec4 ret2 = vec4(0.0);

	vec2 pos = vec2(0.0);
	vec2 size = vec2(0.0);
	float smoothedAlpha = 0.0;
	int total = int(20.0 * process);
	for(int number = 0; number < 20; number++)
	{
		pos = vec2((uv.x+0.8-0.11 * float(number))*prop,uv.y);
		size = vec2(0.03+rect_width,0.1+rect_height);
		smoothedAlpha = roundedBoxSDF(pos,size*prop,radius,edgeSoftness);
		ret1 += smoothedAlpha*borderColor;
	}
	for(int number = 0; number < total; number++)
	{
		pos = vec2((uv.x + 0.8 - 0.11 * float(number))*prop,uv.y);
		size = vec2(0.03+rect_width,0.1+rect_height);
		smoothedAlpha = roundedBoxSDF(pos,size*prop,radius,edgeSoftness);
		ret2 += smoothedAlpha*barColor;
	}
	ret1 = mix(ret1,ret2,ret2.a);// ret2 +ret1;
    return ret1;
}

