vec4 FUNCNAME(vec2 tc)
{    
    int Strength = PREFIX(Strength);
    int Range = PREFIX(Range);
    int Opacity = PREFIX(Opacity);

    vec4 origCol = INPUT(tc);
    vec4 retCol = origCol;

    vec2 uv = tc - vec2(0.5);
    float angle = atan(uv.x, uv.y);
    float radius = length(uv);
    float factor = -1.8 * float(Strength) / 100.0;
    float fRange = float(Range) / 100.0;
    fRange = mix(1.5, 5.0, fRange);
    float distortion = radius * (1.0 + factor * pow(radius, fRange));
    uv = vec2(0.5) + vec2(sin(angle), cos(angle)) * distortion;
    vec4 distortCol = INPUT(uv);
    retCol.rgb = mix(origCol.rgb, distortCol.rgb, float(Opacity)/100.0);
    retCol.rgb *= retCol.a;

    return retCol;
}

