vec4 mixFunc(vec4 back, vec4 overlap, float alp){
  float invAlp = 1.0 - alp;
  vec4 ret = back;
  if(alp > 0.0){
    ret.xyz = overlap.xyz + back.xyz * invAlp;
    ret.a = alp + back.a * invAlp;
  }
  return ret;
}

vec3 rgb2hsv(vec3 c) {
  vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
  vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
  vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));

  float d = q.x - min(q.w, q.y);
  float e = 1.0e-10;

  if (q.x < e) {
      return vec3(0.0, 0.0, 0.0); 
  }

  float h = abs(q.z + (q.w - q.y) / (6.0 * d + e));
  float s = d / q.x;
  float v = q.x;

  return vec3(h, s, v);
}

vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);

  vec3 rgb = c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);

  return rgb;
}

vec4 Glass(vec2 uv, float process){
  vec4 fragColor = vec4(0.0);
  vec2 center = vec2(0.5);

  float zoom = 0.3;
  float exposure = 0.1;
  float blur = 0.6;

  vec2 zoom_uv = uv;
	zoom_uv = (zoom_uv - center) * mix(1.0, 0.75, zoom) + center;
	vec4 zoom_texture = INPUT(zoom_uv);
	zoom_texture = vec4(zoom_texture.rgb * pow(2.0, exposure), zoom_texture.a);

  fragColor = INPUT(uv);
  zoom_texture.rgb = mix(zoom_texture.rgb * mix(0.25, 1.0, blur), zoom_texture.rgb, smoothstep(0.0, 0.001 + 0.499 * blur, 1.0));
  fragColor = mix(fragColor, zoom_texture, smoothstep(0.0, 0.001 + 0.499 * blur, 1.0));
  fragColor.rgb *= fragColor.a;

  return fragColor;
}

vec4 rgbSeparation(vec2 uv,float process) {
  float glitch = PREFIX(Strength) / 5000.0; 
  float angle = process * (PI * 2.0);
  float quantizedAngle = floor(angle / (PI / 8.0)) * (PI / 8.0);
  glitch = abs(glitch * sin(quantizedAngle));

  vec3 col;
  col.r = Glass(vec2(uv.x + glitch, uv.y),process).r;
  col.g = Glass(uv,process).g;
  col.b = Glass(vec2(uv.x - glitch, uv.y),process).b; 

  col *= (1.0 - glitch * 0.5);

  float alpha = Glass(uv,process).a;
  return vec4(col, alpha);
}

vec4 ColorTemperature(vec2 uv, float process) {
  float temperature = PREFIX(Color) / 500.0;
  vec4 fragColor = rgbSeparation(uv, process);
  vec3 hsv = rgb2hsv(fragColor.rgb);

  hsv.y *= (1.0 - abs(temperature) * 0.5);
  hsv.z *= (1.0 + (temperature + 1.0) * 0.25);
  float blueShift = clamp(temperature, 0.0, 1.0);

  fragColor.rgb = hsv2rgb(hsv);
  fragColor.r *= (1.0 + 0.2 * 0.5*(temperature + 1.0));
  fragColor.g *= (1.0 - 0.1 * 0.5*(temperature + 1.0));
  fragColor.b *= (1.0 - 0.1 * 0.5*(temperature + 1.0));

  fragColor.rgb = clamp(fragColor.rgb, 0.0, 1.0);
  return fragColor;
}

vec2 rotate_func(vec2 uv, vec2 center, float theta){
  vec2 temp;
  uv    -= center;
  uv.x  *= iResolution.x/iResolution.y;
  temp.x = dot(vec2(cos(theta), -sin(theta)), uv);
  temp.y = dot(vec2(sin(theta),  cos(theta)), uv);
  temp.x /= iResolution.x/iResolution.y;
  temp   += center;
  return temp;
}

float sdf_box(vec2 p, vec2 b, float angle, float blur){
  p            = p*2.0-1.0;
  float rad    = radians(angle);
  vec2  center = vec2(0.0);
  p            = rotate_func(p, center, rad);
  vec2  pb     = vec2(abs(p.x)-b.x, p.y-2.0);
  float r      = length(max(pb, 0.0))+min(max(pb.x, pb.y),0.0);
  return 1.0 - smoothstep(0.0, blur, r);
}

vec4 PsychedelicScan(vec2 tc, float process)
{
  vec2 uv = tc;
  vec4 fragColor = vec4(0.0);
  float uBlurEdge   = PREFIX(Feather) * 0.01;
  float uDirection  = PREFIX(Rotate) * 0.01;
  float uWidth      = PREFIX(Width) * 0.01;

  float dis = 1.0 + uBlurEdge;
  float offsetX = (process - 1.0) * (dis*2.0) + dis;
  float rotate_angle = mix(0.0, 360.0, uDirection);
  float rad = radians(rotate_angle);
  uv = rotate_func(uv, vec2(0.5, 0.5), rad);
  uv.x = uv.x - offsetX;
  float b1 = mix(0.1, 1.0, uWidth);
  float mask_1 = sdf_box(uv, vec2(b1, b1), 180.0, uBlurEdge);


  fragColor = ColorTemperature(tc,process) * mask_1;
  vec4 background = INPUT(tc);
  fragColor = mixFunc(background, fragColor, fragColor.a);
  return fragColor;
}

