vec4 CircleProgressBar(vec2 tc, float r, float progress, vec3 color)
{
	float factor = iResolution.x/640.0;
	float thickness = 3.5 * factor;
    float middleRadius = 0.5 * (r + thickness);
    float halfWidth = 0.5 * thickness;

    vec2 pos = (tc - vec2(0.5) + vec2(0.22,0.0)) * iResolution.xy;
    float radius = length(pos.xy);

	float fr = halfWidth - abs(radius - middleRadius);
    fr = clamp(fr, 0.0, 1.0);

	float angle = degrees(atan(pos.x, -pos.y)) + 180.0;
	float fa = radians(angle - progress * 360.0) * radius + 1.0;
    fa = clamp(fa, 0.0, 1.0);

    vec4 color1 = vec4(0.0);
    vec4 color2 = vec4(1.0);
    vec4 col = mix(color1, color2, fa);
	col.a *= fr;

	vec4 bgColor = vec4(0.0);
    col = mix(bgColor, col, col.a);

	if(progress > 0.999){
		col = vec4(0.0);
	}

	float matt = smoothstep(middleRadius, middleRadius - halfWidth, radius);
	vec4 circlCol = vec4(color,1.0)*matt;
	if(radius < (r + thickness)){
		col = mix(col, circlCol, circlCol.a);
	}

	return col;
}

