// from https://www.shadertoy.com/view/7sdXz2
float sdRoundSquare(vec2 p, vec2 s, float r) 
{
    vec2 q = abs(p)-s+r;
    return min(max(q.x,q.y),0.0) + length(max(q,0.0)) - r;
}

vec2 rotateFunc(vec2 uv, vec2 center, float theta)
{
	vec2 temp;
	temp.x = dot(vec2(cos(theta), -sin(theta)), uv - center);
	temp.y = dot(vec2(sin(theta), cos(theta)), uv - center);
	return temp + center;
}

vec4 Digital(vec2 tc, vec2 scale, float num_height, int number, vec4 roi, vec3 color)
{
	vec2 uv = tc;
	uv.y = 1.0 - uv.y;
	uv.y += num_height * float(number);
	uv *= scale;
	uv -= vec2(roi.x, roi.y) * scale;
	uv = fract(uv);
    vec4 retCol = INPUT2(uv);
	retCol.rgb = color.rgb * retCol.a;

	float matt = step(roi.x, tc.x)*step(tc.x, roi.z)*step(roi.y, 1.0-tc.y)*step(1.0-tc.y, roi.w);
	retCol *= matt;

	return retCol;
}

vec4 Colon(vec2 tc, vec2 scale, vec4 roi, vec3 font_color)
{
	float offset = -0.08;
	if(iResolution.x < iResolution.y)
		offset = -0.04;

	vec2 uv = tc;
	uv.y = 1.0 - uv.y;
	vec2 center = vec2(roi.x+(roi.z-roi.x)*0.5, (roi.y+(roi.w-roi.y)*0.5));
	uv -= center;
	uv *= scale;
	uv += center;
	uv.y += offset;

	vec4 retCol = INPUT3(uv);
	retCol.rgb = font_color * retCol.a;
	float matt = step(0.0, uv.x)*step(uv.x, 1.0)*step(0.0, uv.y)*step(uv.y, 1.0);
	retCol *= matt;

	return retCol;
}

int maxI(int a, int b)
{
    float x = float(a);
    float y = float(b);
    float m = x > y ? x : y;

	return int(m);
}

int modI(int a,int b){
    return (a)-((a)/(b))*(b);
}

int RightshiftOperation(int a,int b)
{
    int m = int(pow(2.0, float(b)));
	int temp = modI(a / m, 256);
    return temp;
}

float modF(float a,float b){
    return (a)-floor((a)/(b))*(b);
}

float RightshiftOperation(float a, int b){
    float m = 1.0;
    for(int i=0;i<b;i++){
        m *= 2.0;
    }       
    return floor(a/m);
}

float truncation(float a, int b){
    return modF((a),float(b));
}

vec3 calColor(int color){
    float color_red = truncation(RightshiftOperation(float(color), 16), 256);
	float color_green = truncation(RightshiftOperation(float(color), 8), 256);
	float color_blue = truncation(float(color), 256);
	vec3 colors = vec3(float(color_blue), float(color_green), float(color_red)) / 255.0;	
    return colors;
}

