    if(int(iGlobalTime * frame_rate + 0.5) == int(iTotalTime * frame_rate - 0.5)){
        isNotEnd = false;
    }

	vec2 center = vec2(position_x, position_y);
	float theta = radians(rotate);

	vec2 offset = vec2(0.5) - center;
	vec2 uv = tc;
	uv = (uv - center) / (scale + 0.001) + center;
    uv = rotateFunc(uv * iResolution.xy, center * iResolution.xy, theta) / iResolution.xy;
    uv += offset;

	int total_millisecond = iSecond * 100;
	int changeTime = int(floor(iGlobalTime * speed * 100.0));
	int hundredthsOfSec = 0;
    float aFullSecond = modF(iGlobalTime * speed, 1.0);	
	if(total_millisecond >= changeTime && iGlobalTime > 0.0 && aFullSecond != 0.0 && isNotEnd){
		hundredthsOfSec = modI(int(float(total_millisecond - int(floor(iGlobalTime / 4.0 * 100.0)))/2.0), 10);
        if(hundredthsOfSec == 0) 
            hundredthsOfSec = 1;
		hundredthsOfSec = maxI(hundredthsOfSec, 0);
	}

	int totalTime = total_millisecond - changeTime;
	totalTime = maxI(totalTime, 0);

	int second = maxI(modI(totalTime / 100, 60), 0);
	vec3 fontCol = calColor(PREFIX(Theme_color)); 

	/*int red = RightshiftOperation(font_color, 16);
	int green = RightshiftOperation(font_color, 8);
	int blue = modI(font_color, 256);
	vec3 fontCol = vec3(float(blue), float(green), float(red)) / 255.0;
	*/
	float prop = iResolution.x / iResolution.y;
	float imgProp = 30.0 / 600.0;
	float colonProp = 30.0 / 60.0;
	float titleProp = 256.0 / 206.0;

	float numWidth = 0.05 * (20.0 / 35.0);
	float numHeight = numWidth * 2.0 * prop;
	float numGap = numWidth + 0.005;

	float startPos = 0.735;
	float roiY = 0.51;
	float roiY1 = roiY + numHeight;

	vec2 scale_val = vec2(35.0, 35.0 * imgProp * (iResolution.y / iResolution.x));
	vec2 colon_scale = vec2(35.0, 35.0 * colonProp * (iResolution.y / iResolution.x));
	vec2 title_scale = vec2(4.0, 4.0 * titleProp * (iResolution.y / iResolution.x));

	vec4 digitalCol = vec4(0.0);
	for(int i = 0;i < 5; ++i){
		float roiX = startPos + numGap * float(i);
		float roiX1 = roiX + numWidth;
		vec4 roi = vec4(roiX, roiY, roiX1, roiY1);
		int number = 0;
		if(i == 0){
			number = second / 10;
		}else if(i == 1){
			number = modI(second, 10);
		}else if(i == 2){
			digitalCol += Colon(uv, colon_scale, roi, fontCol);
			continue ;
		}else if(i == 3){
			number = modI(totalTime / 10, 10);
		}else if(i == 4){
			number = hundredthsOfSec;
		}
		digitalCol += Digital(uv, scale_val, numHeight, number, roi, fontCol);
	}

	float r = 0.005;
	float process = 0.0;
	if(iSecond > 0){
		process = iGlobalTime  * speed / float(iSecond);
		process = min(process, 1.0);
	}
	float circle_start_pos = 0.1 + 0.8 * process;
	vec2 circle_center = vec2(circle_start_pos, 0.5);
	vec4 circleCol = circle(uv, circle_center, r, fontCol);

	vec2 size = vec2(0.8,0.001)*prop;
	vec2 rect_uv = uv * 2.0 - 1.0;
	rect_uv.x *= prop;
	float dist = sdRoundSquare(rect_uv, size, 0.0);
	dist = 1.0 - smoothstep(0.0, 0.01, dist);
	vec4 lineCol = vec4(fontCol,1.0) * dist;

	vec2 title_uv = uv;
	title_uv.y = 1.0 - title_uv.y;
	title_uv -= vec2(0.38, 0.5-0.06*prop);
	title_uv *= title_scale;
	title_uv = clamp(title_uv, 0.0, 1.0);
	vec4 titleCol = INPUT4(title_uv);
	titleCol.rgb = fontCol * titleCol.a;

	vec4 retCol = mix(lineCol, circleCol, circleCol.a) + digitalCol + titleCol;
	if(retCol.a > 0.0){
		retCol.rgb /= retCol.a;
	}

    float Opacity = float(PREFIX(General_opacity))/100.0;
	vec4 origCol = INPUT1(tc);
	retCol.rgb = mix(origCol.rgb, retCol.rgb, retCol.a);
