vec2 rotate(vec2 pnt, float angle, vec2 center)
{
    float rad = radians(angle);
    mat2 rotMat = mat2( cos(rad), sin(rad), 
                    -sin(rad), cos(rad) );
    pnt -= center;
    pnt.y *= iResolution.y / iResolution.x;
    pnt = rotMat * pnt;
    pnt.y /= iResolution.y / iResolution.x;
    pnt += center;
    return pnt;
}

vec4 rotateBlur(vec2 uv, float range, vec2 center)
{
    vec2 offsetL = vec2(0.0);
    vec2 offsetR = vec2(0.0);
    float sum_weights = 0.0;

    vec4 src = INPUT1(uv);
    vec4 result = src;
    sum_weights += 1.0;
    int sampleCount = 10;
    offsetL =  rotate(uv, range / float(sampleCount), center);
    offsetR =  rotate(uv, -range / float(sampleCount), center);
    float rotateWeight = 1.0;
    for (int i = 1; i < sampleCount; ++i){
        result +=  INPUT1(offsetL) * rotateWeight;
        result +=  INPUT1(offsetR) * rotateWeight;
        offsetL =  rotate(offsetL,  range / float(sampleCount) , center);
        offsetR =  rotate(offsetR, -range / float(sampleCount) , center);
        sum_weights  += 2.0 * rotateWeight;
        rotateWeight *= float(sampleCount-1)/float(sampleCount);
    }
    result /= sum_weights;

    uv -= 0.5;
    uv.y *= iResolution.y/iResolution.x;
    uv += 0.5;
    float radius = length(uv - center);
    float k = smoothstep(-0.2, 0.1 , radius);
    result = mix(src, result, k);
    return result;
}

