float GetIntensity(float process) {
  const float M_PI = 3.1415926535897932384626433832795;
  float intensity = 0.;
  if (process >= 0.0825 && process <= 0.2475) {
    intensity = pow(cos(((process - 0.165) / 0.0825) * M_PI * 0.5), 6.) * 0.4;
  } else if (process >= 0.4125 && process <= 0.5775) {
    intensity = pow(cos(((process - 0.495) / 0.0825) * M_PI * 0.5), 6.) * 0.4;
  } else if (process >= 0.7425 && process <= 0.9075) {
    intensity = pow(cos(((process - 0.825) / 0.0825) * M_PI * 0.5), 3.) * 0.8;
  }

  return intensity;
}

float lum(vec4 c) { return dot(c.rgb, vec3(0.3, 0.59, 0.11)); }

float sobel(vec2 tc) {

  vec2 imageIncrement = vec2(1.0, 1.0) / iResolution.xy;

  float t00 = lum(INPUT(tc + imageIncrement * vec2(-1.0, -1.0)));
  float t10 = lum(INPUT(tc + imageIncrement * vec2(0.0, -1.0)));
  float t20 = lum(INPUT(tc + imageIncrement * vec2(1.0, -1.0)));
  float t01 = lum(INPUT(tc + imageIncrement * vec2(-1.0, 0.0)));
  float t21 = lum(INPUT(tc + imageIncrement * vec2(1.0, 0.0)));
  float t02 = lum(INPUT(tc + imageIncrement * vec2(-1.0, 1.0)));
  float t12 = lum(INPUT(tc + imageIncrement * vec2(0.0, 1.0)));
  float t22 = lum(INPUT(tc + imageIncrement * vec2(1.0, 1.0)));

  vec2 grad;
  grad.x = t00 + 2.0 * t01 + t02 - t20 - 2.0 * t21 - t22;
  grad.y = t00 + 2.0 * t10 + t20 - t02 - 2.0 * t12 - t22;

  return length(grad);
}

vec2 scaleFunc(vec2 uv, vec2 scale, vec2 center) {
  return (uv - center) / (scale) + center;
}

vec4 FUNCNAME(vec2 tc) {

  vec4 color = vec4(0.0, 0.0, 0.0, 0.0);
  float speed = float(PREFIX(Speed)) / 100.;
  float gradual = 1.0;
  float iGlobalTime = PREFIX(global_time);
  float totalTime = PREFIX(total_time);
  float opacity = float(PREFIX(Opacity)) / 100.0;
  // opacity *= 0.6;

  float smooth_intensity =
      smoothstep(0., gradual, iGlobalTime) *
      (1.0 - smoothstep(totalTime - gradual, totalTime, iGlobalTime));

  totalTime = 0.5 + (1.0 - speed) * 2.;
  float process = mod(iGlobalTime, totalTime) / totalTime;
  float intensity = GetIntensity(process);
  vec2 uv = tc;
  uv = scaleFunc(uv, vec2(1. + intensity * 0.33), vec2(0.5));

  vec2 totalDir = vec2(intensity, 0.);
  // totalDir *= smooth_intensity;

  vec2 processColorSp = totalDir * 0.05;

  float rgb_intensity = float(PREFIX(RGB)) / 50.0;
  vec2 temp2 = uv + vec2(processColorSp * rgb_intensity);
  vec2 temp3 = uv - vec2(processColorSp * rgb_intensity);
  vec4 ori_col = INPUT(uv);
  color.ga += ori_col.ga;
  color.r += INPUT(temp2).r * opacity + ori_col.r * (1.0 - opacity);
  color.b += INPUT(temp3).b * opacity + ori_col.b * (1.0 - opacity);

  float edge_intensity = float(PREFIX(Edge)) / 50.0;
  vec2 offset = vec2(processColorSp) * 3. * edge_intensity;
  float r = sobel(uv - offset - vec2(abs(tc.x - 0.5), 0.) * 0.07 * edge_intensity);
  float g = sobel(uv - offset);
  float b = sobel(uv - offset + vec2(abs(tc.x - 0.5), 0.) * 0.07 * edge_intensity);

  color.rgb += vec3(r, g, b) * pow(intensity, .5) * opacity;
  vec4 outCol = color;
  outCol.rgb *= outCol.a;
  return outCol;
}

