#define MAX_RADIUS 3.0
#define HASHSCALE1 .1031
#define HASHSCALE3 vec3(.1031, .1030, .0973)
float hash12(vec2 p)
{
	vec3 p3  = fract(vec3(p.xyx) * HASHSCALE1);
    p3 += dot(p3, p3.yzx + 19.19);
    return fract((p3.x + p3.y) * p3.z);
}
vec4 Ripple(vec2 tc, float iTime) 
{
    float Speed = 50.0 / 50.0;
    float Intensity = 120.0 / 80.0;

    float resolution = 20. * exp2(-2. * Intensity);
    vec2 uv = (tc - 0.5) * iResolution.xy / iResolution.y * resolution + 0.5;

    vec2 circles = vec2(0.);
    vec2 center = vec2(0.5); // 
    vec2 hsh = center;
    vec2 p = center;

    float t = fract(0.35 * iTime * Speed );
    vec2 v = p - uv;
    float d = length(v) - (float(MAX_RADIUS) + 1.) * t;

    float h = 1e-3;
    float d1 = d - h;
    float d2 = d + h;
    float p1 = sin(31. * d1) * smoothstep(-0.6, -0.3, d1) * smoothstep(0., -0.3, d1);
    float p2 = sin(31. * d2) * smoothstep(-0.6, -0.3, d2) * smoothstep(0., -0.3, d2);
    circles += 0.5 * normalize(v) * ((p2 - p1) / (2. * h) * (1. - t) * (1. - t));
    circles /= float((MAX_RADIUS*1.0 + 1.0) * (MAX_RADIUS * 1.0 + 1.0 ));

    float eff_intensity = mix(0.01, 0.15, smoothstep(0.1, 0.6, abs(0.8*2.-1.)));
    vec3 n = vec3(circles, sqrt(1. - dot(circles, circles))); // normal
    vec3 color = INPUT1(tc - eff_intensity * n.xy).rgb + 5.*pow(clamp(dot(n, normalize(vec3(1., 0.7, 0.5))), 0., 1.), 6.);
	vec4 fragColor;
    fragColor = vec4(color, INPUT1(tc).a);
    return fragColor;
}
