    vec4 newColor2 = INPUT2(vec2(texPos2.x, texPos2.y));

    vec4 newColor = mix(newColor1, newColor2, fract(blueColor));
    fragOutCol = mix(textureColor, vec4(newColor.rgb, textureColor.a), intensity);
    fragOutCol.a = textureColor.a;

    return fragOutCol;
}

vec4 FUNCNAME(vec2 tc) 
{
  float iGlobalTime = PREFIX(global_time);
  float PI = 3.14159265;
  float Blur = float(PREFIX(Blur)) * 0.01;
  float Noise = float(PREFIX(Noise)) * 0.01;
  float angle = PI / 180.0;
  vec2  blurCenter = vec2(0.5) * iResolution;
  float radius = float(PREFIX(Range)) * 0.01;
  float Filter = float(PREFIX(Filter)) * 0.01;
  float aspect = iResolution.x / iResolution.y;

  vec2  uv = tc;
  vec2  tuv = rotate2D(uv,angle, aspect, vec2(0.5));
  vec2  xy = tuv * iResolution; 
  vec2  dxy = xy - blurCenter;
  float r = length(dxy);
  float rightAngle = 0.0;
  if (dxy.x == 0.0 && dxy.y > 0.0) {
    rightAngle = PI/2.0;
  } else if (dxy.x == 0.0 && dxy.y < 0.0) {
    rightAngle = -PI/2.0;
  } else{
    rightAngle = atan(dxy.y, dxy.x);
  }

  float leftAngle = rightAngle;
  float deltAngle = PI / 180.0 * Blur;

  float diagonal = length(iResolution);
  float distance = length(dxy);
  float maskRadius = diagonal * radius * 0.5;
  float feather = diagonal * 0.03;
  float mask = smoothstep(maskRadius - feather, maskRadius + feather, distance);
  mask = clamp(mask, 0.0, 1.0);

  vec4 origCol= INPUT1(tc);
  vec4 blurCol = RotateBlur(30, rightAngle, deltAngle, r, blurCenter, iResolution, leftAngle);

  vec4 retCol = mix(origCol, blurCol, mask);
  float val = 0.15 * (2.0 * noise(tc * 200.0) - 1.0);
  retCol += val * Noise;
  retCol = clamp(retCol, 0.0, 1.0);
  retCol = LUT(retCol, Filter);
  retCol.a = origCol.a;
  retCol.rgb = mix(origCol.rgb, retCol.rgb, step(0.00001, retCol.a));

  return retCol;
}

#define PI 3.14159265
float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
