    //k = negative for pincushion, positive for barrel
    float pincushion_pro = KeySpline(vec4(0.09, 0.23, 0.91, 0.07), iPro);
    float k = sin(-1.0*pincushion_pro);
    uvd = uvd*(1.0 + k*uvd*uvd);
    uv = vec2(0.5) + vec2(sin(uva), cos(uva))*uvd;

