    uv.y -= iPro*cos(uv.y*5.2+texdistort_pro*2.4)/100.0;

    col = INPUT(uv);
    if(mask.r > 0.0 && mask.r < 1.0){
      col = col * mask.r;
    }else{
      col = mix(mask, col, mask.r);
    }

    return col;
