vec4 BlurandExposure(vec2 uv, float process) {
  vec4 color = vec4(0.0);
  int samples = 20;

  float blurAmount = 0.05 * (1.0 - process); 
  float stepLength = blurAmount / float(samples);

  for (int i = 0; i < samples; i++) {
      float t = float(i) / float(samples - 1); 
      vec2 sampleUV = uv + vec2(0.0,stepLength * float(i));
      color += INPUT(sampleUV);
  }
  color = color / float(samples);
  color.rgb = color.rgb * (1.5 - 0.5 * process);
  return color;
}

float col(vec2 coord,float time, float Delay, float process)
  {
    float speed = 0.02; 
    float speed_x = 0.1; 
    float speed_y = 0.5; 
    int angle = 4; 
    float intensity = 0.0; 
    if(process <= 0.85){
      intensity = 5.0 * (0.85 - process);
    }else{
      intensity = 0.0;
    }
    int steps = 2; 
    float frequency = 6.0; 
    time = time / Delay;
    float delta_theta = 2.0 * PI / float(angle);  
    float col = 0.0;
    float theta = 0.0;
    for (int i = 0; i < steps; i++)
    {
      vec2 adjc = coord;
      theta = delta_theta*float(i); 
      adjc.x += cos(theta)*time*speed + time * speed_x; 
      adjc.y -= sin(theta)*time*speed - time * speed_y; 
      col = col + cos((0.0015 * adjc.x*cos(theta) - 1.3 * adjc.y*sin(theta))*frequency)*intensity; 
    }
    return sin(col); 
  }

vec2 s(vec2 p, float time, float process){
  float d=time*0.2;
  float strength = 0.0;
  if(process <= 0.85){
    strength = 32.0 * (0.85 - process);
  }else{
    strength = 0.0;
  }
  float x=strength * (p.x+d);
  float y=5.0 * (p.y+d);
  x = cos(x-y)*cos(y) * 2.5;
  y = sin(x+y)*sin(y);
  return vec2(x,y);
}

vec2 applyWaveEffect(vec2 uv, float process) {
  float strength = 0.0;
  if(process <= 0.85){
    strength = 10.0 *(0.85 - process);
  }else{
    strength = 0.0;
  }
  float emboss = 0.2; 
  float delta = 60.0;
  float Delay = 2.0;
  float time = PREFIX(global_time) * 1.3; 

  uv.y = 1.0 - uv.y;

  vec2 p = uv;
  vec2 c1 = p, c2 = p, c3 = p;

  c2.x += uv.x / delta;
  float dx = emboss * (col(c2, time, Delay, process)) / delta;
  c2.x = p.x;

  c2.y += uv.y / delta;
  float dy = emboss * (col(c2, time, Delay, process)) / delta;

  c3.x += dx * 2.0;
  c3.y = (c1.y + dy * 2.0);

  strength = strength * 0.05 + 1.0;

  c1 = uv + strength / iResolution.x * (s(uv, time, process) - s(uv + iResolution.xy, time, process));
  float waveLength = 0.01;

  vec2 ts = vec2(
      uv.x + cos(time) * waveLength * 0.5,
      uv.y - cos(time) * waveLength * strength
  );

  vec2 uvc = vec2((c1.x + ts.x + c3.x) / 3.0, (c1.y + ts.y + c3.y) / 3.0);

  uvc.y = 1.0 - uvc.y;

  return uvc;
}

