float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
  vec2 p1 = vec2(p.x, p.y);
  vec2 p2 = vec2(p.z, p.w);
  float mX1 = p1.x;
  float mY1 = p1.y;
  float mX2 = p2.x; 
  float mY2 = p2.y;
  if (mX1 == mY1 && mX2 == mY2)
    return aX;  // linear
  return CalcBezier(GetTForX(aX, mX1, mX2), mY1, mY2);
}

float Phase01(float t, float startV, float endV) {
  return clamp((t - startV) / max(endV - startV, 0.0001), 0.0, 1.0);
}

float RoundRectMask(vec2 uv, vec2 center, vec2 size, float radius, float feather) {
  float aspect = iResolution.x / iResolution.y;
  vec2 uvAdj = (uv - 0.5) * vec2(aspect, 1.0) + 0.5;
  vec2 centerAdj = (center - 0.5) * vec2(aspect, 1.0) + 0.5;
  vec2 sizeAdj = vec2(size.x * aspect, size.y);

  vec2 halfSize = sizeAdj * 0.5;
  float r = radius * min(sizeAdj.x, sizeAdj.y);
  float f = feather * min(sizeAdj.x, sizeAdj.y);

  vec2 d = abs(uvAdj - centerAdj) - halfSize + vec2(r);
  vec2 outside = max(d, 0.0);
  float dist = length(outside) + min(max(d.x, d.y), 0.0) - r;

  float corner = step(0.0, outside.x) * step(0.0, outside.y);
  float localFeather = max(f * corner, 0.0001);
  return 1.0 - smoothstep(0.0, localFeather, dist);
}

