    vec4 fragColor = INPUT(uv1);

    return fragColor;
}

vec3 HSL_RGBtoHSL(vec3 RGB)
{
    vec3 hsl;
    float R = RGB.x;
    float G = RGB.y;
    float B = RGB.z;
    float Max = 0.0;
    float Min = 0.0;
    float H = 0.0;
    float S = 0.0;
    float L = 0.0;

    Min = min(R, min(G, B));
    Max = max(R, max(G, B));

    if (Min == Max)
    {
        H = 2.0 / 3.0;
        S = 0.0;
        L = R;
    }
    else
    {
        L = (Max + Min) / 2.0;

        if (L < 0.5)
            S = (Max - Min) / (Max + Min);
        else
            S = (Max - Min) / (2.0 - Max - Min);

        if (R == Max)
            H = (G - B) / (Max - Min);
        else if (G == Max)
            H = 2.0 + (B - R) / (Max - Min);
        else
            H = 4.0 + (R - G) / (Max - Min);

        H /= 6.0;
        if (H < 0.0)
            H += 1.0;
    }

    hsl.x = H * 360.0;
    hsl.y = S;
    hsl.z = L;

    return hsl;
}

vec3 HSL_HSLtoRGB(vec3 HSL)
{
    vec3 RGB;
    float H = HSL.x / 360.0;
    float S = HSL.y;
    float L = HSL.z;
    float R = 0.0;
    float G = 0.0;
    float B = 0.0;
    float var_1 = 0.0;
    float var_2 = 0.0;
    float tempr = 0.0;
    float tempg = 0.0;
    float tempb = 0.0;

    if (S == 0.0)
    {
        R = G = B = L;
    }
    else
    {
        if (L < 0.5)
            var_2 = L * (1.0 + S);
        else
            var_2 = (L + S) - (L * S);

        var_1 = 2.0 * L - var_2;

        tempr = H + 1.0 / 3.0;
        if (tempr > 1.0)
            tempr=tempr-1.0;

        tempg = H;

        tempb = H - 1.0 / 3.0;
        if (tempb < 0.0)
            tempb=tempb+1.0;

        // Red
        if (tempr < 1.0 / 6.0)
            R = var_1 + (var_2 - var_1) * 6.0 * tempr;
        else if (tempr < 0.5)
            R = var_2;
        else if (tempr < 2.0 / 3.0)
            R = var_1 + (var_2 - var_1) * ((2.0 / 3.0) - tempr) * 6.0;
        else
            R = var_1;
        // Green
        if (tempg < 1.0 / 6.0)
            G = var_1 + (var_2 - var_1) * 6.0 * tempg;
        else if (tempg < 0.5)
            G = var_2;
        else if (tempg < 2.0 / 3.0)
            G = var_1 + (var_2 - var_1) * ((2.0 / 3.0) - tempg) * 6.0;
        else
            G = var_1;
        // Blue
        if (tempb < 1.0 / 6.0)
            B = var_1 + (var_2 - var_1) * 6.0 * tempb;
        else if (tempb < 0.5)
            B = var_2;
        else if (tempb < 2.0 / 3.0)
            B = var_1 + (var_2 - var_1) * ((2.0 / 3.0) - tempb) * 6.0;
        else
            B = var_1;
    }

    RGB.x = R;
    RGB.y = G;
    RGB.z = B;

    return RGB.zyx;
}

vec4 adjustSat(vec4 origCol, float satVal){
    if(abs(satVal) > 0.00001)
    {
        float maxV = max(origCol.b,max(origCol.r,origCol.g));
        float minV = min(origCol.b,min(origCol.r,origCol.g));
        if(abs(maxV - minV) > 0.00001)
        {
            float grayValue = (origCol.r * 11.0 + origCol.g * 59.0 + origCol.b * 30.0 + 0.196) * 0.01;
            float alpha = satVal;
            float ratio = (maxV - minV) / maxV;
            if(satVal > 0.0){
                alpha = satVal * (1.0 - ratio);
            }
            origCol.rgb += (origCol.rgb - grayValue) * alpha;
        }
        origCol = clamp(origCol, 0.0, 1.0);
    }
    return origCol;
}

float calBrightValue(float bright)
{
    float brightValue = 0.0;

    if (bright > 0.0)
    {
        brightValue = 1.0 + bright / 100.0;
    }
    else
    {
        brightValue = 1.0 - 1.0 / (0.99 + bright / 253.0);
        brightValue *= 0.6;
    }

    return brightValue;
}

vec4 newBrightness(vec4 color, float bright)
{
    vec4 ret;

    if (bright > 0.0)
        ret = color * bright;
    else
        ret = color + bright;

    ret.a = color.a;
    ret = clamp(ret, 0.0, 1.0);

    return ret;
}

vec4 adjustBrightness(vec4 retCol, float brightness)
{
    if(abs(brightness) > 0.00001){
        float brightValue = calBrightValue(brightness);
        retCol = newBrightness(retCol, brightValue);
    }
    return retCol;
}

vec4 adjustContrast(vec4 retCol, float contrastVal)
{
    if(contrastVal < 0.0){
        float contrast = 1.0 / (1.0 + abs(contrastVal) * 0.005);

        if(retCol.r > 0.0 && retCol.r < 0.5){
            retCol.r = pow(retCol.r * 2.0, contrast) / 2.0;
        }else if(retCol.r >= 0.5 && retCol.r < 1.0){
            retCol.r = 1.0 - pow(2.0 - retCol.r * 2.0, contrast) / 2.0;
        }

        if(retCol.g > 0.0 && retCol.g < 0.5){
            retCol.g = pow(retCol.g * 2.0, contrast) / 2.0;
        }else if(retCol.g >= 0.5 && retCol.g < 1.0){
            retCol.g = 1.0 - pow(2.0 - retCol.g * 2.0, contrast) / 2.0;
        }

        if(retCol.b > 0.0 && retCol.b < 0.5){
            retCol.b = pow(retCol.b * 2.0, contrast) / 2.0;
        }else if(retCol.b >= 0.5 && retCol.b < 1.0){
            retCol.b = 1.0 - pow(2.0 - retCol.b * 2.0, contrast) / 2.0;
        }
    }else if(contrastVal > 0.0){
        float contrast = 1.0 + contrastVal * 0.005;

        if(retCol.r > 0.0 && retCol.r < 0.5){
            retCol.r = pow(retCol.r * 2.0, contrast) / 2.0;
        }else if(retCol.r >= 0.5 && retCol.r < 1.0){
            retCol.r = 1.0 - pow(2.0 - retCol.r * 2.0, contrast) / 2.0;
        }

        if(retCol.g > 0.0 && retCol.g < 0.5){
            retCol.g = pow(retCol.g * 2.0, contrast) / 2.0;
        }else if(retCol.g >= 0.5 && retCol.g < 1.0){
            retCol.g = 1.0 - pow(2.0 - retCol.g * 2.0, contrast) / 2.0;
        }

        if(retCol.b > 0.0 && retCol.b < 0.5){
            retCol.b = pow(retCol.b * 2.0, contrast) / 2.0;
        }else if(retCol.b >= 0.5 && retCol.b < 1.0){
            retCol.b = 1.0 - pow(2.0 - retCol.b * 2.0, contrast) / 2.0;
        }
    }
    return clamp(retCol, 0.0, 1.0);
}

float enHanceColor(float color, float coff)
{
    float adjust = coff * color;
    float val = 1.0 - (1.0 - adjust) * (1.0 - color);

    return val;
}

vec4 adjustHighlight(vec4 color, float highLight)
{
    vec4 ret;
    float lumaince = highLight * 0.01 * (max(color.z, max(color.y, color.x)));

    ret.x = enHanceColor(color.x, lumaince);
    ret.y = enHanceColor(color.y, lumaince);
    ret.z = enHanceColor(color.z, lumaince);
    ret.w = color.w;
    ret = clamp(ret, 0.0, 1.0);

    return ret;
}

vec4 adjustShadow(vec4 color, float shadow){
    vec4 retCol = color;
    if(shadow > 0.0){
        if(retCol.r > 0.0)
            retCol.r = pow(retCol.r, (1.0 - shadow * 0.004));
        if(retCol.g > 0.0)
            retCol.g = pow(retCol.g, (1.0 - shadow * 0.004));
        if(retCol.b > 0.0)
            retCol.b = pow(retCol.b, (1.0 - shadow * 0.004));
        retCol = clamp(retCol, 0.0, 1.0);
    }else if(shadow < 0.0){
        if(retCol.r > 0.0)
            retCol.r = pow(retCol.r, (1.0 - shadow * 0.006));
        if(retCol.g > 0.0)
            retCol.g = pow(retCol.g, (1.0 - shadow * 0.006));
        if(retCol.b > 0.0)
            retCol.b = pow(retCol.b, (1.0 - shadow * 0.006));
        retCol = clamp(retCol, 0.0, 1.0);
    }
    return retCol;
}

vec4 LUT(vec4 textureColor, float intensity){
    vec4 fragOutCol;

    float blueColor = textureColor.r * 63.0;

    vec2 quad1;
    quad1.y = floor(floor(blueColor) / 8.0);
    quad1.x = floor(blueColor) - (quad1.y * 8.0);

    vec2 quad2;
    quad2.y = floor(ceil(blueColor) / 8.0);
    quad2.x = ceil(blueColor) - (quad2.y * 8.0);

    vec2 texPos1;
    texPos1.x = (quad1.x * 0.125) + 0.5/512.0 + ((0.125 - 1.0/512.0) * textureColor.b);
    texPos1.y = (quad1.y * 0.125) + 0.5/512.0 + ((0.125 - 1.0/512.0) * textureColor.g);

    vec2 texPos2;
    texPos2.x = (quad2.x * 0.125) + 0.5/512.0 + ((0.125 - 1.0/512.0) * textureColor.b);
    texPos2.y = (quad2.y * 0.125) + 0.5/512.0 + ((0.125 - 1.0/512.0) * textureColor.g);

    vec4 newColor1 = INPUT2(vec2(texPos1.x, texPos1.y));
    vec4 newColor2 = INPUT2(vec2(texPos2.x, texPos2.y));

    vec4 newColor = mix(newColor1, newColor2, fract(blueColor));
    fragOutCol = mix(textureColor, vec4(newColor.rgb, textureColor.s), intensity);
    fragOutCol.a = textureColor.a;

    return fragOutCol;
}

vec4 FUNCNAME(vec2 tc)
{    
    float Hue = PREFIX(Hue);
    float Saturation = PREFIX(Saturation) / 100.0;
    float Brightness = PREFIX(Brightness);
    float Contrast = PREFIX(Contrast);
    float Opacity = PREFIX(Opacity) / 100.0;
    float Highlight = PREFIX(Highlight);
    float Shadow = PREFIX(Shadowed);

    vec4 origCol = INPUT1(tc);
    vec4 retCol = origCol;

    vec3 hsl = HSL_RGBtoHSL(retCol.bgr);
    hsl.x += Hue * 0.01 * 360.0;
    hsl.x = mod(hsl.x, 360.0);
    retCol.rgb = HSL_HSLtoRGB(hsl);

    retCol = LUT(retCol, Opacity);

    if(abs(Highlight) > 0.0){
        retCol = adjustHighlight(retCol, Highlight);
    }

    if(abs(Shadow) > 0.0){
        retCol = adjustShadow(retCol, Shadow);
    }

    retCol = adjustBrightness(retCol, Brightness);
    retCol = adjustContrast(retCol, Contrast);
    retCol = adjustSat(retCol, Saturation);

    retCol.a = origCol.a;
    retCol.rgb *= retCol.a;

    return retCol;
}

