vec4 FUNCNAME(vec2 tc)
{
    vec2 fragCoord = tc * iResolution.xy;
    float iTime = PREFIX(global_time);
    float alpha = PREFIX(Opacity) * 2.0 / 100.0;
    float strength = (PREFIX(Strength) - 50.0) * 2.0 / 100.0;
    float position_x = (PREFIX(Position_X) - 50.0) / 100.0;
    float position_y = (PREFIX(Position_Y)  + 35.0) / 100.0;

    float aa = PREFIX(Speed) * 2.0 / 100.0;
    float bb = (PREFIX(Scale) - 50.0) * 2.0 / 100.0;

    int color = PREFIX(Color);
    float color_r = float((color >> 16) & 0xff) / 255.0;
    float color_g = float((color >> 8) & 0xff) / 255.0;
    float color_b = float(color & 0xff) / 255.0;
    vec3 userColor = vec3(color_b, color_g, color_r);

    float speed = .3 * aa;
    float scale = 2.2 * (1.0 - bb);
    bool turbulence = false;
    float shift = .3; 

    vec2 uv = (fragCoord - 0.5 - vec2(position_x, position_y) *iResolution.xy)/iResolution.y;
    float time = iTime * speed;
    float plainY = uv.y + .5 * (1.0 - strength);

    vec2 center = vec2(0.5);
    uv -= center;
    uv *= scale;
    uv += center;

    float mag = .2;

    float n = fbm(vec3(uv, time*.2)) * 0.5;
    n = fbm(vec3(uv - time*.2, n * mag + time*.1)) * 0.5;
    n = fbm(vec3(uv - time*.4, n * mag + time*.2)) * 0.5;

    if (turbulence) {
        n = abs(n);
    } else {
        n = n*.5 + .5;
    }

    n = pow(n,(shift + plainY * (1.-shift)));
    n *= 1. - plainY;

    vec3 frg_color = vec3( n*.98 , n*.95, n*.997) * userColor;

    vec4 fragColor = vec4(frg_color,1.0);
    vec4 bg_color = INPUT1(tc);

    fragColor.rgb = screen(bg_color.rgb,fragColor.rgb) * alpha;
    return fragColor;
}

float random(float x) {
