#define ZOOM_SCALE 0.5
#define DISTORT_AMOUNT 0.1
#define FADE_SECONDS 0.5

vec2 zoom(vec2 uv, float amount) {
    return 0.5 + ((uv - 0.5) * (1.0-amount));    
}

vec4 transition(vec2 uv, float fadeProgress) {
    if (fadeProgress <= 0.0) {
        return INPUT(uv);
    }

    float verticalDistort = sin(uv.y * 6.28318 + fadeProgress * 2.0) * DISTORT_AMOUNT * fadeProgress;
    uv.x += verticalDistort;

    float currentZoom = fadeProgress * ZOOM_SCALE;
    uv = zoom(uv, currentZoom);

    uv = clamp(uv, 0.0, 1.0);

    vec4 originalColor = INPUT(uv);
    vec4 blackColor = vec4(0.0, 0.0, 0.0, 1.0);

    return mix(originalColor, blackColor, fadeProgress);
}

