vec3 fireParticles(in vec2 uv, in vec2 originalUV) {
  vec3 particles = vec3(0.0);
  vec2 rootUV = floor(uv);
  float deg = degFromRootUV(rootUV);
  vec2 pointUV = voronoiPointFromRoot(rootUV, deg);
  float dist = 2.0;

  // UV manipulation for the faster particle movement
  vec2 tempUV = uv;
  // tempUV += -(noise2_2(uv * 3.0 + time) - 0.5) * 0.07;

  // Sparks sdf
  dist = length(tempUV - pointUV);
  // dist = sdBox(tempUV - pointUV, vec2(PARTICLE_SIZE));

  // Add sparks
  particles +=
      (1.0 - smoothstep(PARTICLE_SIZE * 0.6, PARTICLE_SIZE * 2.0, dist)) *
      base_color * 1.5;

  // Add bloom
  particles +=
      pow((1.0 - smoothstep(0.0, PARTICLE_SIZE * 8.0, dist)) * 1.0, 3.0) *
      base_color * 0.5;

  return particles;
}

// Layering particles to imitate 3D view
vec3 layeredParticles(in vec2 uv, in float sizeMod, in float alphaMod,
                      in int layers) {
  vec3 particles = vec3(0);
  float size = 1.0;
  float alpha = 1.0;
  vec2 offset = vec2(0.0);
  vec2 noiseOffset = vec2(0.0);
  vec2 bokehUV;

  for (int i = 0; i < layers; i++) {
    // Particle noise movement
    // noiseOffset = (noise2_2(uv * size * 2.0 + 0.5) - 0.5) * 0.15;

    // UV with applied movement
    bokehUV = (uv * size + time * movement_direction * movement_speed) +
              offset + noiseOffset;

    // Adding particles
    particles +=
        fireParticles(bokehUV, uv) * alpha * (1.0 - (float(i) / float(layers)));

    // Moving uv origin to avoid generating the same particles
    offset += hash2_2(vec2(alpha, alpha)) * 10.0;

    alpha *= alphaMod;
    size *= sizeMod;
  }

  return particles;
}

