float simplex3d(vec3 p) {
  vec3 s = floor(p + dot(p, vec3(0.3333333)));
  vec3 x = p - s + dot(s, vec3(0.1666667));
  vec3 e = step(vec3(0.0), x - x.yzx);
  vec3 i1 = e * (1.0 - e.zxy);
  vec3 i2 = 1.0 - e.zxy * (1.0 - e);
  vec3 x1 = x - i1 + 0.1666667;
  vec3 x2 = x - i2 + 2.0 * 0.1666667;
  vec3 x3 = x - 1.0 + 3.0 * 0.1666667;
  vec4 w, d;
  w.x = dot(x, x);
  w.y = dot(x1, x1);
  w.z = dot(x2, x2);
  w.w = dot(x3, x3);
  w = max(0.6 - w, 0.0);
  d.x = dot(random3(s), x);
  d.y = dot(random3(s + i1), x1);
  d.z = dot(random3(s + i2), x2);
  d.w = dot(random3(s + 1.0), x3);
  w *= w;
  w *= w;
  d *= w;
  return dot(d, vec4(52.0));
}

vec4 MotionBlur(vec2 tc) {
    float quality = 1.6;

  float amount = 50.;
  amount *= iResolution.x / 720.0 * 1.6;
  float blur = 2.0 * float(PREFIX(Blur)) / 100.0;
  amount *= blur;
  vec2 uv = tc;
  vec2 dir = (uv - 0.5);
  float x = length(uv - 0.5);
  dir = dir / iResolution.x * (amount)*1.2;
  float weight = 1.0;
  vec4 res = INPUT1(uv) * weight;
  float sumWeight = weight;
  float s = (1.0 + abs(amount) * quality * x);
  vec2 d = dir / floor(s);
  for (float i = -1.0; i > -500.0; i -= 1.0) {
    if (i <= -s)
      break;
    weight = 1.0;
    vec4 tmp = (INPUT1(uv - float(i) * d)) * weight;
    res += tmp;
    sumWeight += weight;
  }

  for (float i = 1.0; i < 500.0; i += 1.0) {
    if (i >= s)
      break;
    weight = 1.0;
    vec4 tmp = (INPUT1(uv - float(i) * d)) * weight;
    res += tmp;
    sumWeight += weight;
  }

  return vec4(res / sumWeight);
}

