}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float a = rand(i + vec2(0, 0));
  float b = rand(i + vec2(1, 0));
  float c = rand(i + vec2(0, 1));
  float d = rand(i + vec2(1, 1));
  return float(a + (b - a) * u.x + (c - a) * u.y +
               (a - b - c + d) * u.x * u.y) /
         4.;
}

float mirror(float t, float r) {
  t = fract(t + r);
  return 2. * abs(t - 0.5);
}

float radialNoise(float t, float d) {
  float speed = (float(PREFIX(Speed)) * 2.0 + 5.0) / 50.0;
  float time = PREFIX(global_time) * speed;

  const mat2 m2 = mat2(0.90, 0.44, -0.44, 0.90);
  const float SCALE = 45.;
  d = pow(d, 0.01);
  float doff = -time * 0.07;
  vec2 p = vec2(mirror(t, 0.1), d + doff);
  float f1 = noise(p * SCALE);
  p = 2.1 * vec2(mirror(t, 0.4), d + doff);
  float f2 = noise(p * SCALE);
  p = 3.7 * vec2(mirror(t, 0.8), d + doff);
  float f3 = noise(p * SCALE);
  p = 5.8 * vec2(mirror(t, 0.0), d + doff);
  float f4 = noise(p * SCALE);
  return pow((f1 + 0.5 * f2 + 0.25 * f3 + 0.125 * f4) * 3., 1.);
}

