#define PI 3.1415927
#define TWO_PI 6.283185

#define ANIMATION_SPEED 1.5

#define SIZE_MOD 1.5
#define ALPHA_MOD 0.9
#define LAYERS_COUNT 7

float hash1_2(in vec2 x) {
  return fract(sin(dot(x, vec2(52.127, 61.2871))) * 521.582);
}

vec2 hash2_2(in vec2 x) {
  return fract(sin(x * mat2(20.52, 24.1994, 70.291, 80.171)) * 492.194);
}

vec3 GetColor(int color){
  int r = color & 0xff;
  int g = color >> 8 & 0xff;
  int b = color >> 16 & 0xff;
  return vec3(float(r), float(g), float(b)) / 255.0;
}

// Simple interpolated noise
vec2 noise2_2(vec2 uv) {
  // vec2 f = fract(uv);
  vec2 f = smoothstep(0.0, 1.0, fract(uv));

  vec2 uv00 = floor(uv);
  vec2 uv01 = uv00 + vec2(0, 1);
  vec2 uv10 = uv00 + vec2(1, 0);
  vec2 uv11 = uv00 + 1.0;
  vec2 v00 = hash2_2(uv00);
  vec2 v01 = hash2_2(uv01);
  vec2 v10 = hash2_2(uv10);
  vec2 v11 = hash2_2(uv11);

  vec2 v0 = mix(v00, v01, f.y);
  vec2 v1 = mix(v10, v11, f.y);
  vec2 v = mix(v0, v1, f.x);

  return v;
}

// Rotates point around 0,0
vec2 rotate(vec2 point, float deg) {
  float s = sin(deg);
  float c = cos(deg);
  return mat2(s, c, -c, s) * point;
}

// Cell center from point on the grid
vec2 voronoiPointFromRoot(vec2 root, float deg) {
  vec2 point = hash2_2(root) - 0.5;
  float s = sin(deg);
  float c = cos(deg);
  point = mat2(s, c, -c, s) * point * 0.66;
  point += root + 0.5;
  return point;
}

// Voronoi cell point rotation degrees
float degFromRootUV(vec2 uv, float time) {
  return time * ANIMATION_SPEED * (hash1_2(uv) - 0.5) * 2.0;
}

vec2 randomAround2_2(vec2 point, vec2 range, vec2 uv) {
  return point + (hash2_2(uv) - 0.5) * range;
}

float dot2(vec3 v ) { return dot(v,v); }

float udQuad(vec3 p, vec3 v1, vec3 v2, vec3 v3, vec3 v4)
{
    #if 1
    // handle ill formed quads
    if( dot( cross( v2-v1, v4-v1 ), cross( v4-v3, v2-v3 )) < 0.0 )
    {
        vec3 tmp = v3;
        v3 = v4;
        v4 = tmp;
    }
    #endif

    vec3 v21 = v2 - v1; vec3 p1 = p - v1;
    vec3 v32 = v3 - v2; vec3 p2 = p - v2;
    vec3 v43 = v4 - v3; vec3 p3 = p - v3;
    vec3 v14 = v1 - v4; vec3 p4 = p - v4;
    vec3 nor = cross( v21, v14 );

    return sqrt( (sign(dot(cross(v21,nor),p1)) + 
                  sign(dot(cross(v32,nor),p2)) + 
                  sign(dot(cross(v43,nor),p3)) + 
                  sign(dot(cross(v14,nor),p4))<3.0) 
                  ?
                  min( min( dot2(v21*clamp(dot(v21,p1)/dot2(v21),0.0,1.0)-p1), 
                            dot2(v32*clamp(dot(v32,p2)/dot2(v32),0.0,1.0)-p2) ), 
                       min( dot2(v43*clamp(dot(v43,p3)/dot2(v43),0.0,1.0)-p3),
                            dot2(v14*clamp(dot(v14,p4)/dot2(v14),0.0,1.0)-p4) ))
                  :
                  dot(nor,p1)*dot(nor,p1)/dot2(nor) );
}

vec3 fireParticles(vec2 uv, vec2 originalUV, out bool is_end, int mode, inout vec3 addition_color, float time) {

  vec3 base_color = vec3(1.);

  vec3 particles = vec3(0.0);
  vec3 _addition_color = vec3(0.0);
  vec2 rootUV = floor(uv);
  if (rootUV.x == 0. || rootUV.y ==0.) return particles;
  float deg = degFromRootUV(rootUV, time);
  vec2 pointUV = voronoiPointFromRoot(rootUV, deg);
  float dist = 2.0;

  // UV manipulation for the faster particle movement
  vec2 tempUV = uv;
  float particle_size = 0.04;
  float radian = deg * 5.;

  mat3 rotate_x_mat = mat3(1., 0., 0.,
                            0., cos(radian), sin(radian), 
                            0., -sin(radian), cos(radian));


  mat3 rotate_y_mat = mat3(cos(radian), 0., -sin(radian),
                            0., 1., 0., 
                            sin(radian), 0., cos(radian));

  // radian = deg * 5.;
  float root_deg = 2. * PI * hash1_2(rootUV);
  radian += root_deg;
  mat3 rotate_z_mat = mat3(cos(radian), sin(radian), 0.,
                            -sin(radian), cos(radian), 0.,
                            0., 0., 1.);

  if (mode == 0) {
    vec3 quad[4];
    float quad_size = particle_size * 0.5;
    quad[0] = rotate_x_mat * rotate_y_mat * rotate_z_mat * vec3(-quad_size, -quad_size, 0.);
    quad[1] = rotate_x_mat * rotate_y_mat * rotate_z_mat * vec3(quad_size, -quad_size, 0.);
    quad[2] = rotate_x_mat * rotate_y_mat * rotate_z_mat * vec3(quad_size, quad_size, 0.);
    quad[3] = rotate_x_mat * rotate_y_mat * rotate_z_mat * vec3(-quad_size, quad_size, 0.);

    dist = udQuad(vec3(tempUV - pointUV, 0.), vec3(quad[0].xy, 0.),vec3(quad[1].xy, 0.), vec3(quad[2].xy, 0.), vec3(quad[3].xy, 0.));
  } else if (mode == 1) {
    particle_size = 0.25;
    tempUV += -(noise2_2(uv * 3.0) - 0.5) * 0.1;
    dist = length(tempUV - pointUV);
  }

  float degress = degrees(deg + root_deg);
  while(degress >= 360.) degress -= 360.;
  while(degress < 0.) degress += 360.;
  if (degress > 150. && degress < 210.) {

    float intensity = (1.0 - smoothstep(particle_size * 0., particle_size * 0.1, dist));
    _addition_color += intensity * vec3(0.8) * 1.2;
    particles += intensity * base_color * 0.15;

    if (mode == 0) {
      particles +=
          (1.0 - pow(smoothstep(particle_size * 0.08, particle_size * 1.5, dist), 0.3)) *
          base_color * 0.4;
    } else if (mode == 1) {
      particles +=
          (1.0 - pow(smoothstep(particle_size * 0.08, particle_size * 0.8, dist), 0.3)) *
          base_color * 0.4;
    }


    float factor = 1.0;
    if (degress > 180.) {
      factor = smoothstep(210., 180., degress);
    } else {
      factor = smoothstep(150., 180., degress);
    }

    particles *= pow(factor, 0.2);
    _addition_color *= pow(factor, 0.2);

    addition_color += _addition_color;
  } 

  particles +=
      (1.0 - smoothstep(particle_size * 0., particle_size * 0.05, dist)) *
      base_color * 0.15;

  is_end = dist < particle_size * 0.02;

  return particles;
}

// Layering particles to imitate 3D view
vec3 layeredParticles(vec2 uv, float base_size, float sizeMod, float alphaMod,
                      int layers, int mode, inout vec3 addition_color, float movement_speed, vec2 movement_direction, float time) {
  vec3 particles = vec3(0);
  float size = base_size;
  float alpha = 1.0;
  vec2 offset = vec2(0.0);
  vec2 noiseOffset = vec2(0.0);
  vec2 bokehUV;

  bool is_end = false;

  for (int i = 0; i < layers; i++) {
    // Particle noise movement
    // noiseOffset = (noise2_2(uv * size * 2.0 + 0.5) - 0.5) * 0.15;

    // UV with applied movement
    bokehUV = (uv * size + time * movement_direction * movement_speed) +
              offset + noiseOffset;

    vec3 _addition_color = vec3(0.);
    // Adding particles
    particles +=
        fireParticles(bokehUV, uv, is_end, mode, _addition_color, time) * alpha;

    addition_color += _addition_color * alpha;

    if (is_end) break;

    // Moving uv origin to avoid generating the same particles
    offset += hash2_2(vec2(alpha, alpha)) * 10.0;

    alpha *= alphaMod;
    if (mod(float(i), 2.0) == 1.){
      size *= pow(sizeMod, 2.);
    }

  }

  return particles;
}

vec4 shredded_paper(vec2 tc){
    float speed = PREFIX(Speed) / 100. + 1.0;
    float falling_time = PREFIX(global_time) * speed + 20.0;
    vec2 movement_direction = vec2(0., 1.0);
    float movement_speed = 1.0;
    vec3 color = GetColor(PREFIX(Color));

    float max_len = max(iResolution.x, iResolution.y);
    float min_len = min(iResolution.x, iResolution.y);
    vec2 uv = (2.0 * tc.xy * iResolution.xy  - iResolution.xy) / max_len;
    vec3 col;
    float background_intensity = pow(1.0 - (length(uv - vec2(0., -iResolution.y * 2.5 / max_len)) / (iResolution.y * 5. / min_len)), 5.);
    background_intensity = clamp(background_intensity, 0.0, 1.0);
    // float background_intensity = 0.0;

    col = color * background_intensity * 0.93;

    uv *= 1.8;

    vec3 addition_color = vec3(0.);
    // vec3 particles = layeredParticles(uv, 0.6, 1.1, 1.0, PREFIX(number) * 2, 0, addition_color);
    vec3 particles = layeredParticles(uv, 0.7, 1.3, 1.0, 5 * 2, 0, addition_color, movement_speed, movement_direction, falling_time);
    // vec2 uv, float base_size, float sizeMod, float alphaMod, int layers, int mode, inout vec3 addition_color
    particles += layeredParticles(uv, 1.0, 1., 1.0, int(max(1., float(4.0) * 0.4)), 1, addition_color, movement_speed, movement_direction, falling_time);

    col += particles * color + addition_color;

    col = smoothstep(-0.08, 1.0, col);

    vec4 out_color = vec4(col, 1.);
    vec4 origin_col = INPUT(tc);
    float alpha = (particles.r + background_intensity) / min(10., (max(0.2, (dot(color, vec3(1.)))) * 5.0));
    alpha = clamp(alpha, .0001, 1.);
    out_color = mix(origin_col*1.1, out_color / alpha,  alpha);
    out_color.rgb *= origin_col.a;
    out_color.a = origin_col.a;;
    return out_color;    
}

float sdbEllipsoidV2(vec2 p, vec2 r )
{
    float k1 = length(p/r);
    float k2 = length(p/(r*r));
    return (k1-1.0)*k1/k2;
}

float myIsoscelesTrapezoidSDF(vec2 p, float r1, float h, float r2)
{
    // float r2 = 2.0*h / tan(radians(angle));
    p.x = abs(p.x);
    vec2 qp1 = vec2(max(p.x-((p.y>0.0)?r1:r2), 0.0), abs(p.y)-h);

    vec2 ap = p-vec2(r1,h);
    vec2 ab = vec2(r2,-h) - vec2(r1,h);
    vec2 qp2 = ap-ab*clamp(dot(ap,ab)/dot(ab,ab), 0.0, 1.0);
    float s = (qp1.y<0.0 && qp2.x<0.0)?-1.0:1.0;

    float temp = 100.0;

    // if(p.y < -h) temp = sdbEllipsoidV2(p + vec2(0.,h), vec2(r2, r2*0.6*(r2 < 0.1 ? 1.0 : clamp(1.0 - 4.0*(r2-0.1)*(r2-0.1), 0.3, 1.0))));
    // if(p.y > h) temp = sdbEllipsoidV2(p - vec2(0.,h), vec2(r1, r1*0.6*(r1 < 0.1 ? 1.0 : clamp(1.0 - 4.0*(r1-0.1)*(r1-0.1), 0.3, 1.0))));

    if(s < 0.0 && temp<0.0) s = 1.0;
    temp = min(temp, length(qp1));
    return s*min(temp, length(qp2));
}


