vec2 rotateFunc(vec2 uv, vec2 center, float theta) {
  vec2 temp;
  temp.x = dot(vec2(cos(theta), -sin(theta)), uv - center);
  temp.y = dot(vec2(sin(theta), cos(theta)), uv - center);
  return temp + center;
}

vec4 mixFunc(vec4 back, vec4 overlap, float alp) {

  float invAlp = 1.0 - alp;
  vec4 ret = back;

  if (alp > 0.0) {
    ret.x = overlap.x + back.x * invAlp;
    ret.y = overlap.y + back.y * invAlp;
    ret.z = overlap.z + back.z * invAlp;
    ret.a = alp + back.a * invAlp;
  }

  return ret;
}

int modI(int a, int b) { return (a) - ((a) / (b)) * (b); }

float modF(float a, float b) { return (a)-floor((a) / (b)) * (b); }

int maxI(int a, int b) { return a > b ? a : b; }

float maxF(float a, float b) { return a > b ? a : b; }

float RightshiftOperation(float a, int b) {
  float m = 1.0;
  for (int i = 0; i < b; i++) {
    m *= 2.0;
  }
  return floor(a / m);
}

float truncation(float a, float b) { return modF(a, b); }

vec4 calColor(int color) {
  float color_red = truncation(RightshiftOperation(float(color), 16), 256.0);
  float color_green = truncation(RightshiftOperation(float(color), 8), 256.0);
  float color_blue = truncation(float(color), 256.0);
  vec4 colors = vec4(color_blue, color_green, color_red, 255.0) / 255.0;
  return colors;
}

vec4 Digital(vec2 tc, vec2 scale, float num_height, int number, vec4 roi,
             vec3 color) {
  vec2 uv = tc;
  uv.y = 1.0 - uv.y;
  uv.y += num_height * float(number);
  uv *= scale;
  uv -= vec2(roi.x, 0.5 - num_height * 0.5) * scale;
  uv = fract(uv);
  vec4 retCol = INPUT2(uv);
  float height = iResolution.y * max(float(PREFIX(Size)) / 50.0, 0.001);
  if (height < 400.0) {
    retCol = INPUT4(uv);
  }
  retCol.rgb *= color.rgb * retCol.a;

  float matt = step(roi.x, tc.x) * step(tc.x, roi.z) * step(roi.y, tc.y) *
               step(tc.y, roi.w);
  retCol *= matt;

  return retCol;
}

vec4 Colon(vec2 tc, vec2 scale, vec4 roi, vec3 color) {
  vec2 uv = tc;
  uv.y = 1.0 - uv.y;
