  vec2 colon_scale =
      vec2(20.0, 20.0 * colonProp * (iResolution.y / iResolution.x));

  vec4 retCol = vec4(0.0);
  float roiX = startPos;
  for (int i = 0; i < 8; ++i) {
    float roiX1 = roiX + numWidth;
    vec4 roi = vec4(roiX, roiY, roiX + numWidth, roiY1);

    int number = 0;
    if (i == 0) {
      number = hour / 10;
    } else if (i == 1) {
      number = modI(hour, 10);
    } else if (i == 3) {
      number = minute / 10;
    } else if (i == 4) {
      number = modI(minute, 10);
    } else if (i == 6) {
      number = second / 10;
    } else if (i == 7) {
      number = modI(second, 10);
    }

    vec2 texture_offset = vec2(0.0);
    if (i == 2 || i == 5) {
      texture_offset = vec2(colonOffsetX, colonOffsetY);
