#define PI 3.14159265358979323846
#define TAU 6.28318530717958647692

vec2 rotateFunc(vec2 uv, vec2 center, float theta) {
  vec2 temp;
  temp.x = dot(vec2(cos(theta), -sin(theta)), uv - center);
  temp.y = dot(vec2(sin(theta), cos(theta)), uv - center);
  return temp + center;
}

vec4 mixFunc(vec4 back, vec4 overlap, float alp) {

  float invAlp = 1.0 - alp;
  vec4 ret = back;

  if (alp > 0.0) {
    ret.x = overlap.x + back.x * invAlp;
    ret.y = overlap.y + back.y * invAlp;
    ret.z = overlap.z + back.z * invAlp;
    ret.a = alp + back.a * invAlp;
  }

  return ret;
}

int modI(int a, int b) { return (a) - ((a) / (b)) * (b); }

float modF(float a, float b) { return (a)-floor((a) / (b)) * (b); }

int maxI(int a, int b) { return a > b ? a : b; }

float maxF(float a, float b) { return a > b ? a : b; }

float RightshiftOperation(float a, int b) {
  float m = 1.0;
  for (int i = 0; i < b; i++) {
    m *= 2.0;
  }
  return floor(a / m);
}

float truncation(float a, float b) { return modF(a, b); }

vec4 calColor(int color) {
  float color_red = truncation(RightshiftOperation(float(color), 16), 256.0);
  float color_green = truncation(RightshiftOperation(float(color), 8), 256.0);
  float color_blue = truncation(float(color), 256.0);
  vec4 colors = vec4(color_blue, color_green, color_red, 255.0) / 255.0;
  return colors;
}

vec4 Digital(vec2 tc, vec2 scale, float num_height, int number, vec4 roi,
             vec3 color) {
  // float num_height = 0.1;
  vec2 uv = tc - roi.xy;
  uv /= roi.zw - roi.xy;
  uv.y = 1.0 - uv.y;
  uv.y *= 0.1;
  uv.y += 0.1 * float(number);
  vec4 retCol = INPUT2(uv);
  float height = iResolution.y * max(float(PREFIX(Size)) / 50.0, 0.001);
  if (height < 400.0) {
    retCol = INPUT4(uv);
  }
  retCol.rgb *= color.rgb * retCol.a;

  float matt = step(roi.x, tc.x) * step(tc.x, roi.z) * step(roi.y, tc.y) *
               step(tc.y, roi.w);
  retCol *= matt;

  return retCol;
}

vec4 Colon(vec2 tc, vec2 scale, vec4 roi, vec3 color) {
  vec2 uv = tc - roi.xy;
  uv /= roi.zw - roi.xy;
  uv.y = 1.0 - uv.y;
  vec4 retCol = INPUT3(uv);
  float height = iResolution.y * max(float(PREFIX(Size)) / 50.0, 0.001);
  if (height < 400.0) {
    retCol = INPUT5(uv);
  }
  retCol.rgb *= color.rgb * retCol.a;

  float matt = step(roi.x, tc.x) * step(tc.x, roi.z) * step(roi.y, 1.0 - tc.y) *
               step(1.0 - tc.y, roi.w);
  retCol *= matt;

  return retCol;
}

vec4 TextureDigital(vec2 uv, vec2 iResolution, int totalSecond, vec3 fontCol) {
  float prop = iResolution.x / iResolution.y;
  float imgProp = 60.0 / 1200.0;
  float colonProp = 60.0 / 120.0;

  int curTime = totalSecond;
  curTime = maxI(curTime, 0);

  int hour = maxI(curTime / 60 / 60, 0);
  curTime -= hour * 60 * 60;
  int minute = maxI(curTime / 60, 0);
  curTime -= minute * 60;
  int second = maxI(curTime, 0);

  float numWidth = (0.1 - 3.0 / 10000.0) * (10.0 / 20.0);
  float numHeight = numWidth * 2.0 * prop;
  float numGap = numWidth + 0.005;
  float colonGap = numGap * 0.45;
  float colonOffsetX = numWidth * 0.25;
  float colonOffsetY = numHeight * 0.075;

  // float startPos = 0.235 - 18.0/10000.0;
  float startPos = 0.5 - numGap * 3. - colonGap;
  float roiY = 0.5 - numHeight * 0.5;
  float roiY1 = roiY + numHeight;

  vec2 scale_val = vec2(20.0, 20.0 * imgProp * (iResolution.y / iResolution.x));
  vec2 colon_scale =
      vec2(20.0, 20.0 * colonProp * (iResolution.y / iResolution.x));

  vec4 retCol = vec4(0.0);
  float roiX = startPos;
  for (int i = 0; i < 8; ++i) {
    float roiX1 = roiX + numWidth;
    vec4 roi = vec4(roiX, roiY, roiX + numWidth, roiY1);

    int number = 0;
    if (i == 0) {
      number = hour / 10;
    } else if (i == 1) {
      number = modI(hour, 10);
    } else if (i == 3) {
      number = minute / 10;
    } else if (i == 4) {
      number = modI(minute, 10);
    } else if (i == 6) {
      number = second / 10;
    } else if (i == 7) {
      number = modI(second, 10);
    }

    vec2 texture_offset = vec2(0.0);
    if (i == 2 || i == 5) {
      texture_offset = vec2(colonOffsetX, 0.0);
    }

    roiX1 = roiX + numWidth;
    roi = vec4(roiX - texture_offset.x, roiY - texture_offset.y,
               roiX1 - texture_offset.x, roiY1 - texture_offset.y);

    if (i == 2 || i == 5) {
      retCol += Colon(uv, colon_scale, roi, fontCol);
    } else {
      retCol += Digital(uv, scale_val, numHeight, number, roi, fontCol);
    }

    if (i == 2 || i == 5) {
      roiX += colonGap;
    } else {
      roiX += numGap;
    }
  }
  return retCol;
}

