vec2 Rotate(vec2 v, vec2 o, float a) {
    v = v * iResolution;
    v -= o * iResolution;
    vec4 m = vec4(cos(a), -sin(a), sin(a), cos(a));
    // vec4 m = vec4(cos(-a), -sin(-a), sin(-a), cos(-a));
    float new_x = v.x*m.x + v.y*m.z;
    float new_y = v.x*m.y + v.y*m.w;
    v = vec2(new_x, new_y);
    v += o * iResolution;
    v = v / iResolution;

    return v;
}

