vec2 bezier(float t, vec2 p1, vec2 p2, vec2 p3, vec2 p4) {
	vec2 points[4]=vec2[](p1,p2,p3,p4);
    vec2 p = vec2(0.0);
    int n1 = 4 - 1;
    for(int i = 0; i <= n1; i++) {
        float coef = float(1);
        for(int j = 1; j <= i; j++) {
            coef *= float(n1 - j + 1) / float(j);
        }
        p += points[i] * coef * pow(1.0 - t, float(n1 - i)) * pow(t, float(i));
    }
    return p;
}

float findBezierY(float x, vec2 p2, vec2 p3) {
    float epsilon = 0.0001;
    float tMin = 0.0;
    float tMax = 1.0;
    float t = 0.5;

    vec2 p1 = vec2(0.00,0.00);
    vec2 p4 = vec2(0.80,1.00);

    for(int i = 0; i < 16; i++) {
        vec2 p = bezier(t,p1,p2,p3,p4);
        if(abs(p.x - x) < epsilon) {
            return p.y;
        }
        if(p.x < x) {
            tMin = t;
        } else {
            tMax = t;
        }

        t = (tMin + tMax) / 2.0;
    }
    return bezier(t,p1,p2,p3,p4).y;
}

float getOuterBottomEdgeFade(vec2 coord, float edgeWidth) {
    float dy = coord.y - 1.0;
    return 1.0 - smoothstep(0.0, edgeWidth, dy);
}

vec4 rotateWithMirror(vec2 uv, vec2 pivot, float t) {
    float edgeWidth = 0.1;

    const int samples = 6;
    float maxAngleStep = 0.4;
    float blurDuration = 0.3;

    const int trailSamples = 16;
    float trailLength = 0.15;
    float minTrailAlpha = 0.02;
    float trailFadeInDuration = 0.5;

    float blurStrength = smoothstep(0.0, blurDuration, t);
    float currentAngleStep = maxAngleStep * blurStrength;

    float trailStrength = smoothstep(0.0, trailFadeInDuration, t);

    vec4 totalColor = vec4(0.0);
    float totalWeight = 0.0;

    for(int trail = 0; trail < trailSamples; trail++) {
        float trailProgress = float(trail) / float(trailSamples - 1);

        float currentTrailLength = trailLength * trailStrength;
        float trailTime = t - currentTrailLength * trailProgress;

        if(trailTime < 0.0) continue;

        float trailAlpha = mix(1.0, minTrailAlpha, pow(trailProgress, 2.0));
        trailAlpha *= trailStrength;

        float baseAngle = -trailTime * 60.0;

        for(int i = 0; i < samples; i++) {
            float progress = float(i) / float(samples - 1);
            float currentAngle = baseAngle + (progress - 0.5) * currentAngleStep;

            float weight = exp(-4.0 * pow(progress - 0.5, 2.0)) * trailAlpha;

            vec2 currentUV = uv * iResolution.xy;
            vec2 currentPivot = pivot * iResolution.xy;

            float cosA = cos(radians(currentAngle));
            float sinA = sin(radians(currentAngle));

            vec2 centered = currentUV - currentPivot;
            vec2 rotated = centered * mat2(cosA, -sinA, sinA, cosA);
            vec2 final = rotated + currentPivot;

            vec2 normalizedCoord = final / iResolution.xy;

            vec4 sampleColor = vec4(0.0);

            if(normalizedCoord.x >= 0.0 && normalizedCoord.x <= 1.0 && 
               normalizedCoord.y >= 0.0 && normalizedCoord.y <= 1.0) {
                sampleColor = INPUT(normalizedCoord);
            } 

            else {
                vec2 xMirror = vec2(final.x, -final.y) / iResolution.xy;
                if(xMirror.x >= 0.0 && xMirror.x <= 1.0 && 
                   xMirror.y >= 0.0 && xMirror.y <= 1.0 + edgeWidth) {
                    if(xMirror.y > 1.0) {
                        vec4 color = INPUT(vec2(xMirror.x, 1.0));
                        float fade = getOuterBottomEdgeFade(xMirror, edgeWidth);
                        sampleColor = vec4(color.rgb * fade, color.a);
                    } else {
                        sampleColor = INPUT(xMirror);
                    }
                } 

                else {
                    vec2 yMirror = vec2(-final.x, final.y) / iResolution.xy;
                    if(yMirror.x >= 0.0 && yMirror.x <= 1.0 && 
                       yMirror.y >= 0.0 && yMirror.y <= 1.0) {
                        sampleColor = INPUT(yMirror);
                    } 

                    else {
                        vec2 xyMirror = vec2(-final.x, -final.y) / iResolution.xy;
                        if(xyMirror.x >= 0.0 && xyMirror.x <= 1.0 && 
                           xyMirror.y >= 0.0 && xyMirror.y <= 1.0 + edgeWidth) {
                            if(xyMirror.y > 1.0) {
                                vec4 color = INPUT(vec2(xyMirror.x, 1.0));
                                float fade = getOuterBottomEdgeFade(xyMirror, edgeWidth);
                                sampleColor = vec4(color.rgb * fade, color.a);
                            } else {
                                sampleColor = INPUT(xyMirror);
                            }
                        }
                    }
                }
            }

            if(sampleColor.a > 0.0) {
                totalColor += sampleColor * weight;
                totalWeight += weight;
            }
        }
    }

    return totalWeight > 0.0 ? totalColor / totalWeight : vec4(0.0);
}

