vec3 HSL_RGBtoHSL(vec3 RGB)
{
	vec3 hsl;
	float R = RGB.r;//
	float G = RGB.g;
	float B = RGB.b;
	float Max = 0.0;
	float Min = 0.0;
	float H = 0.0;
	float S = 0.0;
	float L = 0.0;

	Min = min(R, min(G, B));
	Max = max(R, max(G, B));

	if (Min == Max)
	{
		H = 2.0 / 3.0;
		S = 0.0;
		L = R;
	}
	else
	{
		L = (Max + Min) / 2.0;

		if (L < 0.5)
			S = (Max - Min) / (Max + Min);
		else
			S = (Max - Min) / (2.0 - Max - Min);

		if (R == Max)
			H = (G - B) / (Max - Min);
		else if (G == Max)
			H = 2.0 + (B - R) / (Max - Min);
		else
			H = 4.0 + (R - G) / (Max - Min);

		H /= 6.0;
		if (H < 0.0)
			H += 1.0;
	}

	hsl.x = H * 360.0;
	hsl.y = S;
	hsl.z = L;

	return hsl;
}

//---------------------------------------------------------------------------------------//
vec3 HSL_HSLtoRGB(vec3 HSL)
{
	vec3 RGB;
	float H = HSL.x / 360.0;
	float S = HSL.y;
	float L = HSL.z;
	float R = 0.0;
	float G = 0.0;
	float B = 0.0;
	float var_1 = 0.0;
	float var_2 = 0.0;
	float tempr = 0.0;
	float tempg = 0.0;
	float tempb = 0.0;

	if (S == 0.0)
	{
		R = G = B = L;
	}
	else
	{
		if (L < 0.5)
			var_2 = L * (1.0 + S);
		else
			var_2 = (L + S) - (L * S);

		var_1 = 2.0 * L - var_2;

		tempr = H + 1.0 / 3.0;
		if (tempr > 1.0)
            tempr -= tempr;
			//tempr--;

		tempg = H;

		tempb = H - 1.0 / 3.0;
		if (tempb < 0.0)
			tempb += tempb;

		// Red
		if (tempr < 1.0 / 6.0)
			R = var_1 + (var_2 - var_1) * 6.0 * tempr;
		else if (tempr < 0.5)
			R = var_2;
		else if (tempr < 2.0 / 3.0)
			R = var_1 + (var_2 - var_1) * ((2.0 / 3.0) - tempr) * 6.0;
		else
			R = var_1;
		// Green
		if (tempg < 1.0 / 6.0)
			G = var_1 + (var_2 - var_1) * 6.0 * tempg;
		else if (tempg < 0.5)
			G = var_2;
		else if (tempg < 2.0 / 3.0)
			G = var_1 + (var_2 - var_1) * ((2.0 / 3.0) - tempg) * 6.0;
		else
			G = var_1;
		// Blue
		if (tempb < 1.0 / 6.0)
			B = var_1 + (var_2 - var_1) * 6.0 * tempb;
		else if (tempb < 0.5)
			B = var_2;
		else if (tempb < 2.0 / 3.0)
			B = var_1 + (var_2 - var_1) * ((2.0 / 3.0) - tempb) * 6.0;
		else
			B = var_1;
	}
	RGB.r = R;
	RGB.g = G;
	RGB.b = B;

	return RGB;
}

