vec4 FUNCNAME(vec2 tc)  {
	vec4 origCol = INPUT1(tc);
	vec4 retCol = origCol;
	vec2 fragCoord = tc.xy * iResolution.xy;
	float factor = max(iResolution.x, iResolution.y) / 960.0;
	float iGlobalTime = PREFIX(global_time);
	int number = PREFIX(number);
	float speed = PREFIX(speed)*0.0001;
	float alp = float(PREFIX(alpha))/100.0;	
	for(int i = 0; i < number; ++i)
	{
		float a = float(i);
		float hue_val = PREFIX(hue)*a*0.3*fract(iGlobalTime)*360.0;
		float tha = fract(iGlobalTime*speed)*360.0;
		float strength = PREFIX(strength)*0.1*fract(iGlobalTime*a*0.1)*10.0;
		vec2 center = vec2(iResolution.x * 0.5+(random(vec2(a*9.0))*2.0 -1.0)*iResolution.x * 0.5,iResolution.y * 0.5 + (random(vec2(a*15.0))*2.0-1.0)*iResolution.y * 0.5);
		float radius = 25.0 * factor;
		radius *= (1.0 + strength);

		vec2 left_bottom = vec2(center.x - radius, center.y - radius);
		vec2 right_up = vec2(center.x + radius, center.y + radius);

		float matt = step(left_bottom.x,fragCoord.x)*step(fragCoord.x,right_up.x)*step(left_bottom.y,fragCoord.y)*step(fragCoord.y,right_up.y);

		if(matt > 0.5)
		{
			vec2 uv = (fragCoord.xy - left_bottom.xy)/(radius * 2.0 + 1.0);
			uv = rotateFunc(uv, tha);
			uv.y = 1.0 - uv.y;
			vec4 texCol = INPUT2(uv);
			vec3 texHSL = HSL_RGBtoHSL(texCol.xyz);

			texHSL.x += step(0.1, hue_val) * hue_val ;
			texHSL.x += step(360.0, texHSL.x) * (-360.0);

			vec3 texRGB = HSL_HSLtoRGB(texHSL);
			vec4 tepCol = retCol;
			retCol.xyz = min(retCol.xyz + texRGB.xyz, 1.0);
			texCol.w = texCol.w * (fract(iGlobalTime+a*0.5)+1.0)*0.3;
			retCol.xyz = mix(tepCol.xyz,retCol.xyz,texCol.w);
		}
	}
	return mix(origCol, retCol, alp);
}

