float sminCubic( float a, float b, float k )
{
    const float EQUAL_THRESHOLD = 0.0001;
    float h = max( k - abs(a - b) , 0.0 ) / max(k , EQUAL_THRESHOLD);
    return min( a, b ) - h * h * h * k * (1.0 / 6.0);
}


