#define WS_PI		    3.14159354	   
#define PI_180       0.01745329      /* pi/180 */ 
vec2 SineWave(vec2 p, float uType, float uPhase,float uCos, float uSin,float uHeight,float uWidth) 
{
    vec2 targetUV = p * iResolution.xy;
    mat3 sMat = mat3(uCos, -uSin, 0,
                    uSin,  uCos, 0,
                    0,        0, 1);
    targetUV = (sMat * vec3(targetUV, 1.0)).xy;

    float y = targetUV.y;
    float phase = (y / uWidth) * WS_PI * 2.0 - uPhase;
    targetUV.x += uHeight * sin(mix(sin(phase), phase, uType));
    mat3 eMat = mat3(uCos, uSin, 0,
                    -uSin, uCos, 0,
                        0,    0, 1);
    targetUV = (eMat * vec3(targetUV, 1.0)).xy;
    return targetUV / iResolution.xy;
}


