float noise(vec2 p, float iGlobalTime)
{
	vec2 v = vec2(1.,2.*cos(iGlobalTime))*iGlobalTime*8. + p*1.;
	v.x = mod(v.x, 1.0);
	v.y = mod(v.y, 1.0);
	float sample_x = INPUT2(v).x;
	sample_x *= sample_x;
	return sample_x;
}

float onOff(float a, float b, float c, float iGlobalTime)
{
	return step(c, sin(iGlobalTime + a*cos(iGlobalTime*b)));
}

float ramp(float y, float start, float end)
{
	float inside = step(start,y) - step(end,y);
	float fact = (y-start)/(end-start)*inside;
	return (1.-fact) * inside;

}

float stripes(vec2 uv, float iGlobalTime)
{

	float noi = noise(uv*vec2(0.5,1.) + vec2(1.,3.), iGlobalTime);
	return ramp(mod(uv.y*4. + iGlobalTime/2.+sin(iGlobalTime + sin(iGlobalTime*0.63)),1.),0.5,0.6)*noi;
}

vec3 getVideo(vec2 uv, float iGlobalTime)
{
	vec2 look = uv;
	float window = 1./(1.+20.*(look.y-mod(iGlobalTime/4.,1.))*(look.y-mod(iGlobalTime/4.,1.)));
	look.x = look.x + (sin(look.y*10. + iGlobalTime)/50.*onOff(4.,4.,.3, iGlobalTime)*(1.+cos(iGlobalTime*80.))*window);
	float vShift = 0.4*onOff(2.,3.,.9, iGlobalTime)*(sin(iGlobalTime)*sin(iGlobalTime*20.) + 
										 (0.5 + 0.1*sin(iGlobalTime*200.)*cos(iGlobalTime)));
	look.y = mod(look.y + (vShift), 1.);
	vec3 video = INPUT1(look).rgb;
	return video;
}

vec2 screenDistort(vec2 uv)
{
	uv -= vec2(.5,.5);
	uv = uv*1.2*(1./1.2+2.*uv.x*uv.x*uv.y*uv.y);
	uv += vec2(.5,.5);
	return uv;
}

