float gaussian(vec2 i, int samples) {
    float sigma = float(samples)*0.25;
	float pi = 3.14159265;
    return 1.0 / (2.0 * pi * pow(sigma, 2.0)) * exp(-((pow(i.x, 2.0) + pow(i.y, 2.0)) / (2.0 * pow(sigma, 2.0))));
}

vec4 blur(vec2 iuv, vec2 scale, int samples) {
    vec3 col = vec3(0.0);
    vec4 ori = vec4(0.0);
    float accum = 0.0;
    float weight = 0.0;
    vec2 offset = vec2(0.0);
	float alpha = 0.0;

	for (int x = -(samples / 2); x < samples / 2; ++x) {
		for (int y = -(samples / 2); y < samples / 2; ++y) {
			offset = vec2(float(x), float(y));
			weight = gaussian(offset, samples);
			ori = INPUT(iuv + scale * offset);
			alpha = min(1.0, ori.a + alpha);
			col += ori.rgb * weight;
			accum += weight;
		}
	}

    return vec4(col / accum, alpha);
}

