            if(t1 > 0.0){
                retCol.rgb = colorDodge(digitalCol, retCol.rgb);
            }else if(t2 > 0.0){
                retCol.rgb = colorDodge(digitalCol2, retCol.rgb);
            }
        }
    }

    vec4 origCol = INPUT(tc);
    retCol.a = origCol.a;
    retCol.rgb *= retCol.a;

    return retCol;
}

