float col(vec2 coord,float time, float Delay)
  {
    float speed = 0.02; 
    float speed_x = 0.1; 
    float speed_y = 0.5; 
    int angle = 4; 
    float intensity = PREFIX(strength) * 0.04 + 0.5; 
    int steps = 2; 
    float frequency = 6.0; 
    time = time / Delay;
    float delta_theta = 2.0 * PI / float(angle);  
    float col = 0.0;
    float theta = 0.0;
    for (int i = 0; i < steps; i++)
    {
      vec2 adjc = coord;
      theta = delta_theta*float(i); 
      adjc.x += cos(theta)*time*speed + time * speed_x; 
      adjc.y -= sin(theta)*time*speed - time * speed_y; 
      col = col + cos((0.0015 * adjc.x*cos(theta) - 1.3 * adjc.y*sin(theta))*frequency)*intensity; 
    }
    return sin(col); 
  }

