    float block_thresh = pow(random(vec2(floor(iGlobalTime * 10.0 * Speed))), 2.0);
    float line_thresh = pow(random(vec2(floor(iGlobalTime * 15.0 * Speed))), 2.0);
    float noise = random(vec2(floor(iGlobalTime * 15.0 * Speed + 100.0)));
    float rnd = rnd1 * rnd2 * rnd3 * 0.3;

    if(PREFIX(BlockSize) > 0.001){
        if (random(vec2(floor(uv * 16.0 * noise * BlockSize))) < block_thresh || random(vec2(floor(uv * 26.0 * noise * BlockSize))) < line_thresh) {
            retCol.r = INPUT(uv + vec2(rnd, 0.0)).r;
            retCol.g = INPUT(uv + vec2(rnd + 0.005 * BlockRGBSeparate, 0.0)).g;
            retCol.b = INPUT(uv + vec2(rnd, 0.0)).b;
        }
    }

    float seed_time = float(int(iGlobalTime * 60.0 * Speed + 5.0) / 2);
    float num = random(vec2(seed_time + 10.0)) * 10.0 + 5.0;
    num = num * (2.0 - StripSize);
    vec3 digitalCol = digital(uv, seed_time, num);
    num = random(vec2(seed_time + 10.0)) * 10.0 + 10.0;
    num = num * (2.0 - StripSize);
    vec3 digitalCol2 = digital(uv, seed_time, num);

    if(StripAmount > 0.0001 && StripSize > 0.0001){
        float threshold = 0.5;
        float t1 = step(threshold, pow((digitalCol.x + digitalCol.y + digitalCol.z) / 3.0, 2.0 * (2.0 - StripAmount * 0.7)));
        float t2 = step(threshold, pow((digitalCol2.x + digitalCol2.y + digitalCol2.z) / 3.0, 2.0 * (2.0 - StripAmount * 0.7)));
        if(t1 * t2 > 0.0){
            if(t1 > 0.0){
                retCol.rgb = colorDodge(digitalCol, retCol.rgb);
            }else if(t2 > 0.0){
                retCol.rgb = colorDodge(digitalCol2, retCol.rgb);
            }
        }
    }

    vec4 origCol = INPUT(tc);
    retCol.a = origCol.a;
    retCol.rgb *= retCol.a;

    return retCol;
}

float A(float aA1, float aA2) {
  return 1.0 - 3.0 * aA2 + 3.0 * aA1;
}

float B(float aA1, float aA2) {
  return 3.0 * aA2 - 6.0 * aA1;
}

float C(float aA1) {
  return 3.0 * aA1;
}

float GetSlope(float aT, float aA1, float aA2) {
  return 3.0 * A(aA1, aA2) * aT * aT + 2.0 * B(aA1, aA2) * aT + C(aA1);
}

float CalcBezier(float aT, float aA1, float aA2) {
  return ((A(aA1, aA2) * aT + B(aA1, aA2)) * aT + C(aA1)) * aT;
}

float GetTForX(float aX, float mX1, float mX2) {
  float aGuessT = aX;
  for (int i = 0; i < 6; ++i) {
    float currentSlope = GetSlope(aGuessT, mX1, mX2);
    if (currentSlope == 0.0)
      return aGuessT;
    float currentX = CalcBezier(aGuessT, mX1, mX2) - aX;
    aGuessT -= currentX / currentSlope;
  }
  return aGuessT;
}

float KeySpline(vec4 p, float aX) {
