vec4 ApplyWave(vec2 uv, vec4 origCol, float progress) {
  float pullStrength = 0.8;
  vec2 center = vec2(0.5);
  float aspect = iResolution.x / iResolution.y;
  vec2 delta = uv - center;
  delta.x *= aspect;

  float maxR = length(vec2(0.5 * aspect, 0.5));
  float radiusNorm = length(delta) / maxR;

  float pulse1 = sin(progress * 3.141592653);
  float ringRadius1 = progress;
  float ringWidth1 = 0.12 + pulse1 * 0.08;
  float ringStrength1 = smoothstep(ringRadius1 - ringWidth1, ringRadius1, radiusNorm)
                     - smoothstep(ringRadius1, ringRadius1 + ringWidth1, radiusNorm);

  float delay = 0.1;
  float p2 = clamp(progress - delay, 0.0, 1.0);
  float pulse2 = sin(p2 * 3.141592653 * 0.8);
  float ringRadius2 = p2 * 0.8;
  float ringWidth2 = 0.16 + pulse2 * 0.1;
  float ringStrength2 = smoothstep(ringRadius2 - ringWidth2, ringRadius2, radiusNorm)
                     - smoothstep(ringRadius2, ringRadius2 + ringWidth2, radiusNorm);

  vec2 dir = normalize(delta);
  float offset = -0.14 * pullStrength * (1.0 * pulse1 * ringStrength1 + 0.7 * pulse2 * ringStrength2);
  vec2 warpedUv = uv + dir * offset / vec2(aspect, 1.0);

  vec4 warpedCol = INPUT(warpedUv);
  float blend = clamp(pulse1 * ringStrength1 + 0.75 * pulse2 * ringStrength2, 0.0, 1.0);
  return mix(origCol, warpedCol, blend);
}

