  float process = clamp(mod(time, cycle_time) / cycle_time, 0.0, 1.0);

  float fadeInEnd = 0.1;
  float fadeOutStart = 0.9;

  float fadeIn = smoothstep(0.0, fadeInEnd, process);
  float fadeOut = 1.0 - smoothstep(fadeOutStart, 1.0, process);
  float strength = min(fadeIn, fadeOut);

  float t = clamp((process - fadeInEnd) / (fadeOutStart - fadeInEnd), 0.0, 1.0);

  vec4 origCol = INPUT(tc);
  vec4 waveCol = ApplyWave(tc, origCol, t);

  return mix(origCol, waveCol, strength);
}

