vec3 blend3 (vec3 dst, vec3 src) {
    vec3 C0 = vec3(0.0);
    vec3 C1 = vec3(1.0);
    vec3 C_2 = vec3(0.5);
    vec3 ge_2 = step(C_2, src);
    vec3 res0 = blend1(dst, (src + src));
    res0 = mix(C0, C1, step(C_2, res0));
    vec3 res1 = blend2(dst, (src + src) - C1); 
    res1 = mix(C0, C1, step(C_2, res1));
    return mix(res0, res1, ge_2);
}

vec4 Blend(vec4 img, vec4 sucai, float opacity) {
    vec3 imgs = img.rgb;
    vec3 sucais = sucai.rgb;
    sucais = blend3(imgs, sucais);
    imgs = mix(imgs, sucais, sucai.a * opacity);
    return vec4(imgs, 1.0) * img.a;
}

vec2 rotate(vec2 uv, float scale, float angle){
    vec2 center = vec2(0.5, 0.5);
    vec2 offset = vec2(0.0, 0.0);
    vec2 rotatedUV = vec2(cos(angle) * (uv.x - center.x) - sin(angle) * (uv.y - center.y) + center.x,
                           sin(angle) * (uv.x - center.x) + cos(angle) * (uv.y - center.y) + center.y);
    vec2 scaledUV = rotatedUV * scale + offset;
    return scaledUV;
}
