		tuneColor.b = INPUT2(vec2(tuneColor.b, .83333)).b;
    }

    int SumFlag = u_blendFlags1 + u_blendFlags2 + u_blendFlags3 + u_blendFlags4;

    if(SumFlag > 0)
    {
        vec4 blendColor = INPUT3(tc);
