	resultColor.rgb = baseColor.rgb * (1.0 - fgColor.a) + color.rgb * fgColor.a;  
    resultColor.a = orig.a;
	resultColor.rgb *= resultColor.a;

	return mix(orig, resultColor, alp);
}

