vec4 enlarge(vec2 uv,float time)
{
    vec2 offsetR;
    vec2 offsetG;
    vec2 offsetB;
    vec2 uvR;
    vec2 uvG;
    vec2 uvB;

	float Y1 = 0.5;
    //float Y2 = 1.8;
	float Y2 = 0.8;

    //tisose
	vec3 ColorDif1 = vec3(0.8,0.5,0.2);
    vec3 ColorDif2 = vec3(0.8,0.5,0.2);
    vec3 ColorDif6 = vec3(0.8,0.5,0.2);

	vec3 Scale1 = vec3(1.0,1.0,1.0);
    vec3 Scale2 = vec3(1.0,1.0,1.0);
    vec3 Scale6 = vec3(1.0,1.0,1.0);

    if(uv.y>Y1)
    {
        offsetR = ColorDif1.r * vec2(1.0, 0.0) * time;
        offsetG = ColorDif1.g * vec2(1.0, 0.0) * time;
        offsetB = ColorDif1.b * vec2(1.0, 0.0) * time;
        uvR = (uv * 2.0 - 1.0) / (1.0 + (Scale1.r - 1.0)*time) * 0.5 + 0.5;
        uvG = (uv * 2.0 - 1.0) / (1.0 + (Scale1.g - 1.0)*time) * 0.5 + 0.5;
        uvB = (uv * 2.0 - 1.0) / (1.0 + (Scale1.b - 1.0)*time) * 0.5 + 0.5;
    }
    else if(uv.y>Y2)
    {
        offsetR = ColorDif2.r * vec2(1.0, 0.0) * time;
        offsetG = ColorDif2.g * vec2(1.0, 0.0) * time;
        offsetB = ColorDif2.b * vec2(1.0, 0.0) * time;
        uvR = (uv * 2.0 - 1.0) / (1.0 + (Scale2.r - 1.0)*time) * 0.5 + 0.5;
        uvG = (uv * 2.0 - 1.0) / (1.0 + (Scale2.g - 1.0)*time) * 0.5 + 0.5;
        uvB = (uv * 2.0 - 1.0) / (1.0 + (Scale2.b - 1.0)*time) * 0.5 + 0.5;
    }
    else
    {
        offsetR = ColorDif6.r * vec2(1.0, 0.0) * time;
        offsetG = ColorDif6.g * vec2(1.0, 0.0) * time;
        offsetB = ColorDif6.b * vec2(1.0, 0.0) * time;
        uvR = (uv * 2.0 - 1.0) / (1.0 + (Scale6.r - 1.0)*time) * 0.5 + 0.5;
        uvG = (uv * 2.0 - 1.0) / (1.0 + (Scale6.g - 1.0)*time) * 0.5 + 0.5;
        uvB = (uv * 2.0 - 1.0) / (1.0 + (Scale6.b - 1.0)*time) * 0.5 + 0.5;
    }
	vec4 cr = INPUT(vec2(uvR+offsetR));
    vec4 cg = INPUT(vec2(uvG+offsetG));
    vec4 cb = INPUT(vec2(uvB+offsetB));

    cr.bgr *= vec3(1.0,0.0,0.0);
    cg.bgr *= vec3(0.0,1.0,0.0);
    cb.bgr *= vec3(0.0,0.0,1.0);

    return vec4(cr.r+cg.r+cb.r,cr.g+cg.g+cb.g,cr.b+cg.b+cb.b,cr.a+cg.a+cb.a);
}

