vec2 mod289(vec2 x) {
	return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec3 mod289(vec3 x) {
	return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec3 permute(vec3 x)
{
	return mod289(x * x * 34.0 + x);
}

vec3 taylorInvSqrt(vec3 r)
{
	return 1.79284291400159 - 0.85373472095314 * r;
}

float snoise(vec2 v)
{
	const vec4 C = vec4(0.211324865405187, // (3.0-sqrt(3.0))/6.0
	0.366025403784439, // 0.5*(sqrt(3.0)-1.0)
	- 0.577350269189626, // -1.0 + 2.0 * C.x
	0.024390243902439); // 1.0 / 41.0
	// First corner
	vec2 i = floor(v + dot(v, C.yy));
	vec2 x0 = v - i + dot(i, C.xx);

	// Other corners
	vec2 i1;
	i1.x = step(x0.y, x0.x);
	i1.y = 1.0 - i1.x;

	// x1 = x0 - i1  + 1.0 * C.xx;
	// x2 = x0 - 1.0 + 2.0 * C.xx;
	vec2 x1 = x0 + C.xx - i1;
	vec2 x2 = x0 + C.zz;

	// Permutations
	i = mod289(i); // Avoid truncation effects in permutation
	vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0))
	+ i.x + vec3(0.0, i1.x, 1.0));

	vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x1, x1), dot(x2, x2)), 0.0);
	m = m * m;
	m = m * m;

	// Gradients: 41 points uniformly over a line, mapped onto a diamond.
	// The ring size 17*17 = 289 is close to a multiple of 41 (41*7 = 287)
	vec3 x = 2.0 * fract(p * C.www) - 1.0;
	vec3 h = abs(x) - 0.5;
	vec3 ox = floor(x + 0.5);
	vec3 a0 = x - ox;

	// Normalise gradients implicitly by scaling m
	m *= taylorInvSqrt(a0 * a0 + h * h);

	// Compute final noise value at P
	vec3 g;
	g.x = a0.x * x0.x + h.x * x0.y;
	g.y = a0.y * x1.x + h.y * x1.y;
	g.z = a0.z * x2.x + h.z * x2.y;
	return 130.0 * dot(m, g);
}

float noiseStack(vec2 pos,int octaves,float falloff){
	float noise = snoise(vec2(pos));
	float off = 1.0;
	if (octaves>1) {
		pos *= 2.0;
		off *= falloff;
		noise = (1.0-off)*noise + off*snoise(vec2(pos));
	}
	return (1.0+noise)/2.0;
}

vec2 noiseStackUV(vec2 pos,int octaves,float falloff,float diff){
	float displaceA = noiseStack(pos,octaves,falloff);
	float displaceB = noiseStack(pos+vec2(3984.293,423.21),octaves,falloff);
	return vec2(displaceA,displaceB);
}

vec3 CreateFire(float xpart,float ypart,vec2 uv,float flameSize,float realTime,float plusorminus,int fireType, float direct, vec2 iResolution){
    float ypartClip = ypart;
	vec2 coordScaled = uv*7.0;
	vec2 position;
    float ratio = iResolution.x/iResolution.y;   
    if(direct > 0.0){
        position = vec2(coordScaled.x,coordScaled.y) + vec2(1223.0,6434.0);    
        ypartClip *= 1.0/ratio;
    }else{
        position = vec2(coordScaled.y,coordScaled.x) + vec2(6434.0,1223.0);
        ypartClip *= ratio;
    }
    float ypartClippedFalloff = clamp(2.0-ypartClip,0.0,1.0);
	float ypartClipped = min(ypartClip,1.0);

    vec2 flow = vec2(4.1*(0.5-xpart),-2.0*flameSize);
	vec2 timing = plusorminus*realTime*vec2(0.0,-1.7) + flow;

	vec2 displacePos = vec2(1.0,0.5)*2.4*position+realTime*vec2(0.01,-0.7);
	vec2 displace3 = vec2(noiseStackUV(displacePos,2,0.4,0.1));
	vec2 noiseCoord = (vec2(2.0,1.0)*position+timing+0.4*displace3);//timing正负控制火焰方向
	float noise = noiseStack(noiseCoord,3,0.4);
	float flames = pow(ypartClipped,0.3*flameSize)*pow(noise,0.3*flameSize);
	float f = ypartClippedFalloff*pow(1.0-flames*flames*flames,8.0);
	float fff = f*f*f;
    float A = f;
    float B = fff;
    float C = fff*fff;
    vec3 fire;                  
    if(fireType == 1){
        fire = 1.5*vec3(C, B, A);
    }else if(fireType == 2){
        fire = 1.5*vec3(A, C, B);
    }
    else if(fireType == 3){
        fire = 1.5*vec3(B, A, C);
    }
    else if(fireType == 4){
        fire = 1.5*vec3(B, C, A);
    }
    else if(fireType == 5){
        fire = 1.5*vec3(A, B, C);
    }
    else if(fireType == 6){
        fire = 1.5*vec3(C, A, B);
    }
    return fire;
}

vec4 FUNCNAME(vec2 tc) {
	float flameSize = PREFIX(FlameSize)+0.2;
	float speed 	= PREFIX(Speed);
    float iTime 	= PREFIX(global_time)*speed;
    int   fireType 	= PREFIX(FireType);

    vec2  uv 		= tc;
	vec3  fire 		= vec3(0.0,0.0,0.0);
	float xpart;
	float ypart;

    xpart = uv.x;
	if(uv.y < 0.25){
		ypart = uv.y;
