	}

    xpart = uv.x;
	if(uv.y > 0.75){
		ypart = 1.0-uv.y;
	 	fire += CreateFire(xpart,ypart,uv,flameSize,iTime,-1.0,fireType,1.0,iResolution)*(uv.y-0.75)*5.0;
	}   

    xpart = uv.y;
	if(uv.x < 0.25){
