vec4 CreateBlurColor(vec2 uv, int loops, float random, float angle, float blurIntension, vec4 tmpColor, float direct)
{   
    for (int i = 0; i < loops; i++)
    {
        random = fract(43758.5453 * random + 0.61432);
        random = (random - 0.5) * 2.0;                
        float r =  direct*random;
        float deltaX = r*cos(angle);
        float deltaY = r*sin(angle);

        float newX = uv.x + deltaX*blurIntension;
        float newY = uv.y + deltaY*blurIntension;

        tmpColor += INPUT(vec2(newX,newY));
    }
    tmpColor = tmpColor / float(loops); 
    return tmpColor;
}

