vec4 FUNCNAME(vec2 tc) {
	float iGlobalTime = PREFIX(global_time);
	float totalTime = PREFIX(total_time);
	float iDuration = PREFIX(duration)*3.0;

	//iDuration = min(totalTime, iDuration);
	if(iDuration > totalTime)
		iDuration = totalTime;

	float start_pos = totalTime - iDuration;
	vec4 origCol = INPUT(tc);
	vec2 uv = tc;
	//vec4 blackCol = vec4(0.0,0.0,0.0,1.0);
	vec4 blackCol = vec4(0.0,0.0,0.0,origCol.a);
	vec2 center = vec2(0.5,0.5);
	vec2 o = vec2(0.0);
	float a = 0.0;
	//if(iGlobalTime > start_pos|| iGlobalTime > totalTime * 0.975){
	if(iGlobalTime > start_pos|| iGlobalTime > totalTime * 0.975){
		float process = 1.0 - min((iGlobalTime - start_pos) / iDuration, 1.0);
		//float process = min(iGlobalTime / iDuration, 1.0)*0.34+0.0001;
		float iPro = (3.0 * process * process - 2.0 * process * process * process);

		if(iResolution.x < iResolution.y){
		float prop = (iResolution.y / iResolution.x)+0.25;
	    uv.y = uv.y * prop-0.45;
		o = (uv-center)/vec2(3.5*iPro, 3.0*iPro);
		a = 1.2*(o.x*o.x+o.y*o.y)-0.6;
		}
		else{
		float prop = (iResolution.y / iResolution.x)+0.45;
	    uv.y = uv.y * prop;
	    o = (uv-center)/vec2(3.5*iPro, 4.5*iPro);
		a = 1.4*(o.x*o.x+o.y*o.y)-0.8;
		}
		//float result = smoothstep(a*a*a,a*a*a,o.x*o.x*o.y*o.y*o.y);
		float result = step(a*a*a, o.x*o.x*o.y*o.y*o.y);
		return mix(blackCol,origCol,result);
	}
	return origCol;
}

