vec2 rotate2D(vec2 _st, float _angle, float aspt){
    _st.x 	 -= 0.5;
	_st.y    -= 0.5;
    _st.x 	 = _st.x * aspt;
    _st 	 = mat2(cos(_angle),-sin(_angle),sin(_angle),cos(_angle))*_st;
    _st.x 	 = _st.x / aspt;
    _st.x	 += 0.5;
	_st.y 	 += 0.5;
    return _st;
}

vec2 NewUV(vec2 uv)
{
	uv.y =  uv.y > 0.0 && uv.y <= 0.002? 0.002:uv.y;
	uv.y =  uv.y >= 0.998 && uv.y <= 1.0? 0.998:uv.y;
	uv.x =  uv.x > 0.0 && uv.x <= 0.002? 0.002:uv.x;
	uv.x =  uv.x >= 0.998 && uv.x <= 1.0? 0.998:uv.x;
	return uv;
}

