	if(abs(zoom) < 1.0){
		float delta = 1.0+(1.0 - abs(zoom))*5.0;
		zoom 		= 1.0/(zoom/delta);
	}else if(abs(zoom) > 1.0){
		float delta = 1.0+(abs(zoom) - 1.0)*5.0;
		zoom 		= 1.0/(zoom*delta);
