#define Screen(B, L) (1.0 - (1.0 - B)*(1.0 - L))

#define BlendFunc Screen

vec3 channelBlend(vec3 blend, vec3 base){
    vec3 result = vec3(0.0);
    result.r = BlendFunc(blend.r, base.r);
    result.g = BlendFunc(blend.g, base.g);
    result.b = BlendFunc(blend.b, base.b);
    return result;
}

float changeAlpha(float iGlobalTime)
{
    int frameInterval = 50-PREFIX(speed);
    float realInterval = 0.04 * float(frameInterval);
    float k = 1.0 / (realInterval / 2.0);
    float b = 2.0;
    float triWaveIndex = floor(iGlobalTime / realInterval);
    float zerothTriWave = iGlobalTime - realInterval * triWaveIndex;
    if(int(zerothTriWave/(realInterval/2.0)) == 0){
        return k * zerothTriWave;
    }
    else{
        return (-k) * zerothTriWave + (2.0);
    }
}

