vec4 FUNCNAME(vec2 tc) {
	float waveLength 		= PREFIX(WaveLength);
	float amplitude  		= PREFIX(Amplitude);
	float speed      		= PREFIX(Speed);
	vec2  uScanLineJitter 	= vec2(PREFIX(Intension),1.0-PREFIX(Density));
	float iTime 			= PREFIX(global_time);
	vec2  uv 				= tc;
		  uv.x 				+= amplitude*sin(uv.y*(20.0-waveLength)+iTime*speed)/10.0;
	float drift 			= PREFIX(ColorDrift);
	float u 				= uv.x;
	float v 				= uv.y;
	float jitter 			= abs(nrand(v,0.0)*2.0-1.0);
	float jitterv 			= (nrand(iTime*v,0.0)*2.0-1.0)*1.5;	
	float offsetParam 		= step(uScanLineJitter.y,abs(jitter));
	jitter 			= jitter * -offsetParam * (uScanLineJitter.x + uScanLineJitter.x*jitterv);
	if(uScanLineJitter.y > 0.999){
		jitter = 0.0;
	}

	float reX = u + jitter;
	reX = reX < 0.0? -reX:reX;
	reX = reX > 1.0? 1.0 - fract(reX):reX;
	reX = reX > -0.002 && reX < 0.002? 0.002:reX;
	reX = reX > 0.998 && reX < 1.002 ? 0.998:reX;

	float reXX = u + jitter+ u*drift;
	reXX = reXX < 0.0? -reXX:reXX;
	reXX = reXX > 1.0? 1.0 - fract(reXX):reXX;
	reXX = reXX > -0.002 && reXX < 0.002? 0.002:reXX;
	reXX = reXX > 0.998 && reXX < 1.002 ? 0.998:reXX;

	float reXXX = u + jitter- u*drift;
	reXXX = reXXX < 0.0? -reXXX:reXXX;
	reXXX = reXXX > 1.0? 1.0 - fract(reXXX):reXXX;
	reXXX = reXXX > -0.002 && reXXX < 0.002? 0.002:reXXX;
	reXXX = reXXX > 0.998 && reXXX < 1.002 ? 0.998:reXXX;

	vec4  color1 			= INPUT(vec2(reX,   v));
	vec4  color2			= INPUT(vec2(reXX , v));
	vec4  color3 			= INPUT(vec2(reXXX ,v));

	return vec4(color3.x,color2.y,color1.z,(color1.a+color2.a+color3.a)/3.0);
}

