vec3 rainbow(float level)
{
	float r = step(level, 2.0);
	float g = 1.0 - abs(level - 2.0) * 0.5;
	float b = step(3.0, level);

	return vec3(b, g, r);
}

vec3 blendRainbow(float x)
{
    float level1 = floor(x*4.0);
    float level2 = min(4.0, floor(x*4.0) + 1.0);

    vec3 a = rainbow(level1);
    vec3 b = rainbow(level2);

    return mix(a, b, fract(x*4.0));
}

