vec3 heatMap(float gray) {   
	vec3 heatCol;      
    heatCol.r = smoothstep(0.5, 0.8, gray);
    if(gray > 0.9)
    	heatCol.r *= (1.1 - gray) * 5.0;

	heatCol.g = smoothstep(0.0, 0.6, gray);
	if(gray > 0.6) 
		heatCol.g = 1.0 - smoothstep(0.6, 1.0, gray);

	heatCol.b = 1.0 - gray;          
	heatCol = clamp(heatCol, 0.0, 1.0);

	return heatCol;
}

vec3 rainbow(float level)
{
	float r = step(level, 2.0);
	float g = 1.0 - abs(level - 2.0) * 0.5;
	float b = step(3.0, level);

	return vec3(b, g, r);
}

vec3 blendRainbow(float x)
{
    float level1 = floor(x * 4.0);
    float level2 = min(level1 + 1.0, 4.0);

    vec3 a = rainbow(level1);
    vec3 b = rainbow(level2);

    return mix(a, b, fract(x * 4.0));
}

