vec3 shake(vec4 color,vec2 texCoord,float time,int level)
{
    float seg = 0.1;
    float swing = 6.0;
    //float swing = 7.0;
    float yStep = 0.0;

    if (level == 0) 
    {
	    seg = 0.09;
    } 
    else if (level == 1) 
    {
        seg= 0.2;
    } 
    else 
    {
        seg = 0.2;
        swing = 16.0;
		//swing = 10.0;
        yStep = 10.0;
    }
    float ITime = mod(time, 32.0); 
    //float ITime = mod(time, 40.0); 
    float glitch = sat(seg);
    float rnd0 = rand(function2(vec2(ITime, ITime), swing));
    float r0 = sat((1.0 - glitch) * 0.7 + rnd0);
    float rnd1 = rand(vec2(function1(texCoord.x, 10.0 * r0), ITime)); 

    float r1 = 0.5 - 0.5 * glitch + rnd1;
    r1 = 1.0 - max(0.0, ((r1 < 1.0) ? r1 : 0.9999999)); 
    float rnd2 = rand(vec2(function1(texCoord.y, yStep * r1), ITime)); //vert
    float r2 = sat(rnd2);

    float rnd3 = rand(vec2(function1(texCoord.y, 10.0 * r0), ITime));
    float r3 = (1.0 - sat(rnd3 + 0.8)) - 0.1;

    float pxrnd = rand(texCoord + ITime);

    float ofs = 0.05 * r2 * seg * (rnd0 > 0.5 ? 1.0 : -1.0);
    ofs += 0.5 * pxrnd * ofs;

    texCoord.y += 0.1 * r3 * seg;

    float SAMPLES_F = 1.0 / 6.0;

    vec3 sum = vec3(0.0);
    vec3 wsum = vec3(0.0);
    for (int i = 0; i < 6; ++i) 
    {
        float t = float(i) * SAMPLES_F;
        texCoord.x = sat(texCoord.x + ofs * t);
        vec3 samplecol = vec3(color.rgb);
        vec3 s = offset(t);
        samplecol.rgb = samplecol.rgb * s;
        sum += samplecol;
        wsum += s;
    }
    sum /= wsum;

    return sum;
}

float easeInOut(float x,float inflectionPoint)
{
    float result = 0.0;
    if(x < inflectionPoint && x > 0.01)
        result =  pow(x,3.0)/pow(inflectionPoint,3.0);
    else if(x < 1.0 && x >= inflectionPoint)
        result =  pow(1.0 - x,2.0)/pow(1.0 - inflectionPoint,2.0);      
    return result;
}

float easeInOut2(float x,float inflectionPoint)
{
    float result = 0.0;    
    if(x < inflectionPoint && x > 0.01 )
        result = pow(x,2.0)/pow(inflectionPoint,2.0);
    else if(x < 1.0 && x >= inflectionPoint)
        result = (1.0 - x)/(1.0 - inflectionPoint);
    return result;
}

