        {
            y1 = y1 - state1_expanse1 * Progress1 + state2_expanse1 * (Progress1 - progress_y);
            y2 = y2 + state1_expanse1 * Progress1 - state2_expanse1 * (Progress1 - progress_y);

            float temp3 = y3 - state1_expanse2 * Progress1 + state2_expanse2 * (Progress1 - Progress2) - state3_expanse1 * (Progress2 - Progress3);
            float temp4 = y4 + state1_expanse2 * Progress1 + state2_expanse3 * (Progress1 - Progress2) - state3_expanse2 * (Progress2 - Progress3);
            y3 = temp3 + 0.65 * (Progress3 - progress_y);
            y4 = temp4 + 0.7 * (Progress3 - progress_y);      
        }

        float temp2 = min(min(y2,y3),y4);        
        float temp4 = max(max(y2,y3),y4);
        float temp3 = y3;
        if(y2 > y3 && y2 < y4)
            temp3 = y2;
        else if(y2 > y4)
            temp3 = y4;

        y2 = temp2;
        y3 = temp3;
        y4 = temp4;

        if(uv.y < y1)
        {
            float offsetCenter = 0.35;
            newUV.x = offsetCenter + (uv.x - offsetCenter) * scale;
        }
        else if(uv.y < y2)
        {
            float offsetCenter = 1.0;
            newUV.x = offsetCenter + (uv.x - offsetCenter) * scale;
        }
        else if(uv.y < y3)
        {
            float offsetCenter = 0.35 +  sin(progress * PI) * 0.35;            
            newUV.x = offsetCenter + (uv.x - offsetCenter) * scale;
        }
        else if(uv.y < y4)
        {
            scale =1.0 -  sin(progress * PI) * 0.3;
            float offsetCenter = 0.9 - progress_x * 0.4;
			//float offsetCenter = 1.0;
            newUV.x = offsetCenter + (uv.x - offsetCenter) * scale;
        }       
        else
        {
            float offsetCenter = 0.5 +  sin(progress * PI) * 0.3;
            newUV.x = offsetCenter + (uv.x - offsetCenter) * scale;     
        }            
    }
	vec4 color = INPUT(newUV);

    if(elapsedTime > duration * 0.5)
    {
        int level = 0;
        color.rgb = shake(color,newUV,elapsedTime,level);
    }
	return color;
}

