vec3 mod3(vec3 x) {
  return x - floor(x * (1.0 / 290.0)) * 290.0;
}

vec2 mod2(vec2 x) {
  return x - floor(x * (1.0 / 290.0)) * 290.0;
}

vec3 Align(vec3 x) {
  return mod3(((x*34.0)+1.0)*x);
}

float snoise(vec2 v) {
  vec2 i  = floor(v + dot(v, vec2(0.366025403784439)) );
  vec2 x0 = v -   i + dot(i, vec2(0.211324865405187));
  vec2 i1;
  i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + vec4(0.211324865405187,0.211324865405187,-0.577350269189626,-0.577350269189626);
  x12.xy -= i1;
  i = mod2(i); 
  vec3 p = Align( Align( i.y + vec3(0.0, i1.y, 1.0 )) + i.x + vec3(0.0, i1.x, 1.0 ));
  vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
  m = m*m ;
  m = m*m ;
  vec3 x = 2.0 * fract(p * vec3(0.024390243902439)) - 1.0;    
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;
  m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
  vec3 g;
  g.x  = a0.x  * x0.x  + h.x  * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}

float rand(vec2 co)
{
   return fract(sin(dot(co.xy,vec2(12.9898,78.233))) * 43758.5453);
}


vec4 FUNCNAME(vec2 tc) 
{
	vec4 c = INPUT(tc);   
    int alpha = PREFIX(alpha);
    vec2 uv = tc;
    vec2 fragCoord = tc.xy * iResolution.xy;      
    float time = PREFIX(global_time) * 2.0;  
    float noise = max(0.0, snoise(vec2(time, uv.y * 0.3)) - 0.3) * (1.0 / 0.7);    
    noise = noise + (snoise(vec2(time*10.0, uv.y * 2.4)) - 0.5) * 0.15;      
    float xpos = uv.x - noise * noise * 0.25;
	vec4 fragColor = INPUT(vec2(xpos, uv.y));      
    fragColor.rgb = mix(fragColor.rgb, vec3(rand(vec2(uv.y * time))), noise * 0.3).rgb;  
    if (floor(mod(fragCoord.y * 0.25, 2.0)) == 0.0)
    {
        fragColor.rgb *= 1.0 - (0.15 * noise);
    }    

    fragColor.g = mix(fragColor.b, INPUT(vec2(xpos + noise * 0.05, uv.y)).g, 0.25);
    fragColor.r = mix(fragColor.b, INPUT(vec2(xpos - noise * 0.05, uv.y)).r, 0.25);
    return mix( fragColor, c, 1.0 - float(alpha)/100.0 );


}

float noise(float t)
{
	return INPUT2(vec2(t,.0)/vec2(96.0)).z;
}
float noise(vec2 t)
{
	return INPUT2(t/vec2(96.0)).z;
}

vec3 lensflare(vec2 uv,vec2 pos)
{
	vec2 main = uv-pos;
	vec2 uvd = uv*(length(uv));

	float ang = atan(main.x,main.y);
	float dist=length(main); dist = pow(dist,.1);
	float n = noise(vec2(ang*16.0,dist*32.0));

	float f0 = 1.0/(length(uv-pos)*16.0+1.0);

	f0 = f0 + f0*(sin(noise(sin(ang*2.+pos.x)*4.0 - cos(ang*3.+pos.y))*16.)*.1 + dist*.1 + .8);

	float f1 = max(0.01-pow(length(uv+1.2*pos),1.9),.0)*7.0;

	float f2 = max(1.0/(1.0+32.0*pow(length(uvd+0.8*pos),2.0)),.0)*0.25;
	float f22 = max(1.0/(1.0+32.0*pow(length(uvd+0.85*pos),2.0)),.0)*0.23;
	float f23 = max(1.0/(1.0+32.0*pow(length(uvd+0.9*pos),2.0)),.0)*0.21;

	vec2 uvx = mix(uv,uvd,-0.5);

	float f4 = max(0.01-pow(length(uvx+0.4*pos),2.4),.0)*6.0;
	float f42 = max(0.01-pow(length(uvx+0.45*pos),2.4),.0)*5.0;
	float f43 = max(0.01-pow(length(uvx+0.5*pos),2.4),.0)*3.0;

	uvx = mix(uv,uvd,-.4);

	float f5 = max(0.01-pow(length(uvx+0.2*pos),5.5),.0)*2.0;
	float f52 = max(0.01-pow(length(uvx+0.4*pos),5.5),.0)*2.0;
	float f53 = max(0.01-pow(length(uvx+0.6*pos),5.5),.0)*2.0;

	uvx = mix(uv,uvd,-0.5);

	float f6 = max(0.01-pow(length(uvx-0.3*pos),1.6),.0)*6.0;
	float f62 = max(0.01-pow(length(uvx-0.325*pos),1.6),.0)*3.0;
	float f63 = max(0.01-pow(length(uvx-0.35*pos),1.6),.0)*5.0;

	vec3 c = vec3(.0);

	c.r+=f2+f4+f5+f6; c.g+=f22+f42+f52+f62; c.b+=f23+f43+f53+f63;
	c = c*1.3 - vec3(length(uvd)*.05);
	c+=vec3(f0);

	return c;
}

vec3 cm(vec3 color, float factor,float factor2) // color modifier
{
	float w = color.x+color.y+color.z;
	return mix(color,vec3(w)*factor,w*factor2);
}

vec4 FUNCNAME(vec2 tc) 
{
    vec4 ori = INPUT1(tc);
	vec2 uv = tc - 0.5;
	uv.x *= iResolution.x/iResolution.y; //fix aspect ratio   

    vec2 resolution = iResolution.xy;
    int alpha =PREFIX(alpha);
    float iTime = PREFIX(global_time);

    vec2 mouse = vec2(0.0);

	mouse.x *= iResolution.x/iResolution.y; //fix aspect ratio
	mouse.x=sin(iTime)*0.5;
    mouse.y=sin(iTime*0.913)*0.5;

	vec3 color = vec3(1.4,1.2,1.0)*lensflare(uv,mouse.xy);
	color -= noise(gl_FragCoord.xy)*.015;
	color = cm(color,.5,.1);
	vec4 fragColor = vec4(color,1.0);
    fragColor.xyz = fragColor.zyx;
    fragColor.xyz = 1.0 - (1.0 - ori.xyz)*(1.0-fragColor.xyz);
    return mix( fragColor, ori, 1.0 - float(alpha)/100.0 );


}

#define SQRT3 1.732050807
#define PI 3.141592653
vec4 FUNCNAME(vec2 tc) 
{
	vec4 c = INPUT1(tc);

    int alpha = PREFIX(alpha);
    vec2 uv = tc;
    vec2 fragCoord = tc.xy * iResolution.xy;
	vec2 block = floor(fragCoord.xy / vec2(16));
	vec2 uv_noise = block / vec2(96);
    float iTime = PREFIX(global_time) ;
	uv_noise += floor(vec2(iTime) * vec2(1234.0, 3543.0)) / vec2(96);

	float block_thresh = pow(fract(iTime * 1236.0453), 2.0) * 0.2;
	float line_thresh = pow(fract(iTime * 2236.0453), 3.0) * 0.7;

	vec2 uv_r = uv, uv_g = uv, uv_b = uv;

	// glitch some blocks and lines
	if (INPUT2(uv_noise).b < block_thresh ||
		INPUT2(vec2(uv_noise.y, 0.0)).g < line_thresh) {

		vec2 dist = (fract(uv_noise) - 0.5) * 0.3;
		uv_r += dist * 0.1;
		uv_g += dist * 0.2;
		uv_b += dist * 0.125;
	}
    vec4 fragColor = c;
	fragColor.b = INPUT1(uv_r).b;
	fragColor.g = INPUT1(uv_g).g;
	fragColor.r = INPUT1(uv_b).r;

	// loose luma for some blocks
	if (INPUT2(uv_noise).g < block_thresh)
		fragColor.rgb = fragColor.ggg;

	// discolor block lines
	if (INPUT2(vec2(uv_noise.y, 0.0)).b * 3.5 < line_thresh)
		fragColor.rgb = vec3(0.0, dot(fragColor.rgb, vec3(1.0)), 0.0);

	// interleave lines in some blocks
	if (INPUT2(uv_noise).g * 1.5 < block_thresh ||
		INPUT2(vec2(uv_noise.y, 0.0)).g * 2.5 < line_thresh) {
		float line = fract(fragCoord.y / 3.0);
		vec3 mask = vec3(3.0, 0.0, 0.0);
		if (line > 0.333)
			mask = vec3(0.0, 3.0, 0.0);
		if (line > 0.666)
			mask = vec3(0.0, 0.0, 3.0);

		fragColor.xyz *= mask;
	}

    return mix( fragColor, c, 1.0 - float(alpha)/100.0 );


}
